    function check_options()
    {
        $options1 = $this->input->post('options1');
        $options2 = $this->input->post('options2');

        if (empty($options1) && empty($options2)) {
            $this->form_validation->set_message('check_options', lang('tnh_options_or_required'));
            return false;
        }
        return true;
    }

    public function add_productions_plan()
    {
        if (!$this->perAddProductionsPlan) {
            accessDenied();
        }
        if ($this->input->post('add')) {
            $data = [];
            ini_set('max_execution_time', 300);
            $this->form_validation->set_rules('reference_no', lang("tnh_reference_productions_plan"), 'trim|required|is_unique[tbl_productions_plan.reference_no]');
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('planning_cycle', lang("tnh_planning_cycle"), 'required');
            $this->form_validation->set_rules('id_branch', lang("tnh_branch"), 'required');
            $this->form_validation->set_rules('options1', lang("tnh_options"), 'callback_check_options');
            $this->form_validation->set_rules('versions[]', lang("BOM"), 'required');
            $this->form_validation->set_rules('versions_stage[]', lang("Công đoạn"), 'required');
            if ($this->form_validation->run() == true) {
                // $reference_no = $this->input->post('reference_no');
                $reference_no = getReference('productions_plan');
                $dateDB = to_sql_date($this->input->post('date'), true);
                $planning_cycle = $this->input->post('planning_cycle');
                $options1 = $this->input->post('options1') ? $this->input->post('options1') : 0;
                $options2 = $this->input->post('options2') ? $this->input->post('options2') : 0;
                $options3 = $this->input->post('options3') ? $this->input->post('options3') : 0;
                $orders = !empty($this->input->post('orders')[0]) ? $this->input->post('orders')[0] : null;
                $business_plans = !empty($this->input->post('business_plans')[0]) ? $this->input->post('business_plans')[0] : null;

                if (empty($options3)) {
                    $data['result'] = 0;
                    $data['message'] = lang('Vui lòng chọn tự tạo lệnh sản xuất tổng');
                    echo json_encode($data);
                    die;
                }

                $orders_items = !empty($this->input->post('orders_items')[0]) ? $this->input->post('orders_items')[0] : null;
                $business_plans_items = !empty($this->input->post('business_plans_items')[0]) ? $this->input->post('business_plans_items')[0] : null;
                $dt_quantity_reserve = !empty($this->input->post('quantity_reserve')) ? $this->input->post('quantity_reserve') : null;
                $dt_quantity = !empty($this->input->post('quantity')) ? $this->input->post('quantity') : null;
                $id_branch = $this->input->post('id_branch');
                $flagChonse = false;
                if (!empty($business_plans) || !empty($orders)) {
                    $flagChonse = true;
                }

                $p_id_post = $this->input->post('p_id_post');
                $arrObjecOrderstId_post = $this->input->post('arrObjecOrderstId_post');
                $arrObjecBusinesstId_post = $this->input->post('arrObjecBusinesstId_post');

                $safe_inventory = $this->input->post('safe_inventory') ? $this->input->post('safe_inventory') : 0;
                $note = $this->input->post('note', false);
                $status = 'un_approved';
                $select_custom_fields = "";
                $where_custom_fields = "";
                $date_start = NULL;
                $date_end = NULL;
                $sales_orders = NULL;
                $sales_orders_id = NULL;
                $business_plan = NULL;
                $business_plan_id = NULL;
                $arr_date = [];
                $whereOrder = '';
                $whereBusinessPlan = '';
                $queryOrder = "";
                $queryBusinessPlan = "";
                $queryOrderData = "";
                $queryBusinessPlanData = "";

                $arrOrdersItemId = [];
                $arrBusinessItemId = [];
                $arrTypeObject = $this->input->post('type_object');
                if (!empty($arrTypeObject)) {
                    foreach ($arrTypeObject as $key => $value) {
                        $item_object_id = $this->input->post('item_object_id')[$key];
                        if ($value == 'orders') {
                            array_push($arrOrdersItemId, $item_object_id);
                        } else if ($value == 'business_plan') {
                            array_push($arrBusinessItemId, $item_object_id);
                        }
                    }
                }


                if (!empty($planning_cycle)) {
                    $arr_plan = explode('-', trim($planning_cycle));

                    $date1 = to_sql_date(trim($arr_plan[0]));
                    $date2 = to_sql_date(trim($arr_plan[1]));

                    if ($options1 == true) {
                        if (!empty($orders) || $flagChonse) {
                            $orders = !empty($orders) ? str_replace(",", "','", $orders) : 0;
                            $whereOrder = " AND tbl_orders.id IN ('$orders')";
                        }

                        $whereOrder.= ' AND tbl_orders.is_cancel = 0';
                        if (!empty($orders_items)) {
                            $orders_items = !empty($orders_items) ? str_replace(",", "','", $orders_items) : 0;
                            $whereOrder .= " AND tbl_order_items.id IN ('$orders_items')";
                        }

                        if (!empty($arrOrdersItemId)) {
                            $arrOrdersItemId = !empty($arrOrdersItemId) ? str_replace(",", "','", implode(',', $arrOrdersItemId)) : 0;
                            $whereOrder .= " AND tbl_order_items.id IN ('$arrOrdersItemId')";
                        }

                        if (!empty($p_id_post)) {
                            $whereOrder .= " AND tbl_order_items.item_id IN ($p_id_post)";
                        }

                        if (!empty($arrObjecOrderstId_post)) {
                            $whereOrder.= " AND tbl_order_items.order_id IN (".$arrObjecOrderstId_post.")";
                        }

                        $slKeep = "COALESCE((
                            SELECT SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
                            FROM tbltransfer_warehouse_detail
                            WHERE tbltransfer_warehouse_detail.order_id_item = tbl_order_items.id AND tbltransfer_warehouse_detail.tranfer_business_item_id = 0
                        ), 0)";

                        $keepTranferBusinessItem = 'COALESCE((
                            SELECT
                                SUM(tbl_tranfer_business_item.quantity) as quantity
                            FROM tbl_tranfer_business_item
                            WHERE tbl_tranfer_business_item.order_item_id = tbl_order_items.id
                        ), 0)';

                        // $query = "(
                        //     SELECT
                        //         GROUP_CONCAT(distinct(tbl_orders.id) SEPARATOR ',') as id,
                        //         GROUP_CONCAT(distinct(tbl_orders.reference_no) SEPARATOR '||| ') as reference_orders
                        //     FROM tbl_orders
                        //     INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                        //     INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                        //     WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item $whereOrder
                        // )";

                        $query = "(
                            SELECT
                                GROUP_CONCAT(distinct(tbl_orders.id) SEPARATOR ',') as id,
                                GROUP_CONCAT(distinct(tbl_orders.reference_no) SEPARATOR '||| ') as reference_orders
                            FROM tbl_orders
                            INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                            INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                            INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                            WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep) - $keepTranferBusinessItem) > tbl_order_item_shippings.quantity_plan_item $whereOrder
                        )";
                        $rs = $this->db->query($query)->row_array();
                        $sales_orders = $rs['reference_orders'];
                        $sales_orders_id = $rs['id'];

                        if (!empty($rs['reference_orders'])) {
                            // $queryOrder = "
                            // SELECT tbl_order_item_shippings.date_shipping as date_delivery
                            // FROM tbl_orders
                            // INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                            // INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                            // WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item $whereOrder
                            // ";

                            // $queryOrderData = "
                            // SELECT
                            // 'orders' as type_object,
                            // tbl_orders.id as object_id,
                            // tbl_orders.reference_no as reference_no,
                            // tbl_order_items.id as item_object_id,
                            // tbl_order_items.item_id as item_id
                            // FROM tbl_orders
                            // INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                            // INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                            // WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item $whereOrder
                            // GROUP BY tbl_order_items.id
                            // ";

                            $queryOrder = "
                            SELECT tbl_order_item_shippings.date_shipping as date_delivery
                            FROM tbl_orders
                            INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                            INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                            INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                            WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep) - $keepTranferBusinessItem) > tbl_order_item_shippings.quantity_plan_item $whereOrder
                            ";

                            $queryOrderData = "
                            SELECT
                            'orders' as type_object,
                            tbl_orders.id as object_id,
                            tbl_orders.reference_no as reference_no,
                            tbl_order_items.id as item_object_id,
                            tbl_order_items.item_id as item_id
                            FROM tbl_orders
                            INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                            INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                            INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                            WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep) - $keepTranferBusinessItem) > tbl_order_item_shippings.quantity_plan_item $whereOrder
                            GROUP BY tbl_order_items.id
                            ";
                        }
                    }

                    if ($options2 == true) {
                        if (!empty($business_plans) || $flagChonse) {
                            $business_plans = !empty($business_plans) ? str_replace(",", "','", $business_plans) : 0;
                            $whereBusinessPlan = " AND tbl_business_plan.id IN ('$business_plans')";
                        }

                        if (!empty($business_plans_items)) {
                            $business_plans_items = !empty($business_plans_items) ? str_replace(",", "','", $business_plans_items) : 0;
                            $whereBusinessPlan .= " AND tbl_business_plan_items.id IN ('$business_plans_items')";
                        }

                        if (!empty($arrBusinessItemId)) {
                            $arrBusinessItemId = !empty($arrBusinessItemId) ? str_replace(",", "','", implode(',', $arrBusinessItemId)) : 0;
                            $whereBusinessPlan .= " AND tbl_business_plan_items.id IN ('$arrBusinessItemId')";
                        }

                        if (!empty($p_id_post)) {
                            $whereBusinessPlan .= " AND tbl_business_plan_items.items_id IN ($p_id_post)";
                        }

                        if (!empty($arrObjecBusinesstId_post)) {
                            $whereBusinessPlan.= " AND tbl_business_plan_items.business_plan_id IN (".$arrObjecBusinesstId_post.")";
                        }

                        $query = "(
                            SELECT
                                GROUP_CONCAT(distinct(tbl_business_plan.id) SEPARATOR ',') as id,
                                GROUP_CONCAT(distinct(tbl_business_plan.reference_no) SEPARATOR ', ') as reference_no
                            FROM tbl_business_plan
                            INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                            INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                            WHERE tbl_business_plan.status = 'approved' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item $whereBusinessPlan
                        )";
                        $rs = $this->db->query($query)->row_array();
                        $business_plan = $rs['reference_no'];
                        $business_plan_id = $rs['id'];

                        if (!empty($rs['reference_no'])) {
                            $queryBusinessPlan = "
                            SELECT tbl_business_plan_items_date.date as date_delivery
                            FROM tbl_business_plan
                            INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                            INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                            WHERE tbl_business_plan.status = 'approved' AND tbl_business_plan.productions_plan_id = 0 AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item $whereBusinessPlan
                            ";

                            $queryBusinessPlanData = "
                            SELECT
                            'business_plan' as type_object,
                            tbl_business_plan.id as object_id,
                            tbl_business_plan.reference_no as reference_no,
                            tbl_business_plan_items.id as item_object_id,
                            tbl_business_plan_items.items_id as item_id
                            FROM tbl_business_plan
                            INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                            INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                            WHERE tbl_business_plan.status = 'approved' AND tbl_business_plan.productions_plan_id = 0 AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item $whereBusinessPlan
                            GROUP BY tbl_business_plan_items.id
                            ";
                        }
                    }

                    $date_start = $date1;
                    $date_end = $date2;
                }

                $whereUnion = '';
                if (!empty($queryOrder) && !empty($queryBusinessPlan)) {
                    $whereUnion = "UNION ALL";
                }

                if (empty($queryOrder) && empty($queryBusinessPlan)) {
                    $data['result'] = 0;
                    $data['message'] = lang('not_data_exists');
                    echo json_encode($data);
                    die;
                }

                $queryGetDate = "(
                SELECT cs.date_delivery
                FROM (
                    $queryOrder
                    $whereUnion
                    $queryBusinessPlan
                    ) as cs
                GROUP BY cs.date_delivery
                ) ";

                $resultDate = $this->db->query($queryGetDate)->result_array();
                if (!empty($resultDate)) {
                    foreach ($resultDate as $k => $val) {
                        $date = $val['date_delivery'];
                        $selectOrderQuantity = "
                            COALESCE((
                                SELECT
                                    SUM((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - tbl_order_item_shippings.quantity_plan_item)
                                FROM tbl_order_item_shippings
                                INNER JOIN tbl_order_items ON tbl_order_items.id = tbl_order_item_shippings.order_item_id
                                INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                                WHERE tbl_order_item_shippings.order_item_id = od.item_object_id AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') = '$date' AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item
                            ), 0)
                        ";

                        $selectBusinessPlanQuantity = "
                            COALESCE((
                                SELECT
                                    SUM(tbl_business_plan_items_date.quantity - tbl_business_plan_items_date.quantity_plan_item)
                                FROM tbl_business_plan_items_date
                                WHERE tbl_business_plan_items_date.business_plan_items_id = od.item_object_id AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') = '$date' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item
                            ), 0)
                        ";

                        $select = "(IF(od.type_object = 'orders', $selectOrderQuantity, IF(od.type_object = 'business_plan', $selectBusinessPlanQuantity, 0)))";

                        // $select = 0;
                        $select_custom_fields .= ", " . $select . " as '" . $date . "'";

                        array_push($arr_date, $date);
                    }
                }

                $tableOrdersDelivery = "(
                    $queryOrderData
                    $whereUnion
                    $queryBusinessPlanData
                ) as od";

                $warehouses = "(
                    SELECT
                        tblwarehouse_items.id_items,
                        SUM(tblwarehouse_items.product_quantity) as quantity_warehouses
                    FROM tblwarehouse_items
                    WHERE tblwarehouse_items.type_items = 'product' AND tblwarehouse_items.warehouse_id NOT IN (".WAREHOUSES_CAPACITY.", ".WAREHOUSES_HOLD.")
                    GROUP BY tblwarehouse_items.id_items
                ) warehouses";

                // COALESCE(warehouses.quantity_warehouses, 0) as quantity_warehouses,
                $this->db->select("
                    od.type_object as type_object,
                    od.item_object_id as item_object_id,
                    od.item_id as item_id,
                    od.object_id as object_id,
                    tbl_products.code as product_code,
                    tbl_products.name as product_name,
                    tbl_products.quantity_minimum as quantity_minimum,
                    tbl_products.quantity_max as quantity_max,
                    0 as quantity_warehouses,
                    $select_custom_fields,
                ", false)
                    ->from('(SELECT 1 as id) cs')
                    ->join($tableOrdersDelivery, 'od.item_object_id > 0')
                    ->join('tbl_products', 'tbl_products.id = od.item_id', 'left');
                    // ->join($warehouses, 'warehouses.id_items = tbl_products.id', 'left');

                if ($safe_inventory) {
                    $this->db->where('tbl_products.quantity_minimum >', 0);
                }

                $result = $this->db->get()->result_array();
                if (empty($result)) {
                    $data['result'] = 0;
                    $data['message'] = lang('not_data_exists');
                    echo json_encode($data);
                    die;
                }

                $dtProduct = array_reduce($result, function($carry, $item) {
                    $carry[$item['item_id']] = $item;
                    return $carry;
                });

                $productions_plan = [
                    'reference_no' => $reference_no,
                    'date' => $dateDB,
                    'date_start' => $date_start,
                    'date_end' => $date_end,
                    'safe_inventory' => $safe_inventory,
                    'options1' => $options1,
                    'options1_reference_no' => $sales_orders,
                    'options1_id' => $sales_orders_id,
                    'options2' => $options2,
                    'options2_reference_no' => $business_plan,
                    'options2_id' => $business_plan_id,
                    'note' => $note,
                    'status' => $status,
                    'date_created' => date('Y-m-d H:i:s'),
                    'created_by' => get_staff_user_id(),
                    'id_branch' => $id_branch,
                    'options3' => $options3
                ];

                //created preventive
                $arrItemsPerventive = [];
                $product_id_preventive = $this->input->post('product_id_preventive');
                if (!empty($product_id_preventive)) {
                    foreach ($product_id_preventive as $k => $val) {
                        $versions_perventive = !empty($this->input->post('versions_perventive')[$k]) ? $this->input->post('versions_perventive')[$k] : '';
                        $versions_stages_perventive = !empty($this->input->post('versions_stages_perventive')[$k]) ? $this->input->post('versions_stages_perventive')[$k] : '';
                        $is_no_stock = !empty($this->input->post('is_no_stock')[$k]) ? $this->input->post('is_no_stock')[$k] : 0;
                        $quantity_preventive = !empty($this->input->post('quantity_preventive')[$k]) ? number_unformat($this->input->post('quantity_preventive')[$k]) : '';
                        if($is_no_stock == 1){
                            $quantity_preventive = 0;
                        }
                        if (empty($quantity_preventive)) continue;

                        if (empty($versions_perventive)) {
                            $data['result'] = 0;
                            $data['message'] = lang('Vui lòng chọn định mức BOM dự phòng');
                            echo json_encode($data);
                            die;
                        }

                        if (empty($versions_stages_perventive)) {
                            $data['result'] = 0;
                            $data['message'] = lang('Vui lòng chọn định mức giai đoạn dự phòng');
                            echo json_encode($data);
                            die;
                        }

                        $quantity_max = $dtProduct[$val]['quantity_max'] ?? 0;
                        if ($quantity_preventive > $quantity_max) {
                            $data['result'] = 0;
                            $data['message'] = lang('SL dự phòng vượt quá số lượng tối đa của thành phẩm');
                            echo json_encode($data);
                            die;
                        }

                        $arrItemsPerventive[] = [
                            'product_id' => $val,
                            'versions_perventive' => $versions_perventive,
                            'versions_stages_perventive' => $versions_stages_perventive,
                            'quantity_preventive' => $quantity_preventive,
                        ];
                    }
                }

                $arrProductionsPlanObject = [];
                if (!empty($options1) && !empty($sales_orders_id)) {
                    $arr_sales_orders_id = explode(',', $sales_orders_id);
                    $arr_sales_orders_id = array_unique($arr_sales_orders_id);
                    foreach ($arr_sales_orders_id as $key => $value) {
                        $arrProductionsPlanObject[] = [
                            'object_id' => $value,
                            'object_type' => 'orders',
                            'is_preventive' => 0,
                        ];
                    }
                }

                if (!empty($options2) && !empty($business_plan_id)) {
                    $arr_business_plan_id = explode(',', $business_plan_id);
                    $arr_business_plan_id = array_unique($arr_business_plan_id);
                    foreach ($arr_business_plan_id as $key => $value) {
                        $arrProductionsPlanObject[] = [
                            'object_id' => $value,
                            'object_type' => 'business_plan',
                            'is_preventive' => 0,
                        ];
                    }
                }

                //is warehouse and quantity compensation 
                $itemBOMM = $this->input->post('itemBOMM');
                $arrItemBOMCompensation = [];
                if (!empty($itemBOMM)) {
                    foreach ($itemBOMM as $key => $value) {
                        $value['quantity_compensation'] = number_unformat($value['quantity_compensation'], false);
                        $quantity_primary = $value['quantity_compensation'] * $value['quantity_exchange'] / $value['exchange_unit'];

                        if ($value['item_type'] == "materials") {
                            $quantity_convert_warehouses = roundNumberFormat($quantity_primary / $value['exchange_standard_unit'] * $value['exchange_unit'], 0);
                        } else {
                            $quantity_convert_warehouses = roundNumberFormat($quantity_primary * $value['conversion_quantity_unit'], 0);
                        }
                        
                        $arrItemBOMCompensation[] = [
                            'item_id' => $value['item_id'],
                            'item_type' => $value['item_type'],
                            'standard_unit' => $value['standard_unit'],
                            'exchange_standard_unit' => $value['exchange_standard_unit'],
                            'quantity_exchange' => $value['quantity_exchange'],
                            'exchange_unit' => $value['exchange_unit'],
                            'quantity' => $value['quantity'],
                            'quantity_compensation' => $value['quantity_compensation'],
                            'quantity_warehouse' => $value['quantity_warehouse'],
                            'quantity_compensation_sm' => $value['quantity_compensation_sm'],
                            'quantity_primary' => $quantity_primary,
                            'quantity_convert_warehouses' => $quantity_convert_warehouses,
                            'conversion_quantity_unit' => $value['conversion_quantity_unit'],
                            'is_zinc' => $value['is_zinc'],
                        ];
                    }
                }

                $productions_plan_id = $this->manufactures_model->insertProductionsPlan($productions_plan);
                if ($productions_plan_id) {
                    updateReference('productions_plan');
                    foreach ($result as $key => $value) {
                        $temp_str_object = $value['type_object'].'___'.$value['item_object_id'];
                        // $quantity_reserve = !empty($this->input->post('quantity_reserve')[$value['item_object_id']]) ? number_unformat($this->input->post('quantity_reserve')[$value['item_object_id']]) : 0;

                        // $quantity_total_details = !empty($this->input->post('quantity')[$value['item_object_id']]) ? number_unformat($this->input->post('quantity')[$value['item_object_id']]) : 0;

                        // $versions = !empty($this->input->post('versions')[$value['item_object_id']]) ? $this->input->post('versions')[$value['item_object_id']] : '';
                        // $versions_stage = !empty($this->input->post('versions_stage')[$value['item_object_id']]) ? $this->input->post('versions_stage')[$value['item_object_id']] : '';

                        $quantity_reserve = !empty($this->input->post('quantity_reserve')[$temp_str_object]) ? number_unformat($this->input->post('quantity_reserve')[$temp_str_object]) : 0;

                        $quantity_total_details = !empty($this->input->post('quantity')[$temp_str_object]) ? number_unformat($this->input->post('quantity')[$temp_str_object]) : 0;

                        $versions = !empty($this->input->post('versions')[$temp_str_object]) ? $this->input->post('versions')[$temp_str_object] : '';
                        $versions_stage = !empty($this->input->post('versions_stage')[$temp_str_object]) ? $this->input->post('versions_stage')[$temp_str_object] : '';

                        if (empty($versions)) continue;
                        $productions_plan_items = [
                            'productions_plan_id' => $productions_plan_id,
                            'type_object' => $value['type_object'],
                            'object_id' => $value['object_id'],
                            'item_object_id' => $value['item_object_id'],
                            'product_id' => $value['item_id'],
                            'quantity_minimum' => $value['quantity_minimum'],
                            'quantity_warehouses' => $value['quantity_warehouses'],
                            'status' => 'not',
                            'quantity_reserve' => $quantity_reserve,
                            'quantity_total_details' => $quantity_total_details,
                            'versions' => $versions,
                            'versions_stage' => $versions_stage,
                        ];

                        $productions_plan_item_id = $this->manufactures_model->insertProductionsPlanItems($productions_plan_items);
                        $quantityTemp = $quantity_total_details + $quantity_reserve;
                        $productions_plan_details = [];
                        $countDate = count($arr_date) - 1;
                        $indexTemp = 0;
                        foreach ($arr_date as $k => $val) {
                            if (empty($value[$val])) continue;
                            $quantityDate = $value[$val];
                            if ($quantityTemp < 0) break;

                            $quantityDefault = $quantityTemp;
                            $quantityTemp = $quantityTemp - $quantityDate;
                            $quantityPlanDetail = 0;
                            if ($quantityTemp >= 0) {
                                $quantityPlanDetail = $quantityDate;
                            } else if ($quantityTemp < 0) {
                                $quantityPlanDetail = abs($quantityDefault);
                            }
                            $productions_plan_details[$k]= [
                                'productions_plan_item_id' => $productions_plan_item_id,
                                'date' => $val,
                                'quantity' => $quantityPlanDetail
                            ];
                            $indexTemp = $k;
                        }

                        if ($quantityTemp > 0) {
                            $productions_plan_details[$indexTemp]['quantity'] = $productions_plan_details[$indexTemp]['quantity'] + $quantityTemp;
                        }

                        if (!empty($productions_plan_details)) {
                            foreach ($productions_plan_details as $kD => $vD) {
                                $this->manufactures_model->insertProductionsPlanDetails($vD);
                                $this->manufactures_model->updateQuantityPlanShippings($vD['quantity'], $plus = 0, $value['item_object_id'], $value['type_object'], $vD['date']);
                            }
                        }
                        $this->manufactures_model->updateQuantityPlan($quantity_total_details + $quantity_reserve, $plus = 0, $value['item_object_id'], $value['type_object']);
                    }

                    if (!empty($sales_orders_id)) {
                        foreach (explode(',', $sales_orders_id) as $key => $value) {
                            $isFinished = $this->manufactures_model->checkFinishedPlan($value, 'orders');
                            if (empty($isFinished)) {
                                $this->orders_model->updateOrdersNew($value, ['productions_plan_id' => 1]);
                            }
                        }
                    }
                    if (!empty($business_plan_id)) {
                        foreach (explode(',', $business_plan_id) as $key => $value) {
                            $isFinished = $this->manufactures_model->checkFinishedPlan($value, 'business_plan');
                            if (empty($isFinished)) {
                                $this->business_plan_model->updateBusinessPlan($value, ['productions_plan_id' => 1]);
                            }
                        }
                    }

                    //
                    if (!empty($arrItemsPerventive)) {
                        $rs_preventive = $this->manufactures_model->handlingPreventive($productions_plan_id, $arrItemsPerventive);
                        if (!empty($rs_preventive)) {
                            $arrProductionsPlanObject[] = [
                                'object_id' => $rs_preventive,
                                'object_type' => 'business_plan',
                                'is_preventive' => 1,
                            ];
                        }
                    }

                    if (!empty($arrProductionsPlanObject)){
                        foreach ($arrProductionsPlanObject as $key => $value) {
                            $arrProductionsPlanObject[$key]['productions_plan_id'] = $productions_plan_id;
                        }
                        $this->manufactures_model->insertBatchProductionsPlanObject($arrProductionsPlanObject);
                    }

                    //handling BOM
                    $this->manufactures_model->handlingBomProductionsPlan($productions_plan_id);

                    if ($options3) {
                        //create productions orders
                        $po_id = $this->manufactures_model->autoProductionsOrders($productions_plan_id);
                        $data['po_id'] = $po_id;
                    }

                    if (!empty($arrItemBOMCompensation)) {
                        foreach ($arrItemBOMCompensation as $key => $value) {
                            $arrItemBOMCompensation[$key]['productions_plan_id'] = $productions_plan_id;
                        }
                        $this->manufactures_model->insertBatchProductionsPlanCompensation($arrItemBOMCompensation);
                    }
                    
                    set_alert('success', lang('success'));
                    $data['result'] = 1;
                    $data['message'] = lang('success');
                    @pusherTNHNotfication();
                    insertActivityLog([
                        'type_parent_obj' => 'productions_plan',
                        'table_obj' => 'tbl_productions_plan',
                        'id_obj' => $productions_plan_id,
                        'name_obj' => $reference_no,
                        'content' => lang('tnh_his_add_productions_plan') . ' [' . $reference_no . ']',
                        'actions' => 'add'
                    ]);
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        }

        // print_arrays($_POST);
        $data['branch'] = $this->site_model->getBranch($arr_id_not = [BRANCH_DEFAULT]);
        $data['tnh'] = $this->tnh;
        $data['reference_no'] = getReference('productions_plan');
        $data['breadcrumb'] = [array('link' => base_url('admin/manufactures/productions_plan'), 'page' => lang('productions_plan')), array('link' => '#', 'page' => lang('tnh_add_productions_plan'))];
        $data['title'] = lang('tnh_add_productions_plan');
        $this->load->view('admin/manufactures/add_productions_plan', $data);
    }

    public function searchOrdersOfPlan($id = false)
    {
        $data = [];
        $term = $this->input->get('term', TRUE);
        $limit = get_option('select2_limit');
        $params = $this->input->get('params');
        $cOrders = $params['cOrders'];
        $planningCycle = $params['planningCycle'];
        $planningCycle = explode('-', trim($planningCycle));
        $dateStart = to_sql_date(trim($planningCycle[0]));
        $dateEnd = to_sql_date(trim($planningCycle[1]));

        if ($cOrders) {
            $data['results'] = $this->manufactures_model->searchOrdersByPlan($term, $limit, $dateStart, $dateEnd);
        } else {
            $data['results'] = false;
        }
        echo json_encode($data);
    }

