    public function show_table_productions_plan()
    {
        $planning_cycle = $this->input->get('planning_cycle');
        $options1 = $this->input->get('options1');
        $options2 = $this->input->get('options2');
        $orders = !empty($this->input->get('orders')[0]) ? $this->input->get('orders')[0] : null;
        $business_plans = !empty($this->input->get('business_plans')[0]) ? $this->input->get('business_plans')[0] : null;
        $data['orders'] = $orders;
        $data['business_plans'] = $business_plans;
        $safe_inventory = $this->input->get('safe_inventory');
        $flagChonse = false;
        if (!empty($business_plans) || !empty($orders)) {
            $flagChonse = true;
        }

        // if (empty($orders) && empty($business_plans)) {
        //     return '';
        // }

        $sales_orders = '';
        $business_plan = '';
        $arr_plan = [];
        $arr_date = [];
        $th = '';
        $targets = 6;
        $script = '';
        // print_arrays($this->input->get());

        if (!empty($planning_cycle)) {
            $arr_plan = explode('-', trim($planning_cycle));

            $date1 = to_sql_date(trim($arr_plan[0]));
            $date2 = to_sql_date(trim($arr_plan[1]));

            if ($options1 == true) {
                $whereOrder = '';
                if (!empty($orders) || $flagChonse) {
                    $orders = !empty($orders) ? str_replace(",", "','", $orders) : 0;
                    $whereOrder = " AND tbl_orders.id IN ('$orders')";
                }
                $query = "(
                    SELECT
                        GROUP_CONCAT(distinct(tbl_orders.reference_no) SEPARATOR ', ') as reference_orders
                    FROM tbl_orders
                    INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                    INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                    WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 $whereOrder
                )";
                $rs = $this->db->query($query)->row_array();
                $sales_orders = $rs['reference_orders'];
            }

            if ($options2 == true) {
                $whereBusinessPlan = '';
                if (!empty($business_plans) || $flagChonse) {
                    $business_plans = !empty($business_plans) ? str_replace(",", "','", $business_plans) : 0;
                    $whereBusinessPlan = " AND tbl_business_plan.id IN ('$business_plans')";
                }
                $query = "(
                    SELECT
                        GROUP_CONCAT(distinct(tbl_business_plan.reference_no) SEPARATOR ', ') as reference_no
                    FROM tbl_business_plan
                    INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                    INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                    WHERE tbl_business_plan.status = 'approved' AND tbl_business_plan.productions_plan_id = 0 AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' $whereBusinessPlan
                )";
                $rs = $this->db->query($query)->row_array();
                $business_plan = $rs['reference_no'];
            }

            $date1 = new DateTime($date1);
            $date2 = new DateTime($date2);

            $diff = $date1->diff($date2);
            $days = $diff->days;

            for ($i = 0; $i <= $days; $i++) {
                $plus_date = date('d/m/Y', strtotime(to_sql_date(trim($arr_plan[0])) . " + $i days"));

                $th .= '<th>' . $plus_date . '</th>';
                $script .= '{
                    "targets": ' . $targets . ', "name": "date' . $i . '", "className": "text-center",
                },';
                $targets++;
            }
        }
        $data['th'] = $th;
        $data['script'] = $script;
        $data['targets'] = $targets;
        $data['safe_inventory'] = $safe_inventory;
        $data['planning_cycle'] = $planning_cycle;
        $data['options1'] = $options1;
        $data['options2'] = $options2;
        $data['sales_orders'] = $sales_orders;
        $data['business_plan'] = $business_plan;
        $this->load->view('admin/manufactures/view_table_productions_plan', $data);
    }

    public function show_table_productions_plan_new()
    {
        $planning_cycle = $this->input->post('planning_cycle');
        $options1 = $this->input->post('options1');
        $options2 = $this->input->post('options2');
        $orders = !empty($this->input->post('orders')[0]) ? $this->input->post('orders')[0] : null;
        $business_plans = !empty($this->input->post('business_plans')[0]) ? $this->input->post('business_plans')[0] : null;
        $data['orders'] = $orders;
        $data['business_plans'] = $business_plans;

        $orders_items = !empty($this->input->post('orders_items')[0]) ? $this->input->post('orders_items')[0] : null;
        $business_plans_items = !empty($this->input->post('business_plans_items')[0]) ? $this->input->post('business_plans_items')[0] : null;
        $data['orders_items'] = $orders_items;
        $data['business_plans_items'] = $business_plans_items;

        $safe_inventory = $this->input->post('safe_inventory');
        $flagChonse = false;
        if (!empty($business_plans) || !empty($orders)) {
            $flagChonse = true;
        }

        $p_id_post = $this->input->post('p_id_post');
        $cs_id_post = $this->input->post('cs_id_post');
        $arrObjecOrderstId_post = $this->input->post('arrObjecOrderstId_post');
        $arrObjecBusinesstId_post = $this->input->post('arrObjecBusinesstId_post');

        $sales_orders = '';
        $business_plan = '';
        $arr_plan = [];
        $arr_date = [];
        $th = '';
        $targets = 9;
        $script = '';
        // print_arrays($this->input->get());

        if (!empty($planning_cycle)) {
            $arr_plan = explode('-', trim($planning_cycle));

            $date1 = to_sql_date(trim($arr_plan[0]));
            $date2 = to_sql_date(trim($arr_plan[1]));

            $queryOrder = "";
            $queryBusinessPlan = "";

            if ($options1 == true) {
                $whereOrder = '';
                if (!empty($orders) || $flagChonse) {
                    $orders = !empty($orders) ? str_replace(",", "','", $orders) : 0;
                    $whereOrder = " AND tbl_orders.id IN ('$orders')";
                }

                $whereOrder.= " AND tbl_orders.is_cancel = 0";
                if (!empty($p_id_post)) {
                    $whereOrder.= " AND tbl_order_items.item_id IN (".$p_id_post.")";
                }

                if (!empty($arrObjecOrderstId_post)) {
                    $whereOrder.= " AND tbl_order_items.order_id IN (".$arrObjecOrderstId_post.")";
                } else if (!empty($arrObjecBusinesstId_post)) {
                    $whereOrder.= " AND tbl_order_items.order_id IN (0)";
                }

                $slKeep = "COALESCE((
                    SELECT SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
                    FROM tbltransfer_warehouse_detail
                    WHERE tbltransfer_warehouse_detail.order_id_item = tbl_order_items.id AND tbltransfer_warehouse_detail.tranfer_business_item_id = 0
                ), 0)";

                $keepTranferBusinessItem = 'COALESCE((
                    SELECT
                        SUM(tbl_tranfer_business_item.quantity) as quantity
                    FROM tbl_tranfer_business_item
                    WHERE tbl_tranfer_business_item.order_item_id = tbl_order_items.id
                ), 0)';

                $query = "(
                    SELECT
                        GROUP_CONCAT(distinct(tbl_orders.reference_no) SEPARATOR ', ') as reference_orders
                    FROM tbl_orders
                    INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                    INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                    INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                    WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep) - $keepTranferBusinessItem) > tbl_order_item_shippings.quantity_plan_item $whereOrder
                )";

                $rs = $this->db->query($query)->row_array();
                $sales_orders = $rs['reference_orders'];

                if (!empty($sales_orders)) {
                    // $queryOrder = "
                    // SELECT tbl_order_item_shippings.date_shipping as date_delivery
                    // FROM tbl_orders
                    // INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                    // INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                    // WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND tbl_order_item_shippings.quantity_plan_item = 0 AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item $whereOrder
                    // ";
                    $queryOrder = "
                    SELECT tbl_order_item_shippings.date_shipping as date_delivery
                    FROM tbl_orders
                    INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                    INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                    INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                    WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep)) > tbl_order_item_shippings.quantity_plan_item $whereOrder
                    ";
                }
            }

            if ($options2 == true) {
                $whereBusinessPlan = '';
                if (!empty($business_plans) || $flagChonse) {
                    $business_plans = !empty($business_plans) ? str_replace(",", "','", $business_plans) : 0;
                    $whereBusinessPlan = " AND tbl_business_plan.id IN ('$business_plans')";
                }

                if (!empty($p_id_post)) {
                    $whereBusinessPlan.= " AND tbl_business_plan_items.items_id IN (".$p_id_post.")";
                }

                if (!empty($arrObjecBusinesstId_post)) {
                    $whereBusinessPlan.= " AND tbl_business_plan_items.business_plan_id IN (".$arrObjecBusinesstId_post.")";
                } else if (!empty($arrObjecOrderstId_post)) {
                    $whereBusinessPlan.= " AND tbl_business_plan_items.business_plan_id IN (0)";
                }

                $query = "(
                    SELECT
                        GROUP_CONCAT(distinct(tbl_business_plan.reference_no) SEPARATOR ', ') as reference_no
                    FROM tbl_business_plan
                    INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                    INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                    WHERE tbl_business_plan.status = 'approved' AND tbl_business_plan.productions_plan_id = 0 AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item $whereBusinessPlan
                )";
                $rs = $this->db->query($query)->row_array();
                $business_plan = $rs['reference_no'];

                if (!empty($business_plan)) {
                    $queryBusinessPlan = "
                    SELECT tbl_business_plan_items_date.date as date_delivery
                    FROM tbl_business_plan
                    INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                    INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                    WHERE tbl_business_plan.status = 'approved' AND tbl_business_plan.productions_plan_id = 0 AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item $whereBusinessPlan
                    ";
                }
            }

            $whereUnion = '';
            if (!empty($queryOrder) && !empty($business_plan)) {
                $whereUnion = "UNION ALL";
            }

            $queryGetDate = "(
            SELECT cs.date_delivery
            FROM (
                    $queryOrder
                    $whereUnion
                    $queryBusinessPlan
                ) as cs
            GROUP BY cs.date_delivery
            ) ";

            if (!empty($queryOrder) || !empty($business_plan)) {
                $resultDate = $this->db->query($queryGetDate)->result_array();
            }

            if (!empty($resultDate)) {
                foreach ($resultDate as $k => $val) {
                    $th .= '<th>' . _d($val['date_delivery']) . '</th>';
                    $script .= '{
                        "render":function(data, type, row) {
                            if(data == 0) return "";
                            return \'<div class="text-center">\'+tnhFormatNumber(data)+\'</div>\';
                        },
                       "targets": ' . $targets . ', "name": "date' . $k . '", "className": "text-center", "visible": false
                   },';
                    $targets++;
                }
            }
        }
        $data['th'] = $th;
        $data['script'] = $script;
        $data['targets'] = $targets;
        $data['safe_inventory'] = $safe_inventory;
        $data['planning_cycle'] = $planning_cycle;
        $data['options1'] = $options1;
        $data['options2'] = $options2;
        $data['sales_orders'] = $sales_orders;
        $data['business_plan'] = $business_plan;
        $data['p_id_post'] = $p_id_post;
        $data['arrObjecOrderstId_post'] = $arrObjecOrderstId_post;
        $data['arrObjecBusinesstId_post'] = $arrObjecBusinesstId_post;
        $this->load->view('admin/manufactures/view_table_productions_plan_new', $data);
    }

    public function getShowTableProductionsPlan()
    {
        $condition_safe_inventory = $this->input->post('condition_safe_inventory');
        $condition_planning_cycle = $this->input->post('condition_planning_cycle');
        $condition_options1 = $this->input->post('condition_options1');
        $condition_options2 = $this->input->post('condition_options2');
        $orders = !empty($this->input->post('condition_orders')) ? $this->input->post('condition_orders') : null;
        $business_plans = !empty($this->input->post('condition_business_plans')) ? $this->input->post('condition_business_plans') : null;
        $flagChonse = false;
        if (!empty($business_plans) || !empty($orders)) {
            $flagChonse = true;
        }

        $select_custom_fields = "";
        $where_custom_fields = "";
        $custom = [];
        $custom_select = [];
        $target = 6;
        if (!empty($condition_planning_cycle)) {
            $arr_plan = explode('-', trim($condition_planning_cycle));
            $date1 = to_sql_date(trim($arr_plan[0]));
            $date2 = to_sql_date(trim($arr_plan[1]));

            $date1 = new DateTime($date1);
            $date2 = new DateTime($date2);

            $diff = $date1->diff($date2);
            $days = $diff->days;

            for ($i = 0; $i <= $days; $i++) {
                $date = date('Y-m-d', strtotime(to_sql_date(trim($arr_plan[0])) . " + $i days"));
                $select = " 0  ";
                $flag = false;
                if ($condition_options1 == 1) {
                    $flag = true;
                    $whereOrder = '';
                    if (!empty($orders) || $flagChonse) {
                        $orders = !empty($orders) ? str_replace(",", "','", $orders) : 0;
                        $whereOrder = " AND tbl_orders.id IN ('$orders')";
                    }

                    $select = "COALESCE((
                        SELECT
                            SUM(tbl_order_item_shippings.quantity_shipping)
                        FROM tbl_orders
                        INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                        INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                        WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') = '$date' AND tbl_order_items.type_item = 'products' AND tbl_order_items.item_id = tbl_products.id AND tbl_orders.productions_plan_id = 0 $whereOrder
                    ), 0)";
                }
                if ($condition_options2 == 1) {
                    $flag = true;
                    $whereBusinessPlan = '';
                    if (!empty($business_plans) || $flagChonse) {
                        $business_plans = !empty($business_plans) ? str_replace(",", "','", $business_plans) : 0;
                        $whereBusinessPlan = " AND tbl_business_plan.id IN ('$business_plans')";
                    }

                    $bus = "COALESCE((
                        SELECT
                            SUM(tbl_business_plan_items_date.quantity)
                        FROM tbl_business_plan
                        INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                        INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                        WHERE tbl_business_plan.status = 'approved' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') = '$date' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items.items_id = tbl_products.id AND tbl_business_plan.productions_plan_id = 0 $whereBusinessPlan
                    ), 0)";
                    $select .= " + $bus ";
                }
                $select_custom_fields .= ", " . $select . " as date" . $i;
                if ($flag) {
                    $where_custom_fields .= $select . ' > 0 OR ';
                }
                $custom[] = [
                    'index' => $target,
                    'select' => "date" . $i,
                ];
                $custom_select[$target] = $select;
                $target++;
            }
        }

        // print_arrays($this->input->post());

        $warehouses = "(
            SELECT
                tblwarehouse_items.id_items,
                SUM(tblwarehouse_items.product_quantity) as quantity_warehouses
            FROM tblwarehouse_items
            WHERE tblwarehouse_items.type_items = 'product'
            GROUP BY tblwarehouse_items.id_items
        ) warehouses";

        $this->datatables->select("
            0 as number_records,
            tbl_products.code as product_code,
            tbl_products.name as product_name,
            tblunits.unit as unit,
            tbl_products.quantity_minimum as quantity_minimum,
            COALESCE(warehouses.quantity_warehouses, 0) as quantity_warehouses
            $select_custom_fields
            ", FALSE)
            ->from('tbl_products')
            ->join('tblunits', 'tblunits.unitid = tbl_products.unit_id', 'left')
            ->join($warehouses, 'warehouses.id_items = tbl_products.id', 'left');

        if ($condition_safe_inventory) {
            $this->datatables->where('tbl_products.quantity_minimum >', 0);
        }

        if (!empty($where_custom_fields)) {
            $where_custom_fields = trim($where_custom_fields);
            $where_custom_fields = substr($where_custom_fields, 0, -2);
            $this->datatables->where("( $where_custom_fields )");
        }
        // print_arrays($this->db->get_compiled_select('tbl_products'), FALSE);
        $this->datatables->custom_ordering($custom);
        $this->datatables->custom_select($custom_select);

        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;
        }
        echo json_encode($data);
    }

    public function getShowTableProductionsPlanNew()
    {
        $condition_safe_inventory = $this->input->post('condition_safe_inventory');
        $condition_planning_cycle = $this->input->post('condition_planning_cycle');
        $condition_options1 = $this->input->post('condition_options1');
        $condition_options2 = $this->input->post('condition_options2');
        $orders = !empty($this->input->post('condition_orders')) ? $this->input->post('condition_orders') : null;
        $business_plans = !empty($this->input->post('condition_business_plans')) ? $this->input->post('condition_business_plans') : null;
        $orders_items = !empty($this->input->post('condition_orders_items')) ? $this->input->post('condition_orders_items') : null;
        $business_plans_items = !empty($this->input->post('condition_business_plans_items')) ? $this->input->post('condition_business_plans_items') : null;
        $condition_remove_item = !empty($this->input->post('condition_remove_item')) ? $this->input->post('condition_remove_item') : null;
        $condition_p_id_post = $this->input->post('condition_p_id_post');
        $condition_arrObjecOrderstId_post = $this->input->post('condition_arrObjecOrderstId_post');
        $condition_arrObjecBusinesstId_post = $this->input->post('condition_arrObjecBusinesstId_post');

        $arrRemoveOrdersItemId = [];
        $arrRemoveBusinessItemId = [];

        if (!empty($condition_remove_item)) {
            $condition_remove_item = explode('|||', $condition_remove_item);
            foreach ($condition_remove_item as $key => $value) {
                $value = explode('___', $value);
                if ($value[0] == 'orders') {
                    array_push($arrRemoveOrdersItemId, $value[1]);
                } else if ($value[0] == 'business_plan') {
                    array_push($arrRemoveBusinessItemId, $value[1]);
                }
            }
        }

        $flagChonse = false;
        if (!empty($business_plans) || !empty($orders)) {
            $flagChonse = true;
        }


        if (empty($condition_options1) && empty($condition_options2)) {
            return '';
        }

        $select_custom_fields = "";
        $where_custom_fields = "";
        $custom = [];
        $custom_select = [];
        $target = 9;

        if (!empty($condition_planning_cycle)) {
            $arr_plan = explode('-', trim($condition_planning_cycle));
            $date1 = to_sql_date(trim($arr_plan[0]));
            $date2 = to_sql_date(trim($arr_plan[1]));



            $queryOrder = "";
            $queryBusinessPlan = "";

            $queryOrderData = "";
            $queryBusinessPlanData = "";

            $selectQueryOrder = '';
            $selectQueryBusiness = '';

            $whereOrders = '';
            $whereBusinessPlan = '';
            if (!empty($condition_p_id_post)) {
                $whereOrders.= ' AND tbl_order_items.item_id IN ('.$condition_p_id_post.')';
                $whereBusinessPlan.= ' AND tbl_business_plan_items.items_id IN ('.$condition_p_id_post.')';
            }

            if (!empty($condition_arrObjecOrderstId_post)) {
                $whereOrders.= " AND tbl_order_items.order_id IN (".$condition_arrObjecOrderstId_post.")";
            } else if (!empty($condition_arrObjecBusinesstId_post)) {
                $whereOrders.= " AND tbl_order_items.order_id IN (0)";
            }

            if (!empty($condition_arrObjecBusinesstId_post)) {
                $whereBusinessPlan.= " AND tbl_business_plan_items.business_plan_id IN (".$condition_arrObjecBusinesstId_post.")";
            } else if (!empty($condition_arrObjecOrderstId_post)) {
                $whereBusinessPlan.= " AND tbl_business_plan_items.business_plan_id IN (0)";
            }

            $slKeep = "COALESCE((
                SELECT SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
                FROM tbltransfer_warehouse_detail
                WHERE tbltransfer_warehouse_detail.order_id_item = tbl_order_items.id AND tbltransfer_warehouse_detail.tranfer_business_item_id = 0
            ), 0)";

            $keepTranferBusinessItem = 'COALESCE((
                SELECT
                    SUM(tbl_tranfer_business_item.quantity) as quantity
                FROM tbl_tranfer_business_item
                WHERE tbl_tranfer_business_item.order_item_id = tbl_order_items.id
            ), 0)';

            // $selectQueryOrder = "(
            //     SELECT
            //         SUM(tbl_order_item_shippings.quantity_shipping - tbl_order_item_shippings.quantity_plan_item) as quantity_shipping
            //     FROM tbl_order_items
            //     INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
            //     WHERE DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item AND tbl_order_items.id = od.item_object_id
            // )";

            $selectQueryOrder = "(
                SELECT 
                    SUM((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - tbl_order_item_shippings.quantity_plan_item - ($slKeep) - $keepTranferBusinessItem) as quantity_shipping
                FROM tbl_order_items
                INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                WHERE DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep) - $keepTranferBusinessItem) > tbl_order_item_shippings.quantity_plan_item AND tbl_order_items.id = od.item_object_id $whereOrders
            )";

            // $selectQueryBusiness = "(
            //     SELECT
            //         SUM(tbl_business_plan_items_date.quantity - tbl_business_plan_items_date.quantity_plan_item) as quantity_shipping
            //     FROM tbl_business_plan_items
            //     INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
            //     WHERE DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item AND tbl_business_plan_items.id = od.item_object_id
            // )";

            $selectQueryBusiness = "(
                SELECT 
                    SUM(tbl_business_plan_items_date.quantity - tbl_business_plan_items_date.quantity_plan_item) as quantity_shipping
                FROM tbl_business_plan_items
                INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                WHERE DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item AND tbl_business_plan_items.id = od.item_object_id $whereBusinessPlan
            )";

            $selectTotalQuantity = "(IF(od.type_object = 'orders', $selectQueryOrder, IF(od.type_object = 'business_plan', $selectQueryBusiness, 0)))";

            //
            // $selectQueryOrderGroup = "(
            //     SELECT
            //         GROUP_CONCAT(CONCAT(DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%d/%m/%Y'), ' - ', tbl_order_item_shippings.quantity_shipping - tbl_order_item_shippings.quantity_plan_item) SEPARATOR ', ')
            //     FROM tbl_order_items
            //     INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
            //     WHERE DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item AND tbl_order_items.id = od.item_object_id
            // )";

            $selectQueryOrderGroup = "(
                SELECT 
                    GROUP_CONCAT(CONCAT(DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%d/%m/%Y'), ' - ', (tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - tbl_order_item_shippings.quantity_plan_item - ($slKeep) - $keepTranferBusinessItem) SEPARATOR ', ')
                FROM tbl_order_items
                INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                WHERE DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep) - $keepTranferBusinessItem) > tbl_order_item_shippings.quantity_plan_item AND tbl_order_items.id = od.item_object_id $whereOrders
            )";

            // $selectQueryBusinessGroup = "(
            //     SELECT
            //         GROUP_CONCAT(CONCAT(DATE_FORMAT(tbl_business_plan_items_date.date, '%d/%m/%Y'), ' - ', tbl_business_plan_items_date.quantity - tbl_business_plan_items_date.quantity_plan_item) SEPARATOR ', ')
            //     FROM tbl_business_plan_items
            //     INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
            //     WHERE DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item AND tbl_business_plan_items.id = od.item_object_id
            // )";

            $selectQueryBusinessGroup = "(
                SELECT 
                    GROUP_CONCAT(CONCAT(DATE_FORMAT(tbl_business_plan_items_date.date, '%d/%m/%Y'), ' - ', tbl_business_plan_items_date.quantity - tbl_business_plan_items_date.quantity_plan_item) SEPARATOR ', ')
                FROM tbl_business_plan_items
                INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                WHERE DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item AND tbl_business_plan_items.id = od.item_object_id $whereBusinessPlan
            )";

            $selectTotalQuantityGroup = "(IF(od.type_object = 'orders', $selectQueryOrderGroup, IF(od.type_object = 'business_plan', $selectQueryBusinessGroup, 0)))";


            if ($condition_options1 == true) {
                $whereOrder = '';
                if (!empty($orders) || $flagChonse) {
                    $orders = !empty($orders) ? str_replace(",", "','", $orders) : 0;
                    $whereOrder = " AND tbl_orders.id IN ('$orders')";
                }

                $whereOrder .= " AND tbl_orders.is_cancel = 0";
                if (!empty($orders_items)) {
                    $orders_items = !empty($orders_items) ? str_replace(",", "','", $orders_items) : 0;
                    $whereOrder .= " AND tbl_order_items.id IN ('$orders_items')";
                }

                if (!empty($arrRemoveOrdersItemId)) {
                    $arrRemoveOrdersItemId = !empty($arrRemoveOrdersItemId) ? str_replace(",", "','", implode(',', $arrRemoveOrdersItemId)) : 0;
                    $whereOrder .= " AND tbl_order_items.id NOT IN ('$arrRemoveOrdersItemId')";
                }

                if (!empty($condition_p_id_post)) {
                    $whereOrder.= ' AND tbl_order_items.item_id IN ('.$condition_p_id_post.')';
                }

                if (!empty($condition_arrObjecOrderstId_post)) {
                    $whereOrder.= " AND tbl_order_items.order_id IN (".$condition_arrObjecOrderstId_post.")";
                } else if (!empty($condition_arrObjecBusinesstId_post)) {
                    $whereOrder.= " AND tbl_order_items.order_id IN (0)";
                }

                // $queryOrder = "
                // SELECT tbl_order_item_shippings.date_shipping as date_delivery
                // FROM tbl_orders
                // INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                // INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                // WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item $whereOrder
                // ";

                $queryOrder = "
                SELECT tbl_order_item_shippings.date_shipping as date_delivery
                FROM tbl_orders
                INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep) - $keepTranferBusinessItem) > tbl_order_item_shippings.quantity_plan_item $whereOrder
                ";

                // $queryOrderData = "
                //     SELECT
                //         'orders' as type_object,
                //         tbl_orders.reference_no as reference_no,
                //         tbl_order_items.id as item_object_id,
                //         tbl_order_items.item_id as item_id
                //     FROM tbl_orders
                //     INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                //     INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                //     WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item $whereOrder
                //     GROUP BY tbl_order_items.id
                // ";

                $queryOrderData = "
                    SELECT
                        'orders' as type_object,
                        tbl_orders.reference_no as reference_no,
                        tbl_order_items.id as item_object_id,
                        tbl_order_items.item_id as item_id
                    FROM tbl_orders
                    INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                    INNER JOIN tbl_products ON tbl_products.id = tbl_order_items.item_id
                    INNER JOIN tbl_order_item_shippings ON tbl_order_item_shippings.order_item_id = tbl_order_items.id
                    WHERE tbl_orders.status = 'approved' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$date2' AND tbl_order_items.type_item = 'products' AND tbl_orders.productions_plan_id = 0 AND ((tbl_order_item_shippings.quantity_shipping * IF (tbl_products.unit_id = tbl_order_items.unit_id, tbl_products.conversion_quantity_unit, 1)) - ($slKeep) - $keepTranferBusinessItem) > tbl_order_item_shippings.quantity_plan_item $whereOrder
                    GROUP BY tbl_order_items.id
                ";
            }

            if ($condition_options2 == true) {
                $whereBusinessPlan = '';
                if (!empty($business_plans) || $flagChonse) {
                    $business_plans = !empty($business_plans) ? str_replace(",", "','", $business_plans) : 0;
                    $whereBusinessPlan = " AND tbl_business_plan.id IN ('$business_plans')";
                }

                if (!empty($business_plans_items)) {
                    $business_plans_items = !empty($business_plans_items) ? str_replace(",", "','", $business_plans_items) : 0;
                    $whereBusinessPlan .= " AND tbl_business_plan_items.id IN ('$business_plans_items')";
                }

                if (!empty($arrRemoveBusinessItemId)) {
                    $arrRemoveBusinessItemId = !empty($arrRemoveBusinessItemId) ? str_replace(",", "','", implode(',', $arrRemoveBusinessItemId)) : 0;
                    $whereBusinessPlan .= " AND tbl_business_plan_items.id NOT IN ('$arrRemoveBusinessItemId')";
                }

                if (!empty($condition_p_id_post)) {
                    $whereBusinessPlan.= ' AND tbl_business_plan_items.items_id IN ('.$condition_p_id_post.')';
                }

                if (!empty($condition_arrObjecBusinesstId_post)) {
                    $whereBusinessPlan.= " AND tbl_business_plan_items.business_plan_id IN (".$condition_arrObjecBusinesstId_post.")";
                }  else if (!empty($condition_arrObjecOrderstId_post)) {
                    $whereBusinessPlan.= " AND tbl_business_plan_items.business_plan_id IN (0)";
                }

                $queryBusinessPlan = "
                SELECT tbl_business_plan_items_date.date as date_delivery
                FROM tbl_business_plan
                INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                WHERE tbl_business_plan.status = 'approved' AND tbl_business_plan.productions_plan_id = 0 AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item $whereBusinessPlan
                ";

                $queryBusinessPlanData = "
                SELECT
                    'business_plan' as type_object,
                    tbl_business_plan.reference_no as reference_no,
                    tbl_business_plan_items.id as item_object_id,
                    tbl_business_plan_items.items_id as item_id
                FROM tbl_business_plan
                INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id
                WHERE tbl_business_plan.status = 'approved' AND tbl_business_plan.productions_plan_id = 0 AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$date1' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$date2' AND tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item $whereBusinessPlan
                GROUP BY tbl_business_plan_items.id
                ";
            }
        }
        $whereUnion = '';
        if (!empty($queryOrder) && !empty($queryBusinessPlan)) {
            $whereUnion = "UNION ALL";
        }

        $queryGetDate = "(
        SELECT cs.date_delivery
        FROM (
                $queryOrder
                $whereUnion
                $queryBusinessPlan
            ) as cs
        GROUP BY cs.date_delivery
        ) ";

        // print_arrays($queryGetDate);

        $resultDate = $this->db->query($queryGetDate)->result_array();
        $selectQuantityTotal = '';
        if (!empty($resultDate)) {
            foreach ($resultDate as $k => $val) {
                $date = $val['date_delivery'];
                $selectOrderQuantity = "
                    COALESCE((
                        SELECT
                            SUM(tbl_order_item_shippings.quantity_shipping - tbl_order_item_shippings.quantity_plan_item)
                        FROM tbl_order_item_shippings
                        WHERE tbl_order_item_shippings.order_item_id = od.item_object_id AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') = '$date' AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item
                    ), 0)
                ";

                $selectBusinessPlanQuantity = "
                    COALESCE((
                        SELECT
                            SUM(tbl_business_plan_items_date.quantity - tbl_business_plan_items_date.quantity_plan_item)
                        FROM tbl_business_plan_items_date
                        WHERE tbl_business_plan_items_date.business_plan_items_id = od.item_object_id AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') = '$date' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item
                    ), 0)
                ";

                $select = "(IF(od.type_object = 'orders', $selectOrderQuantity, IF(od.type_object = 'business_plan', $selectBusinessPlanQuantity, 0)))";

                // $select = 0;
                $select_custom_fields .= ", " . $select . " as date" . $k;
                $custom[] = [
                    'index' => $target,
                    'select' => "date" . $k,
                ];
                $custom_select[$target] = $select;
                $target++;
            }
        }

        $tableOrdersDelivery = "(
            $queryOrderData
            $whereUnion
            $queryBusinessPlanData
        ) as od";

        // print_arrays($tableOrdersDelivery);

        $warehouses = "(
            SELECT
                tblwarehouse_items.id_items,
                SUM(tblwarehouse_items.product_quantity) as quantity_warehouses
            FROM tblwarehouse_items
            INNER JOIN tbllocaltion_warehouses ON tbllocaltion_warehouses.id = tblwarehouse_items.localtion
            WHERE tblwarehouse_items.type_items = 'product' AND tblwarehouse_items.warehouse_id NOT IN (".WAREHOUSES_CAPACITY.", ".WAREHOUSES_HOLD.") AND tbllocaltion_warehouses.stage_id = 0 AND (
                tbllocaltion_warehouses.pod_id = 0 OR exists (
                    SELECT tbl_productions_orders_details.id
                    FROM tbl_productions_orders_details
                    WHERE tbl_productions_orders_details.id = tbllocaltion_warehouses.pod_id AND tbl_productions_orders_details.object_type = 'business_plan'
                )
            )
            GROUP BY tblwarehouse_items.id_items
        ) warehouses";

        // $select_custom_fields,
        $this->datatables->select("
            tbl_products.id as number_records,
            od.reference_no as reference_no,
            CONCAT(tbl_products.name, '(', tbl_products.code, ')') as product_code,
            tbl_products.versions as versions,
            tbl_products.versions_stage as versions_stage,
            tblunits.unit as unit,
            tbl_products.quantity_minimum as quantity_minimum,
            COALESCE(warehouses.quantity_warehouses, 0) as quantity_warehouses,
            $selectTotalQuantity as quantity,
            CONCAT(od.item_object_id) as quantity_reserve,
            od.type_object as type_object,
            od.item_object_id as item_object_id,
            $selectTotalQuantityGroup as group_quantity,
            '' as actions,
        ", false)
            ->from('(SELECT 1 as id) cs')
            ->join($tableOrdersDelivery, 'od.item_object_id > 0')
            ->join('tbl_products', 'tbl_products.id = od.item_id', 'left')
            ->join('tblunits', 'tblunits.unitid = tbl_products.conversion_unit', 'left')
            ->join($warehouses, 'warehouses.id_items = tbl_products.id', 'left');

        if ($condition_safe_inventory) {
            $this->datatables->where('tbl_products.quantity_minimum >', 0);
        }
        
        $this->datatables->custom_ordering($custom);
        $this->datatables->custom_select($custom_select);
        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;
            $products_id = $value[0];
            $versions = $value[3];

            $this->db->select('tbl_product_versions.versions as versions');
            $this->db->from('tbl_product_versions');
            $this->db->where('tbl_product_versions.product_id', $products_id);
            $product_verions = $this->db->get()->result_array();
            $optionsVersions = "<option></option>";
            if (!empty($product_verions)) {
                foreach ($product_verions as $k => $val) {
                    $selected = ($versions == $val['versions']) ? 'selected' : '';
                    $optionsVersions.= '<option '.$selected.' value="'.$val['versions'].'">'.$val['versions'].'</option>';
                }
            }
            $data->aaData[$key][3] = $optionsVersions;

            //stages
            $versions_stage = $value[4];
            $this->db->select('tbl_product_stages.versions as versions');
            $this->db->from('tbl_product_stages');
            $this->db->where('tbl_product_stages.product_id', $products_id);
            $product_verions_stages = $this->db->get()->result_array();
            $optionsVersionsStages = "<option></option>";
            if (!empty($product_verions_stages)) {
                foreach ($product_verions_stages as $k => $val) {
                    $selected = ($versions_stage == $val['versions']) ? 'selected' : '';
                    $optionsVersionsStages.= '<option '.$selected.' value="'.$val['versions'].'">'.$val['versions'].'</option>';
                }
            }
            $data->aaData[$key][4] = $optionsVersionsStages;

            $actions = '
                <div class="text-center">
                    <input type="hidden" name="poduct_id_css['.$value[10].'___'.$value[11].']" class="form-control poduct_id_css" value="'.$products_id.'">
                    <input type="hidden" name="cs_product_id[]" class="form-control cs_product_id" value="'.$products_id.'">
                    <a href="javascript:void(0)" class="fa fa-pencil text-primary" title="Chỉnh sửa BOM" onclick="clickBom(this, '.$products_id.')"></a>
                    <a href="javascript:void(0)" onclick="removeProductionsPlan(this)" class="fa fa-remove text-danger"></a>
                </div>
            ';
            $data->aaData[$key][13] = $actions;
        }
        echo json_encode($data);
    }

    public function getProductionsPlan()
    {
        if (!$this->perViewProductionsPlan && !$this->perViewOwnProductionsPlan) {
            accessDenied($js = true);
        }

        $branch_staff = get_array_branch_staff();
        $is_admin = is_admin();

        $orders_search = $this->input->post('orders_search');
        $business_plan_search = $this->input->post('business_plan_search');
        $start_date = $this->input->post('start_date');
        $end_date = $this->input->post('end_date');
        $status_table = $this->input->post('status_table');
        $productions_orders_search = $this->input->post('productions_orders_search');

        $order = "(
            SELECT CONCAT(tbl_orders.reference_no, '(', tbl_orders.customer_name, ')')
            FROM tbl_orders
            WHERE tbl_orders.id = tbl_productions_plan_items.object_id
        )";

        $business = "(
            SELECT CONCAT(tbl_business_plan.reference_no, ' (', tbl_business_plan.plan_name, ')')
            FROM tbl_business_plan
            WHERE tbl_business_plan.id = tbl_productions_plan_items.object_id
        )";

        $pb = "(
            SELECT GROUP_CONCAT(DISTINCT(IF(tbl_productions_plan_items.type_object = 'orders', $order, $business)) SEPARATOR 'custom')
            FROM tbl_productions_plan_items
            WHERE tbl_productions_plan_items.productions_plan_id = tbl_productions_plan.id AND tbl_productions_plan_items.object_id > 0
        )";

        $wherePB = "(
            SELECT count(*)
            FROM tbl_productions_plan_items
            WHERE tbl_productions_plan_items.productions_plan_id = tbl_productions_plan.id AND tbl_productions_plan_items.object_id > 0 str_replace
            LIMIT 1
        )";

        $planPattern = "(
            SELECT CONCAT(COALESCE(pp.options1_reference_no, ''), '</br>', COALESCE(pp.options2_reference_no, ''))
            FROM tbl_productions_plan as pp
            WHERE pp.id = tbl_productions_plan.pattern_id
        )";

        $tbTransfer = "(
            SELECT
                tbltransfer_warehouse.productions_capacity_id as productions_capacity_id,
                COUNT(tbltransfer_warehouse.id) as ct_transfer_warehouse
            FROM tbltransfer_warehouse
            GROUP BY tbltransfer_warehouse.productions_capacity_id
        ) tb_transfer";

        $tbPurchases = "(
            SELECT
                tblpurchases.id_plan as id_plan,
                COUNT(tblpurchases.id) as ct_purchases
            FROM tblpurchases
            GROUP BY tblpurchases.id_plan
        ) tb_purchases";

        $tbProductionsOrders = "(
            SELECT
                tbl_productions_orders_items.plan_id as plan_id,
                GROUP_CONCAT(distinct tbl_productions_orders.reference_no) as reference_no
            FROM tbl_productions_orders_items
            INNER JOIN tbl_productions_orders ON tbl_productions_orders.id = tbl_productions_orders_items.productions_orders_id
            GROUP BY tbl_productions_orders_items.plan_id
        ) tb_productions_orders";

        $tbOrdersItemsShipping = "(
            SELECT
                tbl_order_item_shippings.order_item_id as order_item_id,
                GROUP_CONCAT(CONCAT(tbl_orders.reference_no,'___',tbl_order_item_shippings.date_shipping)) as date_shipping
            FROM tbl_order_item_shippings
            JOIN tbl_order_items ON tbl_order_items.id = tbl_order_item_shippings.order_item_id
            JOIN tbl_orders ON tbl_orders.id = tbl_order_items.order_id
            GROUP BY tbl_order_item_shippings.order_item_id
        ) tb_orders_items_shipping";

        $tbBusinessItemsShipping = "(
            SELECT
                tbl_business_plan_items_date.business_plan_items_id as business_plan_items_id,
                GROUP_CONCAT(CONCAT(tbl_business_plan.reference_no,'___',tbl_business_plan_items_date.date, '___', tbl_business_plan.productions_plan_preventive_id)) as date_shipping
            FROM tbl_business_plan_items_date
            JOIN tbl_business_plan_items ON tbl_business_plan_items.id = tbl_business_plan_items_date.business_plan_items_id
            JOIN tbl_business_plan ON tbl_business_plan.id = tbl_business_plan_items.business_plan_id
            GROUP BY tbl_business_plan_items_date.business_plan_items_id
        ) tb_business_items_shipping";

        $tbDateDelivery = "(
            SELECT
                tbl_productions_plan_items.productions_plan_id as plan_id,
                GROUP_CONCAT(tb_orders_items_shipping.date_shipping) as date_order,
                GROUP_CONCAT(tb_business_items_shipping.date_shipping) as date_business
            FROM tbl_productions_plan_items
            LEFT JOIN $tbOrdersItemsShipping ON tb_orders_items_shipping.order_item_id = tbl_productions_plan_items.item_object_id AND tbl_productions_plan_items.type_object = 'orders'
            LEFT JOIN $tbBusinessItemsShipping ON tb_business_items_shipping.business_plan_items_id = tbl_productions_plan_items.item_object_id AND tbl_productions_plan_items.type_object = 'business_plan'
            GROUP BY tbl_productions_plan_items.productions_plan_id
        ) tb_date_delivery";

        $tbTransferBusiness = "(
            SELECT
                tbl_tranfer_business.id_plan as id_plan,
                COUNT(tbl_tranfer_business.id) as ct_transfer_tp
            FROM tbl_tranfer_business
            GROUP BY tbl_tranfer_business.id_plan
        ) tb_transfer_business";

        // tb_productions_orders.reference_no as productions_orders,
        $this->datatables->select("
            tbl_productions_plan.id as id,
            0 as number_records,
            tbl_productions_plan.date as date,
            CONCAT(tbl_productions_plan.reference_no, '___', tblbranch.name) as reference_no,
            '' as productions_orders,
            '' as date_delivery,
            CONCAT(DATE_FORMAT(tbl_productions_plan.date_start, '%d/%m/%Y'), ' - ', DATE_FORMAT(tbl_productions_plan.date_end, '%d/%m/%Y'), '') as planning_cycle,
            IF(tbl_productions_plan.pattern_id > 0, $planPattern, $pb) as pb,
            CONCAT(tbl_productions_plan.options1, '-', tbl_productions_plan.options2, '') as options,
            CONCAT(COALESCE(tb_transfer.ct_transfer_warehouse, 0), '__', COALESCE(tb_purchases.ct_purchases, 0), '__',COALESCE(tb_transfer_business.ct_transfer_tp, 0)) as status,
            tbl_productions_plan.note as note,
            '' as items,
            '' as status_manufactures,
            ", FALSE)
            ->from('tbl_productions_plan')
            ->join('tblbranch', 'tblbranch.id = tbl_productions_plan.id_branch', 'inner')
            ->join($tbTransfer, 'tb_transfer.productions_capacity_id = tbl_productions_plan.id', 'left')
            ->join($tbPurchases, 'tb_purchases.id_plan = tbl_productions_plan.id', 'left')
            ->join($tbTransferBusiness, 'tb_transfer_business.id_plan = tbl_productions_plan.id', 'left');
            // ->join($tbProductionsOrders, 'tb_productions_orders.plan_id = tbl_productions_plan.id', 'left');
            // ->join($tbDateDelivery, 'tb_date_delivery.plan_id = tbl_productions_plan.id', 'left');

        if ($status_table) {
            if ($status_table == "ycmh") {
                $this->datatables->where('tb_purchases.ct_purchases >', 0);
            } else if ($status_table == "keep") {
                $this->datatables->where('tb_transfer.ct_transfer_warehouse >', 0);
            } else if ($status_table == "not_keep") {
                $this->datatables->where('tb_transfer.ct_transfer_warehouse is null');
            } else if ($status_table == "keep_full") {

                $tbTransfer = "(
                    SELECT
                        tbltransfer_warehouse.productions_capacity_id as pp_id, 
                        tbltransfer_warehouse_detail.id_items as item_id, 
                        tbltransfer_warehouse_detail.type as item_type,
                        SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
                    FROM tbltransfer_warehouse
                    INNER JOIN tbltransfer_warehouse_detail ON tbltransfer_warehouse_detail.id_transfer = tbltransfer_warehouse.id
                    WHERE tbltransfer_warehouse.productions_capacity_id != 0
                    GROUP BY tbltransfer_warehouse.productions_capacity_id, tbltransfer_warehouse_detail.id_items, tbltransfer_warehouse_detail.type
                ) tb_transfer";

                $tbBOM = "(
                    SELECT
                        ot.productions_plan_id as pp_id,
                        ot.item_id as item_id,
                        IF (ot.item_type = 'materials', 'nvl', 'product') as item_type,
                        ot.quantity + coalesce(tbl_productions_plan_compensation.quantity_compensation, 0) as quantity_bom
                    FROM (
                        SELECT
                            tbl_productions_plan_bom.productions_plan_id as productions_plan_id, 
                            tbl_productions_plan_bom.item_id as item_id, 
                            tbl_productions_plan_bom.item_type as item_type,
                            SUM(tbl_productions_plan_bom.quantity) as quantity
                        FROM tbl_productions_plan_bom
                        WHERE tbl_productions_plan_bom.item_type != 'element'
                        GROUP BY tbl_productions_plan_bom.productions_plan_id, tbl_productions_plan_bom.item_id, tbl_productions_plan_bom.item_type
                    ) ot
                    LEFT JOIN tbl_productions_plan_compensation ON tbl_productions_plan_compensation.productions_plan_id = ot.productions_plan_id AND tbl_productions_plan_compensation.item_id = ot.item_id AND tbl_productions_plan_compensation.item_type = ot.item_type
                ) tb_bom";

                $tbCheck = "(
                    SELECT
                        tb_bom.pp_id as pp_id,
                        SUM(IF(ROUND(tb_bom.quantity_bom) > ROUND(COALESCE(tb_transfer.quantity_net, 0)), 1, 0)) as ct
                    FROM $tbBOM
                    LEFT JOIN $tbTransfer ON tb_transfer.pp_id = tb_bom.pp_id AND tb_transfer.item_id = tb_bom.item_id AND tb_transfer.item_type = tb_bom.item_type
                    GROUP BY tb_bom.pp_id
                ) tb_check";

                $this->datatables->join($tbCheck, 'tb_check.pp_id = tbl_productions_plan.id', 'left');
                $this->datatables->where('tb_check.ct = 0', false, false);
            } else if ($status_table == "keep_apart_full") {
                $tbTransfer = "(
                    SELECT
                        tbltransfer_warehouse.productions_capacity_id as pp_id, 
                        tbltransfer_warehouse_detail.id_items as item_id, 
                        tbltransfer_warehouse_detail.type as item_type,
                        SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
                    FROM tbltransfer_warehouse
                    INNER JOIN tbltransfer_warehouse_detail ON tbltransfer_warehouse_detail.id_transfer = tbltransfer_warehouse.id
                    WHERE tbltransfer_warehouse.productions_capacity_id != 0
                    GROUP BY tbltransfer_warehouse.productions_capacity_id, tbltransfer_warehouse_detail.id_items, tbltransfer_warehouse_detail.type
                ) tb_transfer";

                $tbW = "(
                    SELECT
                        tblwarehouse_items.id_items as item_id,
                        tblwarehouse_items.type_items as item_type,
                        SUM(tblwarehouse_items.product_quantity) as product_quantity
                    FROM tblwarehouse_items
                    WHERE tblwarehouse_items.warehouse_id != ".WAREHOUSES_CAPACITY." AND tblwarehouse_items.product_quantity > 0
                    GROUP BY tblwarehouse_items.id_items, tblwarehouse_items.type_items
                ) tb_w";

                $tbBOM = "(
                    SELECT
                        ot.productions_plan_id as pp_id,
                        ot.item_id as item_id,
                        IF (ot.item_type = 'materials', 'nvl', 'product') as item_type,
                        ot.quantity + coalesce(tbl_productions_plan_compensation.quantity_compensation, 0) as quantity_bom
                    FROM (
                        SELECT
                            tbl_productions_plan_bom.productions_plan_id as productions_plan_id, 
                            tbl_productions_plan_bom.item_id as item_id, 
                            tbl_productions_plan_bom.item_type as item_type,
                            SUM(tbl_productions_plan_bom.quantity) as quantity
                        FROM tbl_productions_plan_bom
                        WHERE tbl_productions_plan_bom.item_type != 'element'
                        GROUP BY tbl_productions_plan_bom.productions_plan_id, tbl_productions_plan_bom.item_id, tbl_productions_plan_bom.item_type
                    ) ot
                    LEFT JOIN tbl_productions_plan_compensation ON tbl_productions_plan_compensation.productions_plan_id = ot.productions_plan_id AND tbl_productions_plan_compensation.item_id = ot.item_id AND tbl_productions_plan_compensation.item_type = ot.item_type
                ) tb_bom";

                $tbCheck = "(
                    SELECT
                        tb_bom.pp_id as pp_id,
                        SUM(IF(ROUND(COALESCE(tb_transfer.quantity_net, 0)) > 0, 1, 0)) as ct_transfer,
                        SUM(IF(ROUND(tb_bom.quantity_bom) > ROUND(COALESCE(tb_transfer.quantity_net, 0)), 1, 0)) as ct_full,
                        SUM(IF(ROUND(tb_bom.quantity_bom) - ROUND(COALESCE(tb_w.product_quantity, 0)) > ROUND(COALESCE(tb_transfer.quantity_net, 0)), 1, 0)) as ct
                    FROM $tbBOM
                    LEFT JOIN $tbTransfer ON tb_transfer.pp_id = tb_bom.pp_id AND tb_transfer.item_id = tb_bom.item_id AND tb_transfer.item_type = tb_bom.item_type
                    LEFT JOIN $tbW ON tb_w.item_id = tb_bom.item_id AND tb_w.item_type = tb_bom.item_type
                    GROUP BY tb_bom.pp_id
                ) tb_check";

                $this->datatables->join($tbCheck, 'tb_check.pp_id = tbl_productions_plan.id', 'left');
                $this->datatables->where('(tb_check.ct = 0 AND tb_check.ct_transfer > 0 AND tb_check.ct_full > 0)', false, false);
            } else if ($status_table == 'keep_apart_not_full') {
                $tbTransfer = "(
                    SELECT
                        tbltransfer_warehouse.productions_capacity_id as pp_id, 
                        tbltransfer_warehouse_detail.id_items as item_id, 
                        tbltransfer_warehouse_detail.type as item_type,
                        SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
                    FROM tbltransfer_warehouse
                    INNER JOIN tbltransfer_warehouse_detail ON tbltransfer_warehouse_detail.id_transfer = tbltransfer_warehouse.id
                    WHERE tbltransfer_warehouse.productions_capacity_id != 0
                    GROUP BY tbltransfer_warehouse.productions_capacity_id, tbltransfer_warehouse_detail.id_items, tbltransfer_warehouse_detail.type
                ) tb_transfer";

                $tbW = "(
                    SELECT
                        tblwarehouse_items.id_items as item_id,
                        tblwarehouse_items.type_items as item_type,
                        SUM(tblwarehouse_items.product_quantity) as product_quantity
                    FROM tblwarehouse_items
                    WHERE tblwarehouse_items.warehouse_id != ".WAREHOUSES_CAPACITY." AND tblwarehouse_items.product_quantity > 0
                    GROUP BY tblwarehouse_items.id_items, tblwarehouse_items.type_items
                ) tb_w";

                $tbBOM = "(
                    SELECT
                        ot.productions_plan_id as pp_id,
                        ot.item_id as item_id,
                        IF (ot.item_type = 'materials', 'nvl', 'product') as item_type,
                        ot.quantity + coalesce(tbl_productions_plan_compensation.quantity_compensation, 0) as quantity_bom
                    FROM (
                        SELECT
                            tbl_productions_plan_bom.productions_plan_id as productions_plan_id, 
                            tbl_productions_plan_bom.item_id as item_id, 
                            tbl_productions_plan_bom.item_type as item_type,
                            SUM(tbl_productions_plan_bom.quantity) as quantity
                        FROM tbl_productions_plan_bom
                        WHERE tbl_productions_plan_bom.item_type != 'element'
                        GROUP BY tbl_productions_plan_bom.productions_plan_id, tbl_productions_plan_bom.item_id, tbl_productions_plan_bom.item_type
                    ) ot
                    LEFT JOIN tbl_productions_plan_compensation ON tbl_productions_plan_compensation.productions_plan_id = ot.productions_plan_id AND tbl_productions_plan_compensation.item_id = ot.item_id AND tbl_productions_plan_compensation.item_type = ot.item_type
                ) tb_bom";

                $tbCheck = "(
                    SELECT
                        tb_bom.pp_id as pp_id,
                        SUM(IF(ROUND(COALESCE(tb_transfer.quantity_net, 0)) > 0, 1, 0)) as ct_transfer,
                        SUM(IF(ROUND(tb_bom.quantity_bom) > ROUND(COALESCE(tb_transfer.quantity_net, 0)), 1, 0)) as ct_full,
                        SUM(IF(ROUND(tb_bom.quantity_bom) - ROUND(COALESCE(tb_w.product_quantity, 0)) > ROUND(COALESCE(tb_transfer.quantity_net, 0)), 1, 0)) as ct
                    FROM $tbBOM
                    LEFT JOIN $tbTransfer ON tb_transfer.pp_id = tb_bom.pp_id AND tb_transfer.item_id = tb_bom.item_id AND tb_transfer.item_type = tb_bom.item_type
                    LEFT JOIN $tbW ON tb_w.item_id = tb_bom.item_id AND tb_w.item_type = tb_bom.item_type
                    GROUP BY tb_bom.pp_id
                ) tb_check";

                $this->datatables->join($tbCheck, 'tb_check.pp_id = tbl_productions_plan.id', 'left');
                $this->datatables->where('(tb_check.ct > 0 AND tb_check.ct_transfer > 0 AND tb_check.ct_full > 0)', false, false);
            }
        }

