                <ul class="dropdown-menu pull-right" role="menu" aria-labelledby="dropdownMenu1" style="width: 165px">
                    <li>' . $hidden . '</li>
                    <li>' . $view . '</li>
                    <li>' . $edit . '</li>
                    <li>' . $print . '</li>
                    <li>' . $print_detail . '</li>
                    <li>' . $keepStockMaterial . '</li>
                    <li>' . $create_relieve_suffering . '</li>
                    <li class="not-outside">' . $delete . '</li>
                </ul>
            </div>';
            $data->aaData[$key][13] = $actions;

        }

        $data->count_all = $this->manufactures_model->countProductionsPlanStatus('');
        $data->count_keep = $this->manufactures_model->countProductionsPlanStatus('keep');
        $data->count_ycmh = $this->manufactures_model->countProductionsPlanStatus('ycmh');
        $data->count_not_keep = $data->count_all - $data->count_keep;
        echo json_encode($data);
    }

    public function view_productions_plan($id)
    {
        if (!$this->perViewProductionsPlan && !$this->perViewOwnProductionsPlan) {
            accessDenied($js = true);
        }

        $productions_plan = $this->manufactures_model->rowProductionsPlan($id);
        if (!$this->perViewProductionsPlan) {
            checkMyData($productions_plan['created_by'], true);
        }

        $th = '';
        $targets = 7;
        $script = '';
        $date1 = $productions_plan['date_start'];
        $date2 = $productions_plan['date_end'];
        $this->db->select('tbl_productions_plan_details.date', false);
        $this->db->from('tbl_productions_plan');
        $this->db->join('tbl_productions_plan_items', 'tbl_productions_plan_items.productions_plan_id = tbl_productions_plan.id');
        $this->db->join('tbl_productions_plan_details', 'tbl_productions_plan_details.productions_plan_item_id = tbl_productions_plan_items.id');
        $this->db->where('tbl_productions_plan_details.date >=', $date1);
        $this->db->where('tbl_productions_plan_details.date <=', $date2);
        $this->db->where('tbl_productions_plan.id', $id);
        $this->db->group_by('tbl_productions_plan_details.date');

        $resultDate = $this->db->get()->result_array();
        if (!empty($resultDate)) {
            foreach ($resultDate as $k => $val) {
                $th .= '<th>' . _d($val['date']) . '</th>';
                $script .= '{
                    "render":function(data, type, row) {
                        if(data == 0) return "";
                        return \'<div class="text-center">\'+tnhFormatNumber(data)+\'</div>\';
                    },
                   "targets": ' . $targets . ', "name": "date' . $k . '", "className": "text-center",
               },';
                $targets++;
            }
        }

        $data['id'] = $id;
        $data['th'] = $th;
        $data['script'] = $script;
        $data['targets'] = $targets;
        $data['created_by'] = get_staff_full_name($productions_plan['created_by']);
        $data['productions_plan'] = $productions_plan;
        $data['productionsPlanSemiProducts'] = $this->manufactures_model->viewProductionsPlanSemiProducts($id);
        $data['productionsPlanMaterials'] = $this->manufactures_model->viewProductionsPlanMaterials($id);

        $this->load->view('admin/manufactures/view_productions_plan', $data);
    }

    public function getViewProductionsPlan()
    {
        $filter_productions_plan_id = $this->input->post('filter_productions_plan_id');
        $filter_date_start = $this->input->post('filter_date_start');
        $filter_date_end = $this->input->post('filter_date_end');

        $orders = "(
            SELECT tbl_orders.reference_no
            FROM tbl_orders
            WHERE tbl_productions_plan_items.object_id = tbl_orders.id
            LIMIT 1
        )";

        $business_plan = "(
            SELECT tbl_business_plan.reference_no
            FROM tbl_business_plan
            WHERE tbl_productions_plan_items.object_id = tbl_business_plan.id
            LIMIT 1
        )";

        // CONCAT(tbl_products.name, '(', tbl_products.code, ')', '|||', tbl_productions_plan_items.is_preventive) as product_code,
        $this->datatables->select("
            0 as number_records,
            IF(tbl_productions_plan_items.type_object = 'orders', $orders, $business_plan) as reference_order,
            tbl_products.images as images,
            CONCAT(tbl_products.code, '|||', tbl_productions_plan_items.is_preventive) as product_code,
            tbl_products.name as product_name,
            tbl_products.sample_cover_code as sample_cover_code,
            tblunits.unit as unit,
            tbl_productions_plan_items.quantity_warehouses as quantity_warehouses,
            tbl_productions_plan_items.quantity_total_details as quantity_total_details,
            tbl_productions_plan_items.quantity_reserve as quantity_reserve,
            (tbl_productions_plan_items.quantity_total_details + tbl_productions_plan_items.quantity_reserve) as total_quantity,
            ", false)
            ->from('tbl_productions_plan_items')
            ->join('tbl_products', 'tbl_products.id = tbl_productions_plan_items.product_id')
            ->join('tblunits', 'tblunits.unitid = tbl_products.conversion_unit', 'left');

        $this->datatables->where('tbl_productions_plan_items.productions_plan_id', $filter_productions_plan_id);
        $iDisplayStart = $this->input->post('iDisplayStart');
        $custom[] = ['index' => 1, 'select' => 'reference_order'];
        $custom_select[1] = "IF(tbl_productions_plan_items.type_object = 'orders', $orders, $business_plan)";
        $this->datatables->custom_ordering($custom);
        $this->datatables->custom_select($custom_select);

        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;
        }
        echo json_encode($data);
    }

    public function getViewProductionsPlanProceduce()
    {
        $filter_productions_plan_id = $this->input->post('filter_productions_plan_id');

        $quantityHasProduced = "COALESCE((
            SELECT SUM(tbl_productions_orders_details.quantity_warehoused)
            FROM tbl_productions_orders_items
            INNER JOIN tbl_productions_orders_details ON tbl_productions_orders_details.productions_orders_item_id = tbl_productions_orders_items.id
            WHERE tbl_productions_orders_items.production_plan_item_id = tbl_productions_plan_items.id
        ), 0)";

        $order = "(
            SELECT tbl_orders.reference_no
            FROM tbl_orders
            WHERE tbl_orders.id = tbl_productions_plan_items.object_id
        )";

        $business = "(
            SELECT CONCAT(tbl_business_plan.reference_no, ' (', tbl_business_plan.plan_name, ')')
            FROM tbl_business_plan
            WHERE tbl_business_plan.id = tbl_productions_plan_items.object_id
        )";

        $this->datatables->select("
            0 as number_records,
            IF(tbl_productions_plan_items.type_object = 'orders', $order, $business) as object_id,
            tbl_products.code as product_code,
            tbl_products.name as product_name,
            tblunits.unit as unit,
            (tbl_productions_plan_items.quantity_total_details + tbl_productions_plan_items.quantity_reserve) as quantity_total_details,
            0 as quantity_has_produced,
            (tbl_productions_plan_items.quantity_total_details + tbl_productions_plan_items.quantity_reserve - 0) as quantity_rest,
            ", false)
            ->from('tbl_productions_plan_items')
            ->join('tbl_products', 'tbl_products.id = tbl_productions_plan_items.product_id')
            ->join('tblunits', 'tblunits.unitid = tbl_products.unit_id', 'left');

        $this->datatables->where('tbl_productions_plan_items.productions_plan_id', $filter_productions_plan_id);

        $custom[] = ['index' => 1, 'select' => "object_id"];
        $custom_select[1] = "IF(tbl_productions_plan_items.type_object = 'orders', $order, $business)";
        $custom[] = ['index' => 6, 'select' => "quantity_has_produced"];
        $custom_select[6] = "$quantityHasProduced";
        $custom[] = ['index' => 7, 'select' => "quantity_rest"];
        $custom_select[7] = "(tbl_productions_plan_items.quantity_total_details - $quantityHasProduced)";
        $this->datatables->custom_ordering($custom);
        $this->datatables->custom_select($custom_select);

        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;
            // $object_id = $value[1];
            // if (!empty($object_id))
            // {
            //     $arr = explode("__", $object_id);
            //     $typeObject = $arr[0];
            //     $objectId = $arr[1];

            //     if ($typeObject == "orders") {
            //         $order = $this->orders_model->rowOrderById($objectId);
            //         $data->aaData[$key][1] = $order['reference_no'];
            //     } else if ($typeObject == "business_plan") {
            //         $business_plan = $this->business_plan_model->rowBusinessPlanById($objectId);
            //         $data->aaData[$key][1] = $business_plan['reference_no'].' ('. $business_plan['plan_name'].')';
            //     }
            // }
        }
        echo json_encode($data);
    }

    function delete_productions_plan($id)
    {
        $data = [];

        //check permision
        if (!$this->perDeleteProductionsPlan) {
            $data['result'] = 0;
            $data['message'] = lang('access_denied');
            echo json_encode($data);
            die;
        }
        //end

        if ($id) {
            $productions_plan = $this->manufactures_model->rowProductionsPlan($id);
            $itemsPlan = $this->manufactures_model->getProductionsPlanById($id);
            if (!checkMyDataTF($productions_plan['created_by'])) {
                $data['result'] = 0;
                $data['message'] = lang('access_denied');
                echo json_encode($data);
                die;
            }

            $this->db->from('tbl_productions_plan_items');
            $this->db->join('tbl_productions_orders_items', 'tbl_productions_orders_items.production_plan_item_id = tbl_productions_plan_items.item_object_id AND tbl_productions_orders_items.object_item_type = tbl_productions_plan_items.type_object');
            // $this->db->where('tbl_productions_plan_items.type_object', 'orders');
            // $this->db->where('tbl_productions_plan_items.productions_plan_id', $id);
            $this->db->where('tbl_productions_orders_items.plan_id', $id);
            $this->db->limit(1);
            $isUse = $this->db->get()->num_rows();
            if (!empty($isUse)) {
                $data['result'] = 0;
                $data['message'] = lang('Có mặt hàng tạo lệnh sản xuất tổng không thể xóa');
                echo json_encode($data);
                die;
            }

            foreach ($itemsPlan as $key => $value) {
                $planDate = $this->manufactures_model->getProductionsPlanDetails($value['id']);
                $itemsPlan[$key]['planDate'] = $planDate;
            }

            //is trasnfer
            $this->db->from('tbltransfer_warehouse');
            $this->db->where('tbltransfer_warehouse.productions_capacity_id', $id);
            $this->db->limit(1);
            $isTransfer = $this->db->get()->num_rows();
            if (!empty($isTransfer)) {
                $data['result'] = 0;
                $data['message'] = lang('Đã có giữ kho NVL không thể xóa');
                echo json_encode($data);
                die;
            }

            //is purchase
            $this->db->from('tblpurchases');
            $this->db->where('tblpurchases.id_plan', $id);
            $this->db->limit(1);
            $isTransfer = $this->db->get()->num_rows();
            if (!empty($isTransfer)) {
                $data['result'] = 0;
                $data['message'] = lang('Đã có YCMH không thể xóa');
                echo json_encode($data);
                die;
            }

            if ($productions_plan['status'] == "un_approved") {
                if ($this->manufactures_model->deleteProductionsPlan($id)) {
                    foreach ($itemsPlan as $key => $value) {
                        $this->manufactures_model->updateQuantityPlan((float)$value['quantity_total_details'] + (float)$value['quantity_reserve'], $minus = 1, $value['item_object_id'], $value['type_object']);
                        $planDate = $value['planDate'];
                        if (!empty($planDate)) {
                            foreach ($planDate as $k => $val) {
                                $this->manufactures_model->updateQuantityPlanShippings($val['quantity'], $minus = 1, $value['item_object_id'], $value['type_object'], $val['date']);
                            }
                        }
                    }

                    $sales_orders_id = $productions_plan['options1_id'];
                    if (!empty($sales_orders_id)) {
                        foreach (explode(',', $sales_orders_id) as $key => $value) {
                            $this->orders_model->updateOrdersNew($value, ['productions_plan_id' => 0]);
                        }
                    }

                    $business_plan_id = $productions_plan['options2_id'];
                    if (!empty($business_plan_id)) {
                        foreach (explode(',', $business_plan_id) as $key => $value) {
                            $this->business_plan_model->updateBusinessPlan($value, ['productions_plan_id' => 0]);
                        }
                    }
                    $this->manufactures_model->deleteProductionsPlanBom($id);
                    $this->manufactures_model->deleteProductionsPlanWarehouses($id);
                    $this->manufactures_model->deleteProductionsPlanObject($id);
                    $this->manufactures_model->deleteProductionsPlanCompensation($id);

                    //delete business plan
                    $business_plan_preventive = $this->manufactures_model->getBusinessPlanByProductionsPlanPreventiveId($id);
                    if (!empty($business_plan_preventive)) {
                        $items = $this->business_plan_model->getBusinessPlanItems($business_plan_preventive['id']);
                        if ($this->business_plan_model->deleteBusinessPlan($business_plan_preventive['id'])) {
                            foreach ($items as $key => $value) {
                                if ($this->business_plan_model->deleteBusinessPlanItems($value['id'])) {
                                    $this->business_plan_model->deleteBusinessPlanItemsDateBusinessPlanItemsId($value['id']);
                                }
                            }
            
                            $this->business_plan_model->deleteBusinessPlanItemsStages($business_plan_preventive['id']);
            
                            insertActivityLog([
                                'type_parent_obj' => 'business_plan',
                                'table_obj' => 'tbl_business_plan',
                                'id_obj' => $business_plan_preventive['id'],
                                'name_obj' => $business_plan_preventive['reference_no'],
                                'content' => lang('tnh_his_delete_business_plan').' ['.$business_plan_preventive['reference_no'].']',
                                'actions' => 'delete'
                            ]);
            
                            $data['result'] = 1;
                            $data['message'] = lang('success');
                        }
                    }

                    insertActivityLog([
                        'type_parent_obj' => 'productions_plan',
                        'table_obj' => 'tbl_productions_plan',
                        'id_obj' => $id,
                        'name_obj' => $productions_plan['reference_no'],
                        'content' => lang('tnh_his_delete_productions_plan') . ' [' . $productions_plan['reference_no'] . ']',
                        'actions' => 'delete'
                    ]);
                    
                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = lang('browsed_cannot_be_deleted');
            }
        } else {
            $data['result'] = 0;
            $data['message'] = lang('fail');
        }
        echo json_encode($data);
    }

    public function export_excel_production_plan()
    {
        if (!$this->perExportProductionsPlan) {
            accessDenied($js = true);
        }
        $response = [];
        if ($this->input->post('export_excel')) {
            ini_set('memory_limit', '3500M');
            include APPPATH . 'third_party/PHPExcel/PHPExcel.php';
            $this->load->library('PHPExcel');
            $productions_plan_id = $this->input->post('productions_plan_id');
            $productions_plan = $this->manufactures_model->rowProductionsPlan($productions_plan_id);
            if (empty($productions_plan)) {
                $response =  array(
                    'result' => 0,
                    'message' => lang('not_data_exists'),
                );
                echo json_encode($response);
                die;
            }
            $style_excel = style_excel();
            $cloumns_excel = cloumns_excel();

            $objPHPExcel = new PHPExcel();
            $objPHPExcel->getActiveSheet()->getPageMargins()->setTop(0.2); // ~ 1.78cm
            $objPHPExcel->getActiveSheet()->getPageMargins()->setHeader(0.2); // ~1.02cm
            $objPHPExcel->getActiveSheet()->getPageMargins()->setRight(0.2); // ~
            $objPHPExcel->getActiveSheet()->getPageMargins()->setLeft(0.2); // ~1.78cm
            $objPHPExcel->getActiveSheet()->getPageMargins()->setBottom(0.2); // ~1.73cm
            $objPHPExcel->getActiveSheet()->getPageMargins()->setFooter(0); // ~1.02cm

            $objPHPExcel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
            $objPHPExcel->getActiveSheet()->getPageSetup()->setPaperSize(PHPExcel_Worksheet_PageSetup::PAPERSIZE_A4);

            $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setAutoSize(true);
            $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setAutoSize(true);
            $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setAutoSize(true);
            $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setAutoSize(true);
            $objPHPExcel->getActiveSheet()->getColumnDimension('E')->setAutoSize(true);
            $objPHPExcel->getActiveSheet()->getColumnDimension('F')->setAutoSize(true);

            $objPHPExcel->getActiveSheet()->SetCellValue('A1', lang('date'))->getStyle('A1')->applyFromArray($style_excel['bold']);
            $objPHPExcel->getActiveSheet()->SetCellValue('B1', _dt($productions_plan['date']));

            $objPHPExcel->getActiveSheet()->SetCellValue('A2', lang('tnh_planning_cycle'))->getStyle('A2')->applyFromArray($style_excel['bold']);
            $objPHPExcel->getActiveSheet()->SetCellValue('B2', _d($productions_plan['date_start']) . ' - ' . _d($productions_plan['date_end']));

            $objPHPExcel->getActiveSheet()->SetCellValue('A3', lang('tnh_applied_standard'))->getStyle('A3')->applyFromArray($style_excel['bold']);
            $objPHPExcel->getActiveSheet()->SetCellValue('B3', ($productions_plan['safe_inventory'] == 1 ? lang('tnh_safe_inventory') : lang('tnh_not')));

            $objPHPExcel->getActiveSheet()->SetCellValue('A4', lang('tnh_options'))->getStyle('A4')->applyFromArray($style_excel['bold']);
            $objPHPExcel->getActiveSheet()->SetCellValue('B4', ($productions_plan['options1'] == 1 ? lang('tnh_sales_orders') : '') . ' - ' . ($productions_plan['options2'] == 1 ? lang('tnh_business_plan') : ''));

            $objPHPExcel->getActiveSheet()->SetCellValue('A5', lang('note'))->getStyle('A5')->applyFromArray($style_excel['bold']);
            $objPHPExcel->getActiveSheet()->SetCellValue('B5', strip_tags($productions_plan['note']));

            $objPHPExcel->getActiveSheet()->mergeCells('A6:H6');
            $objPHPExcel->getActiveSheet()->SetCellValue('A6', lang('productions_plan'))->getStyle('A6')->applyFromArray($style_excel['title']);;

            $date1 = date_create($productions_plan['date_start']);
            $date2 = date_create($productions_plan['date_end']);
            $diff = date_diff($date1, $date2);
            $days = $diff->days;
            $select_custom_fields = "";
            $arr_date = [];

            for ($i = 0; $i <= $days; $i++) {
                $date = date('d/m/Y', strtotime($productions_plan['date_start'] . " + $i days"));
                $select = "
                    COALESCE((
                        SELECT
                            tbl_productions_plan_details.quantity
                        FROM tbl_productions_plan_details
                        WHERE tbl_productions_plan_details.productions_plan_item_id = tbl_productions_plan_items.id AND DATE_FORMAT(tbl_productions_plan_details.date, '%d/%m/%Y') = '$date'
                    ), 0)
                ";
                $select_custom_fields .= ", " . $select . " as '" . $date . "'";
                array_push($arr_date, $date);
            }

            //$select_custom_fields
            $this->db->select("
                tbl_productions_plan_items.id as id,
                tbl_products.code as product_code,
                tbl_products.name as product_name,
                tblunits.unit as unit,
                tbl_productions_plan_items.quantity_minimum as quantity_minimum,
                tbl_productions_plan_items.quantity_warehouses as quantity_warehouses,
                tbl_productions_plan_items.quantity_total_details as quantity_total_details,
                tbl_productions_plan_items.quantity_reserve as quantity_reserve,
                (tbl_productions_plan_items.quantity_total_details + tbl_productions_plan_items.quantity_reserve) as total_quantity,
                ", false)
                ->from('tbl_productions_plan_items')
                ->join('tbl_products', 'tbl_products.id = tbl_productions_plan_items.product_id')
                ->join('tblunits', 'tblunits.unitid = tbl_products.unit_id', 'left');

            $this->db->where('tbl_productions_plan_items.productions_plan_id', $productions_plan_id);

            $data = $this->db->get()->result_array();
            // print_arrays($data);

            $th = 7;
            $th_continue = 'G';
            $row = 8;
            $number_records = 1;
            foreach ($data as $key => $value) {
                if ($key == 0) {
                    $objPHPExcel->getActiveSheet()->SetCellValue("A$th", lang('tnh_numbers'));
                    $objPHPExcel->getActiveSheet()->SetCellValue("B$th", lang('tnh_product_code'));
                    $objPHPExcel->getActiveSheet()->SetCellValue("C$th", lang('tnh_product_name'));
                    $objPHPExcel->getActiveSheet()->SetCellValue("D$th", lang('unit'));
                    $objPHPExcel->getActiveSheet()->SetCellValue("E$th", lang('tnh_safe_inventory'));
                    $objPHPExcel->getActiveSheet()->SetCellValue("F$th", lang('tnh_quantity_warehouses'));
                    $objPHPExcel->getActiveSheet()->SetCellValue("G$th", lang('tnh_quantity_need'));
                    $objPHPExcel->getActiveSheet()->SetCellValue("H$th", lang('tnh_quantity_reserve'));
                    $objPHPExcel->getActiveSheet()->SetCellValue("I$th", lang('total_quantity'));
                }
                $cloumn = 0;
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $number_records);
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value['product_code']);
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value['product_name']);
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value['unit']);
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value['quantity_minimum']);
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value['quantity_warehouses']);
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value['quantity_total_details']);
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value['quantity_reserve']);
                $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value['total_quantity']);


                $cloumn = 'G';
                // foreach ($arr_date as $k => $val) {
                //     // if (!empty($value[$val]))
                //     // {
                //         // if ($key == 0) {
                //             // $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($th_continue++, $th, $val);
                //             $objPHPExcel->getActiveSheet()->getColumnDimension("$th_continue")->setAutoSize(true);
                //             $objPHPExcel->getActiveSheet()->SetCellValue("$th_continue$th", $val);
                //             $th_continue++;
                //         // }
                //         $objPHPExcel->getActiveSheet()->SetCellValue("$cloumn$row", $value[$val]);
                //         $cloumn++;
                //         // $objPHPExcel->getActiveSheet()->setCellValueByColumnAndRow($cloumn++, $row, $value[$val]);
                //     // }
                // }

                $row++;
                $number_records++;
            }

            $objPHPExcel->getActiveSheet()->getStyle("A7:I$row")->applyFromArray($style_excel['border']);
            $objPHPExcel->getActiveSheet()->getStyle("A7:I" . '7')->applyFromArray($style_excel['bold']);

            $filename = lang('productions_plan') . '.xls';
            $objPHPExcel->getActiveSheet()->freezePane('A1');

            ob_start();
            header('Content-Type: application/vnd.ms-excel');
            header('Content-Disposition: attachment;filename="$filename"');
            header('Cache-Control: max-age=0');
            $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
            $objWriter->save('php://output');
            $xlsData = ob_get_contents();
            ob_end_clean();

            $response =  array(
                'result' => 1,
                'filename' => $filename,
                'message' => lang('success'),
                'file' => "data:application/vnd.ms-excel;base64," . base64_encode($xlsData)
            );
        }
        echo json_encode($response);
    }

    function refereshReference()
    {
        $data = [];
        if ($this->input->get('referesh')) {
            $reference_no = getReference('productions_plan');
            if ($this->manufactures_model->checkExistProductionsPlanByReferenceNo($reference_no)) {
                $this->db->select('MAX(tbl_productions_plan.reference_no) as reference_no', false);
                $this->db->from('tbl_productions_plan');
                $rs = $this->db->get()->row_array();

                $max = $rs['reference_no'];
                $max = subReference($max);
                updateReferenceNormal('productions_plan', $max);
                $reference_no = getReference('productions_plan');
            }
            $data['reference_no'] = $reference_no;
            $data['message'] = lang('tnh_referesh_success');
        }
        echo json_encode($data);
    }

    function agreeProductionsPlan()
    {
        $data = [];

        if (!$this->perApproveProductionsPlan) {
            $data['result'] = 0;
            $data['message'] = lang('access_denied');
            echo json_encode($data);
            die;
        }

        if ($this->input->get()) {
            $productions_plan_id = $this->input->get('productions_plan_id');
            $status = $this->input->get('status');
            $productions_plan = $this->manufactures_model->rowProductionsPlan($productions_plan_id);
            $date = date('Y-m-d H:i');
            $user_id = get_staff_user_id();
            if ($productions_plan['status'] == $status) {
                $data['result'] = 0;
                $data['message'] = lang('tnh_please_referesh_table');
                echo json_encode($data);
                die;
            }
            
            $up = $this->manufactures_model->updateProductionsPlan($productions_plan_id, [
                'status' => $status,
                'date_status' => $date,
                'user_status' => $user_id
            ]);
            if ($up) {
                @pusherTNHNotfication();
                insertActivityLog([
                    'type_parent_obj' => 'productions_plan',
                    'table_obj' => 'tbl_productions_plan',
                    'id_obj' => $productions_plan['id'],
                    'name_obj' => $productions_plan['reference_no'],
                    'content' => lang('tnh_his_agree_productions_plan') . ' [' . $productions_plan['reference_no'] . ']',
                    'actions' => 'agree'
                ]);

                if ($status == "approved") {
                    $userList = $this->staff_model->getStaff();
                    $notifiedUsers = [];

                    $query_str = "SELECT * FROM tbl_productions_plan where id = $productions_plan_id";
                    $query = $this->db->query($query_str);
                    foreach ($query->result() as $row) {
                        $dataHtml = 'Phiếu KẾ HOẠCH SẢN XUẤT ' . $row->reference_no . ' vừa được duyệt bởi ';
                    }

                    foreach ($userList as $key => $value) {
                        $notification_data = [
                            'description' => $dataHtml,
                            'touserid' => $key,
                            'link' => 'change_management/?id=' . $productions_plan_id,
                            'onchange' => ' onclick="view_change_gif(' . $productions_plan_id . '); return false;" ',
                        ];

                        if (add_notification($notification_data)) {
                            array_push($notifiedUsers, $value['staffid']);
                        }
                        pusher_trigger_notification($notifiedUsers);
                    }
                }

                $data['result'] = 1;
                $data['message'] = lang('success');
            } else {
                $data['result'] = 0;
                $data['message'] = lang('fail');
            }
        }
        echo json_encode($data);
    }

