    public function add_purchase($id)
    {
        $productions_plan = $this->manufactures_model->rowProductionsPlan($id);
        if ($this->input->post('save')) {
            $data = [];
            $this->form_validation->set_rules('date', lang("date"), 'required');
            if ($this->form_validation->run() == true) {
                $date = $this->input->post('date', true);
                $name = $this->input->post('name');
                $note = $this->input->post('note', false);
                $counter = $this->input->post('counter');
                $arr_id = [];
                $errors = '';
                if (!empty($counter)) {
                    foreach ($counter as $key => $value) {
                        $items_id = $this->input->post('items_id')[$value];
                        if (empty($items_id)) continue;
                        $arr = explode("__", $items_id);
                        $type = $arr[0];
                        $itemId = $arr[1];
                        if ($type == "materials") {
                            $type = "nvl";
                        } else if ($type == "semi_products" || $type == "semi_products_outside") {
                            $type = "product";
                        } else if ($type == "tools_supplies") {
                            $type = "tools";
                        }
                        $quantity = number_unformat($this->input->post('quantity')[$value]);

                        $index = array_search($items_id, $arr_id);
                        if ($index === false) {
                            $arr_id[] = $items_id;
                        } else {
                            $errors .= 'Có mặt hàng bị trùng vui lòng xóa';
                        }

                        $items[] = [
                            'id' => $itemId,
                            'quantity' => $quantity,
                            'quantity_net' => $quantity,
                            'type' => $type,
                            'note' => ''
                        ];
                    }
                }

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data);
                    die;
                }

                if (empty($items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('un_not_items_purchase');
                    echo json_encode($data);
                    die;
                }

                $fields = [
                    'id_plan' => $id,
                    'name' => $name,
                    'reason' => $note,
                    'date' => $date,
                    'items' => $items
                ];
                $purchases_id = $this->purchases_model->convertCapactityToPurchase($fields);
                if ($purchases_id > 0) {
                    insertActivityLog([
                        'type_parent_obj' => 'productions_plan',
                        'table_obj' => 'tbl_productions_plan',
                        'id_obj' => $id,
                        'name_obj' => $productions_plan['reference_no'],
                        'content' => lang('tnh_add_purchase') . ' [' . $productions_plan['reference_no'] . ']',
                        'actions' => 'add_purchase'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
        } else {
            $data['id'] = $id;
            $this->load->view('admin/manufactures/add_purchase', $data);
        }
    }

