    public function add_productions_orders()
    {
        if (!$this->perAddProductionsOrders) {
            accessDenied();
        }
        die;
        if ($this->input->post('add')) {
            $data = [];
            $this->form_validation->set_rules('reference_no', lang("tnh_reference_productions_orders"), 'trim|required|is_unique[tbl_productions_orders.reference_no]');
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('location', lang("tnh_location"), 'required');
            $this->form_validation->set_rules('versions[]', lang("BOM"), 'required');
            if ($this->form_validation->run() == true) {
                $reference_no = getReference('productions_orders');
                $date = to_sql_date($this->input->post('date'), true);
                $note = $this->input->post('note', false);
                $location = $this->input->post('location');
                $productions_plan = $this->input->post('productions_plan_id');
                $total_quantity = 0;
                $count_items = 0;

                $options1 = $this->input->post('options1');
                $options2 = $this->input->post('options2');
                $productions_plan_reference = '';
                $productions_plan_orders = [];
                $arrOrderId = [];
                $arrBusinessPlanId = [];
                if (!empty($productions_plan)) {
                    $arr_productions_plan_id = explode(',', $productions_plan);

                    foreach ($arr_productions_plan_id as $key => $value) {
                        if (empty($value)) continue;
                        $arrObject = explode('__', $value);
                        $object_id = $arrObject[1];
                        $object_type = $arrObject[0];
                        $productions_plan_orders[$value] = [
                            'productions_plan_id' => $object_id,
                            'productions_order_id' => 0,
                            'total_quantity' => 0,
                            'count_items' => 0,
                            'object_type' => $object_type,
                        ];

                        if ($object_type == "orders") {
                            $arrOrderId[] = $object_id;
                        } else if ($object_type == "business_plan") {
                            $arrBusinessPlanId[] = $object_id;
                        }
                    }

                    if (!empty($arrOrderId)) {
                        $check_productions_plan = $this->manufactures_model->checkStatusProductionsPlanForOrders($arrOrderId)['reference_no'];
                        if ($check_productions_plan) {
                            $data['result'] = 0;
                            $data['message'] = lang('tnh_review') . ' ' . $check_productions_plan;
                            echo json_encode($data);
                            die;
                        }
                        $productions_plan_reference = $this->manufactures_model->rowReferenceOrdersByArrId($arrOrderId)['reference_no'];
                    }

                    if (!empty($arrBusinessPlanId)) {
                        $check_productions_plan = $this->manufactures_model->checkStatusProductionsPlanForBusinessOrders($arrBusinessPlanId)['reference_no'];
                        if ($check_productions_plan) {
                            $data['result'] = 0;
                            $data['message'] = lang('tnh_review') . ' ' . $check_productions_plan;
                            echo json_encode($data);
                            die;
                        }

                        if (!empty($productions_plan_reference)) {
                            $productions_plan_reference.= ',';
                        }

                        $productions_plan_reference.= $this->manufactures_model->rowReferenceBusinessPlanByArrId($arrBusinessPlanId)['reference_no'];
                    }
                }

                $errors = '';
                $items_id = $this->input->post('items_id');
                if (!empty($items_id)) {
                    foreach ($items_id as $key => $value) {
                        $items_id = $value;
                        $counter = $this->input->post('counter')[$key];
                        $type_items = 'products';
                        $info = false;
                        if ($type_items == "products") {
                            $info = $this->products_model->rowProduct($items_id);
                        }
                        
                        $production_plan_item = $this->input->post('production_plan_item')[$key];
                        if (empty($production_plan_item) || empty($info)) {
                            continue;
                        }

                        $arr_production_plan_item_id = explode('__', $production_plan_item);
                        $production_plan_item_id = $arr_production_plan_item_id[1];
                        $object_item_type = $arr_production_plan_item_id[0];
                        $dtProductionsPlanItems = $this->manufactures_model->getProductionsPlanItemsForObject($production_plan_item_id, $object_item_type);
                        $plan_item_id = $dtProductionsPlanItems['id'];
                        $plan_id = $dtProductionsPlanItems['productions_plan_id'];


                        $items_code = $info['code'];
                        $items_name = $info['name'];
                        $quantity = number_unformat($this->input->post('quantity')[$key]);
                        $note_items = $this->input->post('note_items')[$key];
                        $versions_bom = $this->input->post('versions')[$key];
                        if (empty($versions_bom)) {
                            $data['result'] = 0;
                            $data['message'] = lang('Vui lòng chọn BOM');
                            echo json_encode($data);
                            die;
                        }
                        $versions_stage = $info['versions_stage'];

                        $items[$key] = [
                            'production_plan_item_id' => $production_plan_item_id,
                            'type_items' => $type_items,
                            'items_id' => $items_id,
                            'items_code' => $items_code,
                            'items_name' => $items_name,
                            'quantity' => $quantity,
                            'note_items' => $note_items,
                            'versions_bom' => $versions_bom,
                            'versions_stage' => $versions_stage,
                            'productions_capacity_items_id' => 0,
                            'object_item_type' => $object_item_type,
                            'plan_item_id' => $plan_item_id,
                            'plan_id' => $plan_id,
                            'arrBOM' => []
                        ];


                        if (!empty($production_plan_item)) {
                                $rowProductionPlanItem = false;
                                $object_id = 0;
                                if ($object_item_type == "orders") {
                                    $rowProductionPlanItem = $this->manufactures_model->rowOrdersItemsById($production_plan_item_id);
                                    $object_id = $rowProductionPlanItem['order_id'];
                                } else if ($object_item_type == "business_plan") {
                                    $rowProductionPlanItem = $this->manufactures_model->rowBusinessItemsById($production_plan_item_id);
                                    $object_id = $rowProductionPlanItem['business_plan_id'];
                                }

                                if (!empty($rowProductionPlanItem)) {
                                    $cProductionPlanId = $object_item_type.'__'.$object_id;
                                    $productions_plan_orders[$cProductionPlanId]['count_items'] = $productions_plan_orders[$cProductionPlanId]['count_items'] + 1;
                                    $productions_plan_orders[$cProductionPlanId]['total_quantity'] = $productions_plan_orders[$cProductionPlanId]['total_quantity'] + $quantity;

                                    $quantity_produce = $rowProductionPlanItem['quantity_plan'] - $rowProductionPlanItem['quantity_productions_orders'];
                                    if ($quantity_produce < 0) $quantity_produce = 0;
                                    if ($quantity > $quantity_produce) {
                                        $errors .= '<div>' . $items_code . '(' . $items_name . ') SL <= ' . formatNumber($quantity_produce) . '</div>';
                                        continue;
                                    }
                                } else {
                                    continue;
                                }

                        }

                        $total_quantity += $quantity;
                    }
                }


                if (empty($items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_not_items');
                    echo json_encode($data);
                    die;
                }

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data);
                    die;
                }

                $count_items = count($items);
                $staff_id = get_staff_user_id();
                $date_default = date('Y-m-d H:i:s');
                $options = [
                    'date' => $date,
                    'reference_no' => $reference_no,
                    'location_id' => $location,
                    'productions_plan_id' => $productions_plan,
                    'productions_plan_reference_no' => $productions_plan_reference,
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'note' => $note,
                    'status' => 'approved',
                    'user_status' => $staff_id,
                    'date_status' => $date_default,
                    'date_created' => $date_default,
                    'created_by' => $staff_id,
                    'options1' => $options1,
                    'options2' => $options2,
                ];

                // print_arrays($items, $productions_plan_orders);
                $productions_orders_id = $this->manufactures_model->insertProductionsOrders($options);
                if ($productions_orders_id) {
                    updateReference('productions_orders');
                    // if (getReference('productions_orders') == $this->input->post('reference_no')) {
                    //     updateReference('productions_orders');
                    // }
                    foreach ($items as $key => $value) {
                        $value['productions_orders_id'] = $productions_orders_id;
                        unset($value['arrBOM']);
                        $object_item_type = $value['object_item_type'];
                        $productions_orders_items_id = $this->manufactures_model->insertProductionsOrdersItems($value);
                        if ($productions_orders_items_id) {
                            $this->manufactures_model->updateQuantityProductionOrders($value['production_plan_item_id'], $value['quantity'], $plus = 1, $object_item_type);

                            $object_id = 0;
                            $object_type = $value['object_item_type'];
                            if ($object_type == "orders") {
                                $order_item = $this->orders_model->rowOrderItemsById($value['production_plan_item_id']);
                                $object_id = $order_item['order_id'];
                            } else if ($object_type == "business_plan") {
                                $business_item = $this->manufactures_model->rowBusinessItemsById($value['production_plan_item_id']);
                                $object_id = $business_item['business_plan_id'];
                            }

                            
                        }
                    }

                    if (!empty($productions_plan_orders)) {
                        foreach ($productions_plan_orders as $key => $value) {
                            $value['productions_order_id'] = $productions_orders_id;
                            $object_type = $value['object_type'];
                            if ($this->manufactures_model->insertProductionsPlanOrders($value)) {
                                $statusPL = 2;
                                if ($this->manufactures_model->checkPlanFullByOrder($value['productions_plan_id'], $object_type)) {
                                    $statusPL = 1;
                                }
                                if ($object_type == "orders") {
                                    $this->orders_model->updateOrdersNew($value['productions_plan_id'], ['status_productions_orders' => $statusPL]);
                                } else if ($object_type == "business_plan") {
                                    $this->business_plan_model->updateBusinessPlan($value['productions_plan_id'], ['status_productions_orders' => $statusPL]);
                                }
                            }
                        }
                    }

                    $this->manufactures_model->handlingBomProductionsOrders($productions_orders_id);
                    $this->manufactures_model->handlingProductionsDetail($productions_orders_id);
                    $this->manufactures_model->handlingStagesProductionsOrders($productions_orders_id);

                    noti_custom('create_productions_orders', $productions_orders_id, get_staff_user_id(), 0, '', ['actions' => 'add']);

                    @pusherTNHNotfication();
                    insertActivityLog([
                        'type_parent_obj' => 'productions_orders',
                        'table_obj' => 'tbl_productions_orders',
                        'id_obj' => $productions_orders_id,
                        'name_obj' => $reference_no,
                        'content' => lang('tnh_his_add_productions_orders') . ' [' . $reference_no . ']',
                        'actions' => 'add'
                    ]);

                    set_alert('success', lang('success'));
                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        }
        $data['locations'] = $this->site_model->getBranch();
        $data['reference_no'] = getReference('productions_orders');
        $data['tnh'] = $this->tnh;
        $data['title'] = lang('add_productions_orders');
        $data['breadcrumb'] = [array('link' => base_url('admin/manufactures/productions_orders'), 'page' => lang('productions_orders')), array('link' => '#', 'page' => lang('add_productions_orders'))];
        $this->load->view('admin/manufactures/add_productions_orders', $data);
    }

    public function edit_productions_orders($id)
    {
        die;
        ini_set('max_execution_time', 300);
        if (!$this->perEditProductionsOrders) {
            accessDenied();
        }

        $productions_orders = $this->manufactures_model->rowProductionsOrdersById($id);
        if (empty($productions_orders)) {
            set_alert('danger', lang('no_data_exists'));
            redirect($_SERVER["HTTP_REFERER"]);
            die;
        }
        if ($productions_orders['status'] == "approved") {
            set_alert('danger', lang('browsed_cannot_be_edited'));
            redirect($_SERVER["HTTP_REFERER"]);
            die;
        }

        checkMyData($productions_orders['created_by']);

        $productions_orders_items = $this->manufactures_model->getProductionOrdersItemsAndProducts($id);
        if ($this->input->post('save')) {
            $data = [];
