                $this->form_validation->set_rules('reference_no', lang("tnh_reference_productions_orders"), 'trim|required|is_unique[tbl_productions_orders.reference_no]');
            }
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('location', lang("tnh_location"), 'required');
            if ($this->form_validation->run() == true) {
                $reference_no = $this->input->post('reference_no');
                $date = to_sql_date($this->input->post('date'), true);
                $note = $this->input->post('note', false);
                $location = $this->input->post('location');
                $productions_plan = $productions_orders['productions_plan_id'];
                $total_quantity = 0;
                $count_items = 0;

                // print_arrays($productions_plan);

                // $productions_plan_reference = '';
                if (!empty($productions_plan)) {

                    $arr_productions_plan_id = explode(',', $productions_plan);
                    foreach ($arr_productions_plan_id as $key => $value) {
                        $productions_plan_orders[$value] = [
                            'productions_plan_id' => $value,
                            'productions_order_id' => 0,
                            'total_quantity' => 0,
                            'count_items' => 0,
                        ];
                    }
                }

                $items_id = $this->input->post('items_id');
                foreach ($items_id as $key => $value) {
                    $items_id = $value;
                    $counter = $this->input->post('counter')[$key];
                    $type_items = 'products';
                    if ($type_items == "products") {
                        $info = $this->products_model->rowProduct($items_id);
                    }
                    if (empty($info)) {
                        continue;
                    }
                    $production_plan_item = $this->input->post('production_plan_item')[$key];

                    $items_code = $info['code'];
                    $items_name = $info['name'];
                    $quantity = number_unformat($this->input->post('quantity')[$key]);
                    $note_items = $this->input->post('note_items')[$key];
                    $versions_bom = $info['versions'];
                    $versions_stage = $info['versions_stage'];

                    $items[] = [
                        'production_plan_item_id' => $production_plan_item,
                        'productions_orders_id' => $id,
                        'type_items' => $type_items,
                        'items_id' => $items_id,
                        'items_code' => $items_code,
                        'items_name' => $items_name,
                        'quantity' => $quantity,
                        'note_items' => $note_items,
                        'versions_bom' => $versions_bom,
                        'versions_stage' => $versions_stage,
                    ];

                    if (!empty($production_plan_item)) {
                        $rowProductionPlanItem = $this->manufactures_model->rowProductionsPlanItemsById($production_plan_item);
                        // print_arrays($rowProductionPlanItem);
                        if (!empty($rowProductionPlanItem)) {
                            $cProductionPlanId = $rowProductionPlanItem['productions_plan_id'];
                            $productions_plan_orders[$cProductionPlanId] = [
                                'productions_plan_id' => $cProductionPlanId,
                                'productions_order_id' => $id,
                                'count_items' => $productions_plan_orders[$cProductionPlanId]['count_items'] + 1,
                                'total_quantity' => $productions_plan_orders[$cProductionPlanId]['total_quantity'] + $quantity
                            ];
                        }
                    }

                    $total_quantity += $quantity;
                }

                if (empty($items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_not_items');
                    echo json_encode($data);
                    die;
                }

                $count_items = count($items);

                $options = [
                    'date' => $date,
                    'reference_no' => $reference_no,
                    'location_id' => $location,
                    // 'productions_plan_id' => $productions_plan,
                    // 'productions_plan_reference_no' => $productions_plan_reference,
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'note' => $note,
                    'status' => 'un_approved',
                    'date_updated' => date('Y-m-d H:i'),
                    'updated_by' => get_staff_user_id(),
                ];
                // print_arrays($productions_plan_orders);
                $itemsOld = $this->manufactures_model->getProductionsOrdersItems($id);
                $up = $this->manufactures_model->updateProductionsOrders($id, $options);
                if ($up) {
                    $this->manufactures_model->deleteProductionsPlanOrders($id);
                    $this->manufactures_model->deleteProductionsOrdersItems($id);
                    $this->manufactures_model->deleteProductionsOrdersItemsSub($id);
                    $this->manufactures_model->deleteProductionsOrdersItemsStages($id);

                    foreach ($itemsOld as $key => $value) {
                        $this->manufactures_model->updateQuantityProductionOrders($value['production_plan_item_id'], $value['quantity'], $minus = 2);
                    }
                    foreach ($items as $key => $value) {
                        if ($this->manufactures_model->insertProductionsOrdersItems($value)) {
                            $this->manufactures_model->updateQuantityProductionOrders($value['production_plan_item_id'], $value['quantity'], $plus = 1);
                        }
                    }
                    // $this->manufactures_model->insertBatchProductionsOrdersItems($items);
                    if (!empty($arr_productions_plan_id)) {
                        if (!empty($productions_plan_orders)) {
                            foreach ($productions_plan_orders as $key => $value) {
                                if ($this->manufactures_model->insertProductionsPlanOrders($value)) {
                                    $statusPL = 2;
                                    if ($this->manufactures_model->checkPlanFullByOrder($value['productions_plan_id'])) {
                                        $statusPL = 1;
                                    }
                                    $this->manufactures_model->updateProductionsPlan($value['productions_plan_id'], ['productions_orders_id' => $statusPL]);
                                }
                            }
                        }
                    }

                    //more
                    $sub = [];
                    $productions_orders_items = $this->manufactures_model->getProductionsOrdersItems($id);
                    foreach ($productions_orders_items as $key => $value) {
                        $type_items = $value['type_items'];
                        if ($type = "products") {
                            $item_id = $value['items_id'];
                            $quantity = $value['quantity'];

                            //sub
                            $versions_bom = $value['versions_bom'];
                            $version = $this->products_model->getBomByProductIdAndVersions($item_id, $versions_bom);
                            $elements = $this->products_model->getVersionsElementByVersionId($version['id']);
                            $iiPartent = 0;
                            if (!empty($elements)) {
                                foreach ($elements as $k => $val) {
                                    $quantity_element = $val['quantity'];
                                    $total_quantity_element = $quantity * $quantity_element;
                                    $sub[$iiPartent] = [
                                        'productions_orders_id' => $id,
                                        'productions_orders_items_id' => $value['id'],
                                        'type' => 'element',
