                                                if (!empty($row_exchange)) {
                                                    $quantity_exchange = $row_exchange['number_exchange'];
                                                }
                                                $quantity_primary = $total_quantity_item / $quantity_exchange;
                                            }

                                            $sub[$iiPartent] = [
