                                                'quantity_primary' => $quantity_primary
                                            ];

                                            $elementItemsInsert = $this->manufactures_model->insertProductionOrdersItemsSub($sub[$iiPartent]);
                                            if ($elementItemsInsert) {
                                                //handling material replace
                                                $element_item_id = $el['id'];
                                                $elementReplace = $this->products_model->getElementItemsReplaceByElementItemId($element_item_id);

                                                if (!empty($elementReplace)) {
                                                    foreach ($elementReplace as $kk => $vv) {
                                                        $quantity_single_replace = $vv['quantity_replace'];
                                                        $total_quantity_item_replace = $total_quantity_element * $quantity_single_replace;
                                                        $unit_id_replace = $vv['unit_id_replace'];

                                                        if ($vv['type_replace'] == "semi_products" || $vv['type_replace'] == "semi_products_outside") {
                                                            $infoReplace = $this->products_model->rowProduct($vv['item_id_replace']);
                                                            $quantity_exchange_replace = 1;
                                                            $unit_parent_replace_id = $infoReplace['unit_id'];
                                                            $quantity_replace_primary = $total_quantity_item_replace;
                                                        } else {
