                                                            }
                                                            $quantity_replace_primary = $total_quantity_item_replace / $quantity_exchange_replace;
                                                        }

                                                        $rp = [
                                                            'productions_orders_id' => $id,
                                                            'productions_orders_items_id' => $value['id'],
                                                            'parent_id' => $elementItemsInsert,
                                                            'type' => $vv['type_replace'],
                                                            'item_id' => $vv['item_id_replace'],
                                                            'item_code' => $infoReplace['code'],
                                                            'item_name' => $infoReplace['name'],
                                                            'unit_id' => $unit_id_replace,
                                                            'quantity_single' => $quantity_single_replace,
                                                            'quantity' => $total_quantity_item_replace,
                                                            'unit_parent_id' => $unit_parent_replace_id,
                                                            'quantity_exchange' => $quantity_exchange_replace,
                                                            'quantity_primary' => $quantity_replace_primary,
                                                            'leadtime' => $vv['leadtime_replace'],
                                                            'stage_item_id' => $vv['stage_id_replace'],
                                                            'type_replace' => 1,
                                                        ];
                                                        $this->manufactures_model->insertProductionOrdersItemsSub($rp);
                                                    }
                                                }
                                            }
                                            //end handling material replace
                                            $iiPartent++;
                                        }
                                    }
                                }
                            }
                            //end sub

                            //stages
                            $versions_stage = $value['versions_stage'];
                            $vs = $this->products_model->getProductStagesByProductIdAndVersions($item_id, $versions_stage);
                            if (!empty($vs)) {
                                $product_stages = $this->products_model->getProductStagesVersions($vs['id']);
                                if (!empty($product_stages)) {
                                    foreach ($product_stages as $i => $el) {
                                        $stages[] = [
