    public function view_productions_orders($id)
    {
        if (!$this->perViewProductionsOrders && !$this->perViewOwnProductionsOrders) {
            accessDenied($js = true);
        }

        $productions_orders = $this->manufactures_model->rowProductionsOrdersById($id);
        $location = $this->site_model->getBranchById($productions_orders['location_id']);
        $productions_orders_items = $this->manufactures_model->getProductionOrdersItemsAndProducts($id);
        $subs = $this->manufactures_model->getProductionsOrdersItemsSubTotalView($id);

        if (!$this->perViewProductionsOrders) {
            checkMyData($productions_orders['created_by'], true);
        }

        if (!empty($productions_orders['updated_by'])) {
            $data['updated_by'] = get_staff_full_name($productions_orders['updated_by']);
        } else {
            $data['updated_by'] = '';
        }
        if ($productions_orders['user_status']) {
            $data['user_status'] = get_staff_full_name($productions_orders['user_status']);
        } else {
            $data['user_status'] = '';
        }
        $data['created_by'] = get_staff_full_name($productions_orders['created_by']);
        $data['productions_orders'] = $productions_orders;
        $data['productions_orders_items'] = $productions_orders_items;
        $data['subs'] = $subs;
        $data['location'] = $location;
        $data['id'] = $id;
        $this->load->view('admin/manufactures/view_productions_orders', $data);
    }

    function delete_productions_orders($id)
    {
        $data = [];
        //check permision
        if (!$this->perDeleteProductionsOrders) {
            $data['result'] = 0;
            $data['message'] = lang('access_denied');
            echo json_encode($data);
            die;
        }
        //end
        if ($id) {
            $productions_orders = $this->manufactures_model->rowProductionsOrdersById($id);
            if (!checkMyDataTF($productions_orders['created_by'])) {
                $data['result'] = 0;
                $data['message'] = lang('access_denied');
                echo json_encode($data);
                die;
            }

            $items = $this->manufactures_model->getProductionsOrdersItems($id);
            $itemsSub = $this->manufactures_model->getProductionsOrdersItemsSub($id);
            $productions_plan_orders = $this->manufactures_model->getProductionsPlanOrders($id);

            $check = $this->manufactures_model->checkCoditionDeleteDetail($id);
            if (!empty($check)) {
                $data['result'] = 0;
                $data['message'] = $check;
                echo json_encode($data);
                die;
            }
            $productionsOD = $this->manufactures_model->getProductionsOrdersDetails($id);
            // if ($productions_orders['status_details'] == 0) {
                if ($this->manufactures_model->deleteProductionsOrders($id)) {

                    foreach ($items as $key => $value) {
                        $this->manufactures_model->updateQuantityProductionOrders($value['production_plan_item_id'], $value['quantity'], $minus = 2, $value['object_item_type']);

                        if (!empty($productions_orders['productions_plan_id'])) {
                            $this->manufactures_model->updateQuantityPCI($value['productions_capacity_items_id'], $value['quantity'], $minus = 2, $value['object_item_type']);
                        }
                    }

                    if (!empty($productions_plan_orders)) {
                        foreach ($productions_plan_orders as $key => $value) {
                            $statusPL = 0;
                            if ($this->manufactures_model->checkPlanQtyByOrder($value['productions_plan_id'], $value['object_type'])) $statusPL = 1;
                            if ($value['object_type'] == "orders") {
                                $this->orders_model->updateOrdersNew($value['productions_plan_id'], ['status_productions_orders' => $statusPL]);
                            } else if ($value['object_type'] == "business_plan") {
                                $this->business_plan_model->updateBusinessPlan($value['productions_plan_id'], ['status_productions_orders' => $statusPL]);
                            }
                        }
                    }

                    $this->manufactures_model->deleteProductionsOrdersItems($id);
                    $this->manufactures_model->deleteProductionsPlanOrders($id);
                    $this->manufactures_model->deleteProductionsOrdersItemsSub($id);
                    $this->manufactures_model->deleteProductionsOrdersItemsStages($id);

                    $this->manufactures_model->deleteProductionsOdersDetail($id);
                    foreach ($productionsOD as $key => $value) {
                        $this->manufactures_model->deleteUpdateInfoStageByProductionODId($value['id']);
                        $this->manufactures_model->deleteQuantityFinishedPreByProductionODId($value['id']);
                        $this->manufactures_model->deletePODEmployeesByPODId($value['id']);
                        $this->manufactures_model->deletePODDepartments($value['id']);

                        //handling taks
                        $tasks = $this->site_model->getTasksByRelTypeAndRelId($value['id'], 'order_production_details');
                        if (!empty($tasks)) {
                            $this->site_model->deleteTasksByRelIdAndRelType($value['id'], 'order_production_details');
                            foreach ($tasks as $k => $val) {
                                $this->site_model->deleteTaskAssigned($val['id']);
                            }
                        }
                        //
                    }

                    noti_custom('create_productions_orders', $id, get_staff_user_id(), 0, '', ['actions' => 'delete']);
                    insertActivityLog([
                        'type_parent_obj' => 'productions_orders',
                        'table_obj' => 'tbl_productions_orders',
                        'id_obj' => $id,
                        'name_obj' => $productions_orders['reference_no'],
                        'content' => lang('tnh_his_delete_productions_orders') . ' [' . $productions_orders['reference_no'] . ']',
                        'actions' => 'delete'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            // } else {
            //     $data['result'] = 0;
            //     $data['message'] = lang('Đã tạo LSX chi tiết không thể xóa');
            // }
        } else {
            $data['result'] = 0;
            $data['message'] = lang('fail');
        }
        echo json_encode($data);
    }

    function delete_productions_orders_detail($id)
    {
        die;
        $data = [];
        if ($id) {
            $productions_orders = $this->manufactures_model->rowProductionsOrdersById($id);
            if ($productions_orders['status'] == "approved") {
                $check = $this->manufactures_model->checkCoditionDeleteDetail($id);
                if (!empty($check)) {
                    $data['result'] = 0;
                    $data['message'] = $check;
                    echo json_encode($data);
                    die;
                }
                $productionsOD = $this->manufactures_model->getProductionsOrdersDetails($id);
                if ($this->manufactures_model->deleteProductionsOdersDetail($id)) {
                    $this->manufactures_model->updateProductionsOrders($id, ['status_details' => 0]);
                    foreach ($productionsOD as $key => $value) {
                        $this->manufactures_model->deleteUpdateInfoStageByProductionODId($value['id']);
                        $this->manufactures_model->deleteQuantityFinishedPreByProductionODId($value['id']);
                        $this->manufactures_model->deletePODEmployeesByPODId($value['id']);
                        $this->manufactures_model->deletePODDepartments($value['id']);

                        //handling taks
                        $tasks = $this->site_model->getTasksByRelTypeAndRelId($value['id'], 'order_production_details');
                        if (!empty($tasks)) {
                            $this->site_model->deleteTasksByRelIdAndRelType($value['id'], 'order_production_details');
                            foreach ($tasks as $k => $val) {
                                $this->site_model->deleteTaskAssigned($val['id']);
                            }
                        }
                        //
                    }

                    // $this->manufactures_model->deletePODEmployeesByPODId($id);
                    insertActivityLog([
                        'type_parent_obj' => 'productions_orders',
                        'table_obj' => 'tbl_productions_orders',
                        'id_obj' => $id,
                        'name_obj' => $productions_orders['reference_no'],
                        'content' => lang('tnh_his_delete_detail_productions_orders') . ' [' . $productions_orders['reference_no'] . ']',
                        'actions' => 'delete_detail'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = lang('fail');
            }
        } else {
            $data['result'] = 0;
            $data['message'] = lang('fail');
        }
        echo json_encode($data);
    }

    function agreeProductionsOrders()
    {
        $data = [];

        if (!$this->perApproveProductionsOrders) {
            $data['result'] = 0;
            $data['message'] = lang('access_denied');
            echo json_encode($data);
            die;
        }

        if ($this->input->get()) {
            $productions_orders_id = $this->input->get('productions_orders_id');
            $status = $this->input->get('status');
            $productions_orders = $this->manufactures_model->rowProductionsOrdersById($productions_orders_id);
            if ($productions_orders['status_details']) {
                $data['result'] = 0;
                $data['message'] = lang('tnh_created_an_order_details_not_unapproved');
                echo json_encode($data);
                die;
            }
            $date = date('Y-m-d H:i');
            $user_id = get_staff_user_id();
            if ($productions_orders['status'] == $status) {
                $data['result'] = 0;
                $data['message'] = lang('tnh_please_referesh_table');
                echo json_encode($data);
                die;
            }
            $up = $this->manufactures_model->updateProductionsOrders($productions_orders_id, [
                'status' => $status,
                'date_status' => $date,
                'user_status' => $user_id
            ]);
            if ($up) {
                @pusherTNHNotfication();
                insertActivityLog([
                    'type_parent_obj' => 'productions_orders',
                    'table_obj' => 'tbl_productions_orders',
                    'id_obj' => $productions_orders_id,
                    'name_obj' => $productions_orders['reference_no'],
                    'content' => lang('tnh_his_agree_productions_orders') . ' [' . $productions_orders['reference_no'] . ']',
                    'actions' => 'edit'
                ]);

                if ($status == "approved") {
                    $userList = $this->staff_model->getStaff();
                    $notifiedUsers = [];

                    $query_str = "SELECT * FROM tbl_productions_orders where id = $productions_orders_id";
                    $query = $this->db->query($query_str);
                    foreach ($query->result() as $row) {
                        $dataHtml = 'Phiếu LỆNH SX TỔNG ' . $row->reference_no . ' vừa được duyệt bởi ';
                    }

                    foreach ($userList as $key => $value) {
                        $notification_data = [
                            'description' => $dataHtml,
                            'touserid' => $key,
                            'link' => 'change_management/?id=' . $productions_orders_id,
                            'onchange' => ' onclick="view_change_gif(' . $productions_orders_id . '); return false;" ',
                        ];

                        if (add_notification($notification_data)) {
                            array_push($notifiedUsers, $value['staffid']);
                        }
                        pusher_trigger_notification($notifiedUsers);
                    }
                }
                $data['result'] = 1;
                $data['message'] = lang('success');
            } else {
                $data['result'] = 0;
                $data['message'] = lang('fail');
            }
        }
        echo json_encode($data);
    }

    function refereshReferenceProductionsOrders()
    {
        $data = [];
        if ($this->input->get('referesh')) {
            $reference_no = getReference('productions_orders');
            if ($this->manufactures_model->checkExistProductionsOrdersByReferenceNo($reference_no)) {
                $ct = countReferenceMinus('productions_orders');
                $this->db->select("MAX(right(tbl_productions_orders.reference_no, char_length(tbl_productions_orders.reference_no) - $ct) + 0) as reference_no", false);
                $this->db->from('tbl_productions_orders');
                $rs = $this->db->get()->row_array();

                $max = $rs['reference_no'];
                $max++;
                updateReferenceNormal('productions_orders', $max);
                $reference_no = getReference('productions_orders');
            }
            $data['reference_no'] = $reference_no;
            $data['message'] = lang('tnh_referesh_success');
        }
        echo json_encode($data);
    }

    function searchProductionsPlanForOrders($id = false)
    {
        $data = [];
        $term = $this->input->get('term', TRUE);
        $limit = get_option('select2_limit');
        $params = $this->input->get('params');
        $cOrders = $params['cOrders'];
        $cBusiness = $params['cBusiness'];
        $data['results'] = [];
        if (!empty($cOrders)) {
            $isOrderItems = "(
                SELECT tbl_order_items.id
                FROM tbl_order_items
                WHERE tbl_order_items.order_id = tbl_orders.id AND tbl_order_items.quantity_plan > tbl_order_items.quantity_productions_orders
            )";

            $this->db->select('
                CONCAT("orders__", tbl_orders.id) as id,
                tbl_orders.id as order_id,
                CONCAT("ĐHB: ", tbl_orders.reference_no, "(", DATE_FORMAT(tbl_orders.date, "%d/%m/%Y"),")") as text,
                tblclients.company as company,
            ', false);
            $this->db->from('tbl_orders');
            $this->db->join('tblclients', 'tblclients.userid = tbl_orders.customer_id');
            $this->db->where('tbl_orders.status', 'approved');
            $this->db->where("EXISTS ($isOrderItems)");
            if (!empty($term)) {
                $this->db->group_start();
                $this->db->like('tbl_orders.reference_no', $term);
                $this->db->or_like('tblclients.company', $term);
                $this->db->or_like('tbl_orders.note', $term);
                $this->db->group_end();
            }
            $this->db->limit($limit);
            $orders = $this->db->get()->result_array();
            if (!empty($orders)) {
                foreach($orders as $key => $value) {
                    $order_id = $value['order_id'];
                    $this->db->select('
                        tbl_products.code as item_code,
                        tbl_products.name as item_name
                    ');
                    $this->db->from('tbl_order_items');
                    $this->db->join('tbl_products', 'tbl_products.id = tbl_order_items.item_id');
                    $this->db->where('tbl_order_items.type_item', 'products');
                    $this->db->where('tbl_order_items.order_id', $order_id);
                    $this->db->where('(tbl_order_items.quantity_plan > tbl_order_items.quantity_productions_orders)');
                    $this->db->where_in('tbl_products.type_products', ['products', 'semi_products']);
                    $order_items = $this->db->get()->result_array();
                    $orders[$key]['items'] = $order_items;
                }
            }
            $data['results'][] = ['text' => lang('orders'), 'children' => $orders];
        }

        if (!empty($cBusiness)) {
            $isbusinessPlan = "(
                SELECT tbl_business_plan_items.id
                FROM tbl_business_plan_items
                WHERE tbl_business_plan_items.business_plan_id = tbl_business_plan.id AND tbl_business_plan_items.quantity_plan > tbl_business_plan_items.quantity_productions_orders
            )";

            $this->db->select('
                CONCAT("business_plan__", tbl_business_plan.id) as id,
                tbl_business_plan.id as business_plan_id,
                CONCAT("KHBTP: ", tbl_business_plan.reference_no, "(", DATE_FORMAT(tbl_business_plan.date, "%d/%m/%Y"),")") as text,
                "" as company,
            ', false);
            $this->db->from('tbl_business_plan');
            $this->db->where('tbl_business_plan.status !=', 'un_approved');
            $this->db->where("EXISTS ($isbusinessPlan)");
            if (!empty($term)) {
                $this->db->group_start();
                $this->db->like('tbl_business_plan.reference_no', $term);
                $this->db->or_like('tbl_business_plan.plan_name', $term);
                $this->db->group_end();
            }
            $this->db->limit($limit);
            $business_plan = $this->db->get()->result_array();
            if (!empty($business_plan)) {
                foreach($business_plan as $key => $value) {
                    $business_plan_id = $value['business_plan_id'];
                    $this->db->select('
                        tbl_products.code as item_code,
                        tbl_products.name as item_name
                    ');
                    $this->db->from('tbl_business_plan_items');
                    $this->db->join('tbl_products', 'tbl_products.id = tbl_business_plan_items.items_id');
                    $this->db->where('tbl_business_plan_items.type_items', 'products');
                    $this->db->where('tbl_business_plan_items.business_plan_id', $business_plan_id);
                    $this->db->where('(tbl_business_plan_items.quantity_plan > tbl_business_plan_items.quantity_productions_orders)');
                    $this->db->where_in('tbl_products.type_products', ['products', 'semi_products']);
                    $business_plan_items = $this->db->get()->result_array();
                    $business_plan[$key]['items'] = $business_plan_items;
                }
            }
            $data['results'][] = ['text' => lang('business_plan'), 'children' => $business_plan];
        }

        echo json_encode($data);
    }

