    function getProductionsPlanItem()
    {
        $data = [];
        $productions_plan_id = $this->input->post('productions_plan_id');
        $data['result'] = false;
        if (!empty($productions_plan_id)) {
            $productions_plan_id = explode(',', $productions_plan_id);
            $arr_order_id = [];
            $arr_business_id = [];

            if (!empty($productions_plan_id)) {
                foreach ($productions_plan_id as $key => $value) {
                    $arrProductionsPlan = explode('__', $value);
                    $object_type = $arrProductionsPlan[0];
                    $object_id = $arrProductionsPlan[1];
                    if ($object_type == "orders") {
                        $arr_order_id[] = $object_id;
                    } else if ($object_type == "business_plan") {
                        $arr_business_id[] = $object_id;
                    }
                }
            }

            $result = [];
            if (!empty($arr_order_id)) {
                $this->db->select('
                    tbl_orders.reference_no as reference_no,
                    tbl_orders.id as production_plan_id,
                    CONCAT("orders__", tbl_order_items.id) as production_plan_item_id,
                    tbl_products.id as product_id,
                    tbl_products.code,
                    tbl_products.name,
                    IF(tbl_products.images IS NOT NULL && tbl_products.images != "", CONCAT("uploads/products/", "", tbl_products.images, ""), "") as images,
                    (tbl_order_items.quantity_plan - tbl_order_items.quantity_productions_orders) as total_quantity,
                    tbl_products.versions as versions,
                    tbl_order_items.quantity_plan as quantity_plan,
                    tbl_order_items.quantity as quantity,
                    ', false);
                $this->db->from('tbl_orders');
                $this->db->join('tbl_order_items', 'tbl_order_items.order_id = tbl_orders.id');
                $this->db->join('tbl_products', 'tbl_products.id = tbl_order_items.item_id');
                $this->db->where('tbl_orders.status', 'approved');
                $this->db->where_in('tbl_orders.id', $arr_order_id);
                $this->db->where('tbl_order_items.quantity_plan > tbl_order_items.quantity_productions_orders');
                $orders = $this->db->get()->result_array();
                $result = array_merge($result, $orders);
            }
            if (!empty($arr_business_id)) {
                $this->db->select('
                    tbl_business_plan.reference_no as reference_no,
                    tbl_business_plan.id as production_plan_id,
                    CONCAT("business_plan__", tbl_business_plan_items.id) as production_plan_item_id,
                    tbl_products.id as product_id,
                    tbl_products.code,
                    tbl_products.name,
                    IF(tbl_products.images IS NOT NULL && tbl_products.images != "", CONCAT("uploads/products/", "", tbl_products.images, ""), "") as images,
                    (tbl_business_plan_items.quantity_plan - tbl_business_plan_items.quantity_productions_orders) as total_quantity,
                    tbl_products.versions as versions,
                    tbl_business_plan_items.quantity_plan as quantity_plan,
                    tbl_business_plan_items.quantity as quantity,
                ', false);
                $this->db->from('tbl_business_plan');
                $this->db->join('tbl_business_plan_items', 'tbl_business_plan_items.business_plan_id = tbl_business_plan.id');
                $this->db->join('tbl_products', 'tbl_products.id = tbl_business_plan_items.items_id');
                $this->db->where('tbl_business_plan.status !=', 'un_approved');
                $this->db->where_in('tbl_business_plan.id', $arr_business_id);
                $this->db->where('tbl_business_plan_items.type_items', 'products');
                $business_plan = $this->db->get()->result_array();
                $result = array_merge($result, $business_plan);
            } 

            if (!empty($result)) {
                foreach ($result as $key => $value) {
                    $products_id = $value['product_id'];
                    $versions = $value['versions'];

                    $this->db->select('tbl_product_versions.versions as versions');
                    $this->db->from('tbl_product_versions');
                    $this->db->where('tbl_product_versions.product_id', $products_id);
                    $product_verions = $this->db->get()->result_array();
                    $optionsVersions = "<option></option>";
                    if (!empty($product_verions)) {
                        foreach ($product_verions as $k => $val) {
                            $selected = ($versions == $val['versions']) ? 'selected' : '';
                            $optionsVersions.= '<option '.$selected.' value="'.$val['versions'].'">'.$val['versions'].'</option>';
                        }
                    }
                    $result[$key]['optionsVersions'] = $optionsVersions;
                }
            }
            $data['result'] = $result;
        }
        echo json_encode($data);
    }

