    function created_productions_detail($id)
    {
        $productions_orders = $this->manufactures_model->rowProductionsOrdersById($id);
        $items = $this->manufactures_model->getProductionsORdersItemsForCreated($id);
        if ($productions_orders['status'] != "approved") {
            refererModel(lang('tnh_please_approved'));
        }
        if ($productions_orders['status_details']) {
            refererModel(lang('tnh_created_an_order_details'));
        }
        if ($this->input->post('save')) {
            $data = [];
            $this->form_validation->set_rules('deadline[]', lang("deadline"), 'required');
            $this->form_validation->set_rules('departments[]', lang("departments"), 'required');
            $this->form_validation->set_rules('employess[]', lang("staff_admin"), 'required');
            // $this->form_validation->set_rules('phan_cong[]', lang("Phân công"), 'required');
            $details = [];
            if ($this->form_validation->run() == true) {
                $flag = false;
                foreach ($items as $key => $value) {
                    $deadline = $this->input->post('deadline')[$key] ? to_sql_date($this->input->post('deadline')[$key]) : '0000-00-00';
                    $departments = $this->input->post('departments')[$key];

                    $dateCreated = date('Y-m-d H:i:s');
                    $created_by = get_staff_user_id();
                    $reference_no = getReference('productions_orders_details');
                    $details = [
                        'reference_no' => $reference_no,
                        'productions_orders_id' => $id,
                        'productions_orders_item_id' => $value['id'],
                        'deadline' => $deadline,
                        'departments' => implode(',', $departments),
                        'status' => 'un_produced',
                        'created_by' => $created_by,
                        'date_created' => $dateCreated,
                    ];

                    $pod_id = $this->manufactures_model->insertProductionsOrdersDetails($details);
                    if ($pod_id) {
                        $flag = true;
                        updateReference('productions_orders_details');
                        $employees = $this->input->post('employess')[$key];
                        $emp = [];
                        if (!empty($employees)) {
                            foreach ($employees as $k => $val) {
                                $emp[] = [
                                    'employee_id' => $val,
                                    'productions_orders_details_id' => $pod_id,
                                ];
                            }
                            if (!empty($emp)) {
                                $this->manufactures_model->insertBatchPODEmployees($emp);
                            }
                        }

                        if (!empty($departments)) {
                            foreach ($departments as $k => $val) {
                                $depart = [
                                    'pod_id' => $pod_id,
                                    'department_id' => $val,
                                ];
                                $this->manufactures_model->insertPODDepartments($depart);
                            }
                        }

                        //task shift work
                        $shift_works = !empty($this->input->post('shift_work')[$value['id']]) ? $this->input->post('shift_work')[$value['id']] : null;
                        if (!empty($shift_works)) {
                            foreach ($shift_works as $kk => $vv) {
                                $dtShiftWork = $this->site_model->getShiftWorkById($vv);
                                $counterShiftWork = $this->input->post('counterShiftWork')[$value['id']][$kk];
                                $quantityShiftWork = $this->input->post('quantity_shift_work')[$value['id']][$kk];
                                $staff_shift_work = $this->input->post('staff_shift_work')[$counterShiftWork];

                                $rel_id = $pod_id;
                                $rel_type = 'order_production_details';
                                $items_code = $value['items_code'];
                                $items_name = $value['items_name'];

                                $subject = $dtShiftWork['name'] . ' LSXCT ' . $reference_no;
                                $description = '
                                <div>Tên công việc: ' . $subject . '</div>
                                <div>Ngày bắt đầu: ' . _d($dateCreated) . '</div>
                                <div>Ngày kết thúc: ' . _d($deadline) . '</div>
                                <div>Mặt hàng: ' . $items_name . '(' . $items_code . ')</div>
                                <div>Ca làm việc: ' . $dtShiftWork['name'] . '</div>
                                <div>Số lượng: ' . $quantityShiftWork . '</div>
                            ';

                                $dataTask = [
                                    'name' => $subject,
                                    'description' => $description,
                                    'priority' => 2,
                                    'dateadded' => date('Y-m-d H:i:s'),
                                    'startdate' => $dateCreated,
                                    'duedate' => $deadline,
                                    'addedfrom' => 1,
                                    'is_added_from_contact' => 0,
                                    'status' => 4,
                                    'rel_id' => $rel_id,
                                    'rel_type' => $rel_type,
                                    'is_public' => 0,
                                    'billable' => 1,
                                    'shift_work' => $vv,
                                    'quantity_shift_work' => $quantityShiftWork,
                                ];

                                // print_arrays($dataTask);

                                $taskId = $this->site_model->insertTasks($dataTask);
                                if ($taskId) {
                                    $assigned = [];
                                    if (!empty($staff_shift_work)) {
                                        foreach ($staff_shift_work as $k => $val) {
                                            $assigned = [
                                                'staffid' => $val,
                                                'taskid' => $taskId,
                                                'assigned_from' => 1,
                                                'is_assigned_from_contact' => 0,
                                            ];
                                            $assigneeId = $this->site_model->insertTasksAssigned($assigned);
                                            if ($assigneeId > 0) {
                                                //created notification

                                                $notification_data = [
                                                    'description' => $subject,
                                                    'touserid' => $val,
                                                    'link' => '#taskid=' . $taskId,
                                                ];

                                                $notification_data['additional_data'] = serialize([
                                                    $description,
                                                ]);

                                                if (add_notification($notification_data)) {
                                                    pusher_trigger_notification([$val]);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        //end task 
                    }
                }
                if ($flag == true) {
                    $this->manufactures_model->updateProductionsOrders($id, ['status_details' => 1]);
                    //handling taks and email if click chonse
                    $task = $this->input->post('task');
                    $email = $this->input->post('email');
                    $zalo = $this->input->post('zalo');

                    if (!empty($task)) {
                        $listPOI = $this->manufactures_model->getDataForTaskAndEmail($id);
                        if (!empty($listPOI)) {
                            foreach ($listPOI as $key => $value) {
                                $rel_id = $value['id'];
                                $rel_type = 'order_production_details';
                                $items_code = $value['items_code'];
                                $items_name = $value['items_name'];
                                $quantity = $value['quantity'];
                                $reference_no = $value['reference_no'];
                                $date_created = $value['date_created'];
                                $deadline = $value['deadline'];

                                $subject = lang('tnh_assignment_productions') . ' ' . $reference_no;
                                $description = '
                                    <div>Tên công việc: ' . $subject . '</div>
                                    <div>Ngày bắt đầu: ' . _d($date_created) . '</div>
                                    <div>Ngày kết thúc: ' . _d($deadline) . '</div>
                                    <div>Mặt hàng: ' . $items_name . '(' . $items_code . ')</div>
                                    <div>Số lượng: ' . $quantity . '</div>
                                ';

                                $dataTask = [
                                    'name' => $subject,
                                    'description' => $description,
                                    'priority' => 2,
                                    'dateadded' => date('Y-m-d H:i:s'),
                                    'startdate' => $date_created,
                                    'duedate' => $deadline,
                                    'addedfrom' => 1,
                                    'is_added_from_contact' => 0,
                                    'status' => 4,
                                    'rel_id' => $rel_id,
                                    'rel_type' => $rel_type,
                                    'is_public' => 0,
                                    'billable' => 1,
                                ];

                                $taskId = $this->site_model->insertTasks($dataTask);
                                if ($taskId) {
                                    $employees = $this->manufactures_model->getPODEmployees($rel_id);
                                    $assigned = [];
                                    if (!empty($employees)) {
                                        foreach ($employees as $key => $value) {
                                            $assigned = [
                                                'staffid' => $value['employee_id'],
                                                'taskid' => $taskId,
                                                'assigned_from' => 1,
                                                'is_assigned_from_contact' => 0,
                                            ];
                                            $assigneeId = $this->site_model->insertTasksAssigned($assigned);
                                            if ($assigneeId > 0) {
                                                //created notification
                                                $this->db->select('name,visible_to_client,rel_id,rel_type');
                                                $this->db->where('id', $taskId);
                                                $task = $this->db->get(db_prefix() . 'tasks')->row();

                                                $notification_data = [
                                                    'description' => $subject,
                                                    'touserid' => $value['employee_id'],
                                                    'link' => '#taskid=' . $taskId,
                                                ];

                                                $notification_data['additional_data'] = serialize([
                                                    $task->name,
                                                ]);

                                                if (add_notification($notification_data)) {
                                                    pusher_trigger_notification([$value['employee_id']]);
                                                }
                                            }
                                        }
                                        // $assigned = $this->site_model->insertBatchTasksAssigned($assigned);
                                    }
                                }
                            }
                        }
                    }
                    if (!empty($email)) {
                        $emailPDO = $this->manufactures_model->getEmailPOD($id);
                        if (!empty($emailPDO)) {
                            foreach ($emailPDO as $key => $value) {
                                sendEmail([
                                    'email' => $value['email'],
                                    'message' => $value['description'],
                                    'subject' => $value['name'],
                                ]);
                            }
                        }
                    }

                    if (!empty($zalo)) {
                        $zaloPDO = $this->manufactures_model->getEmailPOD($id);
                        if (!empty($zaloPDO)) {
                            foreach ($zaloPDO as $key => $value) {
                                if (!empty($value['id_zalo'])) {
                                    $url = "https://openapi.zalo.me/v2.0/oa/message";
                                    $access_token = get_option('token_zalo');
                                    $query_fields = ['access_token' => $access_token];
                                    $curl = curl_init($url . '?' . http_build_query($query_fields));
                                    curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
                                    curl_setopt($curl, CURLOPT_POST, true);
                                    curl_setopt($curl, CURLOPT_HTTPHEADER, ['Content-Type: application/json']);
                                    $dataZalo = [
                                        'recipient' => [
                                            "user_id" => $value['id_zalo']
                                        ],
                                        'message' => [
                                            'text' => $value['name']
                                        ]
                                    ];
                                    curl_setopt($curl, CURLOPT_POSTFIELDS,  json_encode($dataZalo, JSON_UNESCAPED_UNICODE));
                                    $response = curl_exec($curl);
                                }
                            }
                        }
                    }
                    //
                    insertActivityLog([
                        'type_parent_obj' => 'productions_orders',
                        'table_obj' => 'tbl_productions_orders',
                        'id_obj' => $id,
                        'name_obj' => $productions_orders['reference_no'],
                        'content' => lang('tnh_his_created_productions_detail_productions_orders') . ' [' . $productions_orders['reference_no'] . ']',
                        'actions' => 'created_productions_detail'
                    ]);
                    $data['result'] = 1;
                    $data['message'] = lang('success');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $data['id'] = $id;
            $data['items'] = $items;
            $data['productions_orders'] = $productions_orders;
            $data['departments'] = $this->departments_model->getDepartments();
            $data['shiftWork'] = $this->site_model->getShiftWork();
            $data['staffs'] = $this->site_model->getStaff();
            $this->load->view('admin/manufactures/created_productions_detail', $data);
        }
    }

