    public function getProductionsOrdersDetails()
    {
        if (!$this->perViewOPD && !$this->perViewOwnOPD) {
            accessDenied($js = true);
        }

        $isAdmin = is_admin();
        $status_table = $this->input->post('status_table');
        $productions_orders_search = $this->input->post('productions_orders_search');
        $start_date_search = $this->input->post('start_date_search');
        $end_date_search = $this->input->post('end_date_search');

        $items_search = $this->input->post('items_search');

        $status_table = $this->input->post('status_table');
        $departments_search = $this->input->post('departments_search');

        $order = "(
            SELECT CONCAT(tbl_orders.reference_no, '(', tbl_orders.customer_name, ')')
            FROM tbl_orders
            WHERE tbl_orders.id = tbl_productions_plan_items.object_id
        )";

        $business = "(
            SELECT tbl_business_plan.reference_no
            FROM tbl_business_plan
            WHERE tbl_business_plan.id = tbl_productions_plan_items.object_id
        )";

        $department = "(
            SELECT tbl_pod_departments.pod_id, GROUP_CONCAT(tbldepartments.name SEPARATOR '</br>') as department_name
            FROM tbl_pod_departments
            INNER JOIN tbldepartments ON tbldepartments.departmentid = tbl_pod_departments.department_id
            GROUP BY tbl_pod_departments.pod_id
        ) as dp";

        $dnxvt = "(
            SELECT count(*)
            FROM tbl_suggest_exporting
            WHERE tbl_suggest_exporting.pattern_id = 0 AND tbl_suggest_exporting.productions_orders_details_id = tbl_productions_orders_details.id AND tbl_suggest_exporting.type != 2
            LIMIT 1
        )";

        $xksx = "(
            SELECT count(*)
            FROM tbl_suggest_exporting
            WHERE tbl_suggest_exporting.productions_orders_details_id = tbl_productions_orders_details.id AND tbl_suggest_exporting.status_stock IS NOT NULL
            LIMIT 1
        )";

        $qc = "COALESCE(tbl_check_quality.id, 0)";

        $ntp = "(
            SELECT count(*)
            FROM tbl_purchase_products
            WHERE tbl_purchase_products.productions_orders_details_id = tbl_productions_orders_details.id
            LIMIT 1
        )";

        $ht = "tbl_productions_orders_details.status";

        $priceMaterial = "(
            SELECT
                SUM(tbl_suggest_exporting.grand_total)
            FROM tbl_suggest_exporting
            WHERE tbl_suggest_exporting.reference_stock IS NOT NULL AND tbl_suggest_exporting.grand_total > 0 AND tbl_suggest_exporting.productions_orders_details_id = tbl_productions_orders_details.id
        )";

        $payslips = "(
            SELECT
                SUM(tblother_payslips.total)
            FROM tblother_payslips
            WHERE tblother_payslips.type_vouchers = 9 AND tblother_payslips.vouchers_id = tbl_productions_orders_details.id
        )";

        $purchaseInternal = "(
            SELECT
                SUM(tbl_purchase_internal.grand_total) as total_internal
            FROM tbl_purchase_internal
            WHERE tbl_purchase_internal.grand_total > 0 AND tbl_purchase_internal.pod_id = tbl_productions_orders_details.id
        )";

        $selectCost = "(COALESCE($priceMaterial, 0) + COALESCE($payslips, 0) - COALESCE($purchaseInternal, 0))";
        if (!$isAdmin) {
            $selectCost = 0;
        }

        $this->datatables
            ->select("
                tbl_productions_orders_details.id as id,
                0 as number_records,
                tbl_productions_orders.reference_no as reference_no_order,
                tbl_productions_orders_details.reference_no as reference_no,
                IF(tbl_productions_plan_items.type_object = 'orders', $order, IF(tbl_productions_plan_items.type_object = 'business_plan', $business, '')) as order_or_bussines,
                tbl_productions_orders_details.deadline as deadline,
                dp.department_name as department_name,
                tbl_productions_orders_items.items_code as items_code,
                CONCAT(COALESCE(tbl_products.images, '') , '||', tbl_productions_orders_items.items_name) as items_name,
                tbl_productions_orders_items.quantity as quantity,
                tbl_productions_orders_details.quantity_warehoused as quantity_finished,
                IF (tbl_productions_orders_details.status != 'complete_production', DATEDIFF(tbl_productions_orders_details.deadline, now()), tbl_productions_orders_details.status) as status,
                CONCAT(tbl_check_quality.id, '__', tbl_check_quality.reference_no, '__', tbl_check_quality.status) as qc,
                CONCAT($dnxvt, '||', $xksx, '||', $qc, '||', $ntp, '||', $ht) as workflow,
                $selectCost as total_cost
                ", false)
            ->from('tbl_productions_orders_details')
            ->join('tbl_productions_orders_items', 'tbl_productions_orders_items.id = tbl_productions_orders_details.productions_orders_item_id', 'left')
            ->join('tbl_productions_plan_items', 'tbl_productions_plan_items.id = tbl_productions_orders_items.production_plan_item_id', 'left')
            ->join('tbl_productions_orders', 'tbl_productions_orders.id = tbl_productions_orders_items.productions_orders_id', 'left')
            ->join('tbl_products', 'tbl_products.id = tbl_productions_orders_items.items_id', 'left')
            // ->join('tbldepartments', 'tbldepartments.departmentid = tbl_productions_orders_details.departments', 'left')
            ->join($department, 'dp.pod_id = tbl_productions_orders_details.id', 'left')
            ->join('tbl_check_quality', 'tbl_check_quality.pod_id = tbl_productions_orders_details.id', 'left');

        if (!empty($status_table)) {
            if ($status_table == 1) {
                // $this->datatables->where('tbl_productions_orders.status_details', 0);
            } else if ($status_table == 2) {
                $this->datatables->where('tbl_productions_orders_details.status', 'un_produced');
            } else if ($status_table == 3) {
                $this->datatables->where("tbl_productions_orders_details.quantity_warehoused >", 0);
            } else if ($status_table == 4) {
                $this->datatables->where("(tbl_productions_orders_details.status != 'complete_production' && DATEDIFF(tbl_productions_orders_details.deadline, now()) < 0)");
            } else if ($status_table == 5) {
                $this->datatables->where('tbl_productions_orders_details.status', 'complete_production');
            } else if ($status_table == 6) {
                $this->datatables->where('tbl_productions_orders_details.check_quality_id >', 0);
            }
        }

        if (!$this->perViewOPD) {
            $employees = "(
                SELECT COUNT(*)
                FROM tbl_pod_employees
                WHERE tbl_pod_employees.productions_orders_details_id = tbl_productions_orders_details.id AND tbl_pod_employees.employee_id = " . get_staff_user_id() . "
            )";
            $this->datatables->where("(
                tbl_productions_orders_details.created_by =" . get_staff_user_id() . "
                OR
                $employees > 0
            )");
        }

        if (!empty($productions_orders_search)) {
            $this->datatables->where("tbl_productions_orders_details.productions_orders_id", $productions_orders_search);
        }

        if (!empty($items_search)) {
            $arrItem = explode('__', $items_search);
            $item_id = $arrItem[0];
            $this->datatables->where("tbl_productions_orders_items.items_id", $item_id);
        }

        if (!empty($start_date_search)) {
            $this->datatables->where("DATE_FORMAT(tbl_productions_orders_details.date_created, '%Y-%m-%d') >=", to_sql_date($start_date_search));
        }

        if (!empty($end_date_search)) {
            $this->datatables->where("DATE_FORMAT(tbl_productions_orders_details.date_created, '%Y-%m-%d') <=", to_sql_date($end_date_search));
        }

        if (!empty($departments_search)) {
            $this->datatables->where("(FIND_IN_SET($departments_search, tbl_productions_orders_details.departments) > 0)");
        }

        $custom = [];
        $custom_select = [];

        $custom[] = ['index' => 4, 'select' => "order_or_bussines"];
        $custom_select[4] = "IF(tbl_productions_plan_items.type_object = 'orders', $order, IF(tbl_productions_plan_items.type_object = 'business_plan', $business, ''))";

        $custom[] = ['index' => 14, 'select' => "total_cost"];
        $custom_select[14] = "(COALESCE($priceMaterial, 0) + COALESCE($payslips, 0))";

        $this->datatables->custom_ordering($custom);
        $this->datatables->custom_select($custom_select);

        $detail = '<a class="" title="' . lang('tnh_detail') . '" target="_blank" href="' . base_url('admin/manufactures/detail_productions/$1') . '"><i class="fa fa-file-text-o width-icon-actions" ></i> ' . lang('tnh_detail') . '</a>';

        $warehousing = '<a class="tnh-modal tnh-warehousing" title="' . lang('tnh_warehousing') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/addWarehousing/$1') . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('tnh_warehousing') . '</a>';

        $importQuantityFi = '<a class="tnh-modal tnh-import-finished" title="' . lang('tnh_import_quantity_fi') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/importQuantityFi/$1') . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('tnh_import_quantity_fi') . '</a>';

        $purchaseInternal = '<a class="tnh-modal tnh-purchase-internal" title="' . lang('tnh_add_purchase_internal') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/purchaseInternal/$1') . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('tnh_add_purchase_internal') . '</a>';

        $checkQuality = '<a class="tnh-modal tnh-check-quality" title="' . lang('check_quality') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/checkQuality/$1') . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('check_quality') . '</a>';

        $delete = '<a type="button" class="po" title="' . lang('delete') . '" data-container="body" data-html="true" data-toggle="popover" data-placement="left" data-content="
            <button href=\'' . base_url('admin/manufactures/delete_productions_orders/$1') . '\' class=\'btn btn-danger po-delete-json\'>' . lang('delete') . '</button>
            <button class=\'btn btn-default po-close\'>' . lang('close') . '</button>
        "><i class="fa fa-remove width-icon-actions"></i> ' . lang('delete') . '</a>';

        $print = '<a href="' . base_url('admin/manufactures/print_productions_orders_detail/$1') . '" target="_blank"><i class="fa fa-print"></i> ' . lang('print_vote') . '</a>';

        $exportRevoke = '<a class="tnh-modal tnh-export-revoke" title="' . lang('tnh_export_revoke') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/exportRevoke/$1') . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('tnh_export_revoke') . '</a>';

        $actions = '
        <div class="dropdown text-center">
            <button class="btn btn-primary dropdown-toggle nav-link" type="button" id="dropdownMenu1" data-toggle="dropdown" aria-expanded="true">
            ' . lang('actions') . '
            <span class="caret"></span>
            </button>
            <ul class="dropdown-menu pull-right" role="menu" aria-labelledby="dropdownMenu1">
                <li>' . $detail . '</li>
                <li>' . $warehousing . '</li>
                <li>' . $purchaseInternal . '</li>
                <li>' . $exportRevoke . '</li>
                <li>' . $checkQuality . '</li>
            </ul>
        </div>';

        $this->datatables->add_column('actions', $actions, 'id');
        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][1] = ++$iDisplayStart;
        }

        echo json_encode($data);
    }

    public function detail_productions($id)
    {
        if (!$this->perViewOPD && !$this->perViewOwnOPD) {
            accessDenied();
        }

        $branch_staff = get_array_branch_staff();
        $is_admin = is_admin();
        $where = null;
        if (!$is_admin) {
            if (empty($branch_staff)) $branch_staff = [0];
            $where.= 'tbl_productions_orders.location_id IN ('.implode(',', $branch_staff).')';
        }
        $production_detail = $this->manufactures_model->rowProductionsOrdersByDetail($id, $where);
        if (empty($production_detail)) {
            set_alert('danger', lang('no_data_exists'));
            redirect($_SERVER["HTTP_REFERER"]);
            die;
        }

        $semi_products = $this->manufactures_model->getProductionsOrdersItemsSubByDetail($production_detail['productions_orders_item_id']);
        // $warehousing = $this->manufactures_model->getWarehousingProductByPOD($id);
        $warehousing = $this->manufactures_model->getPurchasesProductByPOD($id);
        $podEmployees = $this->manufactures_model->getPODEmployeesByPODId($id);

        $priceMaterial = "(
            SELECT
                SUM(tbl_suggest_exporting.grand_total) as total_material
            FROM tbl_suggest_exporting
            WHERE tbl_suggest_exporting.reference_stock IS NOT NULL AND tbl_suggest_exporting.grand_total > 0 AND tbl_suggest_exporting.productions_orders_details_id = $id
        )";
        $totalMaterial = $this->db->query($priceMaterial)->row_array();
        $totalMaterial = !empty($totalMaterial) ? $totalMaterial['total_material'] : 0;

        $purchaseInternal = "(
            SELECT
                SUM(tbl_purchase_internal.grand_total) as total_internal
            FROM tbl_purchase_internal
            WHERE tbl_purchase_internal.grand_total > 0 AND tbl_purchase_internal.pod_id = $id
        )";
        $totalInternal = $this->db->query($purchaseInternal)->row_array();
        $totalInternal = !empty($totalInternal) ? $totalInternal['total_internal'] : 0;
        // $totalMaterial = $totalMaterial - $totalInternal;
        $data['totalInternal'] = $totalInternal;

        $payslips = "(
            SELECT
                SUM(tblother_payslips.total) as total_payslips
            FROM tblother_payslips
            WHERE tblother_payslips.type_vouchers = 9 AND tblother_payslips.vouchers_id = $id
        )";
        $totalPayslips = $this->db->query($payslips)->row_array();
        $totalPayslips = !empty($totalPayslips) ? $totalPayslips['total_payslips'] : 0;
        $data['totalMaterial'] = $totalMaterial;
        $data['totalPayslips'] = $totalPayslips;


        $data['production_detail'] = $production_detail;
        $data['semi_products'] = $semi_products;
        $data['warehousing'] = $warehousing;
        $data['podEmployees'] = $podEmployees;
        $data['id'] = $id;
        $data['tnh'] = $this->tnh;
        $data['employees'] = $this->manufactures_model->getAllStaff();
        $data['isAdmin'] = is_admin();

        $object_type = $production_detail['object_type'];
        $object_id = $production_detail['object_id'];
        $production_plan_item_id = $production_detail['production_plan_item_id'];

        $process = '';
        if ($object_type == "orders") {
            $this->db->select('tbl_orders.reference_no as reference_no, tblclients.company as company', false);
            $this->db->from('tbl_orders');
            $this->db->join('tblclients', 'tblclients.userid = tbl_orders.customer_id');
            $this->db->where('tbl_orders.id', $object_id);
            $order = $this->db->get()->row_array();
            $data['order'] = $order;

            
        } else if ($object_type == "business_plan") {
            $this->db->select('tbl_business_plan.reference_no as reference_no', false);
            $this->db->from('tbl_business_plan');
            $this->db->where('tbl_business_plan.id', $object_id);
            $business_plan = $this->db->get()->row_array();
            $data['business_plan'] = $business_plan;

            
        }
        $dtProcess = showProcessDetailProductions($production_detail['productions_orders_item_id'], $object_type, $production_plan_item_id);

        $data['process'] = $dtProcess['process'];
        $data['isFinished'] = $dtProcess['isFinished'];
        $data['breadcrumb'] = [array('link' => base_url('admin/manufactures/order_production_details'), 'page' => lang('tnh_productions_order_details')), array('link' => '#', 'page' => lang('tnh_detail_productions'))];
        $data['title'] = lang('tnh_detail_productions');


        //cong
        $this->db->where('id_order_production_details', $id);
        $this->db->order_by('date_create', 'desc');
        $data['feedback'] = $this->db->get('tblorder_production_details_feedback')->result();
        foreach ($data['feedback'] as $key => $value) {
            $this->db->where('rel_id', $value->id);
            $this->db->where('rel_type', 'feedback_opd');
            $data['feedback'][$key]->file = $this->db->get('tblfiles')->result();
        }
        $data['bot'] = $this->input->get('bot');
        //end cong
        $this->load->view('admin/manufactures/detail_productions', $data);
    }

    public function export_supplies($id)
    {
        $production_detail = $this->manufactures_model->rowProductionsOrdersByDetail($id);
        if ($production_detail['status'] == "complete_production") {
            refererModel(lang('tnh_this_is_completed'));
            die;
        }
        if ($this->input->post('save')) {
            $data = [];
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('export_name', lang("tnh_export_name"), 'required');
            if ($this->form_validation->run() == true) {
                $date = to_sql_date($this->input->post('date'), true);
                $export_name = $this->input->post('export_name');
                $note = $this->input->post('note', false);
                $total_quantity = 0;
                $total_quantity_exchange = 0;
                $tick_save = $this->input->post('tick_save');
                if (!empty($tick_save)) {
                    foreach ($tick_save as $key => $value) {
                        $item_id = $this->input->post('item_id')[$value];
                        $unit_id = $this->input->post('unit_id')[$value];
                        $unit_parent_id = $this->input->post('unit_parent_id')[$value];
                        $number_exchange = $this->input->post('quantity_exchange')[$value];
                        $quantity_export = number_unformat($this->input->post('quantity_export')[$value]);
                        if ($quantity_export > 0) {
                            $info_item = NULL;
                            $type_item = $this->input->post('type_item')[$value];
                            if ($type_item == "semi_products_outside" || $type_item == "semi_products") {
                                $info_item = $this->products_model->rowProduct($item_id);
                            } else if ($type_item == "materials") {
                                $info_item = $this->items_model->rowMaterial($item_id);
                            }
                            if (empty($info_item)) continue;
                            $quantity_exchange = $quantity_export / $number_exchange;
                            $exporting_items[] = [
                                'type_item' => $type_item,
                                'item_id' => $item_id,
                                'item_code' => $info_item['code'],
                                'item_name' => $info_item['name'],
                                'unit_id' => $unit_id,
                                'quantity_export' => $quantity_export,
                                'unit_parent_id' => $unit_parent_id,
                                'number_exchange' => $number_exchange,
                                'quantity_exchange' => $quantity_exchange,
                            ];
                            $total_quantity += $quantity_export;
                            $total_quantity_exchange += $quantity_exchange;
                        }
                    }
                }
                if (empty($exporting_items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_only_save_tick_chonse');
                    echo json_encode($data);
                    die;
                }
                $count_items = count($exporting_items);

                $reference_no = getReference('suggest_exporting');
                $fields = [
                    'productions_orders_details_id' => $id,
                    'reference_no' => $reference_no,
                    'date' => $date,
                    'export_name' => $export_name,
                    'note' => $note,
                    'status' => 'un_approved',
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'total_quantity_exchange' => $total_quantity_exchange,
                    'created_by' => get_staff_user_id(),
                    'date_created' => date('Y-m-d H:i:s'),
                    'type' => '1'
                ];
                $suggest_exporting_id = $this->manufactures_model->insertSuggestExporting($fields);
                if ($suggest_exporting_id) {
                    updateReference('suggest_exporting');
                    foreach ($exporting_items as $key => $value) {
                        $exporting_items[$key]['suggest_exporting_id'] = $suggest_exporting_id;
                    }
                    $this->manufactures_model->insertBatchSuggestExportingItems($exporting_items);

                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($id);
                    $content = lang('tnh_his_export_supplies_productions_orders_details');
                    $content = str_replace('{$1}', $reference_no, $content);
                    $content = str_replace('{$2}', $pod['reference_no'], $content);
                    insertActivityLog([
                        'type_parent_obj' => 'suggest_exporting',
                        'table_obj' => 'tbl_suggest_exporting',
                        'id_obj' => $suggest_exporting_id,
                        'name_obj' => $reference_no,
                        'content' => $content,
                        'actions' => 'add'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $data['reference_no'] = getReference('suggest_exporting');
            $materials = $this->manufactures_model->getMaterialProductionsForExportSupplies($production_detail['productions_orders_item_id']);
            $data['production_detail'] = $production_detail;
            $data['materials'] = $materials;
            $data['id'] = $id;
            $this->load->view('admin/manufactures/export_supplies', $data);
        }
    }

    public function edit_suggest_exporting($id)
    {
        if (!$this->perEditListSuggestExporting) {
            accessDenied();
        }

        $suggest_exporting = $this->manufactures_model->rowSuggestExporting($id);
        if ($suggest_exporting['status'] != "un_approved") {
            refererModel(lang('browsed_cannot_be_edited'));
        }
        $production_detail = $this->manufactures_model->rowProductionsOrdersByDetail($suggest_exporting['productions_orders_details_id']);
        if ($production_detail['status'] == "complete_production") {
            refererModel(lang('tnh_this_is_completed'));
            die;
        }
        if ($this->input->post('save')) {
            $data = [];
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('export_name', lang("tnh_export_name"), 'required');
            if ($this->form_validation->run() == true) {
                $date = to_sql_date($this->input->post('date'), true);
                $export_name = $this->input->post('export_name');
                $note = $this->input->post('note', false);
                $exporting_items_id = $this->input->post('exporting_items_id');
                $total_quantity = 0;
                $total_quantity_exchange = 0;
                $arr_not_delete = [];
                if (!empty($exporting_items_id)) {
                    foreach ($exporting_items_id as $key => $value) {
                        $number_exchange = $this->input->post('quantity_exchange')[$key];
                        $quantity_export = number_unformat($this->input->post('quantity_export')[$key]);
                        if ($quantity_export > 0) {
                            $quantity_exchange = $quantity_export / $number_exchange;
                            $exporting_items[] = [
                                'id' => $value,
                                'quantity_export' => $quantity_export,
                                'number_exchange' => $number_exchange,
                                'quantity_exchange' => $quantity_exchange,
                            ];
                            $total_quantity += $quantity_export;
                            $total_quantity_exchange += $quantity_exchange;
                            array_push($arr_not_delete, $value);
                        }
                    }
                }
                if (empty($exporting_items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_there_is_not_export_quantity_greater_than_zero');
                    echo json_encode($data);
                    die;
                }
                $count_items = count($exporting_items);

                $fields = [
                    'date' => $date,
                    'export_name' => $export_name,
                    'note' => $note,
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'total_quantity_exchange' => $total_quantity_exchange,
                    'updated_by' => get_staff_user_id(),
                    'date_updated' => date('Y-m-d H:i:s'),
                ];
                $up = $this->manufactures_model->updateSuggestExportingById($id, $fields);
                if ($up) {
                    $delete = $this->manufactures_model->getSuggestExportingItemsByNotArrId($arr_not_delete, $id);
                    if (!empty($delete)) {
                        foreach ($delete as $key => $value) {
                            $this->manufactures_model->deleteSuggestExportingItemsById($value['id']);
                        }
                    }
                    if (!empty($exporting_items)) {
                        $this->manufactures_model->updateBatchSuggestExportingItemsById($exporting_items);
                    }

                    $content = lang('tnh_his_edit_export_supplies_productions_orders_details');
                    $content = str_replace('{$1}', $suggest_exporting['reference_no'], $content);
                    $content = str_replace('{$2}', $production_detail['reference_no'], $content);
                    insertActivityLog([
                        'type_parent_obj' => 'suggest_exporting',
                        'table_obj' => 'tbl_suggest_exporting',
                        'id_obj' => $id,
                        'name_obj' => $suggest_exporting['reference_no'],
                        'content' => $content,
                        'actions' => 'edit'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $data['suggest_exporting'] = $suggest_exporting;
            $data['exporting_items'] = $this->manufactures_model->getSuggestExportingItemsView($id);
            $data['id'] = $id;
            $this->load->view('admin/manufactures/edit_export_supplies', $data);
        }
    }

