    public function agreeSuggestExporting()
    {
        $data = [];

        if (!$this->perApproveListSuggestExporting) {
            $data['result'] = 0;
            $data['message'] = lang('access_denied');
            echo json_encode($data);
            die;
        }

        if ($this->input->get()) {
            $suggest_exporting_id = $this->input->get('suggest_exporting_id');
            $status = $this->input->get('status');
            $suggest_exporting = $this->manufactures_model->rowSuggestExporting($suggest_exporting_id);
            $date = date('Y-m-d H:i');
            $user_id = get_staff_user_id();
            if ($suggest_exporting['status'] == $status) {
                $data['result'] = 0;
                $data['message'] = lang('tnh_please_referesh_table');
                echo json_encode($data);
                die;
            }
            if (!empty($suggest_exporting['status_convert_stock'])) {
                $data['result'] = 0;
                $data['message'] = lang('tnh_created_convert_stock');
                echo json_encode($data);
                die;
            }
            $up = $this->manufactures_model->updateSuggestExportingById($suggest_exporting_id, [
                'status' => $status,
                'date_status' => $date,
                'user_status' => $user_id
            ]);
            if ($up) {
                @pusherTNHNotfication();
                $pod = $this->manufactures_model->rowProductionsOrdersDetais($suggest_exporting['productions_orders_details_id']);
                $content = lang('tnh_his_agree_export_supplies_productions_orders_details');
                $content = str_replace('{$1}', $suggest_exporting['reference_no'], $content);
                $content = str_replace('{$2}', $pod['reference_no'], $content);
                insertActivityLog([
                    'type_parent_obj' => 'suggest_exporting',
                    'table_obj' => 'tbl_suggest_exporting',
                    'id_obj' => $suggest_exporting_id,
                    'name_obj' => $suggest_exporting['reference_no'],
                    'content' => $content,
                    'actions' => 'agree'
                ]);

                if ($status == "approved") {
                    $userList = $this->staff_model->getStaff();
                    $notifiedUsers = [];

                    $query_str = "SELECT * FROM tbl_suggest_exporting where id = $suggest_exporting_id";
                    $query = $this->db->query($query_str);
                    foreach ($query->result() as $row) {
                        $dataHtml = 'Phiếu ĐỀ NGHỊ XUẤT VẬT TƯ ' . $row->reference_no . ' vừa được duyệt bởi ';
                    }

                    foreach ($userList as $key => $value) {
                        $notification_data = [
                            'description' => $dataHtml,
                            'touserid' => $key,
                            'link' => 'change_management/?id=' . $suggest_exporting_id,
                            'onchange' => ' onclick="view_change_gif(' . $suggest_exporting_id . '); return false;" ',
                        ];

                        if (add_notification($notification_data)) {
                            array_push($notifiedUsers, $value['staffid']);
                        }
                        pusher_trigger_notification($notifiedUsers);
                    }
                }

                $data['result'] = 1;
                $data['message'] = lang('success');
            } else {
                $data['result'] = 0;
                $data['message'] = lang('fail');
            }
        }
        echo json_encode($data);
    }

