    public function convert_stock($id)
    {

        $this->perApproveExportingProducion = has_permission('stock_exporting_producion', '', 'approve');
        $this->perApproveWarehouseExportingProducion = has_permission('stock_exporting_producion', '', 'approve_warehouse');

        $suggest_exporting = $this->manufactures_model->rowSuggestExporting($id);
        $suggest_exporting_items = $this->manufactures_model->getSuggestExportingItemsConvertStock($id);
        if ($this->input->post()) {
            $data = [];
            if ($suggest_exporting['status'] != 'approved') {
                $data['result'] = 0;
                $data['message'] = lang('tnh_please_approved');
                echo json_encode($data);
                die;
            }
            if (!empty($suggest_exporting['status_convert_stock']) && $suggest_exporting['status_convert_stock'] == "completed") {
                $data['result'] = 0;
                $data['message'] = lang('tnh_created_convert_stock');
                echo json_encode($data);
                die;
            }

            // $this->form_validation->set_rules('warehouses', lang("tnh_warehouses"), 'required');
            $this->form_validation->set_rules('locations[]', lang("tnh_location_warehouse"), 'required');
            if ($this->form_validation->run() == true) {
                $date = date('Y-m-d H:i:s');
                $user_id = get_staff_user_id();
                $warehouses = $this->input->post('warehouses');
                $export_name = $suggest_exporting['export_name'];
                $pattern_id = $suggest_exporting['id'];
                $productions_orders_details_id = $suggest_exporting['productions_orders_details_id'];
                $total_quantity = 0;
                $count_items = 0;
                $total_quantity_exchange = 0;
                $type = 3;
                $errors = "";
                $save_and_warehouse = !empty($this->input->post('save_and_warehouse')) ? $this->input->post('save_and_warehouse') : 0;

                $arr_id = [];
                $arr_info = [];
                $counter = $this->input->post('counter');
                foreach ($counter as $key => $value) {
                    $suggest_exporting_items_id = $this->input->post('suggest_exporting_items_id')[$value];
                    $rowSuggestExportingItem = $this->manufactures_model->rowSuggestExportingItem($suggest_exporting_items_id);
                    $location = $this->input->post('locations')[$value];

                    $quantity_export = number_unformat($this->input->post('quantity_export')[$value]);
                    if (empty($rowSuggestExportingItem) || empty($location)) continue;
                    $quantity_had_export = $rowSuggestExportingItem['quantity_export'] - $rowSuggestExportingItem['quantity_convert_stock'];

                    $unit_id = $rowSuggestExportingItem['unit_id'];
                    $unit_parent_id = $rowSuggestExportingItem['unit_parent_id'];
                    $number_exchange = $rowSuggestExportingItem['number_exchange'];
                    $type_item = $rowSuggestExportingItem['type_item'];
                    $item_id = $rowSuggestExportingItem['item_id'];
                    $item_code = $rowSuggestExportingItem['item_code'];
                    $item_name = $rowSuggestExportingItem['item_name'];
                    $quantity_exchange = $quantity_export / $number_exchange;
                    $pattern_item_id = $suggest_exporting_items_id;

                    if ($quantity_export > formatRoundNumber($quantity_had_export)) {
                        $errors .= '<div>[' . $item_code . '] ' . lang('tnh_slnb') . ' ' . formatNumber($quantity_had_export) . '</div>';
                    }

                    $location = explode('__', $location);
                    $warehouse_id = $location[0];
                    $location_id = $location[1];

                    $items[] = [
                        'pattern_item_id' => $pattern_item_id,
                        'type_item' => $type_item,
                        'item_id' => $item_id,
                        'item_code' => $item_code,
                        'item_name' => $item_name,
                        'unit_id' => $unit_id,
                        'quantity_export' => $quantity_export,
                        'unit_parent_id' => $unit_parent_id,
                        'number_exchange' => $number_exchange,
                        'quantity_exchange' => $quantity_exchange,
                        'location_id' => $location_id,
                        'warehouse_item_id' => $warehouse_id,
                    ];

                    $total_quantity += $quantity_export;
                    $total_quantity_exchange += $quantity_exchange;

                    $str_item_id = $type_item . '__' . $item_id . '__' . $location_id . '__' . $warehouse_id;
                    $index = array_search($str_item_id, $arr_id);
                    if ($index === false) {
                        $arr_id[] = $str_item_id;
                        $arr_info[] = [
                            "quantity" => $quantity_exchange,
                            "item_code" => $item_code,
                            "item_name" => $item_name,
                        ];
                        // $arr_info[]['quantity'] = $quantity_exchange;
                        // $arr_info[$index]['item_code'] = $item_code;
                        // $arr_info[$index]['item_name'] = $item_name;
                    } else {
                        $arr_info[$index]['quantity'] = $arr_info[$index]['quantity'] + $quantity_exchange;
                    }
                }

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data);
                    die;
                }

                if (empty($items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_no_items');
                    echo json_encode($data);
                    die;
                }

                $reference_stock = getReference('stock');
                $count_items = count($items);
                $fields = [
                    'pattern_id' => $suggest_exporting['id'],
                    'type_pattern_id' => $suggest_exporting['type'],
                    'productions_orders_details_id' => $suggest_exporting['productions_orders_details_id'],
                    'reference_no' => NULL,
                    'reference_stock' => $reference_stock,
                    'date' => $suggest_exporting['date'],
                    'export_name' => $suggest_exporting['export_name'],
                    'note' => "",
                    'status' => $suggest_exporting['status'],
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'total_quantity_exchange' => $total_quantity_exchange,
                    'created_by' => $suggest_exporting['created_by'],
                    'date_created' => $suggest_exporting['date_created'],
                    'type' => '3',
                    'warehouse_id' => $warehouses,
                    'status_stock' => 'un_approved_stock',
                    'date_convert_stock' => $date,
                    'convert_stock_by' => $user_id,
                ];

                if ($this->perApproveExportingProducion && $this->perApproveWarehouseExportingProducion) {
                    if (!empty($save_and_warehouse)) {
                        $fields['status_stock'] = 'approved';
                        $fields['date_stock'] = date('Y-m-d H:i:s');
                        $fields['user_stock'] = $user_id;

                        foreach ($arr_id as $key => $value) {
                            $str_item_id = explode('__', $value);
                            $type_item = $str_item_id[0];
                            $item_id = $str_item_id[1];
                            $location = $str_item_id[2];
                            $warehouses = $str_item_id[3];
                            $quantity = $arr_info[$key]['quantity'];
                            $item_code = $arr_info[$key]['item_code'];
                            $item_name = $arr_info[$key]['item_name'];

                            $dtWarehouse = $this->site_model->rowWarehouseById($warehouses);
                            $dtLocation = $this->site_model->rowLocationWarehouseById($location);
                            $quantityWarehouses = $this->manufactures_model->getTotalQuantityWarehouseLocationAndWarehouse($item_id, $type_item, $location, $warehouses)['total_quantity'];
                            if ($quantity > $quantityWarehouses) {
                                $errors .= '<div>Mặt hàng [' . $item_code . '] không đủ số lượng để duyệt kho [' . $dtWarehouse['name'] . '] vị trí [' . $dtLocation['name'] . ']</div>';
                            }
                        }
                    }
                }

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data);
                    die;
                }

                // print_arrays($fields);
                $stock_id = $this->manufactures_model->insertSuggestExporting($fields);
                if ($stock_id) {
                    updateReference('stock');
                    $totalQtySug = 0;
                    foreach ($items as $key => $value) {
                        $value['suggest_exporting_id'] = $stock_id;
                        $sugItemId =  $this->manufactures_model->insertSuggestExportingItems($value);
                        if ($sugItemId) {
                            $this->manufactures_model->updateSetSuggestExportingItem($value['pattern_item_id'], $value['quantity_export'], $plus = 0);
                            $totalQtySug += $value['quantity_export'];
                        }
                    }

                    $statusSug = "apart";
                    if (!$this->manufactures_model->checkFinishedSuggestExportingItems($suggest_exporting['id'])) {
                        $statusSug = "completed";
                    }

                    $this->manufactures_model->updateSetSuggestExporting($suggest_exporting['id'], $totalQtySug, $statusSug, $plus = 0);

                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($suggest_exporting['productions_orders_details_id']);
                    $content = lang('tnh_his_convert_stock_export_supplies_productions_orders_details');
                    $content = str_replace('{$1}', $reference_stock, $content);
                    $content = str_replace('{$2}', $suggest_exporting['reference_no'], $content);
                    $content = str_replace('{$3}', $pod['reference_no'], $content);
                    insertActivityLog([
                        'type_parent_obj' => 'suggest_exporting',
                        'table_obj' => 'tbl_suggest_exporting',
                        'id_obj' => $id,
                        'name_obj' => $reference_stock,
                        'content' => $content,
                        'actions' => 'convert_stock'
                    ]);

                    if ($this->perApproveExportingProducion && $this->perApproveWarehouseExportingProducion) {
                        if (!empty($save_and_warehouse)) {
                            $suggest_exporting_id = $stock_id;
                            $id = $suggest_exporting_id;
                            $_data = array(
                                'warehouseman_id' => get_staff_user_id(),
                                'date_warehouseman' => date('Y-m-d H:i:s')
                            );

                            if (!test_quantity_exporting_producion_warehouses($suggest_exporting_id)) {
                                $data['result'] = 1;
                                $data['message'] = lang('test_quantyti_time_return');
                                echo json_encode($data);
                                die;
                            } else {
                                $success = $this->db->update('tbl_suggest_exporting', $_data, array('id' => $suggest_exporting_id));
                                if ($success) {
                                    log_activity('Export Warehouses items approved [ID export_warehouses: ' . $suggest_exporting_id);
                                    $this->stock_model->decreaseWarehouse($suggest_exporting_id);

                                    $suggest_exporting = $this->manufactures_model->rowSuggestExporting($suggest_exporting_id);
                                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($suggest_exporting['productions_orders_details_id']);
                                    $content = lang('tnh_his_warehouse_exporting_producion');
                                    $content = str_replace('{$1}', $suggest_exporting['reference_stock'], $content);
                                    $content = str_replace('{$2}', $pod['reference_no'], $content);

                                    insertActivityLog([
                                        'type_parent_obj' => 'exporting_producion',
                                        'table_obj' => 'tbl_suggest_exporting',
                                        'id_obj' => $id,
                                        'name_obj' => $suggest_exporting['reference_stock'],
                                        'content' => $content,
                                        'actions' => 'warehouse'
                                    ]);
                                }
                            }
                        }
                    }

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
        } else {
            $data['warehouses'] = $this->stock_model->getWarehouses();
            $data['suggest_exporting'] = $suggest_exporting;
            $data['suggest_exporting_items'] = $suggest_exporting_items;
            $data['id'] = $id;
            $this->load->view('admin/manufactures/convert_stock', $data);
        }
    }

    public function getLocationsForItems()
    {
        $data = [];
        if ($this->input->post()) {
            $warehouse_id = $this->input->post('warehouse_id');
            $id = $this->input->post('id');
            $items = $this->manufactures_model->getSuggestExportingItems($id);
            $locations = [];
            foreach ($items as $key => $value) {
                $warehouses = $this->stock_model->getWarehouseItemsByItemIdAndTypeAndWarehouse($value['item_id'], $value['type_item'], $warehouse_id);
                foreach ($warehouses as $k => $val) {
                    $location_name = recursiveLocations($val['localtion']);
                    $locations[$value['id']][] = [
                        'location_id' => $val['localtion'],
                        'location_name' => $location_name,
                    ];
                }
            }
            $data['locations'] = $locations;
        }
        echo json_encode($data);
    }

    public function getExportStockByDetailId($id)
    {
        $this->datatables
            ->select("
                0 as number_records,
                tbl_suggest_exporting.id as id,
                tbl_suggest_exporting.date_convert_stock as date,
                tbl_suggest_exporting.reference_stock as reference_stock,
                tbl_suggest_exporting.export_name as export_name,
                tbl_suggest_exporting.note as note,
                CONCAT(tblstaff.firstname, ' ', tblstaff.lastname,'') as created_by,
                tbl_suggest_exporting.status_stock as status_stock,
                tbl_suggest_exporting.warehouseman_id as status_warehouse
            ", false)
            ->from('tbl_suggest_exporting')
            ->join('tbl_productions_orders_details', 'tbl_productions_orders_details.id = tbl_suggest_exporting.productions_orders_details_id', 'inner')
            ->join('tblstaff', 'tblstaff.staffid = tbl_suggest_exporting.convert_stock_by', 'left');

        $this->datatables->where('tbl_suggest_exporting.status_stock IS NOT NULL');
        $this->datatables->where('tbl_suggest_exporting.productions_orders_details_id', $id);

        $actions = $delete = $this->perDeleteExportingProducion ? '<a type="button" class="po tnh-delete text-danger" title="' . lang('delete') . '" data-container="body" data-html="true" data-toggle="popover" data-placement="left" data-content="
            <button href=\'' . base_url('admin/stock/delete_suggest_exporting/$1') . '\' class=\'btn btn-danger po-delete-json\'>' . lang('delete') . '</button>
            <button class=\'btn btn-default po-close\'>' . lang('close') . '</button>
        "><i class="fa fa-remove width-icon-actions"></i> ' . lang('delete') . '</a>' : '';

        $this->datatables->add_column('actions', '<div class="text-center">'.$actions.'</div>', 'id');
        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;
        }
        echo json_encode($data);
    }

    public function add_suggest_exporting()
    {
        if (!$this->perAddListSuggestExporting) {
            accessDenied();
        }
        if ($this->input->post('add')) {
            $data = [];
            $this->form_validation->set_rules('reference_no', lang("tnh_reference_no_suggest"), 'required|is_unique[tbl_suggest_exporting.reference_no]');
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('export_name', lang("tnh_export_name"), 'required');
            $this->form_validation->set_rules('productions_orders_detail_id', lang("tnh_reference_productions_orders_details"), 'required');
            if ($this->form_validation->run() == true) {
                // print_arrays($this->input->post());
                $reference_no = $this->input->post('reference_no');
                $date = to_sql_date($this->input->post('date'), true);
                $productions_orders_detail_id = $this->input->post('productions_orders_detail_id');
                $note = $this->input->post('note', false);
                $export_name = $this->input->post('export_name');
                $items = $this->input->post('items_id');
                $total_quantity = 0;
                $count_items = 0;
                $total_quantity_exchange = 0;
                $type = 3;

                $errors = false;

                if (!empty($items)) {
                    foreach ($items as $key => $value) {
                        if (empty($value)) continue;
                        $unit_id = $this->input->post('unit_id')[$key];
                        $unit_parent_id = $this->input->post('unit_parent_id')[$key];
                        $number_exchange = $this->input->post('number_exchange')[$key];
                        $quantity_export = number_unformat($this->input->post('quantity')[$key]);
                        $arr_item = explode('__', $value);
                        $type_item = $arr_item[0];
                        $item_id = $arr_item[1];
                        if ($type_item == "semi_products_outside" || $type_item == "semi_products") {
                            $info_item = $this->products_model->rowProduct($item_id);
                        } else if ($type_item == "materials") {
                            $info_item = $this->items_model->rowMaterial($item_id);
                        } else if ($type_item == "tools_supplies") {
                            $info_item = $this->tools_supplies_model->rowToolsSupplies($item_id);
                        }
                        if (empty($info_item)) continue;

                        $quantity_exchange = $quantity_export / $number_exchange;
                        $exporting_items[] = [
                            'type_item' => $type_item,
                            'item_id' => $item_id,
                            'item_code' => $info_item['code'],
                            'item_name' => $info_item['name'],
                            'unit_id' => $unit_id,
                            'quantity_export' => $quantity_export,
                            'unit_parent_id' => $unit_parent_id,
                            'number_exchange' => $number_exchange,
                            'quantity_exchange' => $quantity_exchange,
                        ];
                        $total_quantity += $quantity_export;
                        $total_quantity_exchange += $quantity_exchange;
                    }
                }

                // print_arrays($exporting_items);

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data);
                    die;
                }

                if (empty($exporting_items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_no_items');
                    echo json_encode($data);
                    die;
                }
                $count_items = count($exporting_items);
                $fields = [
                    'productions_orders_details_id' => $productions_orders_detail_id,
                    'reference_no' => $reference_no,
                    'reference_stock' => null,
                    'date' => $date,
                    'export_name' => $export_name,
                    'note' => $note,
                    'status' => 'un_approved',
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'total_quantity_exchange' => $total_quantity_exchange,
                    'created_by' => get_staff_user_id(),
                    'date_created' => date('Y-m-d H:i:s'),
                    'type' => '3',
                ];
                $suggest_exporting_id = $this->manufactures_model->insertSuggestExporting($fields);
                if ($suggest_exporting_id) {
                    if (getReference('suggest_exporting') == $this->input->post('reference_no')) {
                        updateReference('suggest_exporting');
                    }
                    foreach ($exporting_items as $key => $value) {
                        $exporting_items[$key]['suggest_exporting_id'] = $suggest_exporting_id;
                    }
                    $this->manufactures_model->insertBatchSuggestExportingItems($exporting_items);

                    @pusherTNHNotfication();
                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($productions_orders_detail_id);
                    $content = lang('tnh_his_export_supplies_productions_orders_details');
                    $content = str_replace('{$1}', $reference_no, $content);
                    $content = str_replace('{$2}', $pod['reference_no'], $content);
                    insertActivityLog([
                        'type_parent_obj' => 'suggest_exporting',
                        'table_obj' => 'tbl_suggest_exporting',
                        'id_obj' => $suggest_exporting_id,
                        'name_obj' => $reference_no,
                        'content' => $content,
                        'actions' => 'add'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $data['reference_no'] = getReference('suggest_exporting');
            $data['breadcrumb'] = [array('link' => base_url('admin/manufactures/list_suggest_exporting'), 'page' => lang('list_suggest_exporting')), array('link' => '#', 'page' => lang('tnh_add_suggest_exporting'))];
            $data['title'] = lang('tnh_add_suggest_exporting');
            $data['tnh'] = $this->tnh;
            $this->load->view('admin/manufactures/add_suggest_exporting', $data);
        }
    }

    public function edit_exporting_production($id)
    {
        $suggest_exporting = $this->manufactures_model->rowSuggestExporting($id);
        if ($suggest_exporting['status'] != "un_approved") {
            refererModel(lang('browsed_cannot_be_edited'));
        }
        if ($suggest_exporting['type'] != 3) {
            refererModel(lang('tnh_not_edit_for_bom'));
        }
        if ($this->input->post('edit')) {
            $data = [];
            if ($suggest_exporting['reference_no'] != $this->input->post('reference_no')) {
                $this->form_validation->set_rules('reference_no', lang("tnh_reference_no_suggest"), 'required|is_unique[tbl_suggest_exporting.reference_no]');
            }
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('export_name', lang("tnh_export_name"), 'required');
            $this->form_validation->set_rules('productions_orders_detail_id', lang("tnh_reference_productions_orders_details"), 'required');

            if ($this->form_validation->run() == true) {
                $reference_no = $this->input->post('reference_no');
                $date = to_sql_date($this->input->post('date'), true);
                // $productions_orders_detail_id = $this->input->post('productions_orders_detail_id');
                $note = $this->input->post('note', false);
                $export_name = $this->input->post('export_name');
                $items = $this->input->post('items_id');
                $total_quantity = 0;
                $count_items = 0;
                $total_quantity_exchange = 0;
                $type = 3;

                $errors = false;

                //insert
                if (!empty($items)) {
                    foreach ($items as $key => $value) {
                        if (empty($value)) continue;
                        $unit_id = $this->input->post('unit_id')[$key];
                        $unit_parent_id = $this->input->post('unit_parent_id')[$key];
                        $number_exchange = $this->input->post('number_exchange')[$key];
                        $quantity_export = number_unformat($this->input->post('quantity')[$key]);
                        $arr_item = explode('__', $value);
                        $type_item = $arr_item[0];
                        $item_id = $arr_item[1];
                        if ($type_item == "semi_products_outside" || $type_item == "semi_products") {
                            $info_item = $this->products_model->rowProduct($item_id);
                        } else if ($type_item == "materials") {
                            $info_item = $this->items_model->rowMaterial($item_id);
                        } else if ($type_item == "tools_supplies") {
                            $info_item = $this->tools_supplies_model->rowToolsSupplies($item_id);
                        }
                        if (empty($info_item)) continue;

                        $quantity_exchange = $quantity_export / $number_exchange;
                        $exporting_items[] = [
                            'suggest_exporting_id' => $id,
                            'type_item' => $type_item,
                            'item_id' => $item_id,
                            'item_code' => $info_item['code'],
                            'item_name' => $info_item['name'],
                            'unit_id' => $unit_id,
                            'quantity_export' => $quantity_export,
                            'unit_parent_id' => $unit_parent_id,
                            'number_exchange' => $number_exchange,
                            'quantity_exchange' => $quantity_exchange,
                        ];
                        $total_quantity += $quantity_export;
                        $total_quantity_exchange += $quantity_exchange;
                    }
                }
                //updated
                $arr_id = [];
                $suggest_exporting_items_id = $this->input->post('suggest_exporting_items_id');
                if (!empty($suggest_exporting_items_id)) {
                    foreach ($suggest_exporting_items_id as $key => $value) {
                        if (empty($value)) continue;
                        $row = $this->stock_model->rowSuggestExportingItems($value);
                        if (empty($row)) continue;
                        array_push($arr_id, $value);
                        $number_exchange = $row['number_exchange'];
                        $quantity_export = number_unformat($this->input->post('quantity_edit')[$key]);
                        $quantity_exchange = $quantity_export / $number_exchange;

                        $exporting_items_up[] = [
                            'id' => $value,
                            'quantity_export' => $quantity_export,
                            'quantity_exchange' => $quantity_exchange,
                        ];
                        $total_quantity += $quantity_export;
                        $total_quantity_exchange += $quantity_exchange;
                    }
                }
                //
                if (empty($exporting_items) && empty($exporting_items_up)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_no_items');
                    echo json_encode($data);
                    die;
                }

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data);
                    die;
                }

                $count_items = (!empty($exporting_items) ? count($exporting_items) : 0) + (!empty($exporting_items_up) ? count($exporting_items_up) : 0);
                $fields = [
                    'reference_no' => $reference_no,
                    'reference_stock' => null,
                    'date' => $date,
                    'export_name' => $export_name,
                    'note' => $note,
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'total_quantity_exchange' => $total_quantity_exchange,
                    'updated_by' => get_staff_user_id(),
                    'date_updated' => date('Y-m-d H:i:s'),
                ];
                $up = $this->manufactures_model->updateSuggestExportingById($id, $fields);
                if ($up) {
                    //delete
                    $delete = $this->manufactures_model->getSuggestExportingItemsByNotArrId($arr_id, $id);
                    if (!empty($delete)) {
                        foreach ($delete as $key => $value) {
                            $this->manufactures_model->deleteSuggestExportingItemsById($value['id']);
                        }
                    }
                    //add
                    if (!empty($exporting_items)) {
                        $this->manufactures_model->insertBatchSuggestExportingItems($exporting_items);
                    }
                    //edit
                    if (!empty($exporting_items_up)) {
                        $this->manufactures_model->updateBatchSuggestExportingItemsById($exporting_items_up);
                    }

                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($suggest_exporting['productions_orders_details_id']);
                    $content = lang('tnh_his_edit_export_supplies_productions_orders_details');
                    $content = str_replace('{$1}', $suggest_exporting['reference_no'], $content);
                    $content = str_replace('{$2}', $pod['reference_no'], $content);
                    insertActivityLog([
                        'type_parent_obj' => 'suggest_exporting',
                        'table_obj' => 'tbl_suggest_exporting',
                        'id_obj' => $id,
                        'name_obj' => $suggest_exporting['reference_no'],
                        'content' => $content,
                        'actions' => 'edit'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $suggest_exporting_items = $this->stock_model->getSuggestExportingItemsForStock($id);
            $data['suggest_exporting'] = $suggest_exporting;
            $data['production_orders_detail'] = $this->manufactures_model->rowProductionsOrdersDetais($suggest_exporting['productions_orders_details_id']);
            $data['suggest_exporting_items'] = $suggest_exporting_items;
            $data['id'] = $id;
            $data['breadcrumb'] = [array('link' => base_url('admin/manufactures/list_suggest_exporting'), 'page' => lang('list_suggest_exporting')), array('link' => '#', 'page' => lang('tnh_edit_suggest_exporting'))];
            $data['title'] = lang('tnh_edit_suggest_exporting');
            $data['tnh'] = $this->tnh;
            $this->load->view('admin/manufactures/edit_exporting_production', $data);
        }
    }

    public function refereshReferenceSuggestExporting()
    {
        $data = [];
        if ($this->input->get('referesh')) {
            $reference_no = getReference('suggest_exporting');
            if ($this->manufactures_model->checkExistSuggestExportingReferenceNo($reference_no)) {
                $ct = countReferenceMinus('suggest_exporting');
                $this->db->select("MAX(right(tbl_suggest_exporting.reference_no, char_length(tbl_suggest_exporting.reference_no) - $ct) + 0) as reference_no", false);
                $this->db->from('tbl_suggest_exporting');
                $rs = $this->db->get()->row_array();

                $max = $rs['reference_no'];
                $max++;
                // $max = subReference($max);
                updateReferenceNormal('suggest_exporting', $max);
                $reference_no = getReference('suggest_exporting');
            }
            $data['reference_no'] = $reference_no;
            $data['message'] = lang('tnh_referesh_success');
        }
        echo json_encode($data);
    }

    public function updateInfoStage()
    {
        $data = [];
        if ($this->input->post()) {
            $updateInfoStageId = $this->input->post('updateInfoStageId');
            $productionsOISId = $this->input->post('productionsOISId');
            $productionsODId = $this->input->post('productionsODId');
            $employeeId = $this->input->post('employeeId');
            $dateStart = $this->input->post('dateStart');
            $dateEnd = $this->input->post('dateEnd');
            $quantityBad = $this->input->post('quantityBad');
            $quantitySuccess = $this->input->post('quantitySuccess');
            $totalTime = minusDate($dateStart, $dateEnd);
            $flag = false;
            $maxIdCurrent = $this->input->post('maxId');

            $maxId = $this->manufactures_model->getMaxUpdateInfoStage($productionsODId, $productionsOISId)['max_id'];
            if ($maxIdCurrent != $maxId) {
                $data['result'] = 0;
                $data['message'] = lang('tnh_please_referesh_page_because_data_changes');
                echo json_encode($data);
                die;
            }

            $field = [
                'employee_id' => $employeeId,
                'date_start' => to_sql_date($dateStart),
                'date_end' => to_sql_date($dateEnd),
                'total_time' => $totalTime,
                'quantity_bad' => $quantityBad,
                'quantity_success' => $quantitySuccess,
                'productions_od_id' => $productionsODId,
                'productions_ois_id' => $productionsOISId,
            ];

            if ($updateInfoStageId > 0) {
                //update
                $field['updated_by'] = get_staff_user_id();
                $field['date_updated'] = date('Y-m-d H:i:s');
                $updateInfoStageOld = $this->manufactures_model->rowUpdateInfoStageById($updateInfoStageId);
                $up = $this->manufactures_model->updateUpdateInfoStage($updateInfoStageId, $field);
                if ($up) {
                    $quantityBad = $quantityBad - $updateInfoStageOld['quantity_bad'];
                    $quantitySuccess = $quantitySuccess - $updateInfoStageOld['quantity_success'];
                    $quantitySuccess = $updateInfoStageOld['quantity_success'] + $quantitySuccess;
                    $totalTime = $totalTime - $updateInfoStageOld['total_time'];
                    $this->manufactures_model->updateQuantityBadAndSuccess($productionsOISId, $quantityBad, $quantitySuccess, $totalTime, $otions = 1);
                    $flag = true;
                }
            } else {
                //insert
                $field['created_by'] = get_staff_user_id();
                $field['date_created'] = date('Y-m-d H:i:s');
                $ins = $this->manufactures_model->insertUpdateInfoStage($field);
                if ($ins) {
                    //
                    $this->manufactures_model->updateQuantityBadAndSuccess($productionsOISId, $quantityBad, $quantitySuccess, $totalTime, $otions = 1);
                    $updateInfoStageId = $ins;
                    $flag = true;
                }
            }
            if ($flag) {
                $data['result'] = 1;
                $data['message'] = lang('success');
                $data['view'] = $this->getDataDetailProduction($productionsODId, $productionsOISId);
                $data['updateInfoStageId'] = $updateInfoStageId;
                //handling quantity finished
                $productionOIS = $this->manufactures_model->rowProductionsOrdersItemsStagesId($productionsOISId);
                if ($productionOIS['final_stage'] == 1) {
                    // $this->manufactures_model->updateProductionsOrdersDetailsById($productionsODId, [
                    //     'quantity_finished' => $productionOIS['total_quantity_success']
                    // ]);
                    // $data['quantityFinished'] = $productionOIS['total_quantity_success'];
                }
                //end
                $pod = $this->manufactures_model->rowProductionsOrdersDetais($productionsODId);
                insertActivityLog([
                    'type_parent_obj' => 'productions_orders_details',
                    'table_obj' => 'tbl_productions_orders_details',
                    'id_obj' => $productionsODId,
                    'name_obj' => $pod['reference_no'],
                    'content' => lang('tnh_his_update_report_productions_orders_details') . ' [' . $pod['reference_no'] . ']',
                    'actions' => 'update_report'
                ]);
            } else {
                $data['result'] = 0;
                $data['message'] = lang('fail');
            }
        }
        echo json_encode($data);
    }

    public function getDataDetailProduction($productions_od_id, $ois_id)
    {
        @$maxId = $this->manufactures_model->getMaxUpdateInfoStage($productions_od_id, $ois_id)['max_id'];
        $update_info_stage = $this->manufactures_model->getUpdateInfoStage($productions_od_id, $ois_id);

        $data['employees'] = $this->manufactures_model->getAllStaff();
        $data['update_info_stage'] = $update_info_stage;
        $data['productions_od_id'] = $productions_od_id;
        $data['ois_id'] = $ois_id;
        $data['maxId'] = $maxId;
        ob_start();
        $this->load->view('admin/manufactures/dataUpdateInfo', $data);
        $content = ob_get_contents();
        ob_end_clean();
        return $content;
    }

    public function updateQuantityFinishedPre()
    {
        $data = [];
        if ($this->input->post()) {
            $productions_orders_detail_id = $this->input->post('productions_orders_detail_id');
            $productions_orders_items_stage_id = $this->input->post('productions_orders_items_stage_id');
            $quantity = number_unformat($this->input->post('quantity_pre'));
            $flag = false;
            if (!empty($productions_orders_detail_id) && !empty($productions_orders_items_stage_id)) {

                $field = [
                    'productions_orders_detail_id' => $productions_orders_detail_id,
                    'productions_orders_items_stage_id' => $productions_orders_items_stage_id,
                    'quantity' => $quantity,
                ];

                if (!$this->manufactures_model->checkQuantityFinishedPre($productions_orders_detail_id, $productions_orders_items_stage_id)) {
                    $field['created_by'] = get_staff_user_id();
                    $field['date_created'] = date('Y-m-d H:i:s');
                    if ($this->manufactures_model->insertQuantityFinishedPre($field)) {
                        $flag = true;
                    }
                } else {
                    $field['updated_by'] = get_staff_user_id();
                    $field['date_updated'] = date('Y-m-d H:i:s');

                    if ($this->manufactures_model->updateQuantityFinishedPre($productions_orders_detail_id, $productions_orders_items_stage_id, $field)) {
                        $flag = true;
                    }
                }
                if ($flag) {
                    //update info stage
                    $updateInfoStage = $this->manufactures_model->getUpdateInfoStageHandings($productions_orders_detail_id, $productions_orders_items_stage_id);
                    $total_quantity_bad = 0;
                    $total_quantity_success = $quantity;
                    if (!empty($updateInfoStage)) {
                        foreach ($updateInfoStage as $key => $value) {
                            $quantity_bad = $value['quantity_bad'];
                            $quantity_success = $total_quantity_success - $quantity_bad;
                            $up[] = [
                                'id' => $value['id'],
                                'quantity_bad' => $quantity_bad,
                                'quantity_success' => $quantity_success,
                                'updated_by' => get_staff_user_id(),
                                'date_updated' => date('Y-m-d H:i:s')
                            ];

                            $total_quantity_bad += $quantity_bad;
                            $total_quantity_success = $quantity_success;
                        }
                    }

                    if (!empty($up)) {
                        $this->manufactures_model->updateBatchUpdateInfoStage($up);
                        $this->manufactures_model->updateProductionsOrdersItemsStages($productions_orders_items_stage_id, [
                            'total_quantity_bad' => $total_quantity_bad,
                            'total_quantity_success' => $total_quantity_success,
                        ]);

                        //handling quantity finished
                        $productionOIS = $this->manufactures_model->rowProductionsOrdersItemsStagesId($productions_orders_items_stage_id);
                        if ($productionOIS['final_stage'] == 1) {
                            // $this->manufactures_model->updateProductionsOrdersDetailsById($productions_orders_detail_id, [
                            //     'quantity_finished' => $productionOIS['total_quantity_success']
                            // ]);
                            // $data['quantityFinished'] = $productionOIS['total_quantity_success'];
                        }
                        //end
                    }

                    $data['view'] = $this->getDataDetailProduction($productions_orders_detail_id, $productions_orders_items_stage_id);

                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($productions_orders_detail_id);
                    insertActivityLog([
                        'type_parent_obj' => 'productions_orders_details',
                        'table_obj' => 'tbl_productions_orders_details',
                        'id_obj' => $pod['id'],
                        'name_obj' => $pod['reference_no'],
                        'content' => lang('tnh_his_update_quantity_finished_productions_orders') . ' [' . $pod['reference_no'] . ']',
                        'actions' => 'update_quantity_finished'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            }
        }
        echo json_encode($data);
    }

