                } else {
                    $strStatus = '<div class="text-center"><span data-html="true" data-toggle="popover" data-container="body" data-placement="left" style="cursor: pointer;" title="' . lang('tnh_status') . '" data-content="<p><a id=\'agree-items\' productions_orders_details_id=\'' . $productionsOD['id'] . '\' value=\'complete_production\' class=\'btn btn-success\'>' . lang('tnh_agree_finished') . '</a><button class=\'btn po-close\'>' . lang('close') . '</button></p>" class="label label-warning po">' . lang('tnh_producing') . '</span></div>';
                }

                $data['result'] = 1;
                $data['message'] = lang('success');
                $data['strStatus'] = $strStatus;
            } else {
                $data['result'] = 0;
                $data['message'] = lang('fail');
            }
        }
        echo json_encode($data);
    }

    public function addWarehousingNew($id)
    {
        $item = $this->manufactures_model->rowProductionsOrdersDetaisForWarehousing($id);
        // if ($item['status'] != 'complete_production') {
        //     refererModel(lang('tnh_please_approved_completed'));
