                    $data['message'] = lang('success');
                    $data['quantity_warehoused'] = $quantity_warehoused;
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $data['id'] = $id;
            $data['item'] = $item;
            $data['warehouses'] = $this->stock_model->getWarehouses();
            $data['tasks'] = $this->manufactures_model->getTaskPodWork($id);
            $this->load->view('admin/manufactures/add_warehousing_new', $data);
        }
    }

    public function addWarehousing($id)
    {
        $this->perApproveWarehousePurchaseProducts = has_permission('stock_purchase_products', '', 'approve_warehouse');
        $item = $this->manufactures_model->rowProductionsOrdersDetaisForWarehousing($id);
        // if ($item['status'] != 'complete_production') {
        //     refererModel(lang('tnh_please_approved_completed'));
        //     return;
        // }
        // if (empty($item['check_quality_id'])) {
        //     refererModel(lang('tnh_please_created_qc_after_warehousing'));
        //     return;
        // }
        // $quality =  $this->quality_control_model->rowCheckQuality($item['check_quality_id']);
        // if ($quality['status'] != "allowed_to_stock") {
        //     refererModel(lang('tnh_qc_not_warehousing'));
        //     return;
        // }

        if ($this->input->post('save')) {
            $this->form_validation->set_rules('warehouses', lang("tnh_warehouses"), 'required');
            // $this->form_validation->set_rules('task_work', lang("tnh_task"), 'required');
            if ($this->form_validation->run() == true) {
                // print_arrays($this->input->post(), $item);
                $warehouse_id = $this->input->post('warehouses');
                $location_warehouse = $this->input->post('location_warehouse');
                $quantity = number_unformat($this->input->post('quantity'));
                $note_item = $this->input->post('note_item');
                $task_work = $this->input->post('task_work');
                $task_work = 0;

                $quantity_finished = $item['quantity_finished'];
                $quantity_warehoused = $item['quantity_warehoused'];
                $quantity_less = $quantity_finished - $quantity_warehoused;
                $save_and_warehouse = !empty($this->input->post('save_and_warehouse')) ? $this->input->post('save_and_warehouse') : 0;

                // if ($quantity > $quantity_less) {
                //     $data['result'] = 0;
                //     $data['message'] = lang('tnh_quantity_less').' '.$quantity;
                //     echo json_encode($data); die;
                // }

                //exchange
                $exchange = [];
                $type_item = $item['type_items'];
                $item_id = $item['items_id'];
                if ($type_item == "products" || $type_item == "semi_products" || $type_item == "semi_products_outside") {
                    $exchangeUnits = $this->products_model->getExchangeProductsByProductId($item_id);
                    if (!empty($exchangeUnits)) {
                        foreach ($exchangeUnits as $k => $val) {
                            if (empty($val)) continue;
                            $quantity_exchange = $val['number_exchange'];
                            $total_quantity_exchange = $quantity/$quantity_exchange;
                            $exchange[] = [
                                'unit_id' => $val['unit_id'],
                                'quantity_exchange' => $quantity_exchange,
                                'total_quantity_exchange' => $total_quantity_exchange,
                            ];
                        }
                    }
                }
                //end exchange

                $items = [
                    'item_id' => $item['items_id'],
                    'item_code' => $item['items_code'],
                    'item_name' => $item['items_name'],
                    'type_item' => $item['type_items'],
                    'productions_orders_details_id' => $id,
                    'quantity' => $quantity,
                    'location_id' => $location_warehouse,
                    'note_item' => $note_item,
                    'exchange' => $exchange,
                ];

                $reference_no = getReference('purchase_products');
                $option = [
                    'task_id' => $task_work,
                    'reference_no' => $reference_no,
                    'date' => date('Y-m-d H:i:s'),
                    'productions_orders_details_id' => $id,
                    'warehouse_id' => $warehouse_id,
                    'count_items' => 1,
                    'total_quantity' => $quantity,
                    'created_by' => get_staff_user_id(),
                    'date_created' => date('Y-m-d H:i:s'),
                    'status' => 'un_approved',
                    'type' => 1,
                    'save_and_warehouse' => $save_and_warehouse
                ];
                // print_arrays($option);
                // $warehousing_id = $this->manufactures_model->insertWarehousingProduct($option);
                $warehousing_id = $this->stock_model->insertPurchaseProducts($option);
                if ($warehousing_id) {
                    // updateReference('warehousing');
                    // $items['warehousing_product_id'] = $warehousing_id;
                    // $this->manufactures_model->insertWarehousingProductItems($items);

                    updateReference('purchase_products');
                    $items['purchase_product_id'] = $warehousing_id;
                    $exchange = $items['exchange'];
                    unset($items['exchange']);
                    $purchase_product_item_id = $this->stock_model->insertPurchaseProductItems($items);
                    $quantity_warehoused = $quantity + $quantity_warehoused;
                    $this->manufactures_model->updateProductionsOrdersDetailsById($item['id'], ['quantity_warehoused' => $quantity_warehoused]);

                    $this->manufactures_model->updateSetPOD($id, $quantity, $plus = 0);

                    if (!empty($exchange)) {
                        foreach ($exchange as $k => $val) {
                            $val['purchase_product_items_id'] = $purchase_product_item_id;
                            $this->stock_model->insertPurchaseProductItemExchange($val);
                        }
                    }

                    //approved
                    if ($this->perApproveWarehousePurchaseProducts) {
                        if (!empty($save_and_warehouse)) {
                            $purchaseProduct = $this->stock_model->rowPurchaseProducts($warehousing_id);
                            $_data = array(
                                'status' => 'approved',
                                'warehouseman_id' => get_staff_user_id(),
                                'date_warehouseman' => date('Y-m-d H:i:s')
                            );
                            $success = $this->db->update('tbl_purchase_products', $_data, array('id' => $warehousing_id));
                            if ($success) {
                                log_activity('Import Warehouses items approved [ID export_warehouses: ' . $warehousing_id);
                                $this->stock_model->decreaseWarehouse_purchase_products($warehousing_id);

                                //activity log
                                if (!empty($purchaseProduct['productions_orders_details_id'])) {
                                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($purchaseProduct['productions_orders_details_id']);
                                    $content = lang('tnh_his_warehouse_purchase_product_pod');
                                    $content = str_replace('{$1}', $purchaseProduct['reference_no'], $content);
                                    $content = str_replace('{$2}', $pod['reference_no'], $content);
                                } else {
                                    $content = lang('tnh_his_warehouse_purchase_product');
                                    $content = str_replace('{$1}', $purchaseProduct['reference_no'], $content);
                                }
                                insertActivityLog([
                                    'type_parent_obj' => 'purchase_products',
                                    'table_obj' => 'tbl_purchase_products',
                                    'id_obj' => $warehousing_id,
                                    'name_obj' => $purchaseProduct['reference_no'],
                                    'content' => $content,
                                    'actions' => 'warehouse'
                                ]);
                                //end activity log
                            }
                        }
                    }

                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($id);
                    $content = lang('tnh_his_add_purchase_products_productions_orders_details');
                    $content = str_replace('{$1}', $reference_no, $content);
                    $content = str_replace('{$2}', $pod['reference_no'], $content);
                    insertActivityLog([
                        'type_parent_obj' => 'purchase_products',
                        'table_obj' => 'tbl_purchase_products',
                        'id_obj' => $warehousing_id,
                        'name_obj' => $reference_no,
                        'content' => $content,
                        'actions' => 'add'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                    $data['quantity_warehoused'] = $quantity_warehoused;
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $data['id'] = $id;
            $data['item'] = $item;
            $data['warehouses'] = $this->stock_model->getWarehouses();
            $data['tasks'] = $this->manufactures_model->getTaskPodWork($id);
            $this->load->view('admin/manufactures/add_warehousing', $data);
        }
    }

