    public function gantt_pod()
    {
        $this->perViewGanntPOD = has_permission('manufactures_gantt_pod', '', 'view');
        $this->perViewOWnGanntPOD = has_permission('manufactures_gantt_pod', '', 'view_own');

        if (!$this->perViewGanntPOD && !$this->perViewOWnGanntPOD) {
            accessDenied();
        }

        if ($this->input->post('search') == 'unsearch') {
            $_POST = array();
        }

        $data['title'] = lang('tnh_diagram_gantt_lsx');
        $data['tnh'] = $this->tnh;

        $sum = $this->site_model->countProductionsGantt();
        $numberPage = get_option('number_page_gantt');
        $numPages = ceil($sum / $numberPage);
        $pageCurrent = !empty($this->input->get('page')) ? $this->input->get('page') : 1;
        $start = ($pageCurrent - 1) * $numberPage;
        // $limit   = $numberPage * $pageCurrent - 1;
        $data['numberPage'] = $numberPage;
        $data['numPages'] = $numPages;
        $data['pageCurrent'] = $pageCurrent;
        $data['gantt_data'] = $this->site_model->loadGanttProductionsNews($start, $numberPage);
        $this->load->view('admin/manufactures/gantt_pod', $data);
    }

    public function purchaseInternal($id)
    {
        $pod = $this->manufactures_model->rowProductionsOrdersByDetail($id);
        if ($this->input->post('save')) {
            $data = [];
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('enter_name', lang("tnh_enter_name"), 'required');
            $this->form_validation->set_rules('warehouses', lang("tnh_warehouses"), 'required');
            if ($this->form_validation->run() == true) {
                $date = to_sql_date($this->input->post('date'), true);
                $productions_orders_detail_id = $id;
                $note = $this->input->post('note', false);
                $enter_name = $this->input->post('enter_name');
                $warehouses = $this->input->post('warehouses');
                $items = $this->input->post('items_id');
                $total_quantity = 0;
                $grand_total = 0;
                $count_items = 0;

                if (!empty($items)) {
                    foreach ($items as $key => $value) {
                        if (empty($value)) continue;
                        $location = $this->input->post('locations')[$key];
                        $quantity = number_unformat($this->input->post('quantity')[$key]);

                        $arr_item = explode('__', $value);
                        $type_item = $arr_item[0];
                        $item_id = $arr_item[1];
                        $info_item = '';

                        $typeWarehouse = '';
                        if ($type_item == "materials") {
                            $info_item = $this->items_model->rowMaterial($item_id);
                            $typeWarehouse = 'nvl';
                        } else if ($type_item == "tools_supplies") {
                            $info_item = $this->tools_supplies_model->rowToolsSupplies($item_id);
                            $typeWarehouse = 'tools';
                        } else {
                            $info_item = $this->products_model->rowProduct($item_id);
                            $typeWarehouse = 'product';
                        }

                        // $price_internal = number_unformat($this->input->post('price_internal')[$key]);
                        $priceLast = $this->manufactures_model->getPriceLastNotZero($item_id, $typeWarehouse);
                        $price_internal = 0;
                        if (!empty($priceLast)) {
                            $price_internal = $priceLast['price'];
                        }
                        $amount = $quantity * $price_internal;
                        $grand_total += $amount;

                        if (empty($info_item)) continue;
                        if (empty($location)) {
                            $errors = lang('tnh_location_warehouse_required');
                            break;
                        }

                        $note_item = $this->input->post('note_item')[$key];

                        $its[] = [
                            'type_item' => $type_item,
                            'item_id' => $item_id,
                            'item_code' => $info_item['code'],
                            'item_name' => $info_item['name'],
                            'unit_id' => $info_item['unit_id'],
                            'location_id' => $location,
                            'quantity' => $quantity,
                            'note_item' => $note_item,
                            'price' => $price_internal,
                            'amount' => $amount,
                        ];
                        $total_quantity += $quantity;
                    }
                }

                // print_arrays($its);

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data);
                    die;
                }

                if (empty($its)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_no_items');
                    echo json_encode($data);
                    die;
                }
                $count_items = count($its);
                $fields = [
                    'pod_id' => $productions_orders_detail_id,
                    'reference_no' => getReference('purchase_internal'),
                    'date' => $date,
                    'enter_name' => $enter_name,
                    'note' => $note,
                    'status' => 'un_approved',
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'warehouse_id' => $warehouses,
                    'created_by' => get_staff_user_id(),
                    'date_created' => date('Y-m-d H:i:s'),
                    'status' => 'un_approved',
                    'grand_total' => $grand_total,
                    'type' => 2,
                ];

                $idPurchaseInternal = $this->stock_model->insertPurchaseInternal($fields);
                if ($idPurchaseInternal) {
                    updateReference('purchase_internal');
                    foreach ($its as $key => $value) {
                        $its[$key]['purchase_internal_id'] = $idPurchaseInternal;
                    }
                    $this->stock_model->insertBatchPurchaseInternalItems($its);
                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
        } else {
            $data['pod'] = $pod;
            $data['id'] = $id;
            $data['warehouses'] = $this->stock_model->getWarehouses();
            $data['tnh'] = $this->tnh;
            $this->load->view('admin/manufactures/purchase_internal', $data);
        }
    }

    public function checkQuality($id)
    {
        if (!$this->perQC) {
            accessDenied($js = true);
        }
        $pod = $this->manufactures_model->rowProductionsOrdersByDetail($id);
        if (empty($pod)) {
            refererModel(lang('no_data_exists'));
            $data['result'] = 0;
            $data['message'] = lang('no_data_exists');
            echo json_encode($data);
            die;
        }
        // if ($pod['status'] != 'complete_production') {
        //     refererModel(lang('tnh_this_is_not_completed'));
        //     $data['result'] = 0;
        //     $data['message'] = lang('tnh_this_is_not_completed');
        //     echo json_encode($data);
        //     die;
        // }
        if ($pod['check_quality_id'] > 0) {
            refererModel(lang('tnh_created_check_quality'));
            $data['result'] = 0;
            $data['message'] = lang('tnh_created_check_quality');
            echo json_encode($data);
            die;
        }
        if ($this->input->post('save')) {
            $data = [];
            // $this->form_validation->set_rules('reference_no', lang("tnh_reference_qc"), 'trim|required|is_unique[tbl_check_quality.reference_no]');
            $this->form_validation->set_rules('date', lang("date"), 'required');
            $this->form_validation->set_rules('employee', lang("tnh_employee_checks"), 'required');
            if ($this->form_validation->run() == true) {
                // $reference_no = $this->input->post('reference_no');
                $reference_no = getReference('qc');
                $date = to_sql_date($this->input->post('date'), true);
                $employee = $this->input->post('employee');
                $quantity_qc = number_unformat($this->input->post('quantity_qc'));
                $status = $this->input->post('status');
                $note = $this->input->post('note', false);

                $counter = $this->input->post('counter');
                if (!empty($counter)) {
                    foreach ($counter as $key => $value) {
                        $category_check_id = $this->input->post('category_checks')[$value];
                        $category_result_id = $this->input->post('category_results')[$value];
                        $category_error_id = $this->input->post('category_errors')[$value];
                        $detail_error_id = $this->input->post('detail_error')[$value];
                        $category_cause_error_id = $this->input->post('category_cause_errors')[$value];
                        $items[] = [
                            'item_id' => $pod['items_id'],
                            'category_check_id' => $category_check_id,
                            'category_result_id' => $category_result_id,
                            'category_error_id' => $category_error_id,
                            'detail_error_id' => $detail_error_id,
                            'category_cause_error_id' => $category_cause_error_id,
                        ];
                    }
                }
                if (empty($items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_not_items');
                    echo json_encode($data);
                    die;
                }

                $options = [
                    'date' => $date,
                    'reference_no' => $reference_no,
                    'employee_id' => $employee,
                    'pod_id' => $id,
                    'quantity_qc' => $quantity_qc,
                    'note' => $note,
                    'status' => $status,
                    'created_by' => get_staff_user_id(),
                    'date_created' => date('Y-m-d H:i:s'),
                ];

                $checkQualityId = $this->quality_control_model->insertCheckQuality($options);
                if ($checkQualityId) {
                    if (getReference('qc') == $reference_no) {
                        updateReference('qc');
                    }
                    foreach ($items as $key => $value) {
                        $items[$key]['check_quality_id'] = $checkQualityId;
                    }
                    $this->quality_control_model->insertBatchCheckQualityItem($items);
                    $this->manufactures_model->updateProductionsOrdersDetailsById($id, ['check_quality_id' => $checkQualityId]);

                    $content = lang('tnh_his_check_quality_productions_orders_details');
                    $content = str_replace('{$1}', $reference_no, $content);
                    $content = str_replace('{$2}', $pod['reference_no'], $content);
                    insertActivityLog([
                        'type_parent_obj' => 'check_quality',
                        'table_obj' => 'tbl_check_quality',
                        'id_obj' => $checkQualityId,
                        'name_obj' => $reference_no,
                        'content' => $content,
                        'actions' => 'add'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $data['categoryChecks'] = $this->quality_control_model->getCategoryChecks();
            $data['categoryErrors'] = $this->quality_control_model->getCategoryErrors();
            $data['categoryResults'] = $this->quality_control_model->getCategoryResults();
            $data['categoryCauseErrors'] = $this->quality_control_model->getCategoryCauseErrors();
            $data['employees'] = $this->manufactures_model->getAllStaff();
            $data['reference_no'] = getReference('qc');
            $data['pod'] = $pod;
            $data['id'] = $id;
            $data['tnh'] = $this->tnh;
            $this->load->view('admin/manufactures/check_quality', $data);
        }
    }

