    function refereshCheckQuality()
    {
        $data = [];
        if ($this->input->get('referesh')) {
            $reference_no = getReference('qc');
            if ($this->quality_control_model->checkExistCheckQualityReferenceNo($reference_no)) {
                $ct = countReferenceMinus('qc');
                $this->db->select("MAX(right(tbl_check_quality.reference_no, char_length(tbl_check_quality.reference_no) - $ct) + 0) as reference_no", false);
                $this->db->from('tbl_check_quality');
                $rs = $this->db->get()->row_array();

                $max = $rs['reference_no'];
                $max++;
                updateReferenceNormal('qc', $max);
                $reference_no = getReference('qc');
            }
            $data['reference_no'] = $reference_no;
            $data['message'] = lang('tnh_referesh_success');
        }
        echo json_encode($data);
    }

    public function getPurchaseInternalByDetailProductions($id)
    {
        $this->datatables
            ->select("
                0 as number_records,
                tbl_purchase_internal.id as id,
                tbl_purchase_internal.date as date,
                tbl_purchase_internal.reference_no as reference_no,
                tbl_purchase_internal.enter_name as enter_name,
                tblwarehouse.name as warehouse_name,
                tbl_purchase_internal_items.item_code as item_code,
                tbl_purchase_internal_items.item_name as item_name,
                tblunits.unit as unit_name,
                tbllocaltion_warehouses.name as location_name,
                tbl_purchase_internal_items.quantity as quantity,
                CONCAT(tblstaff.firstname, ' ', tblstaff.lastname, '') as created_by,
                tbl_purchase_internal_items.note_item as note_item,
            ", false)
            ->from('tbl_purchase_internal')
            ->join('tbl_purchase_internal_items', 'tbl_purchase_internal_items.purchase_internal_id = tbl_purchase_internal.id', 'inner')
            ->join('tblstaff', 'tblstaff.staffid = tbl_purchase_internal.created_by', 'left')
            ->join('tblunits', 'tblunits.unitid = tbl_purchase_internal_items.unit_id', 'left')
            ->join('tbllocaltion_warehouses', 'tbllocaltion_warehouses.id = tbl_purchase_internal_items.location_id', 'left')
            ->join('tblwarehouse', 'tblwarehouse.id = tbl_purchase_internal.warehouse_id', 'left');

        $this->datatables->where('tbl_purchase_internal.pod_id', $id);
        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;
        }
        echo json_encode($data);
    }

