    public function getHistoryProductionsDetail($id)
    {
        $pod = $this->manufactures_model->rowProductionsOrdersDetais($id);
        $this->datatables
            ->select("
                0 as number_records,
                tblactivity_log_v2.date as date,
                tblactivity_log_v2.type_parent_obj as type,
                tblactivity_log_v2.content as content,
                CONCAT(tblstaff.firstname, ' ', tblstaff.lastname) as created_by
            ", false)
            ->from('tblactivity_log_v2')
            ->join('tblstaff', 'tblstaff.staffid = tblactivity_log_v2.staff_id', 'left');

        $this->datatables->like('tblactivity_log_v2.content', $pod['reference_no']);
        $this->datatables->where('tblactivity_log_v2.type_parent_obj IN ("suggest_exporting", "productions_orders_details", "check_quality", "purchase_products", "exporting_producion", "purchase_internal")');
        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;
        }
        echo json_encode($data);
    }

    public function getTasksPOD($id)
    {
        $is_admin = is_admin();
        $staff_id = get_staff_user_id();
        $tags = '(
            SELECT GROUP_CONCAT(name SEPARATOR ",")
            FROM tbltaggables
            JOIN tbltags ON tbltaggables.tag_id = tbltags.id
            WHERE tbltaggables.rel_id = tbltasks.id AND rel_type = "task"
            ORDER by tbltaggables.tag_order ASC
        )';

        $this->datatables
            ->select('
                0 as number_records,
                CONCAT(tbltasks.name, "__", tbltasks.id) as task_name,
                COALESCE(tbl_shift_work.name, "") as name_shift_work,
                tbltasks.status as task_status,
                tbltasks.startdate as task_startdate,
                tbltasks.duedate as task_duedate,
                ' . get_sql_select_task_asignees_full_names() . ' as task_assignees,
                ' . $tags . ' as task_tags,
                tbltasks.priority as task_priority,
            ', false)
            ->from('tbltasks')
            ->join('tbl_shift_work', 'tbl_shift_work.id = tbltasks.shift_work', 'left');
        // ->join('tblstaff', 'tblstaff.staffid = tblactivity_log_v2.staff_id', 'left');

        $this->datatables->where('tbltasks.rel_type', 'order_production_details');
        $this->datatables->where('tbltasks.rel_id', $id);

        if (!$is_admin) {
            $isAssigned = "(
                SELECT COUNT(*)
                FROM tbltask_assigned
                WHERE tbltask_assigned.staffid = $staff_id AND tbltasks.id = tbltask_assigned.taskid
            )";

            $this->datatables->where("($isAssigned > 0)");
        }

        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;

            $status = $value[3];
            $data->aaData[$key][2] = $value[2];
            $data->aaData[$key][3] = get_task_status_by_id($status)['name'];
            $data->aaData[$key][4] = _d($value[4]);
            $data->aaData[$key][5] = _d($value[5]);
            $data->aaData[$key][6] = $value[6];
            $data->aaData[$key][7] = render_tags($value[7]);
            $data->aaData[$key][8] =  '<span style="color:' . task_priority_color($value[8]) . ';" class="inline-block">' . task_priority($value[8]);
        }
        echo json_encode($data);
    }

    public function getQuantityLocationConvertStock()
    {
        $data = [];
        if ($this->input->post()) {
            $curLocationId = $this->input->post('curLocationId');
            $curWarehouseId = $this->input->post('curWarehouseId');
            $curSugExportingItemId = $this->input->post('curSugExportingItemId');
            $suggest_exporting_item = $this->manufactures_model->rowSuggestExportingItem($curSugExportingItemId);
            if (!empty($suggest_exporting_item)) {
                $type_item = $suggest_exporting_item['type_item'];
                $item_id = $suggest_exporting_item['item_id'];
                $quantityExchange = $suggest_exporting_item['number_exchange'];
                if ($type_item == "materials") {
                    $type_item = "nvl";
                } else if ($type_item == "tools_supplies") {
                    $type_item = "tools";
                } else if ($type_item == "semi_products_outside" || $type_item == "semi_products") {
                    $type_item = "product";
                }
                $warehouse = $this->manufactures_model->rowWarehouseItems($item_id, $curWarehouseId, $curLocationId, $type_item);
                if (!empty($warehouse)) {
                    $warehouse['product_quantity'] = $warehouse['product_quantity'] * $quantityExchange;
                }
                $data['warehouse'] = $warehouse;
            }
        }
        echo json_encode($data);
    }

    public function importQuantityFi($id)
    {
        $production_detail = $this->manufactures_model->rowProductionsOrdersDetais($id);
        $podItem = $this->manufactures_model->rowProductionsORdersItemsById($production_detail['productions_orders_item_id']);
        if ($this->input->post()) {
            if ($production_detail['status'] == "complete_production") {
                $data['result'] = 0;
                $data['message'] = lang('tnh_this_detailed_production_order_has_been_completed_not_import_quantity');
                echo json_encode($data);
                die;
            }

            $quantity = number_unformat($this->input->post('quantity_import_finished'));
            if (!empty($quantity)) {
                if ($this->manufactures_model->updateSetPOD($id, $quantity, $plus = 0)) {
                    $production_detail = $this->manufactures_model->rowProductionsOrdersDetais($id);
                    $data['quantity_fi'] = $production_detail['quantity_finished'];
                    $data['result'] = 1;
                    $data['message'] = lang('success');

                    insertActivityLog([
                        'type_parent_obj' => 'productions_orders_details',
                        'table_obj' => 'tbl_productions_orders_details',
                        'id_obj' => $production_detail['id'],
                        'name_obj' => $production_detail['reference_no'],
                        'content' => lang('tnh_his_htt_productions_orders_details') . ' [' . $production_detail['reference_no'] . ']',
                        'actions' => 'htt'
                    ]);
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            }
            echo json_encode($data);
            die;
        } else {
            if ($production_detail['status'] == "complete_production") {
                set_alert('danger', lang('tnh_this_detailed_production_order_has_been_completed_not_import_quantity'));
                die("<script type='text/javascript'>setTimeout(function(){ window.top.location.href = '" . (isset($_SERVER["HTTP_REFERER"]) ? $_SERVER["HTTP_REFERER"] : site_url('admin')) . "'; }, 10);</script>");
            }
            $data['id'] = $id;
            $data['production_detail'] = $production_detail;
            $data['podItem'] = $podItem;
            $this->load->view('admin/manufactures/import_quantity_fi', $data);
        }
    }

    public function calendar_pod()
    {
        $this->perViewCalendarPod = has_permission('manufactures_calendar_pod', '', 'view');
        $this->perViewOwnCalendarPod = has_permission('manufactures_calendar_pod', '', 'view_own');
