    public function print_productions_orders_detail($id)
    {
        ob_end_clean();
        $data = [];
        $production_detail = $this->manufactures_model->rowProductionsOrdersByDetail($id);
        $podEmployees = $this->manufactures_model->getPODEmployeesByPODId($id);

        $productions_orders_items_id = $production_detail['productions_orders_item_id'];

        //NVL theo BOM
        $quantityExport = "(
            SELECT SUM(tbl_suggest_exporting_items.quantity_exchange) as quantity_exchange
            FROM tbl_suggest_exporting
            INNER JOIN tbl_suggest_exporting_items ON tbl_suggest_exporting_items.suggest_exporting_id = tbl_suggest_exporting.id
            WHERE tbl_suggest_exporting.reference_stock IS NOT NULL AND tbl_suggest_exporting.status_stock = 'approved' AND tbl_suggest_exporting.warehouseman_id > 0 AND tbl_suggest_exporting_items.type_item = tbl_productions_orders_items_sub.type AND tbl_suggest_exporting_items.item_id = tbl_productions_orders_items_sub.item_id AND tbl_suggest_exporting.productions_orders_details_id = $id AND tbl_suggest_exporting.type_pattern_id IN (1, 2)
        )";

        $this->db
            ->select("
            tbl_productions_orders_items_sub.item_code as item_code,
            tbl_productions_orders_items_sub.type as item_type,
            tbl_productions_orders_items_sub.item_name as item_name,
            tblunits.unit as unit_name,
            SUM(tbl_productions_orders_items_sub.quantity) as quantity,
            $quantityExport as quantity_export,
            SUM(tbl_productions_orders_items_sub.quantity_primary) - COALESCE($quantityExport, 0) as quantity_missing,
        ", false)
            ->from('tbl_productions_orders_items_sub')
            ->join('tbl_stages', 'tbl_stages.id = tbl_productions_orders_items_sub.stage_item_id', 'left')
            ->join('tblunits', 'tblunits.unitid = tbl_productions_orders_items_sub.unit_id', 'left');

        $this->db->group_by('tbl_productions_orders_items_sub.item_id, tbl_productions_orders_items_sub.unit_id');

        $this->db->where("(tbl_productions_orders_items_sub.type = 'materials' OR  tbl_productions_orders_items_sub.type = 'semi_products_outside')");
        $this->db->where('tbl_productions_orders_items_sub.productions_orders_items_id', $productions_orders_items_id);
        $materialBom = $this->db->get()->result_array();
        //end

        //NVL bổ sung
        $this->db
            ->select("
                tbl_suggest_exporting_items.item_code as item_code,
                tbl_suggest_exporting_items.item_name as item_name,
                tblunits.unit as unit_name,
                SUM(tbl_suggest_exporting_items.quantity_export) as quantity,
            ", false)
            ->from('tbl_suggest_exporting')
            ->join('tbl_suggest_exporting_items', 'tbl_suggest_exporting_items.suggest_exporting_id = tbl_suggest_exporting.id AND tbl_suggest_exporting_items.type_item != "tools_supplies"', 'inner')
            ->join('tblunits', 'tblunits.unitid = tbl_suggest_exporting_items.unit_id', 'left');

        $this->db->group_by('tbl_suggest_exporting_items.item_id, tbl_suggest_exporting_items.unit_id');
        $this->db->where('tbl_suggest_exporting.productions_orders_details_id', $id);
        $this->db->where('tbl_suggest_exporting.type_pattern_id !=', 1);
