    public function searchOrdersItemsOfPlanItems($id = false)
    {
        $data = [];
        $term = $this->input->get('term', TRUE);
        $limit = get_option('select2_limit');
        $params = $this->input->get('params');
        $object_id = $params['object_id'];
        $type_object = $params['type_object'];
        $planningCycle = $params['planningCycle'];
        $planningCycle = explode('-', trim($planningCycle));
        $dateStart = to_sql_date(trim($planningCycle[0]));
        $dateEnd = to_sql_date(trim($planningCycle[1]));

        if ($object_id) {
            $object_id = !empty($object_id) ? str_replace(",", "','", $object_id) : 0;
            $strTerm = '';

            if ($type_object == "orders") {
                $sumTotalQuantityDate = "COALESCE((
                    SELECT SUM(tbl_order_item_shippings.quantity_shipping)
                    FROM tbl_order_item_shippings
                    WHERE tbl_order_item_shippings.order_item_id = tbl_order_items.id AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$dateStart' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$dateEnd' AND tbl_order_item_shippings.quantity_shipping > tbl_order_item_shippings.quantity_plan_item
                ), 0)";

                // AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') >= '$dateStart' AND DATE_FORMAT(tbl_order_item_shippings.date_shipping, '%Y-%m-%d') <= '$dateEnd'

                if (!empty($term)) {
                    $strTerm = " AND (tbl_order_items.item_name LIKE '%$term%' OR tbl_order_items.item_code LIKE '%$term%' OR tbl_orders.reference_no LIKE '%$term%')";
                }

                $query = "(
                    SELECT 
                        tbl_order_items.id as id,
                        CONCAT(tbl_order_items.item_name, '(', tbl_orders.reference_no,')') as text
                    FROM tbl_orders
                    INNER JOIN tbl_order_items ON tbl_order_items.order_id = tbl_orders.id
                    WHERE tbl_orders.id IN ('$object_id') AND ($sumTotalQuantityDate > 0) AND tbl_order_items.type_item = 'products' $strTerm
                    LIMIT 20
                )";
            } else if ($type_object == "business_plan") {
                // AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$dateStart' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$dateEnd'
                $sumTotalQuantityDate = "COALESCE((
                    SELECT SUM(tbl_business_plan_items_date.quantity)
                    FROM tbl_business_plan_items_date
                    WHERE tbl_business_plan_items_date.business_plan_items_id = tbl_business_plan_items.id AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') >= '$dateStart' AND DATE_FORMAT(tbl_business_plan_items_date.date, '%Y-%m-%d') <= '$dateEnd' AND tbl_business_plan_items_date.quantity > tbl_business_plan_items_date.quantity_plan_item
                ), 0)";

                if (!empty($term)) {
                    $strTerm = " AND (tbl_business_plan_items.items_name LIKE '%$term%' OR tbl_business_plan_items.items_code LIKE '%$term%' OR tbl_business_plan.reference_no LIKE '%$term%')";
                }

                $query = "(
                    SELECT 
                        tbl_business_plan_items.id as id,
                        CONCAT(tbl_business_plan_items.items_name, '(', tbl_business_plan.reference_no,')') as text
                    FROM tbl_business_plan
                    INNER JOIN tbl_business_plan_items ON tbl_business_plan_items.business_plan_id = tbl_business_plan.id
                    WHERE tbl_business_plan.id IN ('$object_id') AND ($sumTotalQuantityDate > 0) AND tbl_business_plan_items.type_items = 'products' $strTerm
                    LIMIT 20
                )";
            }

            $result = $this->db->query($query)->result_array();
            $data['results'] = $result;
        } else {
            $data['results'] = false;
        }
        echo json_encode($data);
    }

