    public function getTaskById()
    {
        $data = [];
        if ($this->input->get()) {
            $task_work_id = $this->input->get('task_work_id');
            $pod_id = $this->input->get('pod_id');

            $this->db->select('tbltasks.quantity_shift_work');
            $this->db->from('tbltasks');
            $this->db->where('tbltasks.rel_type', 'order_production_details');
            $this->db->where('tbltasks.rel_id', $pod_id);
            $this->db->where('tbltasks.id', $task_work_id);
            $task = $this->db->get()->row_array();

            $quantityShiftWork = $task['quantity_shift_work'];
            $data['quantityShiftWork'] = $quantityShiftWork;

            $this->db->select('SUM(tbl_purchase_products.total_quantity) as total_quantity', false);
            $this->db->from('tbl_purchase_products');
            $this->db->where('tbl_purchase_products.productions_orders_details_id', $pod_id);
            $this->db->where('tbl_purchase_products.task_id', $task_work_id);
            $purchaseProduct = $this->db->get()->row_array();
            $quantityWarehousing = $purchaseProduct['total_quantity'];
            $data['quantityWarehousing'] = $purchaseProduct['total_quantity'];

            $quantityRest = $quantityShiftWork - $quantityWarehousing;
            if ($quantityRest < 0) $quantityRest = 0;
            $data['quantityRest'] = $quantityRest;
        }
        echo json_encode($data);
    }

    public function getCostMaterial($pod_id)
    {

        $tableThuHoi = "(
            SELECT
                tbl_purchase_internal_items.type_item as type_item,
                tbl_purchase_internal_items.item_id as item_id,
                SUM(tbl_purchase_internal_items.quantity) as quantity, 
                SUM(tbl_purchase_internal_items.amount) as amount
            FROM tbl_purchase_internal
            INNER JOIN tbl_purchase_internal_items ON tbl_purchase_internal.id = tbl_purchase_internal_items.purchase_internal_id
            WHERE tbl_purchase_internal.pod_id = $pod_id
            GROUP BY tbl_purchase_internal_items.type_item, tbl_purchase_internal_items.item_id
        ) as tbthuhoi";

        $this->datatables
            ->select("
            0 as number_records,
            tbl_suggest_exporting_items.item_code as item_code,
            tbl_suggest_exporting_items.item_name as item_name,
            tblunits.unit as name_unit,
            SUM(tbl_suggest_exporting_items.quantity_exchange) as quantity_export,
            tbthuhoi.quantity as quantity_recovered,
            SUM(tbl_suggest_exporting_items.amount) as cpnvl,
            COALESCE(tbthuhoi.amount, 0) as cpth,
            (SUM(tbl_suggest_exporting_items.amount) - COALESCE(tbthuhoi.amount, 0)) as total_amount,
        ", false)
            ->from('tbl_suggest_exporting')
            ->join('tbl_suggest_exporting_items', 'tbl_suggest_exporting_items.suggest_exporting_id = tbl_suggest_exporting.id')
            ->join($tableThuHoi, 'tbthuhoi.type_item = tbl_suggest_exporting_items.type_item AND tbthuhoi.item_id = tbl_suggest_exporting_items.item_id', 'left')
            ->join('tblunits', 'tblunits.unitid = tbl_suggest_exporting_items.unit_parent_id', 'left');

        // $this->datatables->where('tbl_suggest_exporting.warehouseman_id >', 1);
        $this->datatables->where('tbl_suggest_exporting.productions_orders_details_id', $pod_id);
        $this->datatables->where('tbl_suggest_exporting.status_stock IS NOT NULL');
        $this->datatables->group_by('tbl_suggest_exporting_items.type_item, tbl_suggest_exporting_items.item_id');

        $iDisplayStart = $this->input->post('iDisplayStart');
        $data = json_decode($this->datatables->generate());
        foreach ($data->aaData as $key => $value) {
            $data->aaData[$key][0] = ++$iDisplayStart;
        }
        echo json_encode($data);
    }

    //--- revoke
    public function getPurchaseInternalExport()
    {
        $data = [];
        $term = $this->input->get('term', TRUE);
        $limit = get_option('select2_limit');

        $isQuantityExport = "(
            SELECT COUNT(*)
            FROM tbl_purchase_internal_items
            WHERE tbl_purchase_internal_items.quantity_export < tbl_purchase_internal_items.quantity AND tbl_purchase_internal_items.purchase_internal_id = tbl_purchase_internal.id
        )";

        $this->db->select('
            tbl_purchase_internal.id as id,
            tbl_purchase_internal.reference_no as text,
        ', false);
        $this->db->from('tbl_purchase_internal');
        $this->db->where('tbl_purchase_internal.warehouseman_id >', 0);
        $this->db->where("$isQuantityExport > 0");
        if ($term) {
            $this->db->like('tbl_purchase_internal.reference_no', $term);
        }
        $this->db->limit($limit);
        $results = $this->db->get()->result_array();

        $data['results'] = $results;

        echo json_encode($data);
    }

    public function getPurchaseInternalItemsExport()
    {
        $data = [];
        if ($this->input->get()) {
            $purchase_internal_revoke = $this->input->get('purchase_internal_revoke');

            $this->db->select('
                tbl_purchase_internal_items.id as id,
                tbl_purchase_internal_items.type_item as type_item,
                tbl_purchase_internal_items.item_id as item_id,
                tbl_purchase_internal_items.item_code as item_code,
                tbl_purchase_internal_items.item_name as item_name,
                tbl_purchase_internal_items.quantity as quantity,
                tbl_purchase_internal_items.quantity_export as quantity_export,
                tbl_purchase_internal_items.location_id as location_id,
                tbl_purchase_internal.warehouse_id as warehouse_id,
            ', false);
            $this->db->from('tbl_purchase_internal');
            $this->db->join('tbl_purchase_internal_items', 'tbl_purchase_internal_items.purchase_internal_id = tbl_purchase_internal.id');
            $this->db->where('tbl_purchase_internal.warehouseman_id >', 0);
            $this->db->where("tbl_purchase_internal_items.quantity > tbl_purchase_internal_items.quantity_export");
            $this->db->where('tbl_purchase_internal.id', $purchase_internal_revoke);
            $results = $this->db->get()->result_array();
            $html = '';
            if (!empty($results)) {
                $warehouse = $this->site_model->rowWarehouseById($results[0]['warehouse_id']);
                foreach ($results as $key => $value) {
                    $location_id = $value['location_id'];
                    $location = $this->site_model->rowLocationWarehouseById($location_id);
                    $quantity = $value['quantity'];
                    $quantityExport = $value['quantity_export'];

                    $tdStt = '<td class="text-center tnh-number">' . (++$key) . '</td>';
                    $tdItemCode = '<td class="">
                        <input type="hidden" name="purchase_internal_item_id[]" id="input" class="form-control" value="' . $value['id'] . '">
                        ' . $value['item_code'] . '
                    </td>';
                    $tdItemName = '<td class="">' . $value['item_name'] . '</td>';
                    $tdLocationWarehouse = '<td class="">' . $warehouse['name'] . '->' . $location['name'] . '</td>';
                    $tdQuantityExport = '<td class="text-center">
                        <div>' . formatNumber($quantityExport) . '</div>
                    </td>';

                    // <input type="text" name="quantity_revoke[]" id="quantity_revoke" class="form-control quantity_revoke" value="'.formatNumber($quantity).'">

                    $tdQuantity = '<td class="text-center">
                        <div>' . formatNumber($quantity) . '</div>
                    </td>';

                    $tdNote = '<td>
                        <textarea name="note_item[]" id="input" class="form-control" rows="3"></textarea>
                    </td>';

                    $html .= '<tr>
                        ' . $tdStt . '
                        ' . $tdItemCode . '
                        ' . $tdItemName . '
                        ' . $tdLocationWarehouse . '
                        ' . $tdQuantity . '
                    </tr>';
                }
            }
            $data['html'] = $html;
        }
        echo json_encode($data);
    }

    public function exportRevoke($id)
    {
        if ($this->input->post('save')) {
            $data = [];

            $this->form_validation->set_rules('date_revoke', lang("date"), 'required');
            $this->form_validation->set_rules('export_name_revoke', lang("tnh_export_name"), 'required');
            $this->form_validation->set_rules('purchase_internal_revoke', lang("purchase_internal"), 'required');
            if ($this->form_validation->run() == true) {
                $purchase_internal_revoke = $this->input->post('purchase_internal_revoke');
                $purchaseInternal = $this->manufactures_model->getPurchaseInternalByExport($purchase_internal_revoke);
                if (empty($purchaseInternal)) {
                    $data['result'] = 0;
                    $data['message'] = 'Không có dữ liệu hoặc phiếu này đã xuất thu hồi';
                    echo json_encode($data);
                    die;
                }

                $date = to_sql_date($this->input->post('date_revoke'), true);
                $reference_no = getReference('stock');
                $export_name = $this->input->post('export_name_revoke');
                $note = $this->input->post('note_revoke');
                $warehouse_id = $purchaseInternal['warehouse_id'];

                $total_quantity = 0;
                $count_items = 0;
                $total_quantity_exchange = 0;
                $type = 5;
                $errors = false;

                $purchase_internal_item_id = $this->input->post('purchase_internal_item_id');
                if (!empty($purchase_internal_item_id)) {
                    foreach ($purchase_internal_item_id as $key => $value) {
                        $purchase_internal_item = $this->manufactures_model->getPurchaseInternalItemsById($value);
                        if (empty($purchase_internal_item)) continue;
                        // $note_item = $this->input->post('note_item')[$key];

                        $type_item = $purchase_internal_item['type_item'];
                        $item_id = $purchase_internal_item['item_id'];
                        $item_code = $purchase_internal_item['item_code'];
                        $item_name = $purchase_internal_item['item_name'];
                        $unit_id = $purchase_internal_item['unit_id'];
                        $quantity = $purchase_internal_item['quantity'];
                        $location_id = $purchase_internal_item['location_id'];

                        $exporting_items[] = [
                            'type_item' => $type_item,
                            'item_id' => $item_id,
                            'item_code' => $item_code,
                            'item_name' => $item_name,
                            'unit_id' => $unit_id,
                            'quantity_export' => $quantity,
                            'unit_parent_id' => $unit_id,
                            'number_exchange' => 1,
                            'quantity_exchange' => $quantity,
                            'location_id' => $location_id,
                            'id_purchase_internal_item' => $value,
                        ];

                        $total_quantity += $quantity;
                        $total_quantity_exchange += $quantity;
                    }
                }

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data);
                    die;
                }

                if (empty($exporting_items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_no_items');
                    echo json_encode($data);
                    die;
                }

                $count_items = count($exporting_items);
                $fields = [
                    'productions_orders_details_id' => $id,
                    'reference_no' => null,
                    'reference_stock' => $reference_no,
                    'date' => $date,
                    'export_name' => $export_name,
                    'note' => $note,
                    'status' => 'un_approved',
                    'total_quantity' => $total_quantity,
                    'count_items' => $count_items,
                    'total_quantity_exchange' => $total_quantity_exchange,
                    'created_by' => get_staff_user_id(),
                    'date_created' => date('Y-m-d H:i:s'),
                    'convert_stock_by' => get_staff_user_id(),
                    'date_convert_stock' => date('Y-m-d H:i:s'),
                    'status_stock' => 'approved',
                    'date_stock' => date('Y-m-d H:i:s'),
                    'user_stock' => get_staff_user_id(),
                    'type' => $type,
                    'date_convert_stock' => $date,
                    'warehouse_id' => $warehouse_id,
                    'purchase_internal_id' => $purchase_internal_revoke,
                ];

                $suggest_exporting_id = $this->manufactures_model->insertSuggestExporting($fields);
                if ($suggest_exporting_id) {
                    updateReference('stock');

                    foreach ($exporting_items as $key => $value) {
                        $value['suggest_exporting_id'] = $suggest_exporting_id;
                        if ($this->manufactures_model->insertSuggestExportingItems($value)) {
                            $this->manufactures_model->updateQuantityExportPurchaseInternal($value['id_purchase_internal_item'], $value['quantity_exchange'], $plus = 1);
                        }
                    }

                    //duyet kho
                    // $_data = array(
                    //     'warehouseman_id' => get_staff_user_id(),
                    //     'date_warehouseman' => date('Y-m-d H:i:s')
                    // );
                    //end

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }

            echo json_encode($data);
            die;
        }

        $data['id'] = $id;
        $data['warehouses'] = $this->stock_model->getWarehouses();
        $this->load->view('admin/manufactures/export_revoke.php', $data);
    }

    public function add_production_planning($id)
    {
        $data = [];
        $business_plan = $this->business_plan_model->rowBusinessPlanById($id);
        if (empty($business_plan)) {
            refererModel(lang('no_data_exists'));
            die;
        }

        if ($business_plan['status'] != 'approved') {
            refererModel(lang('tnh_please_approved'));
            die;
        }

        $this->db->from('tbl_productions_plan');
        $this->db->where("(FIND_IN_SET($id, tbl_productions_plan.options2_id) > 0)");
        $pl = $this->db->get()->num_rows();
        if (!empty($pl)) {
            refererModel(lang('Đạ tạo hoạch định 1 phần không thể tạo nữa'));
            die;
        }

        $isPlanItemsDate = $this->business_plan_model->isPlanItemsDate($id);
        if (empty($isPlanItemsDate)) {
            refererModel(lang('Không có số lượng để sản xuất'));
            die;
        }
        $items = $this->business_plan_model->getItemsProductionsPlan($id);

        if ($this->input->post('save')) {
            $data = [];
            $this->form_validation->set_rules('deadline[]', lang("deadline"), 'required');
            $this->form_validation->set_rules('departments[]', lang("departments"), 'required');
            $this->form_validation->set_rules('employess[]', lang("staff_admin"), 'required');
            $this->form_validation->set_rules('location', lang("tnh_location"), 'required');

            if ($this->form_validation->run() == true) {
                //add productions plan
                $date_general = date('Y-m-d H:i:s');
                $staff_general = get_staff_user_id();

                $reference_no_plan = getReference('productions_plan');
                $datePlanning = $this->business_plan_model->getMaxMinBusinessPlan($id);
                $dateBegin = date_format(date_create($datePlanning['date_start']), 'd/m/Y');
                $dateEnd = date_format(date_create($datePlanning['date_end']), 'd/m/Y');
                $planning_cycle = $dateBegin . '-' . $dateEnd;
                $date_start = $datePlanning['date_start'];
                $date_end = $datePlanning['date_end'];

                $options1 = 0;
                $options2 = 1;
                $safe_inventory = 0;
                $orders = null;
                $business_plans = $id;

                $orders_items = null;
                $business_plans_items = null;

                $dt_quantity_reserve = null;
                $dt_quantity = null;
                $options2_reference_no = $business_plan['reference_no'];
                $business_plan_id = $id;
                $statusPlan = 'approved';

                $productions_plan = [
                    'reference_no' => $reference_no_plan,
                    'date' => $date_general,
                    'date_start' => $date_start,
                    'date_end' => $date_end,
                    'safe_inventory' => $safe_inventory,
                    'options1' => $options1,
                    'options1_reference_no' => null,
                    'options1_id' => null,
                    'options2' => $options2,
                    'options2_reference_no' => $options2_reference_no,
                    'options2_id' => $business_plan_id,
                    'note' => '',
                    'status' => $statusPlan,
                    'date_created' => $date_general,
                    'created_by' => $staff_general,
                    'date_status' => $date_general,
                    'user_status' => $staff_general,
                ];

                if (empty($items)) {
                    $data['result'] = 0;
                    $data['message'] = lang('tnh_not_items');
                    echo json_encode($data);
                    die;
                }

                // print_arrays($productions_plan);
                $productions_plan_id = $this->manufactures_model->insertProductionsPlan($productions_plan);
                if ($productions_plan_id) {
                    updateReference('productions_plan');

                    foreach ($items as $key => $value) {
                        $quantity_reserve = 0;
                        $quantity_total_details = 0;

                        $arrDate = $value['arrDate'];
                        $productions_plan_details = [];
                        foreach ($arrDate as $k => $v) {
                            $quantityPlanDetail = $v['quantity'] - $v['quantity_plan_item'];
                            $productions_plan_details[] = [
                                'date' => $v['date'],
                                'quantity' => $quantityPlanDetail
                            ];
                            $quantity_total_details += $quantityPlanDetail;
                        }

                        $productions_plan_items = [
                            'productions_plan_id' => $productions_plan_id,
                            'type_object' => 'business_plan',
                            'object_id' => $value['business_plan_id'],
                            'item_object_id' => $value['id'],
                            'product_id' => $value['items_id'],
                            'quantity_minimum' => $value['quantity_minimum'],
                            'quantity_warehouses' => $value['quantity_warehouses'],
                            'status' => 'not',
                            'quantity_reserve' => $quantity_reserve,
                            'quantity_total_details' => $quantity_total_details,
                        ];

                        $productions_plan_item_id = $this->manufactures_model->insertProductionsPlanItems($productions_plan_items);
                        if ($productions_plan_item_id) {
                            foreach ($productions_plan_details as $kD => $vD) {
                                $vD['productions_plan_item_id'] = $productions_plan_item_id;
                                $this->manufactures_model->insertProductionsPlanDetails($vD);
                                $this->manufactures_model->updateQuantityPlanShippings($vD['quantity'], $plus = 0, $value['id'], 'business_plan', $vD['date']);
                            }
                        }
                        $this->manufactures_model->updateQuantityPlan($quantity_total_details, $plus = 0, $value['id'], 'business_plan');
                    }
                    $this->business_plan_model->updateBusinessPlan($id, ['productions_plan_id' => 1]);
                    insertActivityLog([
                        'type_parent_obj' => 'productions_plan',
                        'table_obj' => 'tbl_productions_plan',
                        'id_obj' => $productions_plan_id,
                        'name_obj' => $reference_no_plan,
                        'content' => lang('tnh_his_add_productions_plan') . ' [' . $reference_no_plan . ']',
                        'actions' => 'add'
                    ]);

                    //--------------------------add productions capacity
                    $reference_no_capacity = getReference('productions_capacity');
                    $productions_plan_reference = $reference_no_plan;

                    $items = "(
                        SELECT
                            tbl_productions_plan_items.product_id as product_id,
                            SUM(tbl_productions_plan_items.quantity_total_details + tbl_productions_plan_items.quantity_reserve) as total_quantity,
                            SUM(tbl_productions_plan_items.quantity_reserve) as quantity_reserve
                        FROM tbl_productions_plan
                        INNER JOIN tbl_productions_plan_items ON tbl_productions_plan.id = tbl_productions_plan_items.productions_plan_id
                        WHERE tbl_productions_plan_items.productions_plan_id = $productions_plan_id AND tbl_productions_plan.status = 'approved'
                        GROUP BY tbl_productions_plan_items.product_id
                    ) as items";

                    $warehouses = "(
                        SELECT
                            tblwarehouse_items.id_items,
                            SUM(tblwarehouse_items.product_quantity) as quantity_warehouses
                        FROM tblwarehouse_items
                        WHERE tblwarehouse_items.type_items = 'product'
                        GROUP BY tblwarehouse_items.id_items
                    ) warehouses";

                    $this->db->select("
                        tbl_products.id as product_id,
                        tbl_products.code as code,
                        tbl_products.name as name,
                        tbl_products.quantity_minimum as quantity_minimum,
                        COALESCE(warehouses.quantity_warehouses, 0) as quantity_warehouses,
                        COALESCE(items.total_quantity, 0) as quantity_use,
                        COALESCE(items.total_quantity, 0) as quantity_productions,
                        tbl_products.number_labor as number_labor,
                        tbl_products.versions as versions,
                        tbl_products.versions_stage as versions_stage,
                        '' as sub,
                        '' as st,
                        items.quantity_reserve as quantity_reserve
                    ", false)
                        ->from("tbl_products")
                        ->join($warehouses, 'warehouses.id_items = tbl_products.id', 'left')
                        ->join($items, 'items.product_id = tbl_products.id');
                    $rs = $this->db->get()->result_array();

                    if (empty($rs)) {
                        $data['result'] = 0;
                        $data['message'] = lang('not_data_exists') . ' tạo hoạch định sản xuất';
                        echo json_encode($data);
                        die;
                    }

                    $arr_purchases = [];
                    $arr_id_sub = [];
                    $arr_type_sub = [];

                    foreach ($rs as $key => $value) {
                        $product_id = $value['product_id'];
                        $vs = $value['versions'];
                        $quantity = $value['quantity_productions'];
                        if ($quantity < 0) {
                            $quantity = 0;
                            $rs[$key]['quantity_productions'] = 0;
                        }
                        if (!empty($vs)) {
                            $version = $this->products_model->getBomByProductIdAndVersions($product_id, $vs);
                            if (!empty($version)) {
                                $elements = $this->products_model->getVersionsElementByVersionId($version['id']);
                                $rs[$key]['sub'] = [];
                                $iiPartent = 0;
                                foreach ($elements as $k => $val) {
                                    $quantity_element = $quantity * $val['quantity'];
                                    $rs[$key]['sub'][$iiPartent] = [
                                        'type_sub' => 'element',
                                        'id_sub' => 0,
                                        'code_sub' => $val['element_name'],
                                        'name_sub' => $val['element_name'],
                                        'quantity' => $val['quantity'],
                                        'quantity_minimum_sub' => 0,
                                        'quantity_warehouse_sub' => 0,
                                        'quantity_plan_sub' => $quantity_element,
                                        'quantity_purchase_sub' => $quantity_element,
                                        'unit_id' => 0,
                                        'quantity_exchange' => 1,
                                        'quantity_plan_sub_primary' => $quantity_element,
                                        'leadtime' => 0,
                                        'stage_item_id' => 0,
                                    ];
                                    $iiPartent++;
                                    $items = $this->products_model->getElementItemsByElementId($val['id']);
                                    foreach ($items as $n => $v) {
                                        $type_warehouse = '';
                                        if ($v['type'] == "semi_products" || $v['type'] == "semi_products_outside") {
                                            $info = $this->products_model->rowProduct($v['item_id']);
                                            $type_warehouse = 'product';
                                            $unit_id = $v['unit_id'];
                                            $unit_purchase_id = $info['unit_id'];
                                            $quantity_exchange = 1;
                                        } else {
                                            $info = $this->items_model->rowMaterial($v['item_id']);
                                            $type_warehouse = 'nvl';
                                            $unit_id = $v['unit_id'];
                                            $unit_purchase_id = $info['unit_id'];
                                            $row_exchange = $this->products_model->rowExchangeItems($v['item_id'], $unit_id);
                                            $quantity_exchange = 1;
                                            if (!empty($row_exchange)) {
                                                $quantity_exchange = $row_exchange['number_exchange'];
                                            }
                                        }

                                        if (empty($info)) {
                                            $data['result'] = 0;
                                            $data['message'] = '<div>[' . $value['code'] . '] không tìm thấy NVL/BTP [' . $info['code'] . ']</div>';
                                            echo json_encode($data);
                                            die;
                                        }

                                        $quantity_warehouse = 0;

                                        $quantity_plan = $quantity_element * $v['quantity'];
                                        $quantity_plan_sub_primary = $quantity_plan / $quantity_exchange;
                                        $quantity_purchase = 0;
                                        $unit = $this->unit_model->rowUnit($info['unit_id']);

                                        $rs[$key]['sub'][$iiPartent] = [
                                            'parent_id' => 0,
                                            'type_sub' => $v['type'],
                                            'id_sub' => $v['item_id'],
                                            'code_sub' => $info['code'],
                                            'name_sub' => $info['name'],
                                            'quantity' => $v['quantity'],
                                            'quantity_minimum_sub' => $info['quantity_minimum'],
                                            'quantity_warehouse_sub' => $quantity_warehouse,
                                            'quantity_plan_sub' => $quantity_plan,
                                            'quantity_purchase_sub' => $quantity_purchase,
                                            'unit_id' => $unit_id,
                                            'quantity_exchange' => $quantity_exchange,
                                            'quantity_plan_sub_primary' => $quantity_plan_sub_primary,
                                            'leadtime' => $v['leadtime'],
                                            'stage_item_id' => $v['stage_id'],
                                        ];

                                        //handling material replace
                                        $element_item_id = $v['id'];
                                        $elementReplace = $this->products_model->getElementItemsReplaceByElementItemId($element_item_id);

                                        if (!empty($elementReplace)) {
                                            foreach ($elementReplace as $kk => $vv) {
                                                $unit_id_replace = $vv['unit_id_replace'];
                                                if ($vv['type_replace'] == "semi_products" || $vv['type_replace'] == "semi_products_outside") {
                                                    $infoReplace = $this->products_model->rowProduct($vv['item_id_replace']);
                                                    $unit_purchase_id_replace = $infoReplace['unit_id'];
                                                    $quantity_exchange_replace = 1;
                                                } else {
                                                    $infoReplace = $this->items_model->rowMaterial($vv['item_id_replace']);
                                                    $unit_purchase_id_replace = $infoReplace['unit_id'];
                                                    $quantity_exchange_replace = 1;
                                                    $row_exchange_replace = $this->products_model->rowExchangeItems($vv['item_id_replace'], $unit_id_replace);
                                                    if (!empty($row_exchange_replace)) {
                                                        $quantity_exchange_replace = $row_exchange_replace['number_exchange'];
                                                    }
                                                }

                                                if (empty($infoReplace)) {
                                                    $data['result'] = 0;
                                                    $data['message'] = '<div>[' . $value['code'] . '] không tìm thấy NVL/BTP [' . $infoReplace['code'] . ']</div>';
                                                    echo json_encode($data);
                                                    die;
                                                }

                                                $rs[$key]['sub'][$iiPartent]['replace'][] = [
                                                    'parent_id' => 0,
                                                    'type_sub' => $vv['type_replace'],
                                                    'id_sub' => $vv['item_id_replace'],
                                                    'code_sub' => $infoReplace['code'],
                                                    'name_sub' => $infoReplace['name'],
                                                    'quantity' => $vv['quantity_replace'],
                                                    'quantity_minimum_sub' => $infoReplace['quantity_minimum'],
                                                    'quantity_warehouse_sub' => $quantity_warehouse,
                                                    'quantity_plan_sub' => 0,
                                                    'quantity_purchase_sub' => 0,
                                                    'unit_id' => $unit_id_replace,
                                                    'quantity_exchange' => $quantity_exchange_replace,
                                                    'type_replace' => 1,
                                                    'quantity_plan_sub_primary' => 0,
                                                    'leadtime' => $vv['leadtime_replace'],
                                                    'stage_item_id' => $vv['stage_id_replace'],
                                                ];
                                            }
                                        }
                                        $iiPartent++;
                                        //end handling material replace
                                    }
                                }
                            }
                        }
                        //stages
                        $st = $value['versions_stage'];
                        if (!empty($st)) {
                            $versions = $this->products_model->getProductStagesByProductIdAndVersions($product_id, $st);
                            if (!empty($versions)) {
                                $psv = $this->products_model->getProductStagesVersions($versions['id']);
                                if (!empty($psv)) {
                                    $rs[$key]['st'] = [];
                                    foreach ($psv as $k => $val) {
                                        $str_machines = '';
                                        $str_machines_code = '';
                                        if (!empty($val['machines'])) {
                                            $machines = $this->category_model->getMachinesByArrId(explode(',', $val['machines']));
                                            if (!empty($machines)) {
                                                foreach ($machines as $i => $v) {
                                                    $str_machines .= $v['name'] . '</br>';
                                                    $str_machines_code .= $v['code'] . '</br>';
                                                }
                                            }
                                        }
                                        $rs[$key]['st'][] = [
                                            'stage_id' => $val['stage_id'],
                                            'stage_name' => $val['stage_name'],
                                            'stage_code' => $val['stage_code'],
                                            'machine_id' => $val['machines'],
                                            'machine_name' => $str_machines,
                                            'machine_code' => $str_machines_code,
                                            'number_hours' => $val['number_hours'] * $quantity
                                        ];
                                    }
                                }
                            }
                        }
                    }

                    $productions_capacity = [
                        'reference_no' => $reference_no_capacity,
                        'date' => $date_general,
                        'productions_plan_id' => $productions_plan_id,
                        'productions_plan_reference_no' => $productions_plan_reference,
                        'note' => '',
                        'status' => 'approved',
                        'status_purchases' => 'un_purchases',
                        'purchases_id' => 0,
                        'date_created' => $date_general,
                        'created_by' => $staff_general,
                        'date_status' => $date_general,
                        'user_status' => $staff_general,
                    ];
                    $productions_capacity_id = $this->manufactures_model->insertProductionsCapacity($productions_capacity);
                    if ($productions_capacity_id) {
                        updateReference('productions_capacity');

                        foreach ($rs as $key => $value) {
                            $op = [
                                'productions_capacity_id' => $productions_capacity_id,
                                'type_items' => 'products',
                                'items_id' => $value['product_id'],
                                'items_code' => $value['code'],
                                'items_name' => $value['name'],
                                'quantity_minimum' => $value['quantity_minimum'],
                                'quantity_warehouse' => $value['quantity_warehouses'],
                                'quantity_plan' => $value['quantity_use'],
                                'quantity_purchase' => $value['quantity_productions'],
                                'number_labor' => $value['number_labor'],
                                'versions_bom' => $value['versions'],
                                'versions_stages' => $value['versions_stage'],
                                'quantity_reserve' => $value['quantity_reserve'],
                            ];
                            $productions_capacity_items_id = $this->manufactures_model->insertProductionsCapacityItems($op);
                            if ($productions_capacity_items_id) {
                                $sub = $value['sub'];
                                if (!empty($sub)) {
                                    $o = [];
                                    foreach ($sub as $k => $val) {
                                        // $o[] = [
                                        $o = [
                                            'productions_capacity_items_id' => $productions_capacity_items_id,
                                            'type_sub' => $val['type_sub'],
                                            'id_sub' => $val['id_sub'],
                                            'code_sub' => $val['code_sub'],
                                            'name_sub' => $val['name_sub'],
                                            'quantity' => $val['quantity'],
                                            'quantity_minimum_sub' => $val['quantity_minimum_sub'],
                                            'quantity_warehouse_sub' => $val['quantity_warehouse_sub'],
                                            'quantity_plan_sub' => $val['quantity_plan_sub'],
                                            'quantity_purchase_sub' => $val['quantity_purchase_sub'],
                                            'unit_id' => $val['unit_id'],
                                            'quantity_exchange' => $val['quantity_exchange'],
                                            'leadtime' => $val['leadtime'],
                                            'stage_item_id' => $val['stage_item_id'],
                                        ];
                                        $pciId = $this->manufactures_model->insertProductionsCapacityItemsSub($o);
                                        if ($pciId) {
                                            if (!empty($val['replace'])) {
                                                $or = null;
                                                $replace = $val['replace'];
                                                foreach ($replace as $kkk => $vvv) {
                                                    $or[] = [
                                                        'parent_id' => $pciId,
                                                        'productions_capacity_items_id' => $productions_capacity_items_id,
                                                        'type_sub' => $vvv['type_sub'],
                                                        'id_sub' => $vvv['id_sub'],
                                                        'code_sub' => $vvv['code_sub'],
                                                        'name_sub' => $vvv['name_sub'],
                                                        'quantity' => $vvv['quantity'],
                                                        'quantity_minimum_sub' => $vvv['quantity_minimum_sub'],
                                                        'quantity_warehouse_sub' => $vvv['quantity_warehouse_sub'],
                                                        'quantity_plan_sub' => $vvv['quantity_plan_sub'],
                                                        'quantity_purchase_sub' => $vvv['quantity_purchase_sub'],
                                                        'unit_id' => $vvv['unit_id'],
                                                        'quantity_exchange' => $vvv['quantity_exchange'],
                                                        'type_replace' => $vvv['type_replace'],
                                                        'leadtime' => $vvv['leadtime'],
                                                        'stage_item_id' => $vvv['stage_item_id'],
                                                    ];
                                                }
                                                if (!empty($or)) {
                                                    $this->manufactures_model->insertBatchProductionsCapacityItemsSub($or);
                                                }
                                            }
                                        }
                                    }
                                    // $this->manufactures_model->insertBatchProductionsCapacityItemsSub($o);
                                }
                                $st = $value['st'];
                                if (!empty($st)) {
                                    $s = [];
                                    foreach ($st as $k => $val) {
                                        $s[] = [
                                            'productions_capacity_items_id' => $productions_capacity_items_id,
                                            'stage_id' => $val['stage_id'],
                                            'stage_name' => $val['stage_name'],
                                            'stage_code' => $val['stage_code'],
                                            'machine_id' => $val['machine_id'],
                                            'machine_name' => $val['machine_name'],
                                            'machine_code' => $val['machine_code'],
                                            'number_hours' => $val['number_hours'],
                                        ];
                                    }
                                    $this->manufactures_model->insertBatchProductionsCapacityItemsStages($s);
                                }
                            }
                        }
                        $this->manufactures_model->updateProductionsPlan($productions_plan_id, ['status' => 'capacity', 'productions_capacity_id' => $productions_capacity_id]);
                        $this->funcClaPurchases($productions_capacity_id);

                        insertActivityLog([
                            'type_parent_obj' => 'productions_capacity',
                            'table_obj' => 'tbl_productions_capacity',
                            'id_obj' => $productions_capacity_id,
                            'name_obj' => $reference_no_capacity,
                            'content' => lang('tnh_his_add_productions_capacity') . ' [' . $reference_no_capacity . ']',
                            'actions' => 'add'
                        ]);
                    }

                    //----------------------------------------add productions orders
                    $location = $this->input->post('location');
                    $reference_no_orders = getReference('productions_orders');
                    $errors = '';
                    $total_quantity = 0;
                    $itemsOrders = [];
                    $itemProductionsOrders = $this->manufactures_model->getProductionsPlanItemsForProductionsOrdersNew($productions_plan_id);
                    foreach ($itemProductionsOrders as $key => $value) {
                        $items_id = $value['product_id'];
                        $info = $this->products_model->rowProduct($items_id);
                        $type_items = "products";
                        $production_plan_item = $value['production_plan_item_id'];
                        $items_code = $info['code'];
                        $items_name = $info['name'];
                        $quantity = $value['total_quantity'];
                        $note_items = '';
                        $versions_bom = $info['versions'];
                        $versions_stage = $info['versions_stage'];

                        $itemsOrders[$key] = [
                            'production_plan_item_id' => $production_plan_item,
                            'type_items' => $type_items,
                            'items_id' => $items_id,
                            'items_code' => $items_code,
                            'items_name' => $items_name,
                            'quantity' => $quantity,
                            'note_items' => $note_items,
                            'versions_bom' => $versions_bom,
                            'versions_stage' => $versions_stage,
                            'productions_capacity_items_id' => 0,
                            'arrBOM' => []
                        ];

                        if (!empty($production_plan_item)) {
                            $rowProductionPlanItem = $this->manufactures_model->rowProductionsPlanItemsById($production_plan_item);
                            if (!empty($rowProductionPlanItem)) {
                                $cProductionPlanId = $rowProductionPlanItem['productions_plan_id'];
                                $quantity_produce = $rowProductionPlanItem['quantity_total_details'] + $rowProductionPlanItem['quantity_reserve'] - $rowProductionPlanItem['quantity_production_orders'];
                                if ($quantity_produce < 0) $quantity_produce = 0;
                                if ($quantity > $quantity_produce) {
                                    $errors .= '<div>' . $items_code . '(' . $items_name . ') SL <= ' . formatNumber($quantity_produce) . '</div>';
                                    continue;
                                }

                                //Xử lý bom trong hoạch định sản xuất
                                $arrBom = [];

                                $productionCapacityItems = $this->manufactures_model->getProductionsCapacitySubForProductionsOrders($cProductionPlanId, $type_items, $items_id);
                                // print_arrays($productionCapacityItems);

                                if (!empty($productionCapacityItems)) {
                                    $cVersionsBom = $productionCapacityItems['versions_bom'];
                                    $cVersionsStage = $productionCapacityItems['versions_stages'];
                                    $itemsOrders[$key]['versions_bom'] = $cVersionsBom;
                                    $itemsOrders[$key]['versions_stage'] = $cVersionsStage;
                                    $itemsOrders[$key]['productions_capacity_items_id'] = $productionCapacityItems['id'];

                                    $termQuantity =  $quantity;
                                    $productionCapacityItemsSub = $this->manufactures_model->getProductionsCapacityItemsSubOrders($productionCapacityItems['id'], $type_replace = 0);
                                    if (!empty($productionCapacityItemsSub)) {
                                        $iiPartent = 0;
                                        foreach ($productionCapacityItemsSub as $k => $val) {
                                            $productions_capacity_items_sub_id = $val['id'];
                                            $soLuongTrongBom = $val['quantity'];
                                            $loaiBom = $val['type_sub'];
                                            $idMatHang = $val['id_sub'];
                                            $maMatHang = $val['code_sub'];
                                            $tenMatHang = $val['name_sub'];
                                            $donViBom = $val['unit_id'];
                                            $leadtime = $val['leadtime'];
                                            $stage_item_id = $val['stage_item_id'];

                                            $soLuongSuDungDonViChinh = $val['quantity_plan_sub_reality'];
                                            $soLuongSuDungDonViBom = $val['quantity_plan_sub_reality_bom'];
                                            $soLuongDonHangBom = $val['quantity_orders_bom'];
                                            $soLuongDonHangChinh = $val['quantity_orders_primary'];

                                            $soLuongCoTheSuDungDonViBom = $soLuongSuDungDonViBom - $soLuongDonHangBom;

                                            $soLuongQuyDoiRaDonViChinh = $val['quantity_exchange'];

                                            if ($loaiBom == "element") {
                                                //thành phần
                                                $soLuongThanhPhan = $termQuantity * $soLuongTrongBom;
                                                $arrBom[$iiPartent] = [
                                                    'productions_orders_id' => 0,
                                                    'productions_orders_items_id' => 0,
                                                    'parent_id' => 0,
                                                    'type' => 'element',
                                                    'item_id' => 0,
                                                    'item_code' => $maMatHang,
                                                    'item_name' => $tenMatHang,
                                                    'unit_id' => 0,
                                                    'quantity_single' => $soLuongTrongBom,
                                                    'quantity' => $soLuongThanhPhan,
                                                    'unit_parent_id' => 0,
                                                    'quantity_exchange' => 1,
                                                    'quantity_primary' => $soLuongThanhPhan,
                                                    'leadtime' => 0,
                                                    'stage_item_id' => 0,
                                                    'productions_capacity_items_sub_id' => $productions_capacity_items_sub_id,
                                                    'type_replace' => 0
                                                ];
                                                $iiPartent++;
                                            } else {
                                                if (empty($soLuongThanhPhan)) $soLuongThanhPhan = 1;

                                                $soLuongSuDungTrongBom = $soLuongThanhPhan * $soLuongTrongBom;

                                                if ($loaiBom == "semi_products" || $loaiBom == "semi_products_outside") {
                                                    $info = $this->products_model->rowProduct($idMatHang);
                                                } else {
                                                    $info = $this->items_model->rowMaterial($idMatHang);
                                                }

                                                $donViChinh = $info['unit_id'];
                                                if ($soLuongCoTheSuDungDonViBom <= 0) $soLuongCoTheSuDungDonViBom = 0;

                                                $soLuongSuDungHienTai = 0;
                                                $soLuongSuDungMatHang = 0;
                                                if ($soLuongCoTheSuDungDonViBom > 0) {
                                                    //vd: soLuongSuDungMatHang = soLuongCoTheSuDungDonViBom (10) - soLuongSuDungTrongBom(15);
                                                    $soLuongSuDungMatHang = $soLuongCoTheSuDungDonViBom - $soLuongSuDungTrongBom;
                                                    if ($soLuongSuDungMatHang > 0) {
                                                        $soLuongSuDungHienTai = $soLuongSuDungTrongBom;
                                                    } else {
                                                        $soLuongSuDungHienTai = $soLuongCoTheSuDungDonViBom;
                                                    }
                                                }


                                                $soLuongSuDungMatHangChinh = $soLuongSuDungHienTai / $soLuongQuyDoiRaDonViChinh;

                                                $arrBom[$iiPartent] = [
                                                    'productions_orders_id' => 0,
                                                    'productions_orders_items_id' => 0,
                                                    'parent_id' => 0,
                                                    'type' => $loaiBom,
                                                    'item_id' => $idMatHang,
                                                    'item_code' => $maMatHang,
                                                    'item_name' => $tenMatHang,
                                                    'unit_id' => $donViBom,
                                                    'quantity_single' => $soLuongTrongBom,
                                                    'quantity' => $soLuongSuDungHienTai,
                                                    'unit_parent_id' => $donViChinh,
                                                    'quantity_exchange' => $soLuongQuyDoiRaDonViChinh,
                                                    'quantity_primary' => $soLuongSuDungMatHangChinh,
                                                    'leadtime' => $leadtime,
                                                    'stage_item_id' => $stage_item_id,
                                                    'productions_capacity_items_sub_id' => $productions_capacity_items_sub_id,
                                                    'type_replace' => 0
                                                ];

                                                $danhSachBomThayThe = $this->manufactures_model->getProductionsCapacityItemsSubOrders($productionCapacityItems['id'], $type_replace = 1, $productions_capacity_items_sub_id);

                                                if (!empty($danhSachBomThayThe)) {
                                                    //xử lý dữ liệu thay thế
                                                    foreach ($danhSachBomThayThe as $kk => $vv) {

                                                        $productions_capacity_items_sub_id_ThayThe = $vv['id'];
                                                        $soLuongTrongBomThayThe = $vv['quantity'];
                                                        $loaiBomThayThe = $vv['type_sub'];
                                                        $idMatHangThayThe = $vv['id_sub'];
                                                        $maMatHangThayThe = $vv['code_sub'];
                                                        $tenMatHangThayThe = $vv['name_sub'];
                                                        $donViBomThayThe = $vv['unit_id'];
                                                        $leadtimeThayThe = $vv['leadtime'];
                                                        $stage_item_id_ThayThe = $vv['stage_item_id'];

                                                        $soLuongSuDungDonViChinhThayThe = $vv['quantity_plan_sub_reality'];
                                                        $soLuongSuDungDonViBomThayThe = $vv['quantity_plan_sub_reality_bom'];
                                                        $soLuongDonHangBomThayThe = $vv['quantity_orders_bom'];
                                                        $soLuongDonHangChinhThayThe = $vv['quantity_orders_primary'];

                                                        // $soLuongCoTheSuDungDonViBomThayThe = $soLuongSuDungDonViBomThayThe - $soLuongDonHangBom;
                                                        $soLuongCoTheSuDungDonViBomThayThe = $soLuongSuDungDonViBomThayThe - $soLuongDonHangBomThayThe;
                                                        $soLuongQuyDoiRaDonViChinhThayThe = $vv['quantity_exchange'];

                                                        if ($loaiBomThayThe == "semi_products" || $loaiBomThayThe == "semi_products_outside") {
                                                            $infoThayThe = $this->products_model->rowProduct($idMatHangThayThe);
                                                        } else {
                                                            $infoThayThe = $this->items_model->rowMaterial($idMatHangThayThe);
                                                        }

                                                        $donViChinhThayThe = $infoThayThe['unit_id'];

                                                        $soLuongSuDungHienTaiThayThe = 0;
                                                        $soLuongSuDungMatHangThayThe = 0;

                                                        // print_arrays($soLuongSuDungTrongBom);

                                                        if ($soLuongSuDungMatHang < 0) {

                                                            //Còn thiếu trong BOM

                                                            if ($soLuongCoTheSuDungDonViBomThayThe > 0) {
                                                                $soLuongSuDungMatHang = abs($soLuongSuDungMatHang);
                                                                $tempSoLuongSuDungMatHang = $soLuongSuDungMatHang;
                                                                $soLuongSuDungMatHang = $soLuongCoTheSuDungDonViBomThayThe - $soLuongSuDungMatHang;
                                                                if ($soLuongSuDungMatHang >= 0) {
                                                                    $soLuongSuDungHienTaiThayThe = $tempSoLuongSuDungMatHang;
                                                                } else {
                                                                    $soLuongSuDungHienTaiThayThe = $soLuongCoTheSuDungDonViBomThayThe;
                                                                }
                                                            }
                                                        } else if ($soLuongSuDungMatHang > 0) {
                                                            $soLuongSuDungHienTaiThayThe = 0;
                                                        } else if ($soLuongCoTheSuDungDonViBom == 0) {

                                                            // TH: Neu $soLuongCoTheSuDungDonViBom == 0
                                                            // Mặt hàng chính không có sự dụng
                                                            if ($soLuongCoTheSuDungDonViBomThayThe > 0) {
                                                                $soLuongSuDungMatHang = $soLuongCoTheSuDungDonViBomThayThe - $soLuongSuDungTrongBom;
                                                                if ($soLuongSuDungMatHang >= 0) {
                                                                    //Bom thay thế sự dụng hết cho đơn hàng
                                                                    $soLuongSuDungHienTaiThayThe = $soLuongSuDungTrongBom;
                                                                } else {
                                                                    $soLuongSuDungHienTaiThayThe = $soLuongCoTheSuDungDonViBomThayThe;
                                                                }
                                                            }
                                                        }

                                                        $soLuongSuDungMatHangChinhThayThe = $soLuongSuDungHienTaiThayThe / $soLuongQuyDoiRaDonViChinhThayThe;


                                                        $arrBom[$iiPartent]['replace'][] = [
                                                            'productions_orders_id' => 0,
                                                            'productions_orders_items_id' => 0,
                                                            'parent_id' => 0,
                                                            'type' => $loaiBomThayThe,
                                                            'item_id' => $idMatHangThayThe,
                                                            'item_code' => $maMatHangThayThe,
                                                            'item_name' => $tenMatHangThayThe,
                                                            'unit_id' => $donViBomThayThe,
                                                            'quantity_single' => $soLuongTrongBomThayThe,
                                                            'quantity' => $soLuongSuDungHienTaiThayThe,
                                                            'unit_parent_id' => $donViChinhThayThe,
                                                            'quantity_exchange' => $soLuongQuyDoiRaDonViChinhThayThe,
                                                            'quantity_primary' => $soLuongSuDungMatHangChinhThayThe,
                                                            'leadtime' => $leadtimeThayThe,
                                                            'stage_item_id' => $stage_item_id_ThayThe,
                                                            // 'productions_capacity_items_sub_id' => $productions_capacity_items_sub_id,
                                                            'productions_capacity_items_sub_id' => $productions_capacity_items_sub_id_ThayThe,
                                                            'type_replace' => 1
                                                        ];
                                                    }
                                                }

                                                if ($soLuongSuDungMatHang < 0) {
                                                    $soLuongSuDungMatHangCongThem = abs($soLuongSuDungMatHang);
                                                    if (formatDecimalNumber($soLuongSuDungMatHangCongThem) > 0) {
                                                        $soLuongSuDungMatHangChinhCongThem = $soLuongSuDungMatHangCongThem / $soLuongQuyDoiRaDonViChinh;

                                                        $arrBom[$iiPartent]['quantity'] = $arrBom[$iiPartent]['quantity'] + $soLuongSuDungMatHangCongThem;
                                                        $arrBom[$iiPartent]['quantity_primary'] = $arrBom[$iiPartent]['quantity_primary'] + $soLuongSuDungMatHangChinhCongThem;
                                                    }
                                                }
                                                $iiPartent++;
                                                // break;
                                            }
                                        }
                                    }
                                }
                                $itemsOrders[$key]['arrBOM'] = $arrBom;
                                //end 
                            } else {
                                continue;
                            }
                        }
                    }

                    $total_quantity += $quantity;
                    $count_items = count($itemsOrders);

                    $options = [
                        'date' => $date_general,
                        'reference_no' => $reference_no_orders,
                        'location_id' => $location,
                        'productions_plan_id' => $productions_plan_id,
                        'productions_plan_reference_no' => $productions_plan_reference,
                        'total_quantity' => $total_quantity,
                        'count_items' => $count_items,
                        'note' => '',
                        'status' => 'approved',
                        'date_created' => $date_general,
                        'created_by' => $staff_general,
                        'user_status' => $staff_general,
                        'date_status' => $date_general,
                    ];
                    $productions_orders_id = $this->manufactures_model->insertProductionsOrders($options);
                    if ($productions_orders_id) {
                        updateReference('productions_orders');

                        foreach ($itemsOrders as $key => $value) {
                            $value['productions_orders_id'] = $productions_orders_id;
                            $arrBOM = $value['arrBOM'];
                            unset($value['arrBOM']);
                            $productions_orders_items_id = $this->manufactures_model->insertProductionsOrdersItems($value);
                            if ($productions_orders_items_id) {
                                $this->manufactures_model->updateQuantityProductionOrders($value['production_plan_item_id'], $value['quantity'], $plus = 1);

                                //Lưu bom
                                $this->manufactures_model->updateQuantityPCI($value['productions_capacity_items_id'], $value['quantity'], $plus = 1);
                                if (!empty($arrBOM)) {
                                    foreach ($arrBOM as $k => $val) {
                                        $dataReplace = !empty($val['replace']) ? $val['replace'] : '';
                                        if (!empty($val['replace'])) unset($val['replace']);
                                        $val['productions_orders_id'] = $productions_orders_id;
                                        $val['productions_orders_items_id'] = $productions_orders_items_id;

                                        $parent_id = $this->manufactures_model->insertProductionOrdersItemsSub($val);
                                        if ($parent_id) {
                                            $this->manufactures_model->updateQuantityPCISub($val['productions_capacity_items_sub_id'], $val['quantity'], $val['quantity_primary'], $plus = 1);
                                            if (!empty($dataReplace)) {
                                                foreach ($dataReplace as $kk => $vv) {
                                                    $vv['productions_orders_id'] = $productions_orders_id;
                                                    $vv['productions_orders_items_id'] = $productions_orders_items_id;
                                                    $vv['parent_id'] = $parent_id;

                                                    $item_id_replace = $this->manufactures_model->insertProductionOrdersItemsSub($vv);
                                                    if ($item_id_replace) {
                                                        $this->manufactures_model->updateQuantityPCISub($vv['productions_capacity_items_sub_id'], $vv['quantity'], $vv['quantity_primary'], $plus = 1);
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                //end lưu bom

                                //stages
                                $item_id = $value['items_id'];
                                $versions_stage = $value['versions_stage'];
                                $vs = $this->products_model->getProductStagesByProductIdAndVersions($item_id, $versions_stage);
                                if (!empty($vs)) {
                                    $product_stages = $this->products_model->getProductStagesVersions($vs['id']);
                                    if (!empty($product_stages)) {
                                        foreach ($product_stages as $i => $el) {
                                            $stages[] = [
                                                'productions_orders_id' => $productions_orders_id,
                                                'productions_orders_items_id' => $productions_orders_items_id,
                                                'stage_id' => $el['stage_id'],
                                                'machines' => $el['machines'],
                                                'number' => $el['number'],
                                                'number_hours' => $el['number_hours'],
                                                'final_stage' => $el['final_stage']
                                            ];
                                        }
                                    }
                                }
                            }
                        }

                        $this->manufactures_model->insertProductionsPlanOrders([
                            'productions_plan_id' => $productions_plan_id,
                            'productions_order_id' => $productions_orders_id,
                            'total_quantity' => $total_quantity,
                            'count_items' => $count_items,
                        ]);
                        $this->manufactures_model->updateProductionsPlan($productions_plan_id, ['productions_orders_id' => 2]);
                        if (!empty($stages)) {
                            $this->manufactures_model->insertBatchProductionOrdersItemsStages($stages);
                        }

                        insertActivityLog([
                            'type_parent_obj' => 'productions_orders',
                            'table_obj' => 'tbl_productions_orders',
                            'id_obj' => $id,
                            'name_obj' => $reference_no_orders,
                            'content' => lang('tnh_his_edit_productions_orders') . ' [' . $reference_no_orders . ']',
                            'actions' => 'edit'
                        ]);
                    }

                    //created productions orders
                    $id = $productions_orders_id;
                    $productions_orders = $this->manufactures_model->rowProductionsOrdersById($productions_orders_id);
                    $items = $this->manufactures_model->getProductionsORdersItemsForCreated($productions_orders_id);
                    $flag = false;
                    foreach ($items as $key => $value) {
                        $deadline = $this->input->post('deadline')[$key] ? to_sql_date($this->input->post('deadline')[$key]) : '0000-00-00';
                        $departments = $this->input->post('departments')[$key];

                        $dateCreated = date('Y-m-d H:i:s');
                        $created_by = get_staff_user_id();
                        $reference_no = getReference('productions_orders_details');
                        $details = [
                            'reference_no' => $reference_no,
                            'productions_orders_id' => $id,
                            'productions_orders_item_id' => $value['id'],
                            'deadline' => $deadline,
                            'departments' => implode(',', $departments),
                            'status' => 'un_produced',
                            'created_by' => $created_by,
                            'date_created' => $dateCreated,
                        ];

                        $pod_id = $this->manufactures_model->insertProductionsOrdersDetails($details);
                        if ($pod_id) {
                            $flag = true;
                            updateReference('productions_orders_details');
                            $employees = $this->input->post('employess')[$key];
                            $emp = [];
                            if (!empty($employees)) {
                                foreach ($employees as $k => $val) {
                                    $emp[] = [
                                        'employee_id' => $val,
                                        'productions_orders_details_id' => $pod_id,
                                    ];
                                }
                                if (!empty($emp)) {
                                    $this->manufactures_model->insertBatchPODEmployees($emp);
                                }
                            }

                            if (!empty($departments)) {
                                foreach ($departments as $k => $val) {
                                    $depart = [
                                        'pod_id' => $pod_id,
                                        'department_id' => $val,
                                    ];
                                    $this->manufactures_model->insertPODDepartments($depart);
                                }
                            }

                            //task shift work
                            $shift_works = !empty($this->input->post('shift_work')[$value['id']]) ? $this->input->post('shift_work')[$value['id']] : null;
                            if (!empty($shift_works)) {
                                foreach ($shift_works as $kk => $vv) {
                                    $dtShiftWork = $this->site_model->getShiftWorkById($vv);
                                    $counterShiftWork = $this->input->post('counterShiftWork')[$value['id']][$kk];
                                    $quantityShiftWork = $this->input->post('quantity_shift_work')[$value['id']][$kk];
                                    $staff_shift_work = $this->input->post('staff_shift_work')[$counterShiftWork];

