                        if (!empty($email)) {
                            $emailPDO = $this->manufactures_model->getEmailPOD($id);
                            if (!empty($emailPDO)) {
                                foreach ($emailPDO as $key => $value) {
                                    sendEmail([
                                        'email' => $value['email'],
                                        'message' => $value['description'],
                                        'subject' => $value['name'],
