                    //list suggest exporting
                    $this->db->select('*');
                    $this->db->from('tbl_productions_orders_details');
                    $this->db->where('tbl_productions_orders_details.productions_orders_id', $productions_orders_id);
                    $pod = $this->db->get()->result_array();
                    foreach ($pod as $kPod => $vPod) {
                        $reference_no_sg = getReference('suggest_exporting');
                        $productions_orders_detail_id = $vPod['id'];
                        $export_name = 'Đề nghị xuất vật tư [' . $vPod['reference_no'] . ']';
                        $total_quantity = 0;
                        $count_items = 0;
                        $total_quantity_exchange = 0;
                        $type = 1;
                        $productions_orders_items_id = $vPod['productions_orders_item_id'];

                        $exporting_items = null;
                        $materials = $this->manufactures_model->getMaterialSuggestExporting($productions_orders_items_id);
                        if (!empty($materials)) {
                            foreach ($materials as $key => $value) {
                                $item_id = $value['item_id'];
                                $unit_id = $value['unit_id'];
                                $unit_parent_id = $value['unit_parent_id'];
                                $number_exchange = $value['quantity_exchange'];
                                $quantity_export = $value['quantity'];
                                if ($quantity_export > 0) {
                                    $info_item = NULL;
                                    $type_item = $value['type_item'];
                                    if ($type_item == "semi_products_outside" || $type_item == "semi_products") {
                                        $info_item = $this->products_model->rowProduct($item_id);
                                    } else if ($type_item == "materials") {
                                        $info_item = $this->items_model->rowMaterial($item_id);
                                    }
                                    if (empty($info_item)) continue;

                                    $quantity_exchange = $quantity_export / $number_exchange;
                                    $exporting_items[] = [
                                        'type_item' => $type_item,
                                        'item_id' => $item_id,
                                        'item_code' => $info_item['code'],
                                        'item_name' => $info_item['name'],
                                        'unit_id' => $unit_id,
                                        'quantity_export' => $quantity_export,
                                        'unit_parent_id' => $unit_parent_id,
                                        'number_exchange' => $number_exchange,
                                        'quantity_exchange' => $quantity_exchange,
                                    ];
                                    $total_quantity += $quantity_export;
                                    $total_quantity_exchange += $quantity_exchange;
                                }
                            }
                        }

                        if (empty($exporting_items)) {
                            continue;
                        }
                        $count_items = count($exporting_items);
                        $fields = [
                            'productions_orders_details_id' => $productions_orders_detail_id,
                            'reference_no' => $reference_no_sg,
                            'date' => $date_general,
                            'export_name' => $export_name,
                            'note' => '',
                            'status' => 'approved',
                            'total_quantity' => $total_quantity,
                            'count_items' => $count_items,
                            'total_quantity_exchange' => $total_quantity_exchange,
                            'created_by' => $staff_general,
                            'date_created' => $date_general,
                            'date_status' => $date_general,
                            'user_status' => $staff_general,
                            'type' => '1'
                        ];
                        $suggest_exporting_id = $this->manufactures_model->insertSuggestExporting($fields);
                        if ($suggest_exporting_id) {
                            updateReference('suggest_exporting');
                            foreach ($exporting_items as $key => $value) {
                                $exporting_items[$key]['suggest_exporting_id'] = $suggest_exporting_id;
                            }
                            $this->manufactures_model->insertBatchSuggestExportingItems($exporting_items);

                            $content = lang('tnh_his_export_supplies_productions_orders_details');
                            $content = str_replace('{$1}', $reference_no_sg, $content);
                            $content = str_replace('{$2}', $vPod['reference_no'], $content);
                            insertActivityLog([
                                'type_parent_obj' => 'suggest_exporting',
                                'table_obj' => 'tbl_suggest_exporting',
                                'id_obj' => $suggest_exporting_id,
                                'name_obj' => $reference_no_sg,
                                'content' => $content,
                                'actions' => 'add'
                            ]);
                        }
                    }


                    set_alert('success', lang('success'));
                    $data['result'] = 1;
                    $data['message'] = lang('success');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data);
            die;
        } else {
            $data['staffs'] = $this->site_model->getStaff();
            $data['locations'] = $this->category_model->getCapacity();
            $data['items'] = $items;
            $data['order'] = $order;
            $data['id'] = $id;
            $data['departments'] = $this->departments_model->getDepartments();
            $data['shiftWork'] = $this->site_model->getShiftWork();
            $data['staffs'] = $this->site_model->getStaff();
            $this->load->view('admin/orders/add_production_planning_orders', $data);
        }
    }

    //
    public function keep_stock_material($id) {
        if ($this->input->post()) {
            $data = [];
            $productions_plan = $this->manufactures_model->rowProductionsPlan($id);
            $this->form_validation->set_rules('date', lang("date"), 'required');
            if ($this->form_validation->run() == true)
            {
                $date = to_sql_date($this->input->post('date'));
                $note = $this->input->post('note', false);
                $items = $this->input->post('items');
                $localtion_to = $this->site_model->getLocationToPlan($id);
                // $localtion_to = LOCATIONS_DEFAULT_MANUFACTURES;
                $totalQuantity = 0;
                $arr_id = [];
                $arr_info = [];
                $errors = '';
                if (!empty($items)) {
                    foreach ($items as $key => $value) {
                        $items_id = $value['items_id'];
                        if (empty($items_id)) continue;
                        $items_id = explode('__', $items_id);
                        $id_items = $items_id[1];
                        $type = $items_id[0];

                        $quantity_warehouse = 0;
                        $unit_warehouse = 0;
                        $exchange_warehouse = 1;
                        $quantity_payment = 0;
                        $unit_payment = 0;
                        $exchange_payment = 1;
                        $exchange_unit = 1;
                        $recipe = 1;

                        $longs = 1;
                        $wide = 1;
                        $paper = 1;
                        $unit_id = 0;
                        $conversion_quantity_unit = 1;
                        if ($type == "materials") {
                            $type = "nvl";
                            $info = $this->items_model->rowMaterial($id_items);

                            $unit_warehouse = $info['standard_unit'];
                            $exchange_warehouse = !empty($info['exchange_standard_unit']) ? $info['exchange_standard_unit'] : 1;
    
                            $unit_payment = $info['unit_payment'];
                            $exchange_payment = !empty($info['exchange_unit_payment']) ? $info['exchange_unit_payment'] : 1;
    
                            $exchange_unit = $info['exchange_unit'];
    
                            $longs = $info['longs'];
                            $wide = $info['wide'];
                            $paper = $info['paper'];
                            $recipe = $info['recipe'];

                            $unit_id =  $unit_warehouse;
                        } else {
                            $type = "product";
                            $info = $this->products_model->rowProduct($id_items);
                            
                            $unit_warehouse = $info['conversion_unit'];
                            $unit_payment = $info['unit_id'];
                            $unit_id =  $info['unit_id'];

                            $exchange_warehouse = $info['conversion_quantity_unit'];
                            $conversion_quantity_unit = $info['conversion_quantity_unit'];
                        }

                        $info_items = [
                            'recipe' => $recipe,
                            'paper' => $paper,
                            'longs' => $longs,
                            'wide' => $wide,
                        ];

                        $counter = $value['counter'];
                        $str_item_id = $value['items_id'];
                        $index = array_search($str_item_id, $arr_id);
                        if ($index === false) {
                            $arr_id[] = $str_item_id;
                        } else {
                            $errors .= '<div>Có mặt hàng ['.$info['code'].'] bị trùng mặt hàng và vị trí kho chuyển vui lòng xóa</div>';
                            continue;
                        }
                        
                        $price = $info['price_sell'];

                        $tick = !empty($this->input->post('tick')[$counter]) ? $this->input->post('tick')[$counter] : NULL;
                        if (!empty($tick)) {
                            $totalQuantityCorrdinator = 0;
                            foreach ($tick as $k => $val) {
                                $warehousesLocation = explode('__', $val);
                                $warehouse_id = $warehousesLocation[0];
                                $location_id = $warehousesLocation[1];
                                $lot_code = $warehousesLocation[2];
                                $date_sx = $warehousesLocation[3];
                                $date_sd = $warehousesLocation[4];
                                $date_use = $warehousesLocation[5];

                                $quantityCoordinator = number_unformat($this->input->post('quantity_coordinator')[$counter][$k]);
                                if (empty($lot_code) || $lot_code === 'NULL' || $lot_code == null) {
                                    $lot_code = NULL;
                                }

                                if (empty($date_sx) || $date_sx === 'NULL' || $date_sx == null) {
                                    $date_sx = NULL;
                                }

                                if (empty($date_sd) || $date_sd === 'NULL' || $date_sd == null) {
                                    $date_sd = NULL;
                                }

                                if (empty($date_use) || $date_use === 'NULL' || $date_use == null) {
                                    $date_use = NULL;
                                }

                                $dtWarehouse = $this->site_model->getQuantityWarehouse($id_items, $type, $warehouse_id, $location_id, $lot_code, $date_sx, $date_sd);
                                $quantityWarehouse = $dtWarehouse['product_quantity'];

                                if ($type == "nvl" || $type == "materials") {
                                    $quantity_warehouse = $quantityCoordinator;
                                    $quantity_unit = $quantity_warehouse * $exchange_warehouse / $exchange_unit;

                                    $quantity_net =  0;
                                    // $quantity_warehouse = $quantityCoordinator/$exchange_warehouse * $exchange_unit;
                                    $quantity_net = $quantity_warehouse;

                                    if ($recipe == 1) {
                                        $quantity_payment = $quantity_unit/$exchange_payment * $exchange_unit;
                                    } else if ($recipe == 2) {
                                        $quantity_payment = $quantity_unit/$exchange_payment * $exchange_unit * $paper/100;
                                    } else if ($recipe == 3) {
                                        $quantity_payment = $quantity_unit/$exchange_payment * $exchange_unit * $longs * $wide/10000;
                                    }
                                } else {
                                    // $quantity_net = $quantityCoordinator;
                                    // $quantity_unit = $quantity_net;
                                    // $quantity_warehouse = roundNumberFormat($quantity_net * $exchange_warehouse);
                                    // $quantity_payment = $quantity_net;

                                    $quantity_unit = $quantityCoordinator;
                                    $quantity_warehouse = roundNumberFormat($quantity_unit * $exchange_warehouse, 0);
                                    $quantity_net = $quantity_warehouse;
                                    $quantityCoordinator = $quantity_warehouse;
                                }

                                // if ($quantityCoordinator > $quantityWarehouse) {
                                // if ($quantity_net > $quantityWarehouse) {

                                $totalQuantityCorrdinator+= $quantityCoordinator;
                                if ($quantity_warehouse > $quantityWarehouse) {
                                    $errors.= '<div>Kho hàng [' . $dtWarehouse['name_warehouse'] . '] vị trí [' . $dtWarehouse['name_location'] . '] Lot ['.$lot_code.'], Ngày SX ['.($date_sx ? _d($date_sx) : '').'], Ngày SX ['.($date_sd ? _d($date_sd) : '').'] có số lượng kho nhỏ hơn [' . formatNumber($dtWarehouse['product_quantity']/$conversion_quantity_unit) . ']</div>';
                                    continue;
                                }

                                if (empty($quantityCoordinator)) {
                                    $data['result'] = 0;
                                    $data['message'] = lang('Số lượng giữ phải lớn hơn 0');
                                    echo json_encode($data); die;
                                    continue;
                                }

                                $amount = $price * $quantityCoordinator;

                                $tranferItems[] = array(
                                    'id_items' => $id_items,
                                    'quantity' => $quantity_net,
                                    'quantity_net' => $quantity_net,
                                    'type' => $type,
                                    'note' => '',
                                    'warehouses_to' => WAREHOUSES_CAPACITY,
                                    'warehouses_id' => $warehouse_id,
                                    'localtion_id' => $location_id,
                                    'localtion_to' => $localtion_to,
                                    'lot_code' => $lot_code,
                                    'date_sx' => $date_sx,
                                    'date_sd' => $date_sd,
                                    'date_use' => $date_use,
                                    'price' => $price,
                                    'amount' => $amount,
                                    'quantity_unit' => $quantity_unit,
                                    'exchange_unit' => $exchange_unit,
                                    'quantity_stock' => $quantity_warehouse,
                                    'exchange_stock' => $exchange_warehouse,
                                    'quantity_payment' => $quantity_payment,
                                    'exchange_payment' => $exchange_payment,
                                    'info_items' => !empty($info_items) ? json_encode($info_items) : NULL,
                                    'unit_id' => $unit_id,
                                );
                            }
                        } else {
                            $errors .= '<div>Mặt hàng ['.$info['code'].'] vui lòng chọn giữ kho</div>';
                            continue;
                        }

                        if (empty($totalQuantityCorrdinator)) {
                            $data['result'] = 0;
                            $data['message'] = lang('Số lượng giữ phải lớn hơn 0');
                            echo json_encode($data); die;
                        }

                        
                        $totalQuantity += $totalQuantityCorrdinator;
                    }
                }

                if (!empty($errors)) {
                    $data['result'] = 0;
                    $data['message'] = $errors;
                    echo json_encode($data); die;
                }

                if (empty($tranferItems)) {
                    $data['result'] = 0;
                    $data['message'] = lang('Không có mặt hàng để thêm');
                    echo json_encode($data); die;
                }

                $statusTransfer = 2;
                $staffIdTransfer = get_staff_user_id();
                $dateTransfer = date('Y-m-d H:i:s');
                $history_status = '|' . $staffIdTransfer . ',' . $dateTransfer;

                $transfer = array(
                    'code' => sprintf('%06d', ch_getMaxID('id', 'tbltransfer_warehouse') + 1),
                    'prefix' => get_option('prefix_transfer'),
                    'note' => '',
                    'warehouse_id' => 0,
                    'warehouse_to' => 0,
                    'date' => $date,
                    'staff_id' => $staffIdTransfer,
                    'date_create' => $dateTransfer,
                    'status' => $statusTransfer,
                    'total' => $totalQuantity,
                    'history_status' => $history_status,
                    'productions_capacity_id' => $id
                );

                $transfer_id = $this->site_model->insertTransferWarehouse($transfer);
                if ($transfer_id) {
                    foreach ($tranferItems as $k => $v) {
                        $v['id_transfer'] = $transfer_id;
                        $this->site_model->insertTransferWarehouseDetail($v);
                    }

                    //xử lý duyệt kho
                    if (!test_quantity_tranfer($transfer_id)) {
                        //Duyệt kho thất bại
                    } else {
                        $dataTransfer = array(
                            'warehouseman_id' => $staffIdTransfer,
                            'warehouseman_date' => $dateTransfer
                        );
                        $this->db->update('tbltransfer_warehouse', $dataTransfer, array('id' => $transfer_id));
                        $this->transfer_model->increaseTranfersWarehouse($transfer_id, $id);
                    }

                    insertActivityLog([
                        'type_parent_obj' => 'productions_plan',
                        'table_obj' => 'tbl_productions_plans',
                        'id_obj' => $id,
                        'name_obj' => $productions_plan['reference_no'],
                        'content' => lang('Giữ kho NVL') . ' [' . $productions_plan['reference_no'] . ']',
                        'actions' => 'keep_stock_material'
                    ]);

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data); die;
        } else {
            $data['id'] = $id;
            $this->load->view('admin/manufactures/keep_stock_material', $data);
        }

    }

    public function getItemsKeepStockMaterial() {
        $data = [];
        $term = $this->input->get('term', TRUE);
        $limit = get_option('select2_limit');
        $params = $this->input->get('params');
        $productions_plan_id = $params['productions_plan_id'];
        $type = !empty($params['type']) ? $params['type'] : ''; 

        $tbTransferWarehouse = "(
            SELECT
                tbltransfer_warehouse_detail.id_items as id_items,
                SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
            FROM tbltransfer_warehouse
            INNER JOIN tbltransfer_warehouse_detail ON tbltransfer_warehouse_detail.id_transfer = tbltransfer_warehouse.id
            WHERE tbltransfer_warehouse_detail.type = 'product' AND tbltransfer_warehouse.productions_capacity_id = ".$this->db->escape($productions_plan_id)."
            GROUP BY tbltransfer_warehouse_detail.id_items
        ) tb_transfer_detail";

        $this->db->select('
            tbl_productions_plan_bom.item_id as item_id,
            "products" as item_type,
            tbl_productions_plan_bom.item_type as item_type_root,
            CONCAT("products__", tbl_products.id) as id,
            CONCAT(tbl_products.name, "(", tbl_products.code, ")") as text,
            SUM(tbl_productions_plan_bom.quantity_primary) as quantity_primary,
            tb_transfer_detail.quantity_net as quantity_net,
            tblunits.unit as unit_name,
            tblunits.unit as unit_name_stock,
            1 as exchange_standard_unit,
            1 as exchange_unit,
        ', false);
        $this->db->from('tbl_productions_plan_bom');
        $this->db->join('tbl_products', 'tbl_products.id = tbl_productions_plan_bom.item_id');
        $this->db->join('tblunits', 'tblunits.unitid = tbl_products.unit_id', 'left');
        $this->db->join($tbTransferWarehouse, 'tb_transfer_detail.id_items = tbl_productions_plan_bom.item_id', 'left');
        $this->db->where('tbl_productions_plan_bom.productions_plan_id', $productions_plan_id);
        if ($type == "purchases") {
            $this->db->where_in('tbl_productions_plan_bom.item_type', ['semi_products_outside']);
        } else {
            $this->db->where_in('tbl_productions_plan_bom.item_type', ['semi_products_outside', 'semi_products']);
        }
        if (!empty($term)) {
            $this->db->group_start();
            $this->db->like('tbl_products.code', $term);
            $this->db->or_like('tbl_products.name', $term);
            $this->db->group_end();
        }
        $this->db->limit($limit);
        $this->db->group_by('tbl_productions_plan_bom.item_id');
        $semi_product_outside = $this->db->get()->result_array();


        $tbTransferWarehouse = "(
            SELECT
                tbltransfer_warehouse_detail.id_items as id_items,
                SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
            FROM tbltransfer_warehouse
            INNER JOIN tbltransfer_warehouse_detail ON tbltransfer_warehouse_detail.id_transfer = tbltransfer_warehouse.id 
            WHERE tbltransfer_warehouse_detail.type = 'nvl' AND tbltransfer_warehouse.productions_capacity_id = ".$this->db->escape($productions_plan_id)."
            GROUP BY tbltransfer_warehouse_detail.id_items
        ) tb_transfer_detail";

        $this->db->select('
            tbl_productions_plan_bom.item_id as item_id,
            "materials" as item_type,
            tbl_productions_plan_bom.item_type as item_type_root,
            CONCAT("materials__", tbl_materials.id) as id,
            CONCAT(tbl_materials.name, "(", tbl_materials.code, ")") as text,
            SUM(tbl_productions_plan_bom.quantity_primary) as quantity_primary,
            tb_transfer_detail.quantity_net as quantity_net,
            tblunits.unit as unit_name,
            unit_stock.unit as unit_name_stock,
            tbl_materials.exchange_standard_unit as exchange_standard_unit,
            tbl_materials.exchange_unit as exchange_unit
        ', false);
        $this->db->from('tbl_productions_plan_bom');
        $this->db->join('tbl_materials', 'tbl_materials.id = tbl_productions_plan_bom.item_id');
        $this->db->join('tblunits', 'tblunits.unitid = tbl_materials.unit_id', 'left');
        $this->db->join('tblunits unit_stock', 'unit_stock.unitid = tbl_materials.standard_unit', 'left');
        $this->db->join($tbTransferWarehouse, 'tb_transfer_detail.id_items = tbl_productions_plan_bom.item_id', 'left');
        $this->db->where('tbl_productions_plan_bom.productions_plan_id', $productions_plan_id);
        $this->db->where_in('tbl_productions_plan_bom.item_type', ['materials']);
        if (!empty($term)) {
            $this->db->group_start();
            $this->db->like('tbl_materials.code', $term);
            $this->db->or_like('tbl_materials.name', $term);
            $this->db->group_end();
        }
        $this->db->limit($limit);
        $this->db->group_by('tbl_productions_plan_bom.item_id');
        $materials = $this->db->get()->result_array();

        $results = [];
        if (!empty($materials))
        {
            $results[]= ['text' => lang('materials'), 'children' => $materials];
        }
        if (!empty($semi_product_outside)) {
            $results[]= ['text' => lang('semi_products_outside'), 'children' => $semi_product_outside];
        }
        $data['results'] = $results;
        echo json_encode($data);
    }

    public function getWarehousesLocationPlan($item_id = false, $type_item = false)
    {
        $data = [];
        $item_id = !empty($item_id) ? $item_id : $this->input->post('item_id');
        $type_item = !empty($type_item) ? $type_item : $this->input->post('item_type');

        if ($type_item == "materials") {
            $type_item = "nvl";
        } else if ($type_item == "products") {
            $type_item = "product";
        } else if ($type_item == "items") {
            $type_item = "items";
        } else if ($type_item == "tools_supplies") {
            $type_item = "tools";
        }

        $isWarehouses = 0;
        $warehouses = $this->site_model->getWarehouse([WAREHOUSES_CAPACITY]);
        $group = '';
        $option = '';
        $idDefault = 0;
        $quantityDefault = 0;
        foreach ($warehouses as $key => $value) {
            $warehouseId = $value['id'];
            if ($group != $warehouseId) {
                if ($group != '') {
                    $option.= '</optgroup>';
                }
                $option.= '<optgroup label="'.$value['name'].'">';
            }
            $locationWarehouse = $this->site_model->getLocationWarehouseQuantity($warehouseId, $item_id, $type_item);
            if (!empty($locationWarehouse)) {
                $ctLocationWarehouse = count($locationWarehouse);
                foreach ($locationWarehouse as $k => $val) {
                    if ($val['quantity_warehouse'] == 0) continue;
                    if ($val['quantity_warehouse'] != 0 && empty($idDefault)) {
                        $idDefault = $val['id'];
                        $quantityDefault = $val['quantity_warehouse'];
                    }
                    if (empty($idDefault) && ($ctLocationWarehouse - 1) == $k) {
                        $idDefault = $val['id'];
                        $quantityDefault = $val['quantity_warehouse'];
                    }
                    $isWarehouses = 1;
                    $option.= '<option data-quantity="'.$val['quantity_warehouse'].'" value="'.$val['id'].'">'.$val['name_location'].' - '.formatNumber($val['quantity_warehouse']).'</option>';
                }
            }

            $group = $warehouseId;
        }
        if ($group != '') {
            $option.= '</optgroup>';
        }
        $data['option'] = $option;
        $data['idDefault'] = $idDefault;
        $data['quantityDefault'] = $quantityDefault;
        $data['isWarehouses'] = $isWarehouses;
        if ($this->input->post('item_id')) {
            echo json_encode($data);
        } else {
            return $data;
        }
    }

