    public function loadAllKeepStockMaterial() {
        $productions_plan_id = $this->input->post('productions_plan_id');
        $type = $this->input->post('type');

        $arrSemiProduct = [];
        $warehousePlan = $this->manufactures_model->getWarehousesPlanBom($productions_plan_id, 'semi_products', 'product');
        $semi_products = $this->manufactures_model->getProductionsPlanBom(0, ['semi_products'], $productions_plan_id);
        $arrQuantitySemiProduct = [];
        if(!empty($semi_products)) {
            foreach($semi_products as $k => $v) {
                continue;
                $tempW = null;
                $quantityCurrent = 0;
                $quantityPrimary = $v['quantity_primary'] + $v['quantity_compensation_primary'] + $v['quantity_compensation_sm_primary'];
                $quantityRest = $v['quantity_primary'] + $v['quantity_compensation_primary'] + $v['quantity_compensation_sm_primary'];
                $cIndex = 'semi_products__'.$v['item_id'];
                if (!empty($warehousePlan[$cIndex])) {
                    $tempW = $warehousePlan[$cIndex];
                    $quantityCurrent = $tempW['quantity'];
                    if ($quantityCurrent > 0) {
                        $tempQuantity = $quantityCurrent - $quantityPrimary;
                        if ($tempQuantity > 0) {
                            $quantityRest = 0;
                        } else {
                            $quantityRest = abs($tempQuantity);
                            $tempQuantity = 0;
                        }
                        $warehousePlan[$cIndex]['quantity'] = $tempQuantity;
                    } else {
                        $quantityCurrent = 0;
                    }

                    if (!empty($quantityCurrent)) {
                        $quantityUse = $v['quantity_primary'] + $v['quantity_compensation_primary'] + $v['quantity_compensation_sm_primary'] - $quantityCurrent;
                        if ($quantityUse >= 0) {
                            $quantityUse = $quantityCurrent;
                        } else {
                            $quantityUse = $v['quantity_primary'] + $v['quantity_compensation_primary'] + $v['quantity_compensation_sm_primary'];
                        }
                        $arrSemiProduct[$v['id']] = $quantityUse;
                        if (empty($arrQuantitySemiProduct[$cIndex])) {
                            $arrQuantitySemiProduct[$cIndex] = $quantityUse;
                        } else {
                            $arrQuantitySemiProduct[$cIndex] = $arrQuantitySemiProduct[$cIndex]+ $quantityUse;
                        }
                    }
                }
            }
        }

        $materialBomSemiProduct = $this->manufactures_model->getMaterialBomSemiProduct($arrSemiProduct);

        $tbTransferWarehouse = "(
            SELECT
                tbltransfer_warehouse_detail.id_items as id_items,
                SUM(tbltransfer_warehouse_detail.quantity_unit) as quantity_net
            FROM tbltransfer_warehouse
            INNER JOIN tbltransfer_warehouse_detail ON tbltransfer_warehouse_detail.id_transfer = tbltransfer_warehouse.id
