            $this->db->where_in('tbl_productions_plan_bom.item_type', ['semi_products_outside']);
        } else {
            $this->db->where_in('tbl_productions_plan_bom.item_type', ['semi_products_outside', 'semi_products']);
        }
        $this->db->group_by('tbl_productions_plan_bom.item_id');
        $semi_product_outside = $this->db->get()->result_array();

        $tbTransferWarehouse = "(
            SELECT
                tbltransfer_warehouse_detail.id_items as id_items,
                SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
            FROM tbltransfer_warehouse
            INNER JOIN tbltransfer_warehouse_detail ON tbltransfer_warehouse_detail.id_transfer = tbltransfer_warehouse.id
            WHERE tbltransfer_warehouse_detail.type = 'nvl' AND tbltransfer_warehouse.productions_capacity_id = ".$this->db->escape($productions_plan_id)."
            GROUP BY tbltransfer_warehouse_detail.id_items
        ) tb_transfer_detail";

        $tbPurchases = "(
            SELECT
                tblpurchases_items.product_id as product_id,
                SUM(tblpurchases_items.quantity) as quantity
            FROM tblpurchases
            INNER JOIN tblpurchases_items ON tblpurchases_items.purchases_id = tblpurchases.id
            WHERE tblpurchases.id_plan = ".$this->db->escape($productions_plan_id)." AND tblpurchases_items.type = 'nvl'
            GROUP BY tblpurchases_items.product_id
        ) tb_purchases";

        $this->db->select('
            tbl_productions_plan_bom.item_id as item_id,
            "materials" as item_type,
            tbl_productions_plan_bom.item_type as item_type_root,
            CONCAT("materials__", tbl_materials.id) as id,
            CONCAT(tbl_materials.name, "(", tbl_materials.code, ")") as text,
            SUM(tbl_productions_plan_bom.quantity_primary) + coalesce(tb_productions_plan_compensation.quantity_primary, 0) as quantity_primary,
            tb_transfer_detail.quantity_net as quantity_net,
            tblunits.unit as unit_name,
            tb_purchases.quantity as quantity_purchase,
            tbl_productions_plan_bom.unit_parent_id as unit_parent_id,
            unit_parent.unit as unit_parent_name,
            tbl_productions_plan_bom.quantity_exchange as quantity_exchange,
            unit_stock.unit as unit_name_stock,
            tbl_materials.exchange_standard_unit as exchange_standard_unit,
            tbl_materials.exchange_unit as exchange_unit,
            1 as conversion_quantity_unit
        ', false);
        $this->db->from('tbl_productions_plan_bom');
        $this->db->join('tbl_materials', 'tbl_materials.id = tbl_productions_plan_bom.item_id');
        $this->db->join('tblunits', 'tblunits.unitid = tbl_materials.unit_id', 'left');
        $this->db->join('tblunits unit_parent', 'unit_parent.unitid = tbl_productions_plan_bom.unit_parent_id', 'left');
        $this->db->join('tblunits unit_stock', 'unit_stock.unitid = tbl_materials.standard_unit', 'left');
        $this->db->join($tbTransferWarehouse, 'tb_transfer_detail.id_items = tbl_productions_plan_bom.item_id', 'left');
        $this->db->join($tbPurchases, 'tb_purchases.product_id = tbl_productions_plan_bom.item_id', 'left');
        $this->db->join($tbProductionsPlanCompensation, 'tb_productions_plan_compensation.item_id = tbl_productions_plan_bom.item_id AND tb_productions_plan_compensation.item_type = tbl_productions_plan_bom.item_type', 'left');
        $this->db->where('tbl_productions_plan_bom.productions_plan_id', $productions_plan_id);
        $this->db->where_in('tbl_productions_plan_bom.item_type', ['materials']);
        $this->db->group_by('tbl_productions_plan_bom.item_id');
        $materials = $this->db->get()->result_array();
        $arrTemp = [];
        $arrayItems = array_merge($semi_product_outside, $materials);
        if (!empty($arrayItems)) {
            foreach ($arrayItems as $key => $value) {
                $item_id = $value['item_id'];
                $type_item = $value['item_type'];
                // $dtWarehouse = $this->getWarehousesLocationPlan($item_id, $type_item);
                $dtWarehouse = $this->getWarehousesLocationPlanNew($item_id, $type_item);
                $arrayItems[$key]['warehouses'] = $dtWarehouse['option'];
                $arrayItems[$key]['isWarehouses'] = $dtWarehouse['isWarehouses'];
                $arrayItems[$key]['idDefault'] = $dtWarehouse['idDefault'];
                $arrayItems[$key]['quantityDefault'] = $dtWarehouse['quantityDefault'];
                $arrayItems[$key]['arrWarehouses'] = $dtWarehouse['arrWarehouses'];
                if ($type_item == "products") {
                    $indexSemi = 'semi_products__'.$item_id;
                    if (!empty($arrQuantitySemiProduct[$indexSemi])) {
                        $arrayItems[$key]['quantity_primary'] = $arrQuantitySemiProduct[$indexSemi];
                    }
                } else if ($type_item == "materials") {
                    $tIndex = 'materials__'.$item_id;
                    $quantityWMaterial = !empty($materialBomSemiProduct[$tIndex]) ? $materialBomSemiProduct[$tIndex]['quantity'] : 0;
                    if (!empty($quantityWMaterial)) {
                        $arrayItems[$key]['quantity_primary'] = $arrayItems[$key]['quantity_primary'] - $quantityWMaterial;
                    }
                }

                if ($type_item == "products" && ($dtWarehouse['isWarehouses'] == '0' || empty($dtWarehouse['isWarehouses']))) {
                    continue;
                }

                $arrayItems[$key]['quantity_primary'] = round($arrayItems[$key]['quantity_primary'], 4);
                $arrTemp[] = $arrayItems[$key];
            }
        }

        $data['items'] = $arrTemp;
        echo json_encode($data);
    }

    public function getPurchasesGeneral()
    {
        $productions_plan_id = $this->db->escape($this->input->post('view_productions_plan_id'));
        $tbWarehouseProduct = "(
            SELECT
                tblwarehouse_items.id_items as id_items,
                SUM(tblwarehouse_items.product_quantity) as product_quantity
            FROM tblwarehouse_items
            WHERE tblwarehouse_items.type_items = 'product' AND tblwarehouse_items.warehouse_id != ".WAREHOUSES_CAPACITY."
            GROUP BY tblwarehouse_items.id_items
        ) tb_quantity_warehouse";

        $tbWarehouseMaterials = "(
            SELECT
                tblwarehouse_items.id_items as id_items,
                SUM(tblwarehouse_items.product_quantity) as product_quantity
            FROM tblwarehouse_items
            WHERE tblwarehouse_items.type_items = 'nvl' AND tblwarehouse_items.warehouse_id != ".WAREHOUSES_CAPACITY."
            GROUP BY tblwarehouse_items.id_items
        ) tb_quantity_warehouse";

        $tbTransfer = "(
            SELECT
                tbltransfer_warehouse_detail.type as type, 
                tbltransfer_warehouse_detail.id_items as id_items,
                SUM(tbltransfer_warehouse_detail.quantity_net) as quantity
            FROM tbltransfer_warehouse
            INNER JOIN tbltransfer_warehouse_detail ON tbltransfer_warehouse_detail.id_transfer = tbltransfer_warehouse.id
            WHERE tbltransfer_warehouse.productions_capacity_id = $productions_plan_id
            GROUP BY tbltransfer_warehouse_detail.type, tbltransfer_warehouse_detail.id_items
        ) tb_transfer";

        $tbImportToOrder = "(
            SELECT
                tblpurchase_to_order_items.id_items as id_items,
                tblpurchase_to_order_items.type as type,
                SUM(tblpurchase_to_order_items.quantyti_import) as quantity
            FROM tblpurchases
            INNER JOIN tblpurchase_to_order_items ON tblpurchase_to_order_items.id_purchase = tblpurchases.id
            WHERE tblpurchases.id_plan = $productions_plan_id
            GROUP BY tblpurchase_to_order_items.id_items, tblpurchase_to_order_items.type
        ) tb_import_to_order";

        $tbImportOrder = "(
            SELECT
                tblimport_items.product_id as product_id,
                tblimport_items.type as type,
                SUM(tblimport_items.quantity_net) as quantity
            FROM tblpurchases
            INNER JOIN tblpurchase_order ON tblpurchase_order.id_purchases like tblpurchases.id
            INNER JOIN tblimport ON tblimport.id_order = tblpurchase_order.id
            INNER JOIN tblimport_items ON tblimport_items.id_import = tblimport.id
            WHERE tblpurchases.id_plan = $productions_plan_id
            GROUP BY tblimport_items.product_id, tblimport_items.type
        ) tb_import_order";

        $tbProductionsPlanBom = "(
            (
                SELECT 
                    tbl_productions_plan_bom.item_id as item_id,
                    tbl_productions_plan_bom.id as id,
                    tbl_products.code as item_code,
                    tbl_products.name as item_name,
                    tbl_productions_plan_bom.item_type as item_type,
                    SUM(tbl_productions_plan_bom.quantity_primary + tbl_productions_plan_bom.quantity_compensation_primary + tbl_productions_plan_bom.quantity_compensation_sm_primary) as quantity_primary,
                    SUM(tbl_productions_plan_bom.quantity + tbl_productions_plan_bom.quantity_compensation + tbl_productions_plan_bom.quantity_compensation_sm) as quantity,
                    tblunits.unit as unit_name,
                    unit_primary.unit as unit_primary_name,
                    tb_quantity_warehouse.product_quantity as quantity_inventory,
                    tb_transfer.quantity as quantity_transfer,
                    (COALESCE(tb_import_to_order.quantity, 0) + COALESCE(tb_import_order.quantity, 0)) as quantity_import
                FROM tbl_productions_plan_bom
                INNER JOIN tbl_products ON tbl_products.id = tbl_productions_plan_bom.item_id
                LEFT JOIN tblunits ON tblunits.unitid = tbl_productions_plan_bom.unit_id
                LEFT JOIN tblunits unit_primary ON unit_primary.unitid = tbl_productions_plan_bom.unit_parent_id
                LEFT JOIN $tbWarehouseProduct ON tb_quantity_warehouse.id_items = tbl_productions_plan_bom.item_id
                LEFT JOIN $tbTransfer ON tb_transfer.id_items = tbl_products.id AND tb_transfer.type = 'product'
                LEFT JOIN $tbImportToOrder ON tb_import_to_order.id_items = tbl_products.id AND tb_import_to_order.type = 'product'
                LEFT JOIN $tbImportOrder ON tb_import_order.product_id = tbl_products.id AND tb_import_order.type = 'product'
                
                WHERE tbl_productions_plan_bom.productions_plan_id = $productions_plan_id AND tbl_productions_plan_bom.item_type IN ('semi_products_outside')
                GROUP BY tbl_productions_plan_bom.item_id
            )
            UNION ALL
            (
                SELECT 
                    tbl_productions_plan_bom.item_id as item_id,
                    tbl_productions_plan_bom.id as id,
                    tbl_materials.code as item_code,
                    tbl_materials.name as item_name,
                    tbl_productions_plan_bom.item_type as item_type,
                    SUM(tbl_productions_plan_bom.quantity_primary + tbl_productions_plan_bom.quantity_compensation_primary + tbl_productions_plan_bom.quantity_compensation_sm_primary) as quantity_primary,
                    SUM(tbl_productions_plan_bom.quantity + tbl_productions_plan_bom.quantity_compensation + tbl_productions_plan_bom.quantity_compensation_sm) as quantity,
                    tblunits.unit as unit_name,
                    unit_primary.unit as unit_primary_name,
                    tb_quantity_warehouse.product_quantity as quantity_inventory,
                    tb_transfer.quantity as quantity_transfer,
                    (COALESCE(tb_import_to_order.quantity, 0) + COALESCE(tb_import_order.quantity, 0)) as quantity_import
                FROM tbl_productions_plan_bom
                INNER JOIN tbl_materials ON tbl_materials.id = tbl_productions_plan_bom.item_id
                LEFT JOIN tblunits ON tblunits.unitid = tbl_productions_plan_bom.unit_id
                LEFT JOIN tblunits unit_primary ON unit_primary.unitid = tbl_productions_plan_bom.unit_parent_id
                LEFT JOIN $tbWarehouseMaterials ON tb_quantity_warehouse.id_items = tbl_productions_plan_bom.item_id
                LEFT JOIN $tbTransfer ON tb_transfer.id_items = tbl_materials.id AND tb_transfer.type = 'nvl'
                LEFT JOIN $tbImportToOrder ON tb_import_to_order.id_items = tbl_materials.id AND tb_import_to_order.type = 'nvl'
                LEFT JOIN $tbImportOrder ON tb_import_order.product_id = tbl_materials.id AND tb_import_order.type = 'nvl'
                WHERE tbl_productions_plan_bom.productions_plan_id = $productions_plan_id AND tbl_productions_plan_bom.item_type IN ('materials')
                GROUP BY tbl_productions_plan_bom.item_id
            )
        ) tb_cs";

        $aColumns = [
            'tb_cs.item_id as id',
            'tb_cs.item_code as item_code',
            'tb_cs.item_name as item_name',
            'tb_cs.quantity as quantity',
            'tb_cs.quantity_primary as quantity_primary',
            'tb_cs.quantity_transfer as quantity_transfer',
            'tb_cs.quantity_import as quantity_import',
            '(tb_cs.quantity_primary - COALESCE(tb_cs.quantity_transfer, 0) - tb_cs.quantity_import) as quantity_need',
            '"" as purchases_process',
        ];
        $sIndexColumn = 'tb_cs.item_id';
        $sTable       = $tbProductionsPlanBom;
        $where        = [
            'AND (COALESCE(tb_cs.quantity_primary, 0) - COALESCE(tb_cs.quantity_transfer, 0) - COALESCE(tb_cs.quantity_import, 0) - COALESCE(tb_cs.quantity_inventory, 0)) > 0'
        ];
        $filter = [];
        $join = [
        ];
        $result = data_tables_init($aColumns, $sIndexColumn, $sTable, $join, $where, [
            'tb_cs.unit_name as unit_name',
            'tb_cs.unit_primary_name as unit_primary_name',
            'tb_cs.item_type as item_type'
        ], '', [], ['union_all' => true]);

        $output = $result['output'];
        $rResult = $result['rResult'];
        $start = $this->input->post('start');
        $totalQuantity = 0;
        $totalQuantityPrimary = 0;
        $totalQuantityTransfer = 0;
        $totalQuantityImport = 0;
        $totalQuantityNeed = 0;
        foreach ($rResult as $key => $aRow) {
            $start++;
            $item_id = $aRow['id'];
            $item_type = $aRow['item_type'];

            $typePurchase = '';
            if ($item_type == 'materials') {
                $typePurchase = 'nvl';
            } else if ($item_type == 'tools_supplies') {
                $typePurchase = 'tools';
            } else{
                $typePurchase = 'product';
            }

            $row[0] = '<div class="text-center">'.$start.'</div>';
            $row[1] = $aRow['item_code'];
            $row[2] = $aRow['item_name'];
            $row[3] = '<div class="text-center">'.formatNumber($aRow['quantity']).' ('.$aRow['unit_name'].')'.'</div>';
            $row[4] = '<div class="text-center">'.formatNumber($aRow['quantity_primary']).' ('.$aRow['unit_primary_name'].')'.'</div>';
            $row[5] = '<div class="text-center">'.formatNumber($aRow['quantity_transfer']).'</div>';
            $row[6] = '<div class="text-center">'.formatNumber($aRow['quantity_import']).'</div>';
            $row[7] = '<div class="text-center">'.formatNumber($aRow['quantity_need']).' ('.$aRow['unit_primary_name'].')'.'</div>';

            $purchases = "(
                SELECT
                    tblpurchases.id,
                    GROUP_CONCAT(distinct tblpurchases.id) as purchase_id,
                    GROUP_CONCAT(distinct CONCAT(tblpurchases.prefix, '', tblpurchases.code)) as reference_no,
                    SUM(tblpurchases_items.quantity) as quantity
                FROM tblpurchases
                INNER JOIN tblpurchases_items ON tblpurchases_items.purchases_id = tblpurchases.id
                WHERE tblpurchases_items.type = '$typePurchase' AND tblpurchases_items.product_id = '$item_id' AND tblpurchases.id_plan = $productions_plan_id
            )";
            $dtPurchases = $this->db->query($purchases)->row_array();
            $quantityPurchase = $dtPurchases['quantity'];
            $isPurchases = ($dtPurchases['quantity'] > 0) ? 'active' : '';

            $isPurchaseOrder = '';
            $isImport = '';
            $quantityPurchaseOrder = 0;
            $quantityImport = 0;
            if ($isPurchases == "active") {
                $purchase_id = $dtPurchases['purchase_id'];
                $wherePurchasesOrder = [];
                if (!empty($purchase_id)) {
                    foreach (explode(',', $purchase_id) as $k => $val) {
                        $wherePurchasesOrder[] = "tblpurchase_order.id_purchases = '".$val."'";
                    }
                    $wherePurchasesOrder = ' AND ('.implode(' OR ', $wherePurchasesOrder).')';
                }
                // AND tblpurchase_order.id_purchases IN (".$purchase_id.")
                //Đi trực tiếp từ ycmh sang đặt hàng
                $purchases_order = "(
                    SELECT
                        tblpurchase_order.id,
                        GROUP_CONCAT(distinct tblpurchase_order.id) as purchase_order_id,
                        GROUP_CONCAT(distinct CONCAT(tblpurchase_order.prefix, '-', tblpurchase_order.code)) as reference_no,
                        SUM(tblpurchase_order_items.quantity_suppliers) as quantity
                    FROM tblpurchase_order
                    INNER JOIN tblpurchase_order_items ON tblpurchase_order_items.id_purchase_order = tblpurchase_order.id
                    WHERE tblpurchase_order_items.type = '$typePurchase' AND tblpurchase_order_items.product_id = '$item_id' $wherePurchasesOrder
                )";

                $dtPurchasesOrder = $this->db->query($purchases_order)->row_array();
                $quantityPurchaseOrder = $dtPurchasesOrder['quantity'];
                $isPurchaseOrder = ($dtPurchasesOrder['quantity'] > 0) ? 'active' : '';

                if (!empty($isPurchaseOrder)) {
                    $purchases_order_id = $dtPurchasesOrder['purchase_order_id'];
                    $import = "(
                        SELECT
                            tblimport.id,
                            GROUP_CONCAT(distinct tblimport.id) as purchase_order_id,
                            GROUP_CONCAT(distinct CONCAT(tblimport.prefix, '-', tblimport.code)) as reference_no,
                            SUM(tblimport_items.quantity_net) as quantity
                        FROM tblimport
                        INNER JOIN tblimport_items ON tblimport_items.id_import = tblimport.id
                        WHERE tblimport_items.type = '$typePurchase' AND tblimport_items.product_id = '$item_id' AND tblimport.id_order IN (".$purchases_order_id.")
                    )";
                    $dtImport = $this->db->query($import)->row_array();
                    $quantityImport = $dtImport['quantity'];
                    $isImport = ($dtImport['quantity'] > 0) ? 'active' : '';
                }

                //Đi qua gom hàng
                $purchaseToOrder = "(
                    SELECT
                        SUM(tblpurchase_to_order_items.quantity) as quantity_purchase_order,
                        SUM(tblpurchase_to_order_items.quantyti_import) as quantity_import
                    FROM tblpurchase_to_order_items
                    WHERE tblpurchase_to_order_items.type = '$typePurchase' AND tblpurchase_to_order_items.id_items = '$item_id' AND tblpurchase_to_order_items.id_purchase IN (".$purchase_id.")
                )";
                $dtPurchaseToOrder = $this->db->query($purchaseToOrder)->row_array();
                $quantityPurchaseOrder = (float)$quantityPurchaseOrder + (float)$dtPurchaseToOrder['quantity_purchase_order'];
                $quantityImport = (float)$quantityImport + (float)$dtPurchaseToOrder['quantity_import'];

                $isPurchaseOrder = ($quantityPurchaseOrder > 0) ? 'active' : '';
                $isImport = ($quantityImport > 0) ? 'active' : '';
            }

            $txtPurchase = $quantityPurchase > 0 ? 'SL: '.formatNumber($quantityPurchase) : '';
            $txtPurchaseOrders = $quantityPurchaseOrder > 0 ? 'SL: '.formatNumber($quantityPurchaseOrder) : '';
            $txtImport = $quantityImport > 0 ? 'SL: '.formatNumber($quantityImport) : '';
            $row[8] = '
                <ul class="progressbar" style="display: flex;">
                    <li class="'.$isPurchases.'">
                        <div>'.lang('YCMH').'</div>
                        <div class="">'.$txtPurchase.'</div>
                    </li>
                    <li class="'.$isPurchaseOrder.'">
                        <div>'.lang('ĐẶT HÀNG').'</div>
                        <div class="">'.$txtPurchaseOrders.'</div>
                    </li>
                    <li class="'.$isImport.'">
                        <div>'.lang('NHẬP HÀNG').'</div>
                        <div class="">'.$txtImport.'</div>
                    </li>
                </ul>
            ';

            $totalQuantity+= $aRow['quantity'];
            $totalQuantityPrimary+= $aRow['quantity_primary'];
            $totalQuantityTransfer+= $aRow['quantity_transfer'];
            $totalQuantityImport+= $aRow['quantity_import'];
            $totalQuantityNeed+= $aRow['quantity_need'];
            $output['aaData'][] = $row;
        }

        $output['totalQuantity'] = $totalQuantity;
        $output['totalQuantityPrimary'] = $totalQuantityPrimary;
        $output['totalQuantityTransfer'] = $totalQuantityTransfer;
        $output['totalQuantityImport'] = $totalQuantityImport;
        $output['totalQuantityNeed'] = $totalQuantityNeed;
        echo json_encode($output);
    }

