            $row[5] = '<div class="text-center"><a class="btn btn-success fa fa-file-pdf-o"  href="'.admin_url('transfer/print_transfer_nvl/').$transfer_id.'" target="_blank" style=""></a><span class="btn btn-danger fa fa-trash" onclick="deleteTransferToPlan('.$transfer_id.')" style="'.$styleDelete.'"></span></div>';
            $output['aaData'][] = $row;
        }
        echo json_encode($output);
