    public function deleteTransferToPlan() {
        if (!has_permission('transfer', '', 'delete')) {
            $data['result'] = 0;
            $data['message'] = lang('ch_no_delete');
            echo json_encode($data);
            die;
        }

        $data['result'] = 0;
        $data['message'] = lang('fail');

        $transfer_id = $this->input->post('transfer_id');
        $test_quantity = get_table_where('tblwarehouse_product', array('import_id' => $transfer_id, 'quantity_export >' => 0, 'type_export ' => 2), '', 'row');
        if (!empty($test_quantity)) {
            $data['result'] = 0;
            $data['message'] = lang('ch_quantity_export');
            echo json_encode($data);
            die;
        }
        if ($this->transfer_model->delete($transfer_id)) {
            $data['result'] = 1;
            $data['message'] = lang('success');
        }
        echo json_encode($data);
    }

