    {
        $productions_plan_id = $this->db->escape($this->input->post('view_productions_plan_id'));

        // $tbPurchaseToOrder = "(
        //     SELECT
        //         tblpurchase_to_order_items.id_purchase as id_purchase,
        //         count(tblpurchase_to_order_items.id) as ct_purchase_to_order,
        //         SUM(IF (tblpurchase_to_order_items.quantyti_import > 0), 1, 0) as sum_import
        //     FROM tblpurchase_to_order_items
        //     GROUP BY tblpurchase_to_order_items.id_purchase
        // ) tb_purchase_to_order";

        $aColumns = [
            'tblpurchases.id as id',
            'tblpurchases.date as date',
            'CONCAT(tblpurchases.prefix, "", tblpurchases.code) as reference_no',
            'tblpurchases.status as status',
