            // '<a class="tnh-modal" data-tnh="modal" href="'.base_url('admin/manufactures/view_productions_orders/'.$productions_orders_id).'" data-toggle="modal" data-target="#myModal">
            //     '.$aRow['reference_no'].
            // '</a>

