            $labelOptions1 = '';
            if ($options1) {
                $labelOptions1 = '<div><span data-toggle="tooltip" data-html="true" title="'.$refereceNoOrders.'" class="label label-primary pointer">'.lang('tnh_sales_orders').' ['.$countReferenceOrders.'] '.lang('tnh_single').'</span></div>';
            }
            $labelOptions2 = '';
            if ($options2) {
                $labelOptions2 = '<div class="'.(!empty($labelOptions1) ? 'mtop10' : '').'"><span data-toggle="tooltip" data-html="true" title="'.$refereceNoBusiness.'" class="label label-warning pointer">'.lang('tnh_business_plan').' ['.$countReferenceBusiness.'] '.lang('tnh_single').'</span></div>';
            }
           
            $row[4] = $labelOptions1.''.$labelOptions2;
            $this->db->where('productions_orders_id', $productions_orders_id);
            $this->db->join('tbl_productions_orders_details', 'tbl_productions_orders_details.id = tblorder_production_details_feedback.id_order_production_details');
            $quantitycomment = $this->db->count_all_results('tblorder_production_details_feedback');
