                <div>
                    <img class="images-detail" src="'.base_url('assets/img_menu/r1.png').'">
                    <span class="vertical-align-bottom">'.lang('quantity').': '.formatNumber($aRow['total_quantity']).'</span>
                </div>
                <div class="mtop5">
                    <img class="images-detail" src="'.base_url('assets/img_menu/comment.png').'">
                    <span class="vertical-align-bottom">'.lang('comment_string').': '.formatNumber((!empty($quantitycomment) ? $quantitycomment : 0)).'</span>
                </div>
            ';

            $row[5] = '<div class="text-center">'.formatNumber($aRow['total_quantity']).'</div>';
            $row[6] = $aRow['note'];
            $row[7] = '';

            $view = '<a class="tnh-modal" title="' . lang('view') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/view_productions_orders/'.$productions_orders_id) . '"><i class="fa fa-file-text-o width-icon-actions"></i> ' . lang('view') . '</a>';

            $created_productions_detail = $this->perAddProductionsOrders ? '<a onclick="createdProductionsDetail(\''.$productions_orders_id.'\')"  title="' . lang('created_productions_detail') . '" href="javascript:void(0)"><i class="fa fa-plus width-icon-actions"></i> ' . lang('created_productions_detail') . '</a>' : '';

            $deleted_productions_detail = $this->perDeleteProductionsOrders ? '<a type="button" data-toggle="popover" class="po-delete delete-detail" title="' . lang('delete') . '" data-container="body" data-html="true" data-placement="left" data-content="
                <button href=\'' . base_url('admin/manufactures/delete_productions_orders_detail/'.$productions_orders_id) . '\' class=\'btn btn-danger po-delete-json\'>' . lang('delete') . '</button>
                <button class=\'btn btn-default po-close-new\'>' . lang('close') . '</button>
            "><i class="fa fa-remove width-icon-actions"></i> ' . lang('tnh_delete_productions_order_detail') . '</a>' : '';

            if ($status_details == 1) {
                $created_productions_detail = '';
            } else {
                $deleted_productions_detail = '';
            }

            $print = '<a href="' . base_url('admin/manufactures/print_productions_orders_new/'.$productions_orders_id) . '" target="_blank"><i class="fa fa-print"></i> ' . lang('In LSX tổng') . '</a>';

            $print_detail = '<a href="' . base_url('admin/manufactures/print_productions_orders_detail_new/'.$productions_orders_id) . '" target="_blank"><i class="fa fa-print"></i> ' . lang('In chi tiết LSX') . '</a>';


            $excel_detail = '<a href="'.base_url('admin/manufactures/excel_productions_orders_detail/'.$productions_orders_id).'"><i class="fa fa-file-text-o"></i> '.lang('Excel chi tiết LSX').'</a>';

            $delete = $this->perDeleteProductionsOrders ? '<a type="button" class="po" title="' . lang('delete') . '" data-container="body" data-html="true" data-toggle="popover" data-placement="left" data-content="
                <button href=\'' . base_url('admin/manufactures/delete_productions_orders/'.$productions_orders_id) . '\' class=\'btn btn-danger po-delete-json\'>' . lang('delete') . '</button>
                <button class=\'btn btn-default po-close\'>' . lang('close') . '</button>
            "><i class="fa fa-remove width-icon-actions"></i> ' . lang('delete') . '</a>' : '';

            $handlingEndPO = '<a href="javascript:void(0)" onclick="handlingEndPO(\''.$productions_orders_id.'\', 1)"><i class="fa fa-pencil"></i> '.lang('tnh_end_production').'</a>'; 
            if(!empty($aRow['status_orders'])) {
                $handlingEndPO = '<a href="javascript:void(0)" onclick="handlingEndPO(\''.$productions_orders_id.'\', 0)"><i class="fa fa-trash-o"></i> '.lang('tnh_un_end_production').'</a>';
            }

            $delivery = '<a class="tnh-modal" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="'.base_url('admin/manufactures/add_delivery/'.$productions_orders_id).'"><i class="fa fa-plus"></i> '.lang('tnh_add_delivery').'</a>';
            // <li>' . $delivery . '</li>

            $prepare_materials = '<a class="tnh-modal" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="'.base_url('admin/manufactures_temp/prepare_materials/'.$productions_orders_id).'"><i class="fa fa-file-text-o"></i> '.lang('tnh_exporting_stock_producion').'</a>';

            $finished_stages = '<a class="tnh-modal" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="'.base_url('admin/manufactures_temp/finished_stages/'.$productions_orders_id).'"><i class="fa fa-check"></i> '.lang('Hoàn thành công đoạn').'</a>';

            $add_task = $this->perAddProductionsOrders ? '<a href="javascript:void(0)" onclick="new_task(\''.base_url('admin/tasks/task?po_id=' . $productions_orders_id).'\'); return false;"><i class="fa fa-plus"></i> ' . lang('Tạo công việc') . '</a>' : '';

            //items
            // $productions_orders_id
            $statusAuto = 1;
            $isNotProducedYet = 0;
            $isProduction = 0;
            $isFinished = 0;
            $isCancel = 0;
            $this->db->select('
            tbl_productions_orders_items.productions_orders_id as productions_orders_id,
                tbl_productions_orders_items.id as id,
                tbl_products.code as item_code,
                tbl_products.name as item_name,
                tbl_products.images as images,
                tbl_productions_orders_items.quantity,
                tbl_productions_orders_items.object_item_type as object_item_type,
                tbl_productions_orders_items.production_plan_item_id as production_plan_item_id,
                tbl_productions_orders_details.id as pod_id,
                tbl_productions_orders_details.price_costing as price_costing,
                tbl_productions_orders_items.versions_stage as versions_stage
            ');
            $this->db->from('tbl_productions_orders_items');
            $this->db->join('tbl_products', 'tbl_products.id = tbl_productions_orders_items.items_id');
            $this->db->join('tbl_productions_orders_details', 'tbl_productions_orders_details.productions_orders_item_id = tbl_productions_orders_items.id', 'left');
            $this->db->where('tbl_productions_orders_items.productions_orders_id', $productions_orders_id);
            $productions_orders_items = $this->db->get()->result_array();
            if (!empty($productions_orders_items)) {
                foreach ($productions_orders_items as $k => $v) {
                    $object_item_type = $v['object_item_type'];
                    $production_plan_item_id = $v['production_plan_item_id'];
                    $productions_orders_items_id = $v['id'];
                    $reference_no = '';
                    if ($object_item_type == "orders") {
                        $this->db->select('
                            tbl_orders.reference_no as reference_no,
                            tblclients.company as company
                        ');
                        $this->db->from('tbl_order_items');
                        $this->db->join('tbl_orders', 'tbl_orders.id = tbl_order_items.order_id');
                        $this->db->join('tblclients', 'tblclients.userid = tbl_orders.customer_id');
                        $this->db->where('tbl_order_items.id', $production_plan_item_id);
                        $order = $this->db->get()->row_array();
                        if (!empty($order)) {
                            $reference_no = $order['reference_no'].' - '.$order['company'];
                        }
                    } else if ($object_item_type == "business_plan") {
                        $this->db->select('
                            tbl_business_plan.reference_no as reference_no,
                        ');
                        $this->db->from('tbl_business_plan_items');
                        $this->db->join('tbl_business_plan', 'tbl_business_plan.id = tbl_business_plan_items.business_plan_id');
                        $this->db->where('tbl_business_plan_items.id', $production_plan_item_id);
                        $business_plan = $this->db->get()->row_array();
                        if (!empty($business_plan)) {
                            $reference_no = $business_plan['reference_no'];
                        }
                    }
                    $productions_orders_items[$k]['reference_no'] = $reference_no;


					$productions_orders_items[$k]['staff_promotion'] = $this->db->get_where('tbl_productions_orders_detail_staff', ['productions_detail_id' => $productions_orders_items_id])->result_array();
					if(!empty($productions_orders_items)) {
						foreach ($productions_orders_items[$k]['staff_promotion'] as $kstaff => $vstaff) {
							$productions_orders_items[$k]['staff_promotion'][$kstaff]['fullname'] = get_staff_full_name($vstaff['staff_id']);
							$productions_orders_items[$k]['staff_promotion'][$kstaff]['avatar'] = staff_profile_image($vstaff['staff_id'], array('staff-profile-image-small'), 'small', array(
								'data-toggle' => 'tooltip',
								'data-title' => $productions_orders_items[$k]['staff_promotion'][$kstaff]['fullname']
							));
						}
					}

                    $this->db->select('
                        tbl_suggest_exporting.id as id,
                        tbl_suggest_exporting.date as date,
                        CONCAT(tblstaff.firstname, "", tblstaff.lastname) as created_name
                    ', false);
                    $this->db->from('tbl_suggest_exporting');
                    $this->db->join('tblstaff', 'tblstaff.staffid = tbl_suggest_exporting.created_by', 'left');
                    $this->db->where('tbl_suggest_exporting.type', 2);
                    $this->db->where('tbl_suggest_exporting.po_id', $productions_orders_id);
                    $this->db->order_by('tbl_suggest_exporting.date DESC');
                    $this->db->limit(1);
                    $suggest_exporting = $this->db->get()->row_array();
                    $liSuggE = '';
                    if (!empty($suggest_exporting)) {
                        $liSuggE = '<li class="active" style="color: orange;"> Xuất bổ sung
                        <p class="active_poin"> Được ' . $suggest_exporting['created_name'] . ' hoàn thành vào lúc: ' . _dt($suggest_exporting['date']). '</p>
                        </li>';
                    }

                    //process
                    $this->db->select('
                        tbl_productions_orders_items_stages.id as id,
                        tbl_productions_orders_items_stages.active as active,
                        tbl_productions_orders_items_stages.staff_active as staff_active,
                        tbl_productions_orders_items_stages.date_active as date_active,
                        tbl_stages.name as stage_name,
                        CONCAT(tblstaff.firstname, " ", tblstaff.lastname) as staff_name,
                        IF (tblstaff.profile_image IS NOT NULL, CONCAT("'.base_url('uploads/staff_profile_images/').'", tblstaff.staffid, "/small__", tblstaff.profile_image), null) as staff_image,
                        tbl_productions_orders_items_stages.final_stage as final_stage
                    ', false);
                    $this->db->from('tbl_productions_orders_items_stages');
                    $this->db->join('tbl_stages', 'tbl_stages.id = tbl_productions_orders_items_stages.stage_id');
                    $this->db->join('tblstaff', 'tblstaff.staffid = tbl_productions_orders_items_stages.staff_active', 'left');
                    $this->db->where('tbl_productions_orders_items_stages.productions_orders_items_id', $productions_orders_items_id);
                    $this->db->order_by('tbl_productions_orders_items_stages.number ASC');
                    $process = $this->db->get()->result_array();
                    $workflow = '';
                    $li = '';
                    $isActive = 0;
                    $countPro = count($process);
                    if (!empty($process)) {
                        foreach ($process as $kkk => $vvv) {
                            if (!empty($vvv['active'])) {
                                $isActive = $vvv['active'];
                            }

                            if ($kkk == 1) {
                                $li.= $liSuggE;
                            }


                            $li .= '<li ' . ($vvv['active'] ? 'class="active"' : '') . '>' . $vvv['stage_name'] .
                                (!empty($vvv['staff_active']) ? ('<p class="active_poin">' . ('Được ' . get_staff_full_name($vvv['staff_active']) . ($vvv['date_active'] ? ' hoàn thành vào lúc: ' . _dt($vvv['date_active']) : '')) . '</p>') : '')
                                . '</li>';

                            if ($countPro == 1) {
                                $li.= $liSuggE;
                            }


                            if ($kkk == 1 && empty($vvv['active'])) {
                                $isNotProducedYet = 1;
                            }

                            if (!empty($vvv['active']) && empty($vvv['pois_id'])) {
                                $isProduction = 1;
                            }

                            if ($vvv['final_stage'] && empty($vvv['active'])) {
                                $isFinished = 1;
                            }
                        }
                    } else {
                        $li = $liSuggE;
                    }
                    $workflow .= '<div style="display: table; justify-content: center;">
                        <ul class="progressbar" style="display: flex;">
                        ' . $li . '
                        </ul>
                    </div>';

                    if (empty($isActive) && empty($liSuggE)) {
                        $workflow = '</br><div style="width: 250px;" class="text-danger text-left italic tag-not-stage">'.lang('tnh_chua_thuc_hien_san_xuat').'</div>';
                    }
                    $productions_orders_items[$k]['workflow'] = $workflow;
                }
            }
            $row[11] = $productions_orders_items;

			$Pause = '0';
			$strStatus = '';
			$status_orders = $aRow['status_orders'];
			if (!empty($status_orders)) {
				if($status_orders == 1) {
					$strStatus = '<span class="label label-danger">' . lang('Kết thúc sản xuất') . '</span>';
				}
				if($status_orders == 2) {
					$strStatus = '<span class="label label-danger">' . lang('Đang tạm dừng sản xuất') . '</span>';
					$Pause = '2';
				}
			} else if (!$isFinished) {
				$strStatus = '<span class="label label-success">'.lang('Hoàn thành').'</span>';
				$Pause = '1';
			} else if (!empty($isProduction)) {
				$strStatus = '<span class="label label-primary">'.lang('Đang sản xuất').'</span>';

			} else {
				$strStatus = '<span class="label label-warning">'.lang('Chưa sản xuất').'</span>';
				$Pause = '1';
			}
            $row[7] = '<div class="text-center">'.$strStatus.'</div>';
			$row[8] =  '<div class="text-center">'.$aRow['location_name'].'</div>';

            //status gdsx
            $strGDSX = '';
            $status_gdsx = $aRow['status_gdsx'];
            if ($status_gdsx == 1) {
                $strGDSX = '<div class="text-left"><span data-html="true" data-toggle="popover" data-container="body" data-placement="left" style="cursor: pointer;" title="'. lang('tnh_agree') .'" data-content="<p><a id=\'agree\' po_id=\''.$productions_orders_id.'\' value=\'0\' class=\'btn btn-danger\'>'.lang('Bỏ xác nhận').'</a><button class=\'btn po-close\'>'.lang('close').'</button></p>" class="label label-success po">'.lang('Đã xác nhận').'</span></div>';
            } else {
                $strGDSX = '<div class="text-left"><span data-html="true" data-toggle="popover" data-container="body" data-placement="left" style="cursor: pointer;" title="'. lang('tnh_agree') .'" data-content="<p><a id=\'agree\' po_id=\''.$productions_orders_id.'\' value=\'1\' class=\'btn btn-success\'>'.lang('Xác nhận').'</a><button class=\'btn po-close\'>'.lang('close').'</button></p>" class="label label-danger po">'.lang('Chưa xác nhận').'</span></div>';
            }
            $row[9] = $strGDSX;

			$optionPause = '';
			if(!empty($Pause)) {
				if ($Pause == 1) {
					$optionPause = '<li><a onclick="handPause(\''.$productions_orders_id.'\', 2)"><i class="fa fa-pause" aria-hidden="true"></i> Tạm dừng SX</a></li>';
				}
				else if ($Pause == 2) {
					$optionPause = '<li><a onclick="handPause(\''.$productions_orders_id.'\', 0)"><i class="fa fa-play" aria-hidden="true"></i> Tiếp tục sản xuất</a></li>';
					$handlingEndPO = '';
				}
			}

            $moderation_criteria = '<a class="tnh-modal" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="'.base_url('admin/manufactures_temp/moderation_criteria/'.$productions_orders_id).'"><i class="fa fa-check"></i> '.lang('Tiêu chí điều độ').'</a>';

			$actions = '
            <div class="dropdown text-center">
                <button class="btn btn-primary dropdown-toggle nav-link" type="button" id="dropdownMenu1" data-toggle="dropdown" aria-expanded="true">
                ' . lang('actions') . '
                <span class="caret"></span>
                </button>
                <ul class="dropdown-menu pull-right" role="menu" aria-labelledby="dropdownMenu1" style="width: 190px;">
                    <li>' . $print . '</li>
                    <li>' . $print_detail . '</li>
                    <li>' . $excel_detail . '</li>
                    <li>' . $prepare_materials . '</li>
                    <li>' . $finished_stages . '</li>
                    <li>' . $handlingEndPO . '</li>
                    <li>' . $moderation_criteria . '</li>
                    ' . $optionPause . '
                    <li>'.$add_task.'</li>
                    <li class="not-outside">' . $delete . '</li>
                </ul>
            </div>';

			$row[10] = $actions;


            $output['aaData'][] = $row;

            $total_quantity+= $aRow['total_quantity'];
        }
        $output['total_quantity'] = $total_quantity;
        echo json_encode($output);
    }

    public function createdProductionsDetail() {
        $productions_orders_id = $this->input->post('productions_orders_id');
        $data = $this->manufactures_model->handlingProductionsDetail($productions_orders_id);
        echo json_encode($data);
    }

    public function detail_productions_orders($id) {
        if (!$this->perViewProductionsOrders && !$this->perViewOwnProductionsOrders) {
            accessDenied();
        }

        $data = [];
        $branch_staff = get_array_branch_staff();
        $is_admin = is_admin();
        $where = null;
        if (!$is_admin) {
            if (empty($branch_staff)) $branch_staff = [0];
            $where.= 'tbl_productions_orders.location_id IN ('.implode(',', $branch_staff).')';
        }
        $productions_orders = $this->manufactures_model->rowProductionsOrdersById($id, $where);
        if (empty($productions_orders)) {
            set_alert('danger', lang('no_data_exists'));
            redirect($_SERVER["HTTP_REFERER"]);
            die;
        }

        $tbProductionsPlanOrdersByOrders = "(
            SELECT
                tbl_orders.reference_no as reference_no,
                tblclients.company as company
            FROM tbl_productions_plan_orders
            INNER JOIN tbl_orders ON tbl_orders.id = tbl_productions_plan_orders.productions_plan_id
            INNER JOIN tblclients ON tblclients.userid = tbl_orders.customer_id
            WHERE tbl_productions_plan_orders.object_type = 'orders' AND tbl_productions_plan_orders.productions_order_id = ".$this->db->escape($id)."
        )";
        $orders = $this->db->query($tbProductionsPlanOrdersByOrders)->result_array();

        $tbProductionsPlanOrdersByBusinessPlan = "(
            SELECT
                tbl_business_plan.reference_no as reference_no
            FROM tbl_productions_plan_orders
            INNER JOIN tbl_business_plan ON tbl_business_plan.id = tbl_productions_plan_orders.productions_plan_id
            WHERE tbl_productions_plan_orders.object_type = 'business_plan' AND tbl_productions_plan_orders.productions_order_id = ".$this->db->escape($id)."
        )";
        $business_plan = $this->db->query($tbProductionsPlanOrdersByBusinessPlan)->result_array();
        
        $data['id'] = $id;
        $data['branch'] = $this->site_model->getBranchById($productions_orders['location_id']);
        $data['orders'] = $orders;
        $data['business_plan'] = $business_plan;
        $data['created_by'] = get_staff_full_name($productions_orders['created_by']);
        $data['productions_orders'] = $productions_orders;
        $data['title'] = lang('tnh_detail_productions_orders');
        $data['breadcrumb'] = [array('link' => base_url('admin/manufactures/productions_orders'), 'page' => lang('productions_orders')), array('link' => '#', 'page' => $data['title'])];
        $this->load->view('admin/manufactures/detail_productions_orders', $data);
    }

