            $row[1] = 'group';
            $row[2] = $start.'.'.$strReferenceNo;
            $row[3] = $strObject;
            $row[4] = '';
            $row[5] = '';
            $output['aaData'][] = $row;

            if ($productions_plan_id) {
                $this->db->select('
