    public function getProductionsOrdersDetailsNew() {
        if (!$this->perViewOPD && !$this->perViewOwnOPD) {
            accessDenied($js = true);
        }

        $isAdmin = is_admin();
        $branch_staff = get_array_branch_staff();
        $is_admin = $isAdmin;

        $status_table = $this->input->post('status_table');
        $productions_orders_search = $this->input->post('productions_orders_search');
        $start_date_search = $this->input->post('start_date_search');
        $end_date_search = $this->input->post('end_date_search');
        $items_search = $this->input->post('items_search');
        $status_table = $this->input->post('status_table');

        $tbStatus = "(
            SELECT
                tbl_productions_orders_items_stages.productions_orders_items_id as productions_orders_items_id,
                MAX(tbl_stages.name) as stage_name,
                MAX(tbl_stages.id) as stage_id,
                MAX(tbl_productions_orders_items_stages.final_stage) as final_stage,
                MAX(tbl_productions_orders_items_stages.number) as number
            FROM tbl_productions_orders_items_stages
            INNER JOIN tbl_stages ON tbl_stages.id = tbl_productions_orders_items_stages.stage_id
            WHERE tbl_productions_orders_items_stages.active = 1
            GROUP BY tbl_productions_orders_items_stages.productions_orders_items_id
            ORDER BY tbl_productions_orders_items_stages.active DESC, MAX(tbl_productions_orders_items_stages.number) DESC
        ) tb_status";

        $tbStatus = "(
            SELECT
                tb_cs.productions_orders_items_id as productions_orders_items_id,
                tb_cs.final_stage as final_stage,
                tb_cs.number as number,
                (tbl_stages.name) as stage_name,
                (tbl_stages.id) as stage_id
            FROM (
                SELECT
                    tbl_productions_orders_items_stages.productions_orders_items_id as productions_orders_items_id,
                    MAX(tbl_productions_orders_items_stages.id) as id,
                    MAX(tbl_productions_orders_items_stages.final_stage) as final_stage,
                    MAX(tbl_productions_orders_items_stages.number) as number
                FROM tbl_productions_orders_items_stages
                WHERE tbl_productions_orders_items_stages.active = 1
                GROUP BY tbl_productions_orders_items_stages.productions_orders_items_id
                ORDER BY tbl_productions_orders_items_stages.active DESC, MAX(tbl_productions_orders_items_stages.number) DESC
            ) tb_cs
            INNER JOIN tbl_productions_orders_items_stages ON tb_cs.id = tbl_productions_orders_items_stages.id
            INNER JOIN tbl_stages ON tbl_stages.id = tbl_productions_orders_items_stages.stage_id
        ) tb_status";

        $tbOrders = "(
            SELECT
                tbl_orders.id as object_id,
                tbl_orders.reference_no as reference_no,
                tblclients.company as company,
                tbl_orders.date as date
            FROM tbl_orders
            INNER JOIN tblclients ON tblclients.userid = tbl_orders.customer_id
            WHERE tbl_orders.status_productions_orders != 0
        ) tb_orders";

        $tbBusinessPlan = "(
            SELECT
                tbl_business_plan.id as object_id,
                tbl_business_plan.reference_no reference_no
            FROM tbl_business_plan
            WHERE tbl_business_plan.status_productions_orders != 0
        ) tb_business_plan";

        $priceMaterial = "(
            SELECT
                tbl_suggest_exporting.productions_orders_details_id as pod_id,
                SUM(tbl_suggest_exporting.grand_total) as grand_total
            FROM tbl_suggest_exporting
            WHERE tbl_suggest_exporting.reference_stock IS NOT NULL AND tbl_suggest_exporting.grand_total > 0 
            GROUP BY tbl_suggest_exporting.productions_orders_details_id
        ) tb_price_material";

        $payslips = "(
            SELECT
                tblother_payslips.vouchers_id as pod_id,
                SUM(tblother_payslips.total) as grand_total
            FROM tblother_payslips
            WHERE tblother_payslips.type_vouchers = 9
            GROUP BY tblother_payslips.vouchers_id
        ) tb_payslips";

        $purchaseInternal = "(
            SELECT
                tbl_purchase_internal.pod_id as pod_id,
                SUM(tbl_purchase_internal.grand_total) as grand_total
            FROM tbl_purchase_internal
            WHERE tbl_purchase_internal.grand_total > 0
            GROUP BY tbl_purchase_internal.pod_id
        ) tb_purchase_internal";

        $selectCost = "(COALESCE(tb_price_material.grand_total, 0) + COALESCE(tb_payslips.grand_total, 0) - COALESCE(tb_purchase_internal.grand_total, 0))";
        if (!$isAdmin) {
            $selectCost = 0;
        }

        $aColumns = [
            'tbl_productions_orders_details.id as id',
            '"0" as numbers',
            'tbl_productions_orders.reference_no as reference_no_order',
            'tbl_productions_orders_details.reference_no as reference_no',
            'CONCAT(COALESCE(tbl_products.images, ""), "||", tbl_products.code) as item_name',
            'tbl_productions_orders_details.quantity_warehoused as quantity_finished',
            'tbl_stages.name as status',
            ''.$selectCost.' as total_cost',
            '"" as actions'
        ];
        $sIndexColumn = 'id';
        $sTable       = 'tbl_productions_orders_details';
        $where        = [

        ];
        $filter = [];
        
        $join = [
            'INNER JOIN tbl_productions_orders_items ON tbl_productions_orders_items.id = tbl_productions_orders_details.productions_orders_item_id',
            'INNER JOIN tbl_productions_orders ON tbl_productions_orders.id = tbl_productions_orders_items.productions_orders_id',
            'INNER JOIN tbl_products ON tbl_products.id = tbl_productions_orders_items.items_id',
            'LEFT JOIN '.$tbStatus.' ON tb_status.productions_orders_items_id = tbl_productions_orders_items.id',
            'LEFT JOIN tbl_stages ON tbl_stages.id = tb_status.stage_id',
            'LEFT JOIN tblbranch ON tbl_productions_orders.location_id  = tblbranch.id',
            'LEFT JOIN '.$tbOrders.' ON tb_orders.object_id  = tbl_productions_orders_details.object_id AND tbl_productions_orders_details.object_type = "orders"',
            'LEFT JOIN '.$tbBusinessPlan.' ON tb_business_plan.object_id  = tbl_productions_orders_details.object_id AND tbl_productions_orders_details.object_type = "business_plan"',
        ];

        if ($isAdmin) {
            array_push($join, "LEFT JOIN $priceMaterial ON tb_price_material.pod_id = tbl_productions_orders_details.id");
            array_push($join, "LEFT JOIN $payslips ON tb_payslips.pod_id = tbl_productions_orders_details.id");
            array_push($join, "LEFT JOIN $purchaseInternal ON tb_purchase_internal.pod_id = tbl_productions_orders_details.id");
        }

        if (!empty($productions_orders_search)) {
            array_push($where, "AND tbl_productions_orders_details.productions_orders_id = ".$this->db->escape($productions_orders_search));
        }

        if (!empty($status_table)) {
            if ($status_table == 1) {
            } else if ($status_table == 2) {
                array_push($where, 'AND tbl_productions_orders_details.status = "un_produced"');
            } else if ($status_table == 3) {
                array_push($where, 'AND tbl_productions_orders_details.quantity_warehoused > 0');
            } else if ($status_table == 4) {
                array_push($where, 'AND (tbl_productions_orders_details.status != "complete_production" && DATEDIFF(tbl_productions_orders_details.deadline, now()) < 0)');
            } else if ($status_table == 5) {
                array_push($where, 'AND tbl_productions_orders_details.status = "complete_production"');
            }
        }

        if (!empty($items_search)) {
            $arrItem = explode('__', $items_search);
            $item_id = $arrItem[0];
            array_push($where, 'AND tbl_productions_orders_items.items_id = "'.$item_id.'"');
        }

        if (!empty($start_date_search)) {
            $start_date_search = to_sql_date($start_date_search). ' 00:00:00';
            array_push($where, "AND tbl_productions_orders_details.date_created >= '$start_date_search'");
        }

        if (!empty($end_date_search)) {
            $end_date_search = to_sql_date($end_date_search). ' 23:59:59';
            array_push($where, "AND tbl_productions_orders_details.date_created <= '$end_date_search'");
        }

        if (!$is_admin) {
            if (empty($branch_staff)) $branch_staff = [0];
            array_push($where, 'AND tbl_productions_orders.location_id IN ('.implode(',', $branch_staff).')');
        }

        $result = data_tables_init($aColumns, $sIndexColumn, $sTable, $join, $where, [
            'tblbranch.name as branch_name',
            'tbl_productions_orders_details.object_type as object_type',
            'tb_orders.reference_no as reference_no_orders',
            'tb_orders.company as company',
            'tb_business_plan.reference_no as reference_no_business_plan',
            'tbl_productions_orders_items.quantity as quantity',
            'tb_status.final_stage as final_stage',
            'tb_status.number as number',
            'tbl_productions_orders_items.id as poi_id'
        ], '', []);
        

        $output = $result['output'];
        $rResult = $result['rResult'];
        $start = $this->input->post('start');
        $totalQuantity = 0;
        $totalQuantityFinished = 0;
        $totalCost = 0;
        foreach ($rResult as $key => $aRow) {
            $start++;
            $poi_id = $aRow['poi_id'];
            $maxStages = "(
                SELECT
                    MAX(tbl_productions_orders_items_stages.number) as number
                FROM tbl_productions_orders_items_stages
                INNER JOIN tbl_stages ON tbl_stages.id = tbl_productions_orders_items_stages.stage_id
                WHERE tbl_productions_orders_items_stages.productions_orders_items_id = '$poi_id'
            )";
            $max = $this->db->query($maxStages)->row_array()['number'];
            $number = $aRow['number'];
            $percent = 0;
            if ($max > 0) {
                $percent = $number/$max *100;
            }
            $txtReferenceObject = '';
            if ($aRow['object_type'] == "orders") {
                $txtReferenceObject = '<div class="bold">'.$aRow['reference_no_orders'].' - '.$aRow['company'].'</div>';
            } else if ($aRow['object_type'] == "business_plan") {
                $txtReferenceObject = '<div class="bold">'.$aRow['reference_no_business_plan'].'</div>';
            }

            $productions_orders_details_id = $aRow['id'];
            $row[0] = $productions_orders_details_id;
            $row[1] = '<div class="text-center">'.$start.'</div>';
            $row[2] = $aRow['reference_no_order'];
            $row[3] = $aRow['reference_no'].'<div class="italic" style="color: #323a45;">'.$aRow['branch_name'].'</div>';
            $row[4] = $aRow['item_name'].'___'.$txtReferenceObject.'___'.$aRow['quantity'].'___'.$percent;
            $row[5] = $aRow['quantity_finished'];

            $final_stage = $aRow['final_stage'];
            $divFinised = '';
            if ($final_stage) {
                $divFinised = '<div class="panel-finished" style="margin: auto;">
                    <div class="">'.lang('tnh_finished_production').'</div>
                </div>';
            }
//            $row[6] = !empty($aRow['status']) ? '
//                <div class="text-left" style="width: 180px; position: relative;">
//                    <span class="dot-cs"></span>
//                    <div style="margin-left: 10px;">'.$aRow['status'].'</div>
//                    '.$divFinised.'
//                </div>' : '<div class="text-danger text-left italic tag-not-stage" style="width: 180px;">'.lang('Chưa thực hiện sản xuất').'</div>';
            $row[6] = !empty($aRow['status']) ? $aRow['status'] : lang('Chưa thực hiện sản xuất');
            $row[7] = $aRow['total_cost'];

            $totalQuantity+= $aRow['quantity'];
            $totalQuantityFinished+= $aRow['quantity_finished'];
            $totalCost+= $aRow['total_cost'];

            $detail = '<a class="" title="' . lang('tnh_detail') . '" target="_blank" href="' . base_url('admin/manufactures/detail_productions/'.$productions_orders_details_id) . '"><i class="fa fa-file-text-o width-icon-actions" ></i> ' . lang('tnh_detail') . '</a>';

            $warehousing = '<a class="tnh-modal tnh-warehousing" title="' . lang('tnh_warehousing') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/addWarehousing/'.$productions_orders_details_id) . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('tnh_warehousing') . '</a>';

            $purchaseInternal = '<a class="tnh-modal tnh-purchase-internal" title="' . lang('tnh_add_purchase_internal') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/purchaseInternal/'.$productions_orders_details_id) . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('tnh_add_purchase_internal') . '</a>';

            $checkQuality = '<a class="tnh-modal tnh-check-quality" title="' . lang('check_quality') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/checkQuality/'.$productions_orders_details_id) . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('check_quality') . '</a>';

            $print = '<a href="' . base_url('admin/manufactures/print_productions_orders_detail/'.$productions_orders_details_id) . '" target="_blank"><i class="fa fa-print"></i> ' . lang('print_vote') . '</a>';

            $exportRevoke = '<a class="tnh-modal tnh-export-revoke" title="' . lang('tnh_export_revoke') . '" data-tnh="modal" data-toggle="modal" data-target="#myModal" href="' . base_url('admin/manufactures/exportRevoke/'.$productions_orders_details_id) . '"><i class="fa fa-plus width-icon-actions"></i> ' . lang('tnh_export_revoke') . '</a>';

            $actions = '
            <div class="dropdown text-center">
                <button class="btn btn-primary dropdown-toggle nav-link" type="button" id="dropdownMenu1" data-toggle="dropdown" aria-expanded="true">
                ' . lang('actions') . '
                <span class="caret"></span>
                </button>
                <ul class="dropdown-menu pull-right" role="menu" aria-labelledby="dropdownMenu1">
                    <li>' . $detail . '</li>
                </ul>
            </div>';
            $row[8] = $actions;
            $output['aaData'][] = $row;
        }

        $output['totalQuantity']= $totalQuantity;
        $output['totalQuantityFinished']= $totalQuantityFinished;
        $output['totalCost']= $totalCost;
        echo json_encode($output);
    }

    public function agreeProcess() {
        $pois_id = $this->input->post('pois_id');
        $status = $this->input->post('status');
        $pod_id = $this->input->post('pod_id');
        $type = $this->input->post('type');

        $active = !empty($status) ? 1 : 0;
        $staff_active = get_staff_user_id();
        $date_active = date('Y-m-d H:i:s');

        if (!is_admin() && $active == 0) {
            $data['result'] = 0;
            $data['message'] = lang('Quyền Admin mới được xóa ở đây vui lòng liên hệ admin');
            echo json_encode($data); die;
        }

        if ($active == 1 && $type != "begins_production") {
            $this->db->select('
                tbl_productions_orders_items_stages.id as id,
                tbl_stages.name as stage_name, 
                tbl_productions_orders_items_stages.active as active, 
                tbl_productions_orders_items_stages.date_active as date_active,
                tbl_productions_orders_items_stages.staff_active as staff_active,
                CONCAT(tblstaff.firstname, " ", tblstaff.lastname) as staff_name,
                tblstaff.profile_image as profile_image,
                tbl_stages.status_qc as status_qc,
                tbl_stages.id as stage_id,
                tbl_productions_orders_items_stages.final_stage as final_stage,
                tbl_stages.type as type,
                tbl_productions_orders_items_stages.begin_productions as begin_productions,
                tbl_productions_orders_items_stages.date_productions as date_productions,
                tbl_productions_orders_items_stages.staff_productions as staff_productions,
                CONCAT(staff_productions.firstname, " ", staff_productions.lastname) as staff_name_productions,
                staff_productions.profile_image as profile_image_productions,
                tbl_productions_orders_items_stages.productions_orders_items_id as productions_orders_items_id,
                tbl_productions_orders_items_stages.number as number
            ', false);
            $this->db->from('tbl_productions_orders_items_stages');
            $this->db->join('tbl_stages', 'tbl_stages.id = tbl_productions_orders_items_stages.stage_id');
            $this->db->join('tblstaff', 'tblstaff.staffid = tbl_productions_orders_items_stages.staff_active', 'left');
            $this->db->join('tblstaff staff_productions', 'staff_productions.staffid = tbl_productions_orders_items_stages.staff_productions', 'left');
            $this->db->where('tbl_productions_orders_items_stages.id', $pois_id);
            $dtPois = $this->db->get()->row_array();
            if (!empty($dtPois)) {

                $qc = $this->manufactures_model->isQCPre(0, $dtPois['productions_orders_items_id'], 0, $dtPois['number']);
                if ($qc == 2 || $qc == 3) {
                    $data['result'] = 0;
                    $data['message'] = lang('Có mặt hàng chưa QC công đoạn trước hoặc chưa đạt');
                    echo json_encode($data); die;
                }

                // $this->db->select('count(tbl_productions_orders_items_stages.id) as ct', false);
                // $this->db->from('tbl_productions_orders_items_stages');
                // $this->db->join('tbl_stages', 'tbl_stages.id = tbl_productions_orders_items_stages.stage_id');
                // $this->db->where('tbl_productions_orders_items_stages.productions_orders_items_id', $dtPois['productions_orders_items_id']);
                // $this->db->where('tbl_productions_orders_items_stages.number <', $dtPois['number']);
                // $this->db->where_in('tbl_stages.type', [2]);
                // $ct = $this->db->get()->row_array()['ct'];

                $this->db->select('count(tbl_productions_orders_items_stages.id) as ct', false);
                $this->db->from('tbl_productions_orders_items_stages');
                $this->db->join('tbl_stages', 'tbl_stages.id = tbl_productions_orders_items_stages.stage_id');
                $this->db->where('tbl_productions_orders_items_stages.productions_orders_items_id', $dtPois['productions_orders_items_id']);
                $this->db->where('tbl_productions_orders_items_stages.number <', $dtPois['number']);
                $this->db->where_in('tbl_productions_orders_items_stages.type', [2]);
                $ct = $this->db->get()->row_array()['ct'];

                if ($dtPois['type'] || !empty($ct)) {
                    $data['result'] = 0;
                    $data['message'] = lang('Bạn không được phép hoàn thành giai đoạn này');
                    echo json_encode($data);
                    die;
                }
            }
        }

        $data['result'] = 0;
        $data['message'] = lang('fail');
        
        $pois = $this->manufactures_model->getProductionsOrderItemsStagesById($pois_id);
        $stage_id = $pois['stage_id'];
        if ($stage_id == STAGES_MATERIAL) {
            $data['result'] = 0;
            $data['message'] = lang('Giai đoạn này không thể thực hiện bên đây');
            echo json_encode($data); die;
        }

        $productions_orders_items_id = $pois['productions_orders_items_id'];
        if ($active == $pois['active']) {
            $data['result'] = 0;
            $data['message'] = lang('Trạng thái hiện tại đã thay đổi');
            $data['process'] = showProcessDetailProductions($productions_orders_items_id)['process'];
            echo json_encode($data); die;
        }

        if ($status == 0) {
            $queryQC = "(
                SELECT
                    count(tbl_check_quality_items.id) as ct_qc
                FROM tbl_check_quality_items
                INNER JOIN tbl_check_quality ON tbl_check_quality.id = tbl_check_quality_items.check_quality_id
                LEFT JOIN tblstaff ON tblstaff.staffid = tbl_check_quality.created_by
                WHERE tbl_check_quality_items.pod_id = ".$this->db->escape($pod_id)." AND tbl_check_quality_items.id_stage = '$stage_id'
            )";
            $isQC = $this->db->query($queryQC)->row_array()['ct_qc'];
            if (!empty($isQC)) {
                $data['result'] = 0;
                $data['message'] = lang('Đã có QC giai đoạn này không thể bỏ duyệt');
                echo json_encode($data); die;
            }

            //is suggest and purchase products
            $this->db->select('tbl_suggest_exporting.id as id');
            $this->db->from('tbl_suggest_exporting');
            $this->db->where('tbl_suggest_exporting.productions_orders_details_id', $pod_id);
            $this->db->where('tbl_suggest_exporting.pois_id', $pois_id);
            $this->db->where('tbl_suggest_exporting.type <', 10);
            $suggest_exporting = $this->db->get()->result_array();
            // if (!empty($suggest_exporting)) {
            //     foreach ($suggest_exporting as $key => $value) {
            //         if(!test_quantity_exporting_producion_warehouses($value['id'])) {
            //             $data['result'] = 2;
            //             $data['message'] = lang('test_quantyti_time_return');
            //             echo json_encode($data); die;
            //         }
            //     }
            // }

            $this->db->select('tbl_purchase_products.*');
            $this->db->from('tbl_purchase_products');
            $this->db->where('tbl_purchase_products.productions_orders_details_id', $pod_id);
            $this->db->where('tbl_purchase_products.pois_id', $pois_id);
            $this->db->where('tbl_purchase_products.type <', 10);
            $purchase_products = $this->db->get()->result_array();
            if (!empty($purchase_products)) {
                foreach ($purchase_products as $key => $value) {
                    $test_quantity = get_table_where('tblwarehouse_product', array('import_id' => $value['id'], 'quantity_export >' => 0, 'type_export ' => 18), '', 'row');
                    if (!empty($test_quantity)) {
                        $data['result'] = 2;
                        $data['message'] = lang('ch_quantity_nd');
                        echo json_encode($data); die;
                    }
                }
            }


            $staff_active = 0;
            $date_active = null;
        }

        if ($this->input->post()) {
            if ($type == "begins_production") {
                //đang sản xuất
                $up = $this->manufactures_model->updateProductionsOrderItemsStages($pois_id, [
                    'begin_productions' => $active,
                    'staff_productions' => $staff_active,
                    'date_productions' => $date_active,
                ]);
                if (!empty($up)) {
                    $data['result'] = 1;
                    $data['message'] = lang('success');
                }
            } else {
                //
                $up = $this->manufactures_model->updateProductionsOrderItemsStages($pois_id, [
                    'active' => $active,
                    'staff_active' => $staff_active,
                    'date_active' => $date_active,
                ]);
                if (!empty($up)) {
                    $pod = $this->manufactures_model->rowProductionsOrdersDetais($pod_id);
                    //remove suggest exporting
                    if (!empty($suggest_exporting)) {
                        foreach($suggest_exporting as $key => $value) {
                            $ktr = get_table_where('tbl_suggest_exporting', array('id' => $value['id']), '', 'row');
                            $items = get_table_where('tbl_suggest_exporting_items', array('suggest_exporting_id' => $value['id']));
                            $_data = array(
                                'warehouseman_id' => 0,
                                'date_warehouseman' => NULL
                            );
                            $success = $this->db->update('tbl_suggest_exporting', $_data, array('id' => $value['id']));
                            if ($success) {
                                // $this->stock_model->increaseadWarehouse($value['id'], $items, 0);
                                if ($ktr->warehouseman_id != 0) {
                                	$this->stock_model->increaseadWarehouse($value['id'], $items, 0);
                            	}
                                $this->manufactures_model->deleteSuggestExportingById($value['id']);
                                $this->manufactures_model->deleteSuggestExportingItems($value['id']);
                            }
                        }
                    }

                    //remove purchase products
                    if (!empty($purchase_products)) {
                        foreach ($purchase_products as $key => $value) {
                            $ktr = get_table_where('tbl_purchase_products', array('id' => $value['id']), '', 'row');
                            $_data = array(
                                'status' => 'un_approved',
                                'warehouseman_id' => 0,
                                'date_warehouseman' => NULL
                            );
                            $success = $this->db->update('tbl_purchase_products', $_data, array('id' => $value['id']));
                            if ($success) {
                                // $this->stock_model->increaseadWarehouse_purchase_products($value['id']);
                                if ($ktr->warehouseman_id != 0) {
                                	$this->stock_model->increaseadWarehouse_purchase_products($value['id']);
                            	}
                                $this->stock_model->deletePurchaseProducts($value['id']);
                                $this->stock_model->deletePurchaseProductItems($value['id']);
                                $this->manufactures_model->deletePurchaseProductPoisub($value['id']);
                                if (!empty($value['final_stage'])) {
                                    $this->manufactures_model->updateQuantityWarehoused($value['productions_orders_details_id'], $value['total_quantity'], $minus = 1);
                                }
                            }
                        }
                    }

                    if ($status == 1 && $pois['final_stage']) {
                        // noti_custom('pod', $pod_id, $staff_active, $pois_id, 'finishedPOD');
                    }

                    if ($status == 1) {
                        noti_custom('qc_po_detail', $pod_id, $staff_active, 0, 'finishedQCPODetail', [
                            'arrPOIS' => [$pois_id],
                            'pod_id' => $pod_id,
                            'stage_id' => $stage_id,
                        ]);
                    }

                    $data['result'] = 1;
                    $data['message'] = lang('success');
                }
            }
        }
        $data['process'] = showProcessDetailProductions($productions_orders_items_id)['process'];
        echo json_encode($data);
    }

    public function searchOrdersAndBusinessPlan() {
        $term = $this->input->get('term');
        $limit = get_option('select2_limit');
        $branch_staff = get_array_branch_staff();
        $is_admin = is_admin();

        $this->db->select('
            CONCAT("orders__", tbl_orders.id) as id, 
            CONCAT(tbl_orders.reference_no, "(", tblclients.company, ")") as text
        ', false);
        $this->db->from('tbl_orders');
        $this->db->join('tblclients', 'tblclients.userid = tbl_orders.customer_id');
        if (!empty($term))
        {
            $this->db->group_start();
            $this->db->like('tbl_orders.reference_no', $term);
            $this->db->or_like('tblclients.company', $term);
            $this->db->or_like('tbl_orders.note', $term);
            $this->db->group_end();
        }

        if (!$is_admin) {
            if (empty($branch_staff)) $branch_staff = [0];
            $this->db->where('tbl_orders.id_branch IN ('.implode(',', $branch_staff).')', false, false);
        }

        $this->db->limit($limit);
        $orders = $this->db->get()->result_array();

        $this->db->select('
            CONCAT("business_plan__", tbl_business_plan.id) as id, 
            tbl_business_plan.reference_no as text
        ', false);
        $this->db->from('tbl_business_plan');
        if (!empty($term))
        {
            $this->db->group_start();
            $this->db->like('tbl_business_plan.reference_no', $term);
            $this->db->group_end();
        }

        if (!$is_admin) {
            if (empty($branch_staff)) $branch_staff = [0];
            $this->db->where('tbl_business_plan.id_branch IN ('.implode(',', $branch_staff).')', false, false);
        }
        $this->db->limit($limit);
        $business_plan = $this->db->get()->result_array();

        $data['results'][] = ['text' => lang('orders'), 'children' => $orders];
        $data['results'][] = ['text' => lang('business_plan'), 'children' => $business_plan];
        echo json_encode($data);
    }

    public function getExportMaterialsWarehouses() {
        if (!$this->perViewOPD && !$this->perViewOwnOPD) {
            accessDenied(true);
        }
        $pod_id = $this->input->post('pod_id');

        $tbItems = "(
            (
                SELECT
                    tbl_suggest_exporting_items.item_id as item_id,
                    tbl_suggest_exporting_items.type_item as type_item,
                    tbl_materials.code as item_code,
                    tbl_materials.name as item_name,
                    tbl_materials.images as images,
                    SUM(tbl_suggest_exporting_items.quantity_exchange) as quantity
                FROM tbl_suggest_exporting
                INNER JOIN tbl_suggest_exporting_items ON tbl_suggest_exporting_items.suggest_exporting_id = tbl_suggest_exporting.id
                INNER JOIN tbl_materials ON tbl_suggest_exporting_items.item_id = tbl_materials.id
                WHERE tbl_suggest_exporting_items.type_item = 'materials' AND tbl_suggest_exporting.productions_orders_details_id = ".$this->db->escape($pod_id)."
                GROUP BY tbl_suggest_exporting_items.item_id
            )
            UNION ALL
            (
                SELECT
                    tbl_suggest_exporting_items.item_id as item_id,
                    tbl_suggest_exporting_items.type_item as type_item,
                    tbl_tools_supplies.code as item_code,
                    tbl_tools_supplies.name as item_name,
                    tbl_tools_supplies.images as images,
                    SUM(tbl_suggest_exporting_items.quantity_exchange) as quantity
                FROM tbl_suggest_exporting
                INNER JOIN tbl_suggest_exporting_items ON tbl_suggest_exporting_items.suggest_exporting_id = tbl_suggest_exporting.id
                INNER JOIN tbl_tools_supplies ON tbl_suggest_exporting_items.item_id = tbl_tools_supplies.id
                WHERE tbl_suggest_exporting_items.type_item = 'tools_supplies' AND tbl_suggest_exporting.productions_orders_details_id = ".$this->db->escape($pod_id)."
                GROUP BY tbl_suggest_exporting_items.item_id
            )
            UNION ALL
            (
                SELECT
                    tbl_suggest_exporting_items.item_id as item_id,
                    tbl_suggest_exporting_items.type_item as type_item,
                    tbl_products.code as item_code,
                    tbl_products.name as item_name,
                    tbl_products.images as images,
                    SUM(tbl_suggest_exporting_items.quantity_exchange) as quantity
                FROM tbl_suggest_exporting
                INNER JOIN tbl_suggest_exporting_items ON tbl_suggest_exporting_items.suggest_exporting_id = tbl_suggest_exporting.id
                INNER JOIN tbl_products ON tbl_suggest_exporting_items.item_id = tbl_products.id
                WHERE tbl_suggest_exporting_items.type_item NOT IN ('tools_supplies', 'materials', 'products') AND tbl_suggest_exporting.productions_orders_details_id = ".$this->db->escape($pod_id)."
                GROUP BY tbl_suggest_exporting_items.item_id
            )
        ) tb_cs";

        $aColumns = [
            'CONCAT(tb_cs.item_name, "(", tb_cs.item_code,")") as item',
            'tb_cs.quantity as quantity',
        ];
        $sIndexColumn = 'tb_cs.item_id';
        $sTable       = $tbItems;
        $where        = [
        ];
        $filter = [];
        
        $join = [
        ];

        $result = data_tables_init($aColumns, $sIndexColumn, $sTable, $join, $where, [
            'tb_cs.images as images',
            'tb_cs.type_item as type_item',
        ], '', [], ['union_all' => true]);
        

        $output = $result['output'];
        $rResult = $result['rResult'];
        $start = $this->input->post('start');
        foreach ($rResult as $key => $aRow) {
            $start++;
            $type_item = $aRow['type_item'];
            $images = $aRow['images'];

            if (empty($images)) {
                $images = base_url('assets/images/tnh/no_image.png');
            } else if ($type_item == "materials") {
                $images = base_url('uploads/materials/'.$images);
            } else if ($type_item == "tools_supplies") {
                $images = base_url('uploads/tools_supplies/'.$images);
            } else {
                $images = base_url('uploads/products/'.$images);
            }

            $divImages = '<div class="td-image"><div class="preview_image" style="width: auto;"><div class="display-block contract-attachment-wrapper img"><div style="width:45px;"><a href="'.$images.'" data-lightbox="customer-profile" class="display-block mbot5"><div class=""><img src="'.$images.'" style="border-radius: 50%"></div></a></div></div></div></div>';

            $row[0] = '<div class="flex-center">'.$divImages.' '.$aRow['item'].'</div>';
            $row[1] = '<div class="text-center">'.formatNumber($aRow['quantity']).'</div>';
            $output['aaData'][] = $row;
        }
        echo json_encode($output);
    }

    public function handlingSemiProduct() {
        $data = [];
