            if ($this->form_validation->run() == true) {
                $sp_actions = $this->input->post('sp_actions');
                if ($sp_actions == "view") {
                    $data['result'] = 0;
                    $data['message'] = lang('Chỉ được xem không thể lưu');
                    echo json_encode($data); die;
                }

