                $pp_id = $this->input->post('pp_id');
                // $localtion_semi_product = $this->site_model->getLocationPOD($sp_pod_id, $warehouses_semi_product);
                // $localtion_semi_product = $this->site_model->getLocationToPlan($pp_id);
                $localtion_semi_product = LOCATIONS_DEFAULT_MANUFACTURES;
                $dataItems = [];
                $arrSaveBom = [];

                $total_quantity_purchases = 0;
                $count_quantity_purchases = 0;

                $total_quantity_se = 0;
                $total_quantity_exchange_se = 0;
                $count_quantity_se = 0;
                $total_quantity_warehouse = 0;
                $total_quantity_payment = 0;

                $items = $this->input->post('items');
                $isErrors = true;
                $arrSumMaterials = [];
                if (!empty($items)) {
                    foreach ($items as $key => $value) {
                        $item_type_sp = "products";
