                                    $exchange_payment = !empty($info_mt['exchange_unit_payment']) ? $info_mt['exchange_unit_payment'] : 1;

                                    $exchange_unit = $info_mt['exchange_unit'];

                                    $longs = $info_mt['longs'];
                                    $wide = $info_mt['wide'];
