    public function getNotiPurchaseProducts() {
        $pod_id_pp = $this->input->post('pod_id_pp');
        $pois_id_pp = $this->input->post('pois_id_pp');
        $cqi_id_pp = $this->input->post('cqi_id_pp');
        $stage_name = $this->input->post('stage_name');

        $aColumns = [
            'tbl_products.images as images',
            'CONCAT(tbl_products.name, " - ", tbl_products.code) as item_name',
            'CONCAT(tblwarehouse.name, " - ", tbllocaltion_warehouses.name) as name_warehouse',
            'SUM(tblwarehouse_product.quantity_export) as quantity_export',
        ];
        $sIndexColumn = 'id';
        $sTable       = 'tbl_purchase_products';
        $where        = [

        ];
        $filter = [];
        
        $join = [
            'INNER JOIN tbl_purchase_product_items ON tbl_purchase_product_items.purchase_product_id = tbl_purchase_products.id',
            'INNER JOIN tblwarehouse_product ON tblwarehouse_product.import_id = tbl_purchase_products.id AND tbl_purchase_product_items.item_id = tblwarehouse_product.product_id  AND tblwarehouse_product.type_export = 18',
            'INNER JOIN tbllocaltion_warehouses ON tbllocaltion_warehouses.id = tblwarehouse_product.localtion',
            'LEFT JOIN tblwarehouse ON tblwarehouse.id = tbl_purchase_products.warehouse_id',
            'INNER JOIN tbl_products ON tbl_products.id = tbl_purchase_product_items.item_id'
        ];

        array_push($where, "AND tbl_purchase_products.productions_orders_details_id = ".$this->db->escape($pod_id_pp));
        array_push($where, "AND tbl_purchase_products.pois_id = ".$this->db->escape($pois_id_pp));
        array_push($where, "AND tblwarehouse_product.quantity_export > 0");
        array_push($where, "AND tblwarehouse_product.type_items = 'product'");
        if ($cqi_id_pp) {
            array_push($where, "AND tbl_purchase_products.cqi_id = ".$this->db->escape($cqi_id_pp));
        }


        $result = data_tables_init($aColumns, $sIndexColumn, $sTable, $join, $where, [
            'tbl_purchase_product_items.purchase_product_id', 
            'tbl_purchase_product_items.type_item', 
            'tbl_purchase_product_items.item_id'
        ], 'GROUP BY tbl_purchase_product_items.purchase_product_id, tbl_purchase_product_items.type_item, tbl_purchase_product_items.item_id', []);
        

        $output = $result['output'];
        $rResult = $result['rResult'];
        $start = $this->input->post('start');
        $totalQuantityExport = 0;
        foreach ($rResult as $key => $aRow) {
            $start++;
            $images = $aRow['images'];
            if (empty($images)) {
                $images = base_url('assets/images/tnh/no_image.png');
            } else {
                $images = base_url('uploads/products/'.$images);
            }

            $divImages = '<div class="td-image"><div class="preview_image" style="width: auto;"><div class="display-block contract-attachment-wrapper img"><div style="width:45px; margin: auto;"><a href="'.$images.'" data-lightbox="customer-profile" class="display-block mbot5"><div class=""><img src="'.$images.'" style="border-radius: 50%"></div></a></div></div></div></div>';

            $row[0] = $divImages ;
            $row[1] = $aRow['item_name'].'<div>('.$stage_name.')</div>';
            $row[2] = '<div class="text-center">'.$aRow['name_warehouse'].'</div>';
            $row[3] = '<div class="text-center">'.formatNumber($aRow['quantity_export']).'</div>';

            $totalQuantityExport+= $aRow['quantity_export'];
            $output['aaData'][] = $row;
        }
        $output['quantity_export'] = $totalQuantityExport;
        echo json_encode($output);
    }

