                        $content = str_replace('{$2}', $pod['reference_no'], $content);

                        insertActivityLog([
                            'type_parent_obj' => 'exporting_producion',
                            'table_obj' => 'tbl_suggest_exporting',
                            'id_obj' => $suggest_exporting_id,
                            'name_obj' => $reference_suggest_exporting,
                            'content' => $content,
                            'actions' => 'add'
                        ]);
