                if (!empty($items)) {
                    foreach ($items as $key => $value) {
                        $item_type_sp = "products";
                        $arr_id_sp = explode('__', $value['id']);
                        $type_order_sp = $arr_id_sp[0];
                        $item_id_sp = $arr_id_sp[1];
