                    $content = lang('tnh_his_add_purchase_product');
                    $content = str_replace('{$1}', $reference_purchase, $content);
                    insertActivityLog([
                        'type_parent_obj' => 'purchase_products',
                        'table_obj' => 'tbl_purchase_products',
                        'id_obj' => $purchase_product_id,
                        'name_obj' => $reference_purchase,
                        'content' => $content,
                        'actions' => 'add'
                    ]);

                     //purchase errors
                     if (!empty($itemsErrors)) {
                        $reference_purchase = getReference('purchase_products');
                        $purchases = [
                            'reference_no' => $reference_purchase,
                            'date' => $dateGerenal,
                            'productions_orders_details_id' => $sp_pod_id,
                            'warehouse_id' => WAREHOUSES_ERRORS,
                            'count_items' => count($itemsErrors),
                            'total_quantity' => $total_quantity_errors,
                            'created_by' => $staffGerenal,
                            'date_created' => $dateGerenal,
                            'status' => 'un_approved',
                            'pois_id' => $sp_pois_id,
                            'type' => $typePurchase,
                            'sp_type' => $sp_type,
                            'cqi_id' => $sp_cqis_id,
                            'parent_id' => $purchase_product_id,
                            'is_errors' => 1,
                            'branch_id' => $branch_id
                        ];

                        $purchase_product_errors_id = $this->stock_model->insertPurchaseProducts($purchases);
                        if (!empty($purchase_product_errors_id)) {
                            updateReference('purchase_products');
                            if (!empty($itemsErrors)) {
                                foreach ($itemsErrors as $key => $value) {
                                    $arrPOISub = $value['arrPOISub'];
                                    unset($value['arrPOISub']);
                                    $value['purchase_product_id'] = $purchase_product_errors_id;
                                    $purchase_product_item_id = $this->stock_model->insertPurchaseProductItems($value);
                                    if ($purchase_product_item_id) {
                                        if (!empty($arrPOISub)) {
                                            foreach ($arrPOISub as $k => $v) {
                                                $arrPOISub[$k]['purchase_product_id'] = $purchase_product_errors_id;
                                                $arrPOISub[$k]['purchase_product_items_id'] = $purchase_product_item_id;
                                            }
                                        }
                                    }
        
                                    if (!empty($arrPOISub)) {
                                        $this->manufactures_model->insertBatchPurchaseProductPoisub($arrPOISub);
                                    }
                                }
                            }

                            if ($final_stage && $object_type_c == 'business_plan') {

                            } else if (!empty($save_and_warehouse)) {
                                $purchaseProduct = $this->stock_model->rowPurchaseProducts($purchase_product_errors_id);
                                $_data = array(
                                    'status' => 'approved',
                                    'warehouseman_id' => get_staff_user_id(),
                                    'date_warehouseman' => date('Y-m-d H:i:s')
                                );
                                $success = $this->db->update('tbl_purchase_products', $_data, array('id' => $purchase_product_errors_id));
                                if ($success) {
                                    log_activity('Import Warehouses items approved [ID export_warehouses: ' . $purchase_product_errors_id);
                                    $this->stock_model->decreaseWarehouse_purchase_products($purchase_product_errors_id);
        
                                    //activity log
                                    if (!empty($purchaseProduct['productions_orders_details_id']))
                                    {
                                        $pod = $this->manufactures_model->rowProductionsOrdersDetais($purchaseProduct['productions_orders_details_id']);
                                        $content = lang('tnh_his_warehouse_purchase_product_pod');
                                        $content = str_replace('{$1}', $purchaseProduct['reference_no'], $content);
                                        $content = str_replace('{$2}', $pod['reference_no'], $content);
                                    } else {
                                        $content = lang('tnh_his_warehouse_purchase_product');
                                        $content = str_replace('{$1}', $purchaseProduct['reference_no'], $content);
                                    }
                                    insertActivityLog([
                                        'type_parent_obj' => 'purchase_products',
                                        'table_obj' => 'tbl_purchase_products',
                                        'id_obj' => $purchase_product_errors_id,
                                        'name_obj' => $purchaseProduct['reference_no'],
                                        'content' => $content,
                                        'actions' => 'warehouse'
                                    ]);
                                    //end activity log
                                }
                            }
                        }
                    }

                    //handling bom
                    if (!empty($arrSaveBom)) {
                        $this->products_model->handlingBOMPOD($arrSaveBom);
                    }

                    noti_custom('qc_po_detail', $sp_pod_id, $staffGerenal, 0, 'finishedQCPODetail', [
                        'arrPOIS' => [$sp_pois_id],
                        'pod_id' => $sp_pod_id,
                        'stage_id' => $stage_id,
                    ]);

                    $this->db->select('
                        tbl_productions_orders_items_stages.id as id,
                        tbl_stages.name as stage_name, 
                        tbl_stages.id as stage_id,
                        tbl_productions_orders.reference_no,
                        tbl_productions_orders_items.items_code,
                        tbl_productions_orders_items.items_name,    
                        tbl_productions_orders_items.quantity,    
                        SUM(tbl_purchase_products.total_quantity) as quantity_done,    
                    ', false);
                    $this->db->from('tbl_productions_orders_items_stages');
                    $this->db->join('tbl_stages', 'tbl_stages.id = tbl_productions_orders_items_stages.stage_id');
                    $this->db->join('tbl_productions_orders_details', 'tbl_productions_orders_details.productions_orders_item_id = tbl_productions_orders_items_stages.productions_orders_items_id', 'left');
                    $this->db->join('tbl_productions_orders_items', 'tbl_productions_orders_items.id = tbl_productions_orders_items_stages.productions_orders_items_id', 'left');
                    $this->db->join('tbl_purchase_products', 'tbl_purchase_products.pois_id = tbl_productions_orders_items_stages.id', 'left');
                    $this->db->join('tbl_productions_orders', 'tbl_productions_orders.id = tbl_productions_orders_details.productions_orders_id', 'left');
                    $this->db->where('tbl_productions_orders_items_stages.stage_id', $stage_id);
                    $this->db->where('tbl_productions_orders_details.id', $sp_pod_id);
                    $this->db->where('tbl_productions_orders_details.date_created >', '2025-09-01 00:00:00');
                    $this->db->group_by('tbl_productions_orders_items_stages.id');
                    $this->db->order_by('tbl_stages.id DESC');
                    $rows = $this->db->get()->result_array();
                    foreach ($rows as $key => $value) {
                        $updatedRow = $this->_api_row($value);
                        sendSocket([
                            'action'     => 'update',
                            'updatedRow' => $updatedRow
                        ], [], 'loadProgress');
                    }



                    $data['process'] = showProcessDetailProductions($pod['productions_orders_item_id'])['process'];
                    $data['result'] = 1;
                    $data['message'] = lang('success').''.$errors;
                } else {
                    $data['result'] = 0;
                    $data['message'] = lang('fail');
                }
            } else {
                $data['result'] = 0;
                $data['message'] = validation_errors();
            }
            echo json_encode($data); die;
        } else {

            $data['cqi_id'] = $this->input->post('cqi_id');
            $data['quantity'] = $this->input->post('quantity');
            $data['cqis_id'] = $this->input->post('cqis_id');

            $data['actions'] = $this->input->post('actions');
            $data['pod_id'] = $this->input->post('pod_id');
            $data['type'] = $this->input->post('type');
            $data['pois_id'] = $this->input->post('pois_id');
            $data['dtPois'] = $this->manufactures_model->getProductionsOrdersItemsStagesById($data['pois_id']);
            $data['warehouses'] = $this->stock_model->getWarehouses(false, [WAREHOUSES_CAPACITY]);
            $data['productions_plan'] = $this->manufactures_model->getProductionsPlanPOD($data['pod_id']);
            $data['title'] = lang('tnh_enter_products');
            $this->load->view('admin/manufactures/handling_products_step', $data);
        }
    }
    private function _api_row($r)
    {
        // Chuẩn hóa row theo format frontend đang dùng
        return [
            'stage_id' => $r['id'],
            'order_code' => $r['reference_no'],
            'stage_idd' => $r['stage_id'],
            'sku'        => $r['items_code'],
            'stage'      => $r['stage_name'],
            'qty_plan'   => (int) $r['quantity'],
            'qty_done'   => (int) $r['quantity_done'],
            'qty_todo'   => (int) ($r['quantity'] - $r['quantity_done']),
            'percent'    => round(($r['quantity_done'] / $r['quantity'] * 100), 2),
            'bar_color'  => $this->_getColor(($r['quantity_done'] / $r['quantity'] * 100)),
        ];
    }
    private function _getColor($percent)
    {
        if ($percent >= 75) return '#22c55e'; // green
        if ($percent >= 40) return '#facc15'; // yellow
        return '#ef4444'; // red
    }
    public function loadALLProductsStep() {
        $pod_id = $this->input->post('pod_id');
