        $quantity = number_unformat($this->input->post('quantity'));
        $actions = $this->input->post('actions');
        $productions_orders_items = $this->manufactures_model->loadDataProductsStep($pod_id, $pois_id, $quantity, $actions);
        $data['items'] = $productions_orders_items;
        echo json_encode($data);
    }

    public function getMaterialDetailProductions() {
        if (!$this->perViewOPD && !$this->perViewOwnOPD) {
            accessDenied(true);
        }

        $pod_id = $this->input->post('pod_id');
        $poi_id = $this->input->post('pois_id');

        $tbSuggestExportMaterial = "(
            SELECT
                sei_1.item_id as item_id,
                SUM(sei_1.quantity_export) as quantity_export
            FROM tbl_suggest_exporting se_1
            INNER JOIN tbl_suggest_exporting_items sei_1 ON sei_1.suggest_exporting_id = se_1.id
            WHERE se_1.warehouseman_id > 0 AND se_1.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei_1.type_item = 'materials'
            GROUP BY sei_1.item_id
        ) tb_se";

        $tbSuggestExportMaterialSemi = "(
            SELECT
                sei_1.item_id as item_id,
                SUM(sei_1.quantity_export) as quantity_export
            FROM tbl_suggest_exporting se_1
            INNER JOIN tbl_suggest_exporting_items sei_1 ON sei_1.suggest_exporting_id = se_1.id
            WHERE se_1.warehouseman_id > 0 AND se_1.productions_orders_details_id = ".$this->db->escape($pod_id)." AND (sei_1.type_item = 'semi_products' OR sei_1.type_item = 'products')
            GROUP BY sei_1.item_id
        ) tb_se_semi";
    
        $tbProductionsOrdersItemsSub = "(
            (
                SELECT 
                    pois.item_id as item_id,
                    pois.type as item_type,
                    tbl_materials.code as item_code,
                    tbl_materials.name as item_name,
                    tbl_materials.images as images,
                    tblunits.unit as unit_name,
                    SUM(pois.quantity + pois.quantity_compensation_sm + pois.quantity_compensation) as quantity,
                    tb_se.quantity_export as quantity_export

                FROM tbl_productions_orders_items_sub pois
                INNER JOIN tbl_materials ON tbl_materials.id = pois.item_id
                LEFT JOIN $tbSuggestExportMaterial ON tb_se.item_id = pois.item_id
                LEFT JOIN tblunits ON tblunits.unitid = pois.unit_id
                WHERE pois.type = 'materials' AND pois.productions_orders_items_id = ".$this->db->escape($poi_id)."
                GROUP BY pois.item_id
            )
            UNION ALL
            (
                SELECT
                    sei.item_id as item_id,
                    sei.type_item as item_type,
                    tbl_materials.code as item_code,
                    tbl_materials.name as item_name,
                    tbl_materials.images as images,
                    tblunits.unit as unit_name,
                    0 as quantity,
                    SUM(sei.quantity_export) as quantity_export
                FROM tbl_suggest_exporting se
                INNER JOIN tbl_suggest_exporting_items sei ON sei.suggest_exporting_id = se.id
                INNER JOIN tbl_materials ON tbl_materials.id = sei.item_id
                LEFT JOIN tblunits ON tblunits.unitid = sei.unit_id
                WHERE se.warehouseman_id > 0 AND se.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei.type_item = 'materials' AND se.reference_stock IS NOT NULL AND NOT EXISTS (
                    SELECT pois.id
                    FROM tbl_productions_orders_items_sub pois
                    WHERE pois.type = 'materials' AND pois.productions_orders_items_id = ".$this->db->escape($poi_id)."
                )
                GROUP BY sei.item_id
            )
            UNION ALL
            (
                SELECT 
                    pois.item_id as item_id,
                    pois.type as item_type,
                    tbl_products.code as item_code,
                    tbl_products.name as item_name,
                    tbl_products.images as images,
                    tblunits.unit as unit_name,
                    SUM(pois.quantity + pois.quantity_compensation_sm + pois.quantity_compensation) as quantity,
                    tb_se_semi.quantity_export as quantity_export

                FROM tbl_productions_orders_items_sub pois
                INNER JOIN tbl_products ON tbl_products.id = pois.item_id
                LEFT JOIN $tbSuggestExportMaterialSemi ON tb_se_semi.item_id = pois.item_id
                LEFT JOIN tblunits ON tblunits.unitid = pois.unit_id
                WHERE pois.type = 'semi_products' AND pois.productions_orders_items_id = ".$this->db->escape($poi_id)."
                GROUP BY pois.item_id
            )
            UNION ALL
            (
                SELECT
                    sei.item_id as item_id,
                    sei.type_item as item_type,
                    tbl_products.code as item_code,
                    tbl_products.name as item_name,
                    tbl_products.images as images,
                    tblunits.unit as unit_name,
                    0 as quantity,
                    SUM(sei.quantity_export) as quantity_export
                FROM tbl_suggest_exporting se
                INNER JOIN tbl_suggest_exporting_items sei ON sei.suggest_exporting_id = se.id
                INNER JOIN tbl_products ON tbl_products.id = sei.item_id
                LEFT JOIN tblunits ON tblunits.unitid = sei.unit_id
                WHERE se.warehouseman_id > 0 AND se.type != 7 AND se.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei.type_item = 'semi_products' AND se.reference_stock IS NOT NULL AND NOT EXISTS (
                    SELECT pois.id
                    FROM tbl_productions_orders_items_sub pois
                    WHERE pois.type = 'semi_products' AND pois.productions_orders_items_id = ".$this->db->escape($poi_id)."
                )
                GROUP BY sei.item_id
            )
            UNION ALL
            (
                SELECT
                    sei.item_id as item_id,
                    sei.type_item as item_type,
                    tbl_tools_supplies.code as item_code,
                    tbl_tools_supplies.name as item_name,
                    tbl_tools_supplies.images as images,
                    tblunits.unit as unit_name,
                    0 as quantity,
                    SUM(sei.quantity_export) as quantity_export

                FROM tbl_suggest_exporting se
                INNER JOIN tbl_suggest_exporting_items sei ON sei.suggest_exporting_id = se.id
                INNER JOIN tbl_tools_supplies ON tbl_tools_supplies.id = sei.item_id
                LEFT JOIN tblunits ON tblunits.unitid = sei.unit_id
                WHERE se.warehouseman_id > 0 AND se.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei.type_item = 'tools_supplies' AND se.reference_stock IS NOT NULL
                GROUP BY sei.item_id
            )
        ) tb_cs";

        $aColumns = [
           'tb_cs.images as images',
           'CONCAT(tb_cs.item_name, " - ", tb_cs.item_code) as item_code',
           'tb_cs.unit_name as unit_name',
           'tb_cs.quantity as quantity',
           'tb_cs.quantity_export as quantity_export',
           'COALESCE(tb_cs.quantity, 0) - COALESCE(tb_cs.quantity_export) as quantity_rest',
           '0 as quantity_recall',
        ];
        $sIndexColumn = 'tb_cs.item_id';
        $sTable       = $tbProductionsOrdersItemsSub;
        $where        = [

        ];
        $filter = [];
        
        $join = [
            
        ];

        $result = data_tables_init($aColumns, $sIndexColumn, $sTable, $join, $where, [
            'tb_cs.item_type as item_type'
        ], '', [], ['union_all' => true]);
        

        $output = $result['output'];
        $rResult = $result['rResult'];
        $start = $this->input->post('start');
        $typeGroup = '';
        $totalQuantity = 0;
        $totalQuantityExport = 0;
        $totalQuantityRest = 0;
        $totalQuantityReCall = 0;
        foreach ($rResult as $key => $aRow) {
            $start++;
            $item_type = $aRow['item_type'];
            if ($typeGroup != $item_type) {
                $row[0] = 'group';
                $row[1] = lang($aRow['item_type']);
                $row[2] = '';
                $row[3] = '';
                $row[4] = '';
                $row[5] = '';
                $row[6] = '';
                $typeGroup = $item_type;
                $output['aaData'][] = $row;
            }

            $images = $aRow['images'];
            if (empty($images)) {
                $images = base_url('assets/images/tnh/no_image.png');
            } else if ($item_type == "materials") {
                $images = base_url('uploads/materials/'.$images);
            } else if ($item_type == "tools_supplies") {
                $images = base_url('uploads/tools_supplies/'.$images);
            } else {
                $images = base_url('uploads/products/'.$images);
            }

            $divImages = '<div class="td-image"><div class="preview_image" style="width: auto;"><div class="display-block contract-attachment-wrapper img"><div style="width:45px; margin: auto;"><a href="'.$images.'" data-lightbox="customer-profile" class="display-block mbot5"><div class=""><img src="'.$images.'" style="border-radius: 50%"></div></a></div></div></div></div>';
        
            $row[0] = $divImages;
            $row[1] = $aRow['item_code'];
            $row[2] = '<div class="text-center">'.$aRow['unit_name'].'</div>';
            $row[3] = '<div class="text-center">'.formatNumber($aRow['quantity']).'</div>';
            $row[4] = '<div class="text-center">'.formatNumber($aRow['quantity_export']).'</div>';
            $row[5] = '<div class="text-center">'.formatNumber($aRow['quantity_rest']).'</div>';
            $row[6] = '<div class="text-center">'.formatNumber($aRow['quantity_recall']).'</div>';
            $output['aaData'][] = $row;

            $totalQuantity+= $aRow['quantity'];
            $totalQuantityExport+= $aRow['quantity_export'];
            $totalQuantityRest+= $aRow['quantity_rest'];
            $totalQuantityReCall+= $aRow['quantity_recall'];
        }
        $output['totalQuantity'] = $totalQuantity;
        $output['totalQuantityExport'] = $totalQuantityExport;
        $output['totalQuantityRest'] = $totalQuantityRest;
        $output['totalQuantityReCall'] = $totalQuantityReCall;
        echo json_encode($output);
    }

    public function init_chart_materials() {
        if (!$this->perViewOPD && !$this->perViewOwnOPD) {
            accessDenied(true);
        }

        $data = [];
        $pod_id = $this->input->post('pod_id');
        $pois_id = $this->input->post('pois_id');
        $start = $this->input->post('start');
        $end = $this->input->post('end');

        $tbSuggestExportMaterial = "(
            SELECT
                sei_1.item_id as item_id,
                SUM(sei_1.quantity_export) as quantity_export
            FROM tbl_suggest_exporting se_1
            INNER JOIN tbl_suggest_exporting_items sei_1 ON sei_1.suggest_exporting_id = se_1.id
            WHERE se_1.warehouseman_id > 0 AND se_1.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei_1.type_item = 'materials'
            GROUP BY sei_1.item_id
        ) tb_se";

        $tbSuggestExportMaterialSemi = "(
            SELECT
                sei_1.item_id as item_id,
                SUM(sei_1.quantity_export) as quantity_export
            FROM tbl_suggest_exporting se_1
            INNER JOIN tbl_suggest_exporting_items sei_1 ON sei_1.suggest_exporting_id = se_1.id
            WHERE se_1.warehouseman_id > 0 AND se_1.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei_1.type_item = 'semi_products'
            GROUP BY sei_1.item_id
        ) tb_se_semi";
        
        $tbProductionsOrdersItemsSub = "(
            SELECT
                tb_cs.*
            FROM (
                (
                    SELECT 
                        pois.item_id as item_id,
                        pois.type as item_type,
                        tbl_materials.code as item_code,
                        tbl_materials.name as item_name,
                        tbl_materials.images as images,
                        tblunits.unit as unit_name,
                        SUM(pois.quantity + pois.quantity_compensation + pois.quantity_compensation_sm) as quantity,
                        tb_se.quantity_export as quantity_export

                    FROM tbl_productions_orders_items_sub pois
                    INNER JOIN tbl_materials ON tbl_materials.id = pois.item_id
                    LEFT JOIN $tbSuggestExportMaterial ON tb_se.item_id = pois.item_id
                    LEFT JOIN tblunits ON tblunits.unitid = pois.unit_id
                    WHERE pois.type = 'materials' AND pois.productions_orders_items_id = ".$this->db->escape($pois_id)."
                    GROUP BY pois.item_id
                )
                UNION ALL
                (
                    SELECT
                        sei.item_id as item_id,
                        sei.type_item as item_type,
                        tbl_materials.code as item_code,
                        tbl_materials.name as item_name,
                        tbl_materials.images as images,
                        tblunits.unit as unit_name,
                        0 as quantity,
                        SUM(sei.quantity_export) as quantity_export
                    FROM tbl_suggest_exporting se
                    INNER JOIN tbl_suggest_exporting_items sei ON sei.suggest_exporting_id = se.id
                    INNER JOIN tbl_materials ON tbl_materials.id = sei.item_id
                    LEFT JOIN tblunits ON tblunits.unitid = sei.unit_id
                    WHERE se.warehouseman_id > 0 AND se.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei.type_item = 'materials' AND se.reference_stock IS NOT NULL AND NOT EXISTS (
                        SELECT pois.id
                        FROM tbl_productions_orders_items_sub pois
                        WHERE pois.type = 'materials' AND pois.productions_orders_items_id = ".$this->db->escape($pois_id)."
                    )
                    GROUP BY sei.item_id
                )
                UNION ALL
                (
                    SELECT 
                        pois.item_id as item_id,
                        pois.type as item_type,
                        tbl_products.code as item_code,
                        tbl_products.name as item_name,
                        tbl_products.images as images,
                        tblunits.unit as unit_name,
                        SUM(pois.quantity + pois.quantity_compensation + pois.quantity_compensation_sm) as quantity,
                        tb_se_semi.quantity_export as quantity_export

                    FROM tbl_productions_orders_items_sub pois
                    INNER JOIN tbl_products ON tbl_products.id = pois.item_id
                    LEFT JOIN $tbSuggestExportMaterialSemi ON tb_se_semi.item_id = pois.item_id
                    LEFT JOIN tblunits ON tblunits.unitid = pois.unit_id
                    WHERE pois.type = 'semi_products' AND pois.productions_orders_items_id = ".$this->db->escape($pois_id)."
                    GROUP BY pois.item_id
                )
                UNION ALL
                (
                    SELECT
                        sei.item_id as item_id,
                        sei.type_item as item_type,
                        tbl_products.code as item_code,
                        tbl_products.name as item_name,
                        tbl_products.images as images,
                        tblunits.unit as unit_name,
                        0 as quantity,
                        SUM(sei.quantity_export) as quantity_export
                    FROM tbl_suggest_exporting se
                    INNER JOIN tbl_suggest_exporting_items sei ON sei.suggest_exporting_id = se.id
                    INNER JOIN tbl_products ON tbl_products.id = sei.item_id
                    LEFT JOIN tblunits ON tblunits.unitid = sei.unit_id
                    WHERE se.warehouseman_id > 0 AND se.type != 7 AND se.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei.type_item = 'semi_products' AND se.reference_stock IS NOT NULL AND NOT EXISTS (
                        SELECT pois.id
                        FROM tbl_productions_orders_items_sub pois
                        WHERE pois.type = 'semi_products' AND pois.productions_orders_items_id = ".$this->db->escape($pois_id)."
                    )
                    GROUP BY sei.item_id
                )
                UNION ALL
                (
                    SELECT
                        sei.item_id as item_id,
                        sei.type_item as item_type,
                        tbl_tools_supplies.code as item_code,
                        tbl_tools_supplies.name as item_name,
                        tbl_tools_supplies.images as images,
                        tblunits.unit as unit_name,
                        0 as quantity,
                        SUM(sei.quantity_export) as quantity_export

                    FROM tbl_suggest_exporting se
                    INNER JOIN tbl_suggest_exporting_items sei ON sei.suggest_exporting_id = se.id
                    INNER JOIN tbl_tools_supplies ON tbl_tools_supplies.id = sei.item_id
                    LEFT JOIN tblunits ON tblunits.unitid = sei.unit_id
                    WHERE se.warehouseman_id > 0 AND se.productions_orders_details_id = ".$this->db->escape($pod_id)." AND sei.type_item = 'tools_supplies' AND se.reference_stock IS NOT NULL
                    GROUP BY sei.item_id
                )
            ) tb_cs
            LIMIT $start, $end 
        )";
        $categories = [];
        $max = 0;
        $dataQuantity = [];
        $dataQuantityExport = [];
        $dataQuantityRecall = [];
        $items = $this->db->query($tbProductionsOrdersItemsSub)->result_array();
        if (!empty($items)) {
            foreach ($items as $key => $value) {
                $item_code = $value['item_code'];
                $categories[] = $item_code;

                $dataQuantity[] = (float)roundNumberFormat($value['quantity']);
                $dataQuantityExport[] = (float)roundNumberFormat($value['quantity_export']);
                $dataQuantityRecall[] = 0;
            }
        }

        $data['dataQuantity'] = $dataQuantity;
        $data['dataQuantityExport'] = $dataQuantityExport;
        $data['dataQuantityRecall'] = $dataQuantityRecall;
        $data['categories'] = $categories;
        echo json_encode($data); die;
    }

