    public function getShowDetailManufactures()
    {
        $start_date_search = !empty($this->input->post('start_date_search')) ? to_sql_date($this->input->post('start_date_search')) : date('Y-m-d');
        $end_date_search = !empty($this->input->post('end_date_search')) ? to_sql_date($this->input->post('end_date_search')) : date('Y-m-d');


        $customer_search = $this->input->post('customer_search');
        $product_id = $this->input->post('product_id');

        // $slKeep = "COALESCE((
        //     SELECT SUM(tbltransfer_warehouse_detail.quantity_net ) as quantity_net
        //     FROM tbltransfer_warehouse_detail
        //     WHERE tbltransfer_warehouse_detail.order_item_id = tbl_order_items.id
        // ), 0)";
        $slKeep = "COALESCE((
            SELECT SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
            FROM tbltransfer_warehouse_detail
            WHERE tbltransfer_warehouse_detail.order_id_item = tbl_order_items.id AND tbltransfer_warehouse_detail.tranfer_business_item_id = 0
        ), 0)";

        $tbQuantity = "(
            SELECT
                tbl_order_items.order_id as order_id,
                SUM(tbl_order_item_shippings.quantity_shipping - tbl_order_item_shippings.quantity_plan_item - IF (tbl_order_items.quantity_delivery > 0, tbl_order_items.quantity_delivery, $slKeep)) as quantity_delivery
            FROM tbl_order_items
            INNER JOIN tbl_order_item_shippings ON tbl_order_items.id = tbl_order_item_shippings.order_item_id
            WHERE tbl_order_items.type_item = 'products' AND tbl_order_items.item_id = ".$product_id." AND tbl_order_item_shippings.date_shipping >= '$start_date_search' AND tbl_order_item_shippings.date_shipping <= '$end_date_search'
            GROUP BY tbl_order_items.order_id
        ) tb_quantity";

        $aColumns = [
            'tbl_orders.id as id',
            'tbl_orders.date as date',
            'tblclients.company as company',
            'tbl_orders.reference_no as reference_no',
            'tb_quantity.quantity_delivery as quantity_delivery',
        ];
        $sIndexColumn = 'id';
        $sTable       = 'tbl_orders';
        $where        = [
        ];
        $filter = [];
        $join = [
            'INNER JOIN tblclients ON tblclients.userid = tbl_orders.customer_id',
            'INNER JOIN '.$tbQuantity.' ON tbl_orders.id = tb_quantity.order_id',
        ];

        if (!empty($customer_search)) {
            array_push($where, ' AND tbl_orders.customer_id ='.$customer_search);
        }

        array_push($where, ' AND tb_quantity.quantity_delivery > 0 AND tbl_orders.status = "approved"');

        $result = data_tables_init($aColumns, $sIndexColumn, $sTable, $join, $where, [
        ], '', []);

        $output = $result['output'];
        $rResult = $result['rResult'];
        $start = $this->input->post('start');
        $totalQuantity = 0;
        foreach ($rResult as $key => $aRow) {
            $start++;

            $row[0] = '<div class="text-center">'.$start.'</div>';
            $row[1] = '<div class="text-center">'._d($aRow['date']).'</div>';
            $row[2] = $aRow['company'];
            $row[3] = $aRow['reference_no'];
            $row[4] = '<div class="text-center">'.formatNumber($aRow['quantity_delivery']).'</div>';

            $totalQuantity+= $aRow['quantity_delivery'];
            $output['aaData'][] = $row;
        }

        $output['totalQuantity'] = $totalQuantity;
        echo json_encode($output);
    }

