    public function getStatisticalPlanning() {
        if (!$this->perViewProductionsOrders && !$this->perViewOwnProductionsOrders) {
            accessDenied(true);
        }

        $customer_search = $this->input->post('customer_search');
        $start_date_search = $this->input->post('start_date_search');
        $end_date_search = $this->input->post('end_date_search');

        $tbWarehouseItems = "(
            SELECT
                tblwarehouse_items.id_items as id_items,
                SUM(tblwarehouse_items.product_quantity) as product_quantity
            FROM tblwarehouse_items
            WHERE tblwarehouse_items.type_items = 'product'
            GROUP BY tblwarehouse_items.id_items
        ) tb_warehouse_items";

        $aColumns = [
            'tbl_productions_orders.id as id',
            'tblclients.zcode as zcode',
            'tbl_orders.reference_no as reference_no',
            'tbl_productions_orders.reference_no as reference_no_manufactures',
            'tbl_productions_orders.date as date',
            'tbl_products.code as item_code',
            'tbl_productions_orders_items.quantity as quantity',
            'tbl_species.name as name_species',
            'tbl_type_print.name as name_type_print',
            'tb_warehouse_items.product_quantity as quantity_warehouses',
            'tbl_products.images as images',
        ];

        $sIndexColumn = 'id';
        $sTable       = 'tbl_productions_orders';
        $where        = [
            ' AND tbl_productions_orders_items.type_items = "products"',
        ];

        if (!empty($customer_search)) {
            array_push($where, "AND tbl_orders.customer_id = ".$this->db->escape($customer_search));
        }

        if (!empty($start_date_search)) {
            $start_date_search = to_sql_date($start_date_search).' 00:00:00';
            array_push($where, "AND tbl_productions_orders.date >= '".$start_date_search."'");
        }

        if (!empty($end_date_search)) {
            $end_date_search = to_sql_date($end_date_search).' 23:59:59';
            array_push($where, "AND tbl_productions_orders.date <= '".$end_date_search."'");
        }

        $filter = [];

        $join = [
            'INNER JOIN tbl_productions_plan_orders ON tbl_productions_plan_orders.productions_order_id = tbl_productions_orders.id',
            'INNER JOIN tbl_orders ON tbl_orders.id = tbl_productions_plan_orders.productions_plan_id',
            'INNER JOIN tblclients ON tblclients.userid = tbl_orders.customer_id',
            'INNER JOIN tbl_productions_orders_items ON tbl_productions_orders_items.productions_orders_id = tbl_productions_orders.id',
            'INNER JOIN tbl_products ON tbl_products.id = tbl_productions_orders_items.items_id',
            'LEFT JOIN tbl_species ON tbl_species.id = tbl_products.species',
            'LEFT JOIN tbl_type_print ON tbl_type_print.id = tbl_products.id',
            'LEFT JOIN '.$tbWarehouseItems.' ON tb_warehouse_items.id_items = tbl_products.id',
        ];

        $result = data_tables_init($aColumns, $sIndexColumn, $sTable, $join, $where, [
        ], 'ORDER BY tbl_productions_orders.date ASC', []);

        $output = $result['output'];
        $rResult = $result['rResult'];
        $start = $this->input->post('start');
        $group = '';
        $quantity = 0;
        $quantity_warehouses = 0;
        foreach ($rResult as $key => $aRow) {
            $start++;
            $id = $aRow['id'];

            $row[0] = '<div class="text-center">'.$start.'</div>';
            $row[1] = '<div class="text-center">'.$aRow['zcode'].'</div>';
            $row[2] = '<div class="text-left">'.$aRow['reference_no'].'</div>';
            $row[3] = $aRow['reference_no_manufactures'];
            $row[4] = '<div class="text-center">'.(!empty($aRow['date']) ? _d($aRow['date']) : '').'</div>';
            $row[5] = '<div class="text-center">'.$aRow['item_code'].'</div>';
            $row[6] = '<div class="text-center">'.formatNumber($aRow['quantity']).'</div>';
            $row[7] = '<div class="text-center">'.$aRow['name_species'].'</div>';
            $row[8] = '<div class="text-center">'.$aRow['name_type_print'].'</div>';
            $row[9] = '<div class="text-center">'.formatNumber($aRow['quantity_warehouses']).'</div>';

            $images = base_url('assets/images/tnh/no_image.png');
            if (!empty($aRow['images'])) {
                $images = base_url('uploads/products/' . $aRow['images']);
            }
            $row[10] = '<div class="td-image">
                <div class="preview_image" style="width: auto;">
                    <div class="display-block contract-attachment-wrapper img">
                        <div style="width:45px; margin: auto;">
                            <a href="' . $images . '" data-lightbox="customer-profile" class="display-block mbot5">
                                <div class="">
                                    <img src="' . $images . '" style="border-radius: 50%">
                                </div>
                            </a>
                        </div>
                    </div>
                </div>
            </div>';

            $quantity+= $aRow['quantity'];
            $quantity_warehouses+= $aRow['quantity_warehouses'];
            $output['aaData'][] = $row;
        }

        $output['quantity'] = $quantity;
        $output['quantity_warehouses'] = $quantity_warehouses;
        echo json_encode($output);
    }

    public function excel_statistical_planning() {
        if (!$this->perViewProductionsOrders && !$this->perViewOwnProductionsOrders) {
            accessDenied();
        }

        ini_set('memory_limit', '3500M');
        include APPPATH . 'third_party/PHPExcel/PHPExcel.php';
        $this->load->library('PHPExcel');

        $style_excel = style_excel();
        $cloumns_excel = cloumns_excel();
        $objPHPExcel = new PHPExcel();

        $customer_search = $this->input->get('customer_search');
        $start_date_search = $this->input->get('start_date_search');
        $end_date_search = $this->input->get('end_date_search');

        $str_customer = lang('all');
        if (!empty($customer_search)) {
            $dtCustomer = get_table_where('tblclients', ['userid' => $customer_search], '', 'row_array', '', 'company');
            $str_customer = $dtCustomer['company'];
        }
        
        $str_start_date = lang('all');
        if (!empty($start_date_search)) {
            $str_start_date = $start_date_search;
        }

        $str_end_date = lang('all');
        if (!empty($start_date_search)) {
            $str_end_date = $start_date_search;
        }

        $tbWarehouseItems = "(
            SELECT
                tblwarehouse_items.id_items as id_items,
                SUM(tblwarehouse_items.product_quantity) as product_quantity
            FROM tblwarehouse_items
            WHERE tblwarehouse_items.type_items = 'product'
            GROUP BY tblwarehouse_items.id_items
        ) tb_warehouse_items";

        $this->db->select('
            tbl_productions_orders.id as id,
            tblclients.zcode as zcode,
            tbl_orders.reference_no as reference_no,
            tbl_productions_orders.reference_no as reference_no_manufactures,
            tbl_productions_orders.date as date,
            tbl_products.code as item_code,
            tbl_productions_orders_items.quantity as quantity,
            tbl_species.name as name_species,
            tbl_type_print.name as name_type_print,
            tb_warehouse_items.product_quantity as quantity_warehouses,
            tbl_products.images as images,
        ', false);
        $this->db->from('tbl_productions_orders');
        $this->db->join('tbl_productions_plan_orders', 'tbl_productions_plan_orders.productions_order_id = tbl_productions_orders.id', 'inner');
        $this->db->join('tbl_orders', 'tbl_orders.id = tbl_productions_plan_orders.productions_plan_id', 'inner');
        $this->db->join('tblclients', 'tblclients.userid = tbl_orders.customer_id', 'inner');
        $this->db->join('tbl_productions_orders_items', 'tbl_productions_orders_items.productions_orders_id = tbl_productions_orders.id', 'inner');
        $this->db->join('tbl_products', 'tbl_products.id = tbl_productions_orders_items.items_id', 'inner');
        $this->db->join('tbl_species', 'tbl_species.id = tbl_products.species', 'left');
        $this->db->join('tbl_type_print', 'tbl_species.id = tbl_products.species', 'left');
        $this->db->join($tbWarehouseItems, 'tb_warehouse_items.id_items = tbl_products.id', 'left');

