        $objPHPExcel->getActiveSheet()->setCellValue('B5', 'Mã KH');
        $objPHPExcel->getActiveSheet()->setCellValue('C5', 'Mã ĐĐH');
        $objPHPExcel->getActiveSheet()->setCellValue('D5', 'LSX tổng');
        $objPHPExcel->getActiveSheet()->setCellValue('E5', 'Ngày sản xuất');
