    public function getShowDetailManufacturesBusinessPlan()
    {
        $start_date_search = !empty($this->input->post('start_date_search')) ? to_sql_date($this->input->post('start_date_search')) : date('Y-m-d');
        $end_date_search = !empty($this->input->post('end_date_search')) ? to_sql_date($this->input->post('end_date_search')) : date('Y-m-d');

        $product_id = $this->input->post('product_id');
        $slKeep = "COALESCE((
            SELECT SUM(tbltransfer_warehouse_detail.quantity_net) as quantity_net
            FROM tbltransfer_warehouse_detail
            WHERE tbltransfer_warehouse_detail.order_id_item = tbl_order_items.id AND tbltransfer_warehouse_detail.tranfer_business_item_id = 0
        ), 0)";

        $tbQuantity = "(
            SELECT
                tbl_business_plan_items.business_plan_id as business_plan_id,
                SUM(tbl_business_plan_items_date.quantity - tbl_business_plan_items_date.quantity_plan_item) as quantity_delivery
            FROM tbl_business_plan_items
            INNER JOIN tbl_business_plan_items_date ON tbl_business_plan_items.id = tbl_business_plan_items_date.business_plan_items_id
            WHERE tbl_business_plan_items.type_items = 'products' AND tbl_business_plan_items.items_id = ".$product_id." AND tbl_business_plan_items_date.date >= '$start_date_search' AND tbl_business_plan_items_date.date <= '$end_date_search'
            GROUP BY tbl_business_plan_items.business_plan_id
        ) tb_quantity";

        $aColumns = [
            'tbl_business_plan.id as id',
            'tbl_business_plan.date as date',
            'tbl_business_plan.reference_no as reference_no',
            'tbl_business_plan.plan_name as plan_name',
            'tb_quantity.quantity_delivery as quantity_delivery',
        ];
        $sIndexColumn = 'id';
        $sTable       = 'tbl_business_plan';
        $where        = [
        ];
        $filter = [];
        $join = [
            'INNER JOIN '.$tbQuantity.' ON tbl_business_plan.id = tb_quantity.business_plan_id',
        ];

        array_push($where, ' AND tb_quantity.quantity_delivery > 0 AND tbl_business_plan.status = "approved"');

        $result = data_tables_init($aColumns, $sIndexColumn, $sTable, $join, $where, [
        ], '', []);

        $output = $result['output'];
        $rResult = $result['rResult'];
        $start = $this->input->post('start');
        $totalQuantity = 0;
        foreach ($rResult as $key => $aRow) {
            $start++;

            $row[0] = '<div class="text-center">'.$start.'</div>';
            $row[1] = '<div class="text-center">'._d($aRow['date']).'</div>';
            $row[2] = $aRow['reference_no'];
            $row[3] = $aRow['plan_name'];
            $row[4] = '<div class="text-center">'.formatNumber($aRow['quantity_delivery']).'</div>';

            $totalQuantity+= $aRow['quantity_delivery'];
            $output['aaData'][] = $row;
        }

        $output['totalQuantity'] = $totalQuantity;
        echo json_encode($output);
    }

	public function changeStaffAssignDetail($productions_detail_id = '') {
		$staff_assign = $this->input->post('staff_assign');
		$data = [];
		$arrayID = [];
		if($this->input->post()) {
			if(!empty($staff_assign)) {
				foreach ($staff_assign as $key => $value) {
					$this->db->where('productions_detail_id', $productions_detail_id);
					$this->db->where('staff_id', $value);
					$kt_productions_orders = $this->db->get('tbl_productions_orders_detail_staff')->row();
					if (!empty($kt_productions_orders)) {
						$arrayID[] = $kt_productions_orders->id;
					} else {
						$this->db->insert('tbl_productions_orders_detail_staff', [
							'productions_detail_id' => $productions_detail_id,
							'staff_id' => $value,
						]);
						$arrayID[] = $this->db->insert_id();
					}
				}
			}

			$this->db->where('productions_detail_id', $productions_detail_id);
			if (!empty($arrayID)) {
				$this->db->where_not_in('id', $arrayID);
			}
			$this->db->delete('tbl_productions_orders_detail_staff');

			noti_custom('add_staff_manufactures_detail', $productions_detail_id, get_staff_user_id(), 0, 'add_staff_manufactures_detail', ['actions' => 'add', 'staff_id_add' => [$staff_assign]]);
			$data['success'] = true;
			$data['alert_type'] = 'success';
			$data['message'] = lang('success');
		}
		else {
			$data['success'] = false;
			$data['alert_type'] = 'danger';
			$data['message'] = lang('fail');
		}

		echo json_encode($data);die();
	}

	public function get_assiged_promotion($id_promotion = '') {
    	$data['title'] = 'Nhân viên phụ trách chi tiết đơn hàng';

    	$this->db->select('GROUP_CONCAT(staff_id) as staff_id');
    	$this->db->where('productions_detail_id', $id_promotion);
    	$data['staff_productions'] = $this->db->get('tbl_productions_orders_detail_staff')->row('staff_id');
    	if(!empty($data['staff_productions'])) {
			$data['staff_productions'] = explode(',', $data['staff_productions']);
		}

    	$this->db->where('active', 1);
    	$data['staff'] = $this->db->get('tblstaff')->result_array();

    	$data['id_promotion'] = $id_promotion;
    	$this->load->view('admin/manufactures/c_modal_assiged', $data);
	}

    public function loadProductsPreventive() {
        $data = [];
        $dataPOST = $this->input->post();
        if (!empty($dataPOST)) {
            $condition_safe_inventory = $this->input->post('condition_safe_inventory');
            $condition_planning_cycle = $this->input->post('condition_planning_cycle');
            $condition_options1 = $this->input->post('condition_options1');
            $condition_options2 = $this->input->post('condition_options2');
            $orders = !empty($this->input->post('condition_orders')) ? $this->input->post('condition_orders') : null;
            $business_plans = !empty($this->input->post('condition_business_plans')) ? $this->input->post('condition_business_plans') : null;
            $orders_items = !empty($this->input->post('condition_orders_items')) ? $this->input->post('condition_orders_items') : null;
            $business_plans_items = !empty($this->input->post('condition_business_plans_items')) ? $this->input->post('condition_business_plans_items') : null;
            $condition_remove_item = !empty($this->input->post('condition_remove_item')) ? $this->input->post('condition_remove_item') : null;
            $condition_p_id_post = $this->input->post('condition_p_id_post');

            $cs_product_id = $this->input->post('cs_product_id');
            $arrProducts = [];
            if (!empty($cs_product_id)) {
                $cs_product_id = array_unique($cs_product_id);
                $this->db->select('
                    tbl_products.id as product_id,
                    tbl_products.code as item_code,
                    tbl_products.name as item_name,
                    tbl_products.versions as versions,
                    tbl_products.versions_stage as versions_stage,
                    tblunits.unit as unit_name,
                    tbl_products.is_no_stock as is_no_stock,
                    tbl_products.quantity_max as quantity_max
                ', false);
                $this->db->from('tbl_products');
                $this->db->join('tblunits', 'tblunits.unitid = tbl_products.conversion_unit', 'left');
                $this->db->where_in('tbl_products.id', $cs_product_id);
                $dtProducts = $this->db->get()->result_array();
                if (!empty($dtProducts)) {
                    foreach ($dtProducts as $key => $value) {
                        $versions = $value['versions'];
                        $this->db->select('tbl_product_versions.versions as versions');
                        $this->db->from('tbl_product_versions');
                        $this->db->where_in('tbl_product_versions.product_id', $value['product_id']);
                        $product_verions = $this->db->get()->result_array();
                        $optionsVersions = "<option></option>";
                        if (!empty($product_verions)) {
                            foreach ($product_verions as $k => $val) {
                                $selected = ($versions == $val['versions']) ? 'selected' : '';
                                $optionsVersions.= '<option '.$selected.' value="'.$val['versions'].'">'.$val['versions'].'</option>';
                            }
                        }
                        $dtProducts[$key]['optionsVersions'] = $optionsVersions;

                        //stages
                        $versions_stage = $value['versions_stage'];
                        $this->db->select('tbl_product_stages.versions as versions');
                        $this->db->from('tbl_product_stages');
                        $this->db->where_in('tbl_product_stages.product_id', $value['product_id']);
                        $product_verions_stages = $this->db->get()->result_array();
                        $optionsVersionsStages = "<option></option>";
                        if (!empty($product_verions_stages)) {
                            foreach ($product_verions_stages as $k => $val) {
                                $selected = ($versions_stage == $val['versions']) ? 'selected' : '';
                                $optionsVersionsStages.= '<option '.$selected.' value="'.$val['versions'].'">'.$val['versions'].'</option>';
                            }
                        }
                        $dtProducts[$key]['optionsVersionsStages'] = $optionsVersionsStages;
                    }
                }
                $arrProducts = $dtProducts;
            }
            $data['arrProducts'] = $arrProducts;
        }
        echo json_encode($data);
    }

