    public function print_productions_orders_new($id) {
        ob_end_clean();
        $data = [];

        $data['title'] = lang('productions_orders');
        $data['type'] = 'P';
        $data['img'] = '';
        $message = "";

        $this->db->select('
            tbl_productions_orders.id as id,
            tbl_productions_orders.reference_no as reference_no,
