    public function print_productions_orders_detail_new1($id){
        $data = [];
        $order = get_table_where('tbl_productions_orders',['id' => $id],'','row_array');

        $this->db->select('
            tbl_order_items.id as id,
            tbl_productions_orders_items.type_items as type_item,
            tbl_productions_orders_items.items_id as item_id,
            tbl_order_items.product_name_customer as product_name_customer,
            tbl_order_items.ct_counter_item as ct_counter_item,
            IF(tbl_productions_orders_items.object_item_type = "orders",tbl_productions_orders_items.quantity,0) as quantity,
            IF(tbl_productions_orders_items.object_item_type = "business_plan",tbl_productions_orders_items.quantity,0) as quantity_new,
            tbl_orders.reference_no as reference_no,
            tbl_business_plan.reference_no as reference_no_plan,
            ');
        $this->db->from('tbl_productions_orders_items');
        $this->db->join('tbl_order_items','tbl_order_items.id = tbl_productions_orders_items.production_plan_item_id AND tbl_productions_orders_items.object_item_type = "orders"','left');
        $this->db->join('tbl_orders','tbl_orders.id = tbl_order_items.order_id','left');
        $this->db->join('tbl_business_plan_items','tbl_business_plan_items.id = tbl_productions_orders_items.production_plan_item_id AND tbl_productions_orders_items.object_item_type = "business_plan"','left');
        $this->db->join('tbl_business_plan','tbl_business_plan.id = tbl_business_plan_items.business_plan_id','left');
