                    $totalQuantityNew = sumTotalRowFirst($items_id,$type_item,$items,$key,'quantity_new',$info['code']);
                }

                $quntityOld += $value['quantity_new'] + $value['quantity'];
                $quntityOldNew += $value['quantity_new'] + $value['quantity'];


                if(($totalQuantity + $totalQuantityNew) == $quntityOld){
                    $htmlOrderColumnsNew .= '<tr>
