            GROUP_CONCAT(distinct IF (tbl_productions_orders_items.object_item_type = "orders", tbl_productions_orders_details.object_id, "") SEPARATOR "|||") as group_object_orders_id,
            GROUP_CONCAT(distinct IF (tbl_productions_orders_items.object_item_type = "business_plan", tbl_productions_orders_details.object_id, "") SEPARATOR "|||") as group_object_business_plan_id,
            GROUP_CONCAT(distinct IF (tbl_productions_orders_items.object_item_type = "orders", tbl_productions_orders_items.production_plan_item_id, "") SEPARATOR "|||") as group_object_items_id,
            SUM(IF (tbl_productions_plan_items.is_preventive = 1, tbl_productions_orders_items.quantity, 0)) as quantity_preventive,
            SUM(IF (tbl_productions_plan_items.is_preventive = 0, tbl_productions_orders_items.quantity, 0)) as quantity,
        ', false);
        $this->db->from('tbl_productions_orders_items');
        $this->db->join('tbl_productions_plan_items', 'tbl_productions_plan_items.id = tbl_productions_orders_items.plan_item_id');
        $this->db->join('tbl_productions_orders_details', 'tbl_productions_orders_details.productions_orders_item_id = tbl_productions_orders_items.id');
        $this->db->join('tbl_products', 'tbl_products.id = tbl_productions_orders_items.items_id');
        $this->db->join('tblunits', 'tblunits.unitid = tbl_products.conversion_unit');
        $this->db->where('tbl_productions_orders_items.productions_orders_id',$id);
        $this->db->group_by('tbl_productions_orders_items.items_id, tbl_productions_orders_items.type_items');

        // $this->db->order_by('tbl_productions_orders_items.items_id asc,tbl_productions_orders_items.type_items asc,tbl_productions_orders_items.object_item_type desc');
        $items = $this->db->get()->result_array();

        $total_quantity_items = 0;
        if (!empty($items)) {
            foreach ($items as $key => $value) {
                $items_id = $value['items_id'];
                $quantity = $value['quantity'];
                $quantity_preventive = $value['quantity_preventive'];
                $total_quantity = $quantity + $quantity_preventive;

                $group_object_items_id = $value['group_object_items_id'];
                $product_name_customer = '';
                if (!empty($group_object_items_id)) {
                    $this->db->select('GROUP_CONCAT(distinct tbl_order_items.product_name_customer) as product_name_customer', false);
                    $this->db->from('tbl_order_items');
                    $this->db->where_in('tbl_order_items.id', explode('|||', $group_object_items_id));
                    $order_item = $this->db->get()->row_array();
                    if (!empty($order_item)) {
                        $product_name_customer = $order_item['product_name_customer'];
                    }
                }

                $group_object_orders_id = $value['group_object_orders_id'];
                $str_order = '';
                if (!empty($group_object_orders_id)) {
                    $this->db->select('
                        GROUP_CONCAT(tbl_orders.reference_no SEPARATOR "<br>") as reference_no
                    ', false);
                    $this->db->from('tbl_orders');
                    $this->db->where_in('tbl_orders.id', explode('|||', $group_object_orders_id));
                    $dtOrder = $this->db->get()->row_array();
                    if (!empty($dtOrder)) {
                        $str_order.= $dtOrder['reference_no'];
                    }
                }

                $group_object_business_plan_id = $value['group_object_business_plan_id'];
                if (!empty($group_object_business_plan_id)) {
                    $this->db->select('
                        GROUP_CONCAT(tbl_business_plan.reference_no SEPARATOR "<br>") as reference_no
                    ', false);
                    $this->db->from('tbl_business_plan');
                    $this->db->where_in('tbl_business_plan.id', explode('|||', $group_object_business_plan_id));
                    $dtBusinessPlan = $this->db->get()->row_array();
                    if (!empty($dtBusinessPlan)) {
                        if (!empty($str_order)) {
                            $str_order.= '<br>'.$dtBusinessPlan['reference_no'];
                        } else {
                            $str_order.= $dtBusinessPlan['reference_no'];
                        }
                    }
                }

                $tdNumber = '<td class="text-center" style="width: 10%;">' . (++$key) . '</td>';
                $tdCode = '<td style="width: 20%;">' . ($value['item_code']) . '</td>';
                // $tdName = '<td style="width: 20%;font-family: kozgopromedium;font-size:11px">'.$product_name_customer.'</td>';
                $tdName = '<td style="width: 20%;font-size:11px; text-align: left;">'.$value['item_name'].'</td>';
                $tdOrder = '<td class="text-center" style="width: 12%;">'.$str_order.'</td>';
                $tdUnit = '<td class="text-center" style="width: 8%;">' . $value['unit_name'] . '</td>';
                $tdQuantity = '<td class="text-center" style="width: 10%;">' . formatNumber($quantity) . '</td>';
                $tdQuanityNew = '<td class="text-center" style="width: 10%;">' . formatNumber($quantity_preventive) . '</td>';
                $tdTotalQuantity = '<td class="text-center" style="width: 10%;">' . formatNumber($total_quantity) . '</td>';
                $total_quantity_items+= $total_quantity;

                $htmlOrderColumns = '';
                $productsColumns = $this->products_model->getProductsColumns($items_id);
                $thSub = '';
                $trHtmlChild = '';

                if (!empty($group_object_orders_id)) {
                    $productsColumns[] = [
                        'id' => 0,
                        'columns_id' => 0,
                        'name' => 'quantity_put',
                    ];

                    $productsColumns[] = [
                        'id' => 0,
                        'columns_id' => 0,
                        'name' => 'quantity_loss',
                    ];

                    $productsColumns[] = [
                        'id' => 0,
                        'columns_id' => 0,
                        'name' => 'sample_quantity_item',
                    ];

                    $selectOrderItemsColumns = '';
                    $group_by = '';
                    $select_group = '';
                    $slSum = '';

                    if (!empty($productsColumns)) {
                        foreach ($productsColumns as $kP => $vP) {
                            $selectOrderItemsColumns.= 'MAX(IF (tbl_order_items_columns.columns_value = "'.$vP['name'].'", tbl_order_items_columns.columns_name, "")) as c_'.$kP.' ,';

                            if ($vP['name'] != 'quantity_put' && $vP['name'] != 'quantity_loss' && $vP['name'] != 'sample_quantity_item') {
                                $select_group .= 'tb_cs.c_'.$kP.',';
                                $group_by.= 'tb_cs.c_'.$kP.',';

                                $font = 'kozgopromedium';
                                if (preg_match('/[\x{4e00}-\x{9fff}]/u', ($vP['name'] ?? ''))) {
                                    // Có ký tự Trung Quốc, ưu tiên font droidsansfallback
                                    $font = 'droidsansfallback';
                                } elseif (preg_match('/[\p{Hiragana}\p{Katakana}（）]/u', ($vP['name'] ?? ''))) {
                                    // Chỉ có ký tự tiếng Nhật, dùng kozgopromedium
                                    $font = 'kozgopromedium';
                                }

                                $thSub.= '<th class="text-center" style="font-family: '.$font.';font-size:11px;">'.$vP['name'].'</th>';
                            } else {
                                $slSum.= ' tb_cs.c_'.$kP.' +';
                                $select_group .= 'SUM(tb_cs.c_'.$kP.') as c_'.$kP.',';
                            }
                        }
                        $selectOrderItemsColumns = rtrim($selectOrderItemsColumns, ',');
                        if (!empty($group_by)) {
                            $group_by = rtrim($group_by, ',');
                        }

                        $slSum = rtrim($slSum, '+');
                        $select_group.= 'SUM('.$slSum.') as c_'.(++$kP).'';
                        // if (!empty($select_group)) {
                        //     $select_group = rtrim($select_group, ',');
                        // }
                    }

                    // $group_object_items_id = explode('|||', $group_object_items_id);
                    $group_object_items_id = str_replace('|||', ',', $group_object_items_id);
                    $group_object_items_id = ltrim($group_object_items_id, ',');

                    // $this->db->select('
                    //     tbl_order_items_columns.order_item_id,
                    //     tbl_order_items_columns.counter_items_number,
                    //     '.$selectOrderItemsColumns.'
                    // ');
                    // $this->db->from('tbl_order_items_columns');
                    // $this->db->where_in('tbl_order_items_columns.order_item_id', $group_object_items_id);
                    // $this->db->group_by('tbl_order_items_columns.order_item_id, tbl_order_items_columns.counter_items_number');
                    // $order_items_columns = $this->db->get()->result_array();
                    $query = '(
                        SELECT
                            '.$select_group.'
                        FROM (
                            SELECT
                                tbl_order_items_columns.order_item_id, 
                                tbl_order_items_columns.counter_items_number,
                                '.$selectOrderItemsColumns.'
                            FROM tbl_order_items_columns
                            WHERE tbl_order_items_columns.order_item_id IN ('.$group_object_items_id.')
                            GROUP BY tbl_order_items_columns.order_item_id, tbl_order_items_columns.counter_items_number
                        ) tb_cs
                        '.($group_by ? 'GROUP BY '.$group_by.'' : '').'
                    )';
                    $order_items_columns = $this->db->query($query)->result_array();
                    $arrTemp = [];
