            'alignment' => array(
                'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,
                'vertical' => PHPExcel_Style_Alignment::VERTICAL_CENTER
            )
        ]);

        $BStyle = array(
            'font' => array(
                'bold' => true,
                'color' => array('rgb' => '111112'),
                'size' => 11,
                'name' => 'Times New Roman',
            ),
            'alignment' => array(
                'horizontal' => 'center',
                'vertical' => 'center',
            ),
            'borders' => array(
                'allborders' => array(
                    'style' => PHPExcel_Style_Border::BORDER_THIN
                )
            ),
        );
        $startRow++;
        $objPHPExcel->getActiveSheet()->setCellValue('B'.$startRow, 'Ngày: ');
        $objPHPExcel->getActiveSheet()->setCellValue('C'.$startRow, _d($order['date'], true));

        $startRow++;
        $objPHPExcel->getActiveSheet()->setCellValue('B'.$startRow, 'Mã LSX: ');
        $objPHPExcel->getActiveSheet()->setCellValue('C'.$startRow, $order['reference_no']);

        $startRow+=2;
        $objPHPExcel->getActiveSheet()->getStyle('A'.$startRow.':H'.$startRow)->applyFromArray(
            array(
                'fill' => array(
                    'type' => PHPExcel_Style_Fill::FILL_SOLID,
                    'color' => array('rgb' => '9BC2E6')
                )
            )
        );
        $objPHPExcel->getActiveSheet()->setCellValue('A'.$startRow, 'STT')->getStyle('A'.$startRow)->applyFromArray($BStyle);
        $objPHPExcel->getActiveSheet()->setCellValue('B'.$startRow, 'Mã TP')->getStyle('B'.$startRow)->applyFromArray($BStyle);
        $objPHPExcel->getActiveSheet()->setCellValue('C'.$startRow, 'Tên TP')->getStyle('C'.$startRow)->applyFromArray($BStyle);
        $objPHPExcel->getActiveSheet()->setCellValue('D'.$startRow, 'Đơn hàng/ KHKD')->getStyle('D'.$startRow)->applyFromArray($BStyle);
        $objPHPExcel->getActiveSheet()->setCellValue('E'.$startRow, 'ĐVT')->getStyle('E'.$startRow)->applyFromArray($BStyle);
        $objPHPExcel->getActiveSheet()->setCellValue('F'.$startRow, 'Số lượng')->getStyle('F'.$startRow)->applyFromArray($BStyle);
        $objPHPExcel->getActiveSheet()->setCellValue('G'.$startRow, 'Số lượng dự phòng')->getStyle('G'.$startRow)->applyFromArray($BStyle);
        $objPHPExcel->getActiveSheet()->setCellValue('H'.$startRow, 'Tổng số lượng')->getStyle('H'.$startRow)->applyFromArray($BStyle);

        $objPHPExcel->getActiveSheet()->getStyle("B".$startRow.":V".$startRow)->applyFromArray([
            'font' => array(
                'bold' => true,
            ),
        ]);

        $objPHPExcel->getActiveSheet()->getStyle("A".$startRow.":V".$startRow)->applyFromArray([
            'font' => array(
                'bold' => true,
            ),
        ]);


        $row = $startRow;
        $group = '';
        $start = 0;
        $total_quantity_items = 0;
        if (!empty($rs)) {
            foreach ($rs as $key => $value) {

                $row++;
                $start++;

                $items_id = $value['items_id'];
                $quantity = $value['quantity'];
                $quantity_preventive = $value['quantity_preventive'];
                $total_quantity = $quantity + $quantity_preventive;

                $group_object_items_id = $value['group_object_items_id'];
                $product_name_customer = '';
                if (!empty($group_object_items_id)) {
                    $this->db->select('GROUP_CONCAT(distinct tbl_order_items.product_name_customer) as product_name_customer', false);
                    $this->db->from('tbl_order_items');
                    $this->db->where_in('tbl_order_items.id', explode('|||', $group_object_items_id));
                    $order_item = $this->db->get()->row_array();
                    if (!empty($order_item)) {
                        $product_name_customer = $order_item['product_name_customer'];
                    }
                }

                $group_object_orders_id = $value['group_object_orders_id'];
                $str_order = '';
                if (!empty($group_object_orders_id)) {
                    $this->db->select('
                        GROUP_CONCAT(tbl_orders.reference_no) as reference_no
                    ', false);
                    $this->db->from('tbl_orders');
                    $this->db->where_in('tbl_orders.id', explode('|||', $group_object_orders_id));
                    $dtOrder = $this->db->get()->row_array();
                    if (!empty($dtOrder)) {
                        $str_order.= $dtOrder['reference_no'];
                    }
                }

                $group_object_business_plan_id = $value['group_object_business_plan_id'];
                if (!empty($group_object_business_plan_id)) {
                    $this->db->select('
                        GROUP_CONCAT(tbl_business_plan.reference_no) as reference_no
                    ', false);
                    $this->db->from('tbl_business_plan');
                    $this->db->where_in('tbl_business_plan.id', explode('|||', $group_object_business_plan_id));
                    $dtBusinessPlan = $this->db->get()->row_array();
                    if (!empty($dtBusinessPlan)) {
                        if (!empty($str_order)) {
                            $str_order.= ','.$dtBusinessPlan['reference_no'];
                        } else {
                            $str_order.= $dtBusinessPlan['reference_no'];
                        }
                    }
                }

                $objPHPExcel->getActiveSheet()->setCellValue('A' . $row, (++$key));
                $objPHPExcel->getActiveSheet()->setCellValue('B' . $row, $value['item_code']);
                $objPHPExcel->getActiveSheet()->setCellValue('C' . $row, $product_name_customer);
                $objPHPExcel->getActiveSheet()->setCellValue('D' . $row, $str_order)->getStyle("D$row")->getAlignment()->setWrapText(true);
                $objPHPExcel->getActiveSheet()->setCellValue('E' . $row, $value['unit_name']);
                $objPHPExcel->getActiveSheet()->setCellValue('F' . $row, $quantity)->getStyle("F$row")->getNumberFormat()->setFormatCode(formatMoneyExcel($quantity));
                $objPHPExcel->getActiveSheet()->setCellValue('G' . $row, $quantity_preventive)->getStyle("G$row")->getNumberFormat()->setFormatCode(formatMoneyExcel($quantity_preventive));
                $objPHPExcel->getActiveSheet()->setCellValue('H' . $row, $total_quantity)->getStyle("H$row")->getNumberFormat()->setFormatCode(formatMoneyExcel($total_quantity));
                $total_quantity_items+= $total_quantity;

                $htmlOrderColumns = '';
                $productsColumns = $this->products_model->getProductsColumns($items_id);
                $thSub = '';
                $trHtmlChild = '';

                if (!empty($group_object_orders_id)) {
                    $productsColumns[] = [
                        'id' => 0,
                        'columns_id' => 0,
                        'name' => 'quantity_put',
                    ];

                    $productsColumns[] = [
                        'id' => 0,
                        'columns_id' => 0,
                        'name' => 'quantity_loss',
                    ];

                    $productsColumns[] = [
                        'id' => 0,
                        'columns_id' => 0,
                        'name' => 'sample_quantity_item',
                    ];

                    $selectOrderItemsColumns = '';
                    $group_by = '';
                    $select_group = '';
                    $slSum = '';
                    $i = 1;
                    if (!empty($productsColumns)) {
                        $row ++;
                        $objPHPExcel->getActiveSheet()->setCellValue('A'.$row,
                            'STT')->getStyle('A'.$row)->applyFromArray($BStyle);
                        foreach ($productsColumns as $kP => $vP) {
                            $selectOrderItemsColumns .= 'MAX(IF (tbl_order_items_columns.columns_value = "' . $vP['name'] . '", tbl_order_items_columns.columns_name, "")) as c_' . $kP . ' ,';

                            if ($vP['name'] != 'quantity_put' && $vP['name'] != 'quantity_loss' && $vP['name'] != 'sample_quantity_item') {
                                $select_group .= 'tb_cs.c_' . $kP . ',';
                                $group_by .= 'tb_cs.c_' . $kP . ',';

                                $objPHPExcel->getActiveSheet()->setCellValue($columsExcel[($i)].$row,
                                    $vP['name'])->getStyle($columsExcel[($i)].$row)->applyFromArray($BStyle);
                                $i++;
                            } else {
                                $slSum .= ' tb_cs.c_' . $kP . ' +';
                                $select_group .= 'SUM(tb_cs.c_' . $kP . ') as c_' . $kP . ',';
                            }
                        }
                        $objPHPExcel->getActiveSheet()->setCellValue($columsExcel[($i)].$row,
                            lang('tnh_quantity_put'))->getStyle($columsExcel[($i)].$row)->applyFromArray($BStyle);
                        $i++;
                        $objPHPExcel->getActiveSheet()->setCellValue($columsExcel[($i)].$row,
                            lang('tnh_quantity_loss'))->getStyle($columsExcel[($i)].$row)->applyFromArray($BStyle);
                        $i++;
                        $objPHPExcel->getActiveSheet()->setCellValue($columsExcel[($i)].$row,
                            lang('tnh_sample_quantity'))->getStyle($columsExcel[($i)].$row)->applyFromArray($BStyle);
                        $i++;
                        $objPHPExcel->getActiveSheet()->setCellValue($columsExcel[($i)].$row,
                            lang('Tổng số lượng'))->getStyle($columsExcel[($i)].$row)->applyFromArray($BStyle);
                        $selectOrderItemsColumns = rtrim($selectOrderItemsColumns, ',');
                        if (!empty($group_by)) {
                            $group_by = rtrim($group_by, ',');
                        }

                        $slSum = rtrim($slSum, '+');
                        $select_group .= 'SUM(' . $slSum . ') as c_' . (++$kP) . '';
                    }

                    $group_object_items_id = str_replace('|||', ',', $group_object_items_id);
                    $group_object_items_id = ltrim($group_object_items_id, ',');

                    $query = '(
                        SELECT
                            ' . $select_group . '
                        FROM (
                            SELECT
                                tbl_order_items_columns.order_item_id, 
                                tbl_order_items_columns.counter_items_number,
                                ' . $selectOrderItemsColumns . '
                            FROM tbl_order_items_columns
                            WHERE tbl_order_items_columns.order_item_id IN (' . $group_object_items_id . ')
                            GROUP BY tbl_order_items_columns.order_item_id, tbl_order_items_columns.counter_items_number
                        ) tb_cs
                        ' . ($group_by ? 'GROUP BY ' . $group_by . '' : '') . '
                    )';
                    $order_items_columns = $this->db->query($query)->result_array();
                    $arrTemp = [];
                    if (!empty($order_items_columns)) {

                        foreach ($order_items_columns as $kIC => $vIC) {
                            $row ++;
                            $length = count($vIC);
                            $trHtmlChild .= '<tr>';
                            $objPHPExcel->getActiveSheet()->setCellValue('A' . $row, (++$kIC));
                            for ($i = 0; $i < $length; $i++) {
                                $j = $i + 1;
                                if (is_numeric($vIC['c_' . $i])){
                                    $objPHPExcel->getActiveSheet()->setCellValue($columsExcel[($j)] . $row, $vIC['c_' . $i])->getStyle($columsExcel[($j)].$row)->getNumberFormat()->setFormatCode(formatMoneyExcel($vIC['c_' . $i]));
                                } else {
                                    $objPHPExcel->getActiveSheet()->setCellValue($columsExcel[($j)] . $row, $vIC['c_' . $i])->getStyle($columsExcel[($j)].$row)->getAlignment()->setWrapText(true);
                                }
                                $j++;
                            }

                        }
                    }
                }

            }
        }

        $row++;

        $objPHPExcel->getActiveSheet()->setCellValue('B' . $row, 'TỔNG CỘNG')->getStyle("B$row")->applyFromArray($BStyle);
        $objPHPExcel->getActiveSheet()->setCellValue('H' . $row, $total_quantity_items)->getStyle("H$row")->applyFromArray($BStyle)->getNumberFormat()->setFormatCode(formatMoneyExcel($total_quantity_items));

        $objPHPExcel->getActiveSheet()->getColumnDimension('A')->setWidth(5);
        $objPHPExcel->getActiveSheet()->getColumnDimension('B')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('C')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('D')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('E')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('F')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('G')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('H')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('I')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('J')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('K')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('L')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('M')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('N')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('O')->setWidth(15);
        $objPHPExcel->getActiveSheet()->getColumnDimension('P')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('Q')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('R')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('S')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('T')->setWidth(20);
        $objPHPExcel->getActiveSheet()->getColumnDimension('U')->setWidth(30);
        $objPHPExcel->getActiveSheet()->getColumnDimension('V')->setWidth(30);
        $filename = lang('chi_tiet_lenh_san_xuat') . '.xls';

        $objPHPExcel->getActiveSheet()->getStyle("A".$startRow.":H$row")->applyFromArray([
           'borders' => array(
               'allborders' => array(
                   'style' => PHPExcel_Style_Border::BORDER_THIN
               )
           ),
            'alignment' => array(
                'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,
                'vertical' => PHPExcel_Style_Alignment::VERTICAL_CENTER
            )
        ]);

        $objPHPExcel->getActiveSheet()->getStyle("A1:H$row")->getAlignment()->setWrapText(true);

        $objPHPExcel->getActiveSheet()->freezePane('A1');
        $objWriter = PHPExcel_IOFactory::createWriter($objPHPExcel, 'Excel5');
        header('Content-Type: application/vnd.ms-excel');
        header('Content-Disposition: attachment;filename="' . $filename . '"');
        header('Cache-Control: max-age=0');

        $objWriter->save('php://output');
        exit();
    }

    function searchProductionsPlanNew()
    {
        $data = [];
        if ($this->input->get()) {
            $term = $this->input->get('term');
            $limit = get_option('select2_limit');

            $this->db->select('
                tbl_productions_plan.id as id, 
                tbl_productions_plan.reference_no as text, 
            ', false);
            $this->db->from('tbl_productions_plan');
            if (!empty($term))
            {
                $this->db->group_start();
                $this->db->like('tbl_productions_plan.reference_no', $term);
                $this->db->group_end();
            }
            $this->db->limit($limit);
            $data['results'] = $this->db->get()->result_array();
        }
        echo json_encode($data);
    }


	public function status_pause() {
		$id = $this->input->post('id');
		$status_orders = $this->input->post('status_orders');
		if(empty($status_orders)) {
			$status_orders = 0;
		}

		if(!empty($id)) {
			$this->db->where('id', $id);
			$success = $this->db->update('tbl_productions_orders', ['status_orders' => $status_orders]);
			if(!empty($success)) {
				echo json_encode([
					'success' => true,
					'alert_type' => 'success',
					'message' => 'Cập nhật trạng thái thành công'
				]);die();
			}
		}
		echo json_encode([
			'success' => false,
			'alert_type' => 'danger',
			'message' => 'Cập nhật trạng thái không thành công'
		]);die();
	}

    public function agreePO() {
        $data = [];
        // if (!$this->perApproveOrders) {
        //     $data['result'] = 0;
        //     $data['message'] = lang('access_denied');
        //     echo json_encode($data);
        //     die;
        // }

        if ($this->input->get()) {
            $po_id = $this->input->get('po_id');
            $status = $this->input->get('status');

            $po = get_table_where('tbl_productions_orders', ['id' => $po_id], '', 'row_array');
            $date = date('Y-m-d H:i:s');
            $user_id = get_staff_user_id();
            if ($po['status_gdsx'] == $status) {
                $data['result'] = 0;
                $data['message'] = lang('tnh_please_referesh_table');
                echo json_encode($data);
                die;
            }

            $this->db->where('id', $po_id);
			$success = $this->db->update('tbl_productions_orders', [
                'status_gdsx' => $status,
                'user_gdsx' => $user_id,
                'date_gdsx' => $date,
            ]);
            if ($success) {
                $data['result'] = 1;
                $data['message'] = lang('Đổi trạng thái thành công');
            } else {
                $data['result'] = 0;
                $data['message'] = lang('Đổi trạng thái thất bại');
            }
        }

        echo json_encode($data);
    }
}